INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95203, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "柜子", "is_correct": false, "explanation": "语义：柜子不是可以走上去的平台，“走上去”说不通。"}, {"text": "雨伞", "is_correct": false, "explanation": "语义：雨伞是遮雨的用具，不能说“走上去”。"}, {"text": "电视", "is_correct": false, "explanation": "配价：“走上去”需要一个能让人踩上去的地方，电视不能承受人走上去。"}, {"text": "地台", "is_correct": true, "explanation": "正确：地台高出地面一步，老人能走上去。"}], "explanations": {"柜子": "语义：柜子不是可以走上去的平台，“走上去”说不通。", "雨伞": "语义：雨伞是遮雨的用具，不能说“走上去”。", "电视": "配价：“走上去”需要一个能让人踩上去的地方，电视不能承受人走上去。", "地台": "正确：地台高出地面一步，老人能走上去。"}, "sentence_index": 6, "correct_answer": "地台"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我把地台放进书包，带到了学校。", "explanation": "这里应该用〈课本〉。地台是房间里固定的平台，不能放进书包带走。"}, {"text": "我们坐地台去了火车站。", "explanation": "这里应该用〈地铁〉。地台是固定的平台，不能用来乘坐前往别处。"}, {"text": "他喝了一杯地台。", "explanation": "这里应该用〈茶〉。地台是家具式的平台，不能喝。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bab70b32-5cd7-4ce1-9368-e9b36247ac3a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95203, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "卧室的窗边有一双地台，可以放书。", "corrected_sentence": "卧室的窗边有一个地台，可以放书。", "error_description": "错误：一双地台。正确：一个地台。〈双〉用于成对的东西，地台是单个的平台，应用〈个〉。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bab70b32-5cd7-4ce1-9368-e9b36247ac3a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95203, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们把地台们擦了一遍。", "corrected_sentence": "我们把地台擦了一遍。", "error_description": "错误：地台们。正确：地台。〈地台〉是单个的平台，不能加〈们〉表示复数。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bab70b32-5cd7-4ce1-9368-e9b36247ac3a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
