INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95205, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "事情都做完了。", "primary_collocate": null, "pronunciation": "wán bì", "ipa": "wan˧˥ pi˥˩", "syllable_count": 2, "sentences": [{"text": "检查完毕，没有发现问题。", "target_word": "完毕", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "准备完毕，我们可以出发了。", "target_word": "完毕", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说：“收拾完毕，才可以回家。”", "target_word": "完毕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "打扫完毕后，他洗了手。", "target_word": "完毕", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "菜已经准备完毕，请大家入座。", "target_word": "完毕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "登记完毕后，请到旁边等一下。", "target_word": "完毕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房间已经整理完毕。", "target_word": "完毕", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工作完毕，大家都很高兴。", "target_word": "完毕", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "行李装箱完毕，我们就出发。", "target_word": "完毕", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他说：“我这边已经安装完毕。”", "target_word": "完毕", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "完畢", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "准备、检查、整理等工作全部做完", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cbe411f-991a-416c-a28b-6dca83adf8ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95205, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "完毕", "is_correct": true, "explanation": "“完毕”表示检查已经全部做完，与“没有发现问题”的检查结果相符。"}, {"text": "发现", "is_correct": false, "explanation": "语义：“发现”与后半句“没有发现问题”自相矛盾，检查中不可能既发现又没有发现。"}, {"text": "迟到", "is_correct": false, "explanation": "配价：“迟到”是不及物动词，不能作“检查”的结果成分，“检查迟到”不成立。"}, {"text": "开始", "is_correct": false, "explanation": "语义：“开始”说明检查刚开头，与“没有发现问题”这一已有结论不符。"}], "explanations": {"完毕": "“完毕”表示检查已经全部做完，与“没有发现问题”的检查结果相符。", "发现": "语义：“发现”与后半句“没有发现问题”自相矛盾，检查中不可能既发现又没有发现。", "迟到": "配价：“迟到”是不及物动词，不能作“检查”的结果成分，“检查迟到”不成立。", "开始": "语义：“开始”说明检查刚开头，与“没有发现问题”这一已有结论不符。"}, "sentence_index": 0, "correct_answer": "完毕"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "电梯突然完毕了。", "explanation": "这里应该用〈停止〉。“完毕”指事情按计划做完，不用于设备突然中断的情况。"}, {"text": "比赛因为下雨完毕了。", "explanation": "这里应该用〈中断〉。“完毕”指正常做完，被外力打断时要说“中断”。"}, {"text": "他的生命完毕了。", "explanation": "这里应该用〈结束〉。“完毕”多用于工作、活动等事务，不用于人的生命。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12927d7c-59d1-40f3-ad1f-89500df274f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95205, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "完毕", "is_correct": true, "explanation": "“完毕”表示房间已经收拾好，与“已经”的完成语气相合。"}, {"text": "出发", "is_correct": false, "explanation": "语义：“出发”表示动身离开，不能作“整理”的结果，句义不通。"}, {"text": "发生", "is_correct": false, "explanation": "配价：“发生”是不及物动词，“整理发生”不成立，不能作结果成分。"}, {"text": "停留", "is_correct": false, "explanation": "配价：“停留”不能接在“整理”之后作结果，且“房间停留”语义不通。"}], "explanations": {"完毕": "“完毕”表示房间已经收拾好，与“已经”的完成语气相合。", "出发": "语义：“出发”表示动身离开，不能作“整理”的结果，句义不通。", "发生": "配价：“发生”是不及物动词，“整理发生”不成立，不能作结果成分。", "停留": "配价：“停留”不能接在“整理”之后作结果，且“房间停留”语义不通。"}, "sentence_index": 6, "correct_answer": "完毕"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "客人们已经完毕了。", "explanation": "这里应该用〈离开〉。“完毕”只说事情做完，不说人离开。"}, {"text": "他的病已经完毕了。", "explanation": "这里应该用〈痊愈〉。“完毕”用于事务做完，不用于疾病好转。"}, {"text": "天已经完毕了。", "explanation": "这里应该用〈放晴〉。“完毕”用于事务做完，不用于天气变化。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12927d7c-59d1-40f3-ad1f-89500df274f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95205, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工作很完毕，大家可以回家了。", "corrected_sentence": "工作已经完毕，大家可以回家了。", "error_description": "错误：“很完毕”。正确：“已经完毕”。“完毕”表示动作做完的结果，不能用程度副词“很”修饰，应改用表示完成的“已经”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12927d7c-59d1-40f3-ad1f-89500df274f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95205, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我这边已经安装了完毕，您可以检查了。", "corrected_sentence": "我这边已经安装完毕，您可以检查了。", "error_description": "错误：“安装了完毕”。正确：“安装完毕”。“完毕”是结果补语，要紧接在动词“安装”之后，中间不能插入“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12927d7c-59d1-40f3-ad1f-89500df274f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
