INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95206, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "事情全部结束；完成。", "primary_collocate": null, "pronunciation": "wán bì", "ipa": "wan˧˥ pi˥˩", "syllable_count": 2, "sentences": [{"text": "比赛完毕，大家一起拍了照。", "target_word": "完毕", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "会议完毕后，同事们去吃饭。", "target_word": "完毕", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "演出完毕，观众热烈地鼓掌。", "target_word": "完毕", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "考试完毕，学生们走出教室。", "target_word": "完毕", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "手续办理完毕，您可以走了。", "target_word": "完毕", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "表演完毕，孩子们向大家鞠躬。", "target_word": "完毕", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "仪式完毕，客人们慢慢离开。", "target_word": "完毕", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "讨论完毕，大家开始写报告。", "target_word": "完毕", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "试验完毕，结果很好。", "target_word": "完毕", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "一切完毕，我们关灯回家吧。", "target_word": "完毕", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "完畢", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "比赛、会议、演出、仪式等活动全部结束", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cbe411f-991a-416c-a28b-6dca83adf8ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95206, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "完毕", "is_correct": true, "explanation": "“完毕”表示比赛已经结束，与后面大家一起拍照的情形相符。"}, {"text": "分开", "is_correct": false, "explanation": "语义：“分开”与“一起”相反，与“大家一起拍了照”矛盾。"}, {"text": "放弃", "is_correct": false, "explanation": "搭配：“放弃”须由参赛者作主语（如“他放弃了比赛”），不能以“比赛”作主语，“比赛放弃”不成立。"}, {"text": "投降", "is_correct": false, "explanation": "配价：“投降”只用于人或队伍作主语，不能用“比赛”作主语。"}], "explanations": {"完毕": "“完毕”表示比赛已经结束，与后面大家一起拍照的情形相符。", "分开": "语义：“分开”与“一起”相反，与“大家一起拍了照”矛盾。", "放弃": "搭配：“放弃”须由参赛者作主语（如“他放弃了比赛”），不能以“比赛”作主语，“比赛放弃”不成立。", "投降": "配价：“投降”只用于人或队伍作主语，不能用“比赛”作主语。"}, "sentence_index": 0, "correct_answer": "完毕"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的感冒已经完毕了。", "explanation": "这里应该用〈好了〉。“完毕”用于事务做完，不用于疾病好转。"}, {"text": "音乐节还没开始，就已经完毕了。", "explanation": "这里应该用〈取消〉。“完毕”指事情正常做完，活动还没开始就停掉要说“取消”。"}, {"text": "观众已经完毕了。", "explanation": "这里应该用〈离场〉。“完毕”表示事情做完，不用于说人离开。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12927d7c-59d1-40f3-ad1f-89500df274f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95206, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "完毕", "is_correct": true, "explanation": "“完毕”表示仪式已经结束，之后客人才会离开，与句意相合。"}, {"text": "开始", "is_correct": false, "explanation": "语义：仪式刚开始时客人不会离开，“开始”与后句“客人们慢慢离开”矛盾。"}, {"text": "出发", "is_correct": false, "explanation": "搭配：“出发”指人或车的移动，“仪式出发”搭配不当。"}, {"text": "准备", "is_correct": false, "explanation": "配价：“准备”指预先做安排，不能作“仪式”的结果成分，“仪式准备”不成立。"}], "explanations": {"完毕": "“完毕”表示仪式已经结束，之后客人才会离开，与句意相合。", "开始": "语义：仪式刚开始时客人不会离开，“开始”与后句“客人们慢慢离开”矛盾。", "出发": "搭配：“出发”指人或车的移动，“仪式出发”搭配不当。", "准备": "配价：“准备”指预先做安排，不能作“仪式”的结果成分，“仪式准备”不成立。"}, "sentence_index": 6, "correct_answer": "完毕"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他们的爱情已经完毕了。", "explanation": "这里应该用〈结束〉。“完毕”用于事务做完，不用于感情或关系的终止。"}, {"text": "孩子们都已经完毕了，不再需要父母照顾。", "explanation": "这里应该用〈长大〉。“完毕”用于事情、活动做完，不能用来说人长大成人。"}, {"text": "天已经完毕了。", "explanation": "这里应该用〈放晴〉。“完毕”用于事务做完，不用于天气变化。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12927d7c-59d1-40f3-ad1f-89500df274f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95206, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "演出很完毕，观众可以离场了。", "corrected_sentence": "演出已经完毕，观众可以离场了。", "error_description": "错误：“很完毕”。正确：“已经完毕”。“完毕”表示动作做完的结果，不能用程度副词“很”修饰，应改用“已经”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12927d7c-59d1-40f3-ad1f-89500df274f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95206, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们把场地收拾了完毕，就回家了。", "corrected_sentence": "我们把场地收拾完毕，就回家了。", "error_description": "错误：“收拾了完毕”。正确：“收拾完毕”。“完毕”是结果补语，要紧接在动词“收拾”之后，中间不能插入“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12927d7c-59d1-40f3-ad1f-89500df274f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
