INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95207, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "对别人说话很有礼貌，不随便。", "primary_collocate": null, "pronunciation": "kè qi", "ipa": "kʰɤ˥˩ tɕʰi", "syllable_count": 2, "sentences": [{"text": "他说话很客气。", "target_word": "客气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在电话里说得很客气。", "target_word": "客气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理对客人说话总是很客气。", "target_word": "客气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他客气地问我：“请问几点了？”", "target_word": "客气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的信写得很客气。", "target_word": "客气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板跟我们说话一点也不客气。", "target_word": "客气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对陌生人说话特别客气。", "target_word": "客气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他跟学生说话很客气，从不大声骂人。", "target_word": "客气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "服务员客气地说：“请坐。”", "target_word": "客气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的回答很客气，没有生气。", "target_word": "客气", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "客客气气", "label": "重叠"}, {"form": "客气地", "label": "状语形式"}], "register": "口语", "sense_fingerprint": "说话有礼貌，不随便", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc8986b3-b2f6-4123-8222-d26c9cd9393b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95207, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "客气", "is_correct": true, "explanation": "正确：“客气”形容说话有礼貌、不随便，符合句意。"}, {"text": "新鲜", "is_correct": false, "explanation": "语义：“新鲜”形容食物、空气等，不能形容说话的态度。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：“高大”形容人的身材，不能修饰“说话”。"}, {"text": "矮小", "is_correct": false, "explanation": "体貌：“矮小”形容身材或物体的大小，不能修饰“说话”。"}], "explanations": {"客气": "正确：“客气”形容说话有礼貌、不随便，符合句意。", "新鲜": "语义：“新鲜”形容食物、空气等，不能形容说话的态度。", "高大": "体貌：“高大”形容人的身材，不能修饰“说话”。", "矮小": "体貌：“矮小”形容身材或物体的大小，不能修饰“说话”。"}, "sentence_index": 0, "correct_answer": "客气"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他说话很客气，常常骂人。", "explanation": "这里不能用〈客气〉。“客气”指对人有礼貌，与“常常骂人”矛盾，这里应该说〈粗鲁〉。"}, {"text": "他很客气，一进门就把门口的鞋踢到了一边。", "explanation": "这里不能用〈客气〉。“客气”指有礼貌，与“踢鞋”矛盾，这里应该说〈无礼〉。"}, {"text": "他对新同事很客气，从不打招呼。", "explanation": "这里不能用〈客气〉。“客气”指有礼貌地待人，不会“从不打招呼”，这里应该说〈冷淡〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b0d75e0-6e6b-44b8-a337-cd25b194b54f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95207, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "客气", "is_correct": true, "explanation": "正确：“客气”形容对陌生人说话有礼貌，符合句意。"}, {"text": "年轻", "is_correct": false, "explanation": "语义：“年轻”说的是年龄，不能用来形容说话的态度。"}, {"text": "满意", "is_correct": false, "explanation": "配价：“满意”要说明对什么满意，不能直接修饰“说话”的态度。"}, {"text": "辉煌", "is_correct": false, "explanation": "语义：“辉煌”形容成就或场面，与说话的态度不搭。"}], "explanations": {"客气": "正确：“客气”形容对陌生人说话有礼貌，符合句意。", "年轻": "语义：“年轻”说的是年龄，不能用来形容说话的态度。", "满意": "配价：“满意”要说明对什么满意，不能直接修饰“说话”的态度。", "辉煌": "语义：“辉煌”形容成就或场面，与说话的态度不搭。"}, "sentence_index": 6, "correct_answer": "客气"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这只狗很客气，见了人就咬。", "explanation": "这里不能用〈客气〉。“客气”形容人的言行有礼貌，不用于描述狗的行为，这里应该说〈凶〉。"}, {"text": "这把椅子坐起来很客气。", "explanation": "这里不能用〈客气〉。“客气”只用于人的言行，椅子没有言行，这里应该说〈舒服〉。"}, {"text": "这块饼干吃起来很客气。", "explanation": "这里不能用〈客气〉。“客气”只用于人的言行，饼干没有言行，这里应该说〈酥脆〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b0d75e0-6e6b-44b8-a337-cd25b194b54f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95207, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他说话地客气，让人觉得舒服。", "corrected_sentence": "他说话很客气，让人觉得舒服。", "error_description": "“地”用错：“说话地客气”应改为“说话很客气”。“客气”前应用程度副词“很”，“地”不能放在“说话”后面修饰“客气”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b0d75e0-6e6b-44b8-a337-cd25b194b54f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95207, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他对陌生人说话很客气地，让人觉得舒服。", "corrected_sentence": "他对陌生人说话很客气，让人觉得舒服。", "error_description": "错误：“客气地，”。正确：“很客气，”。“客气”后面直接接逗号，这里多加的“地”是多余的。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b0d75e0-6e6b-44b8-a337-cd25b194b54f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
