INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95208, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "对人有礼貌，言行谦让。", "primary_collocate": null, "pronunciation": "kè qi", "ipa": "kʰɤ˥˩ tɕʰi", "syllable_count": 2, "sentences": [{"text": "朋友之间不用太客气。", "target_word": "客气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他很客气，总是让我先走。", "target_word": "客气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你太客气了，不用送我。", "target_word": "客气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "邻居对我们很客气。", "target_word": "客气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她吃饭时很客气，不好意思夹菜。", "target_word": "客气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对老人特别客气，总是让座。", "target_word": "客气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们是老朋友，别客气。", "target_word": "客气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她客气地把好座位让给了客人。", "target_word": "客气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吃饭时，他客气得不好意思多吃。", "target_word": "客气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新同事都很客气，大家相处得好。", "target_word": "客气", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "客客气气", "label": "重叠"}, {"form": "客气地", "label": "状语形式"}], "register": "口语", "sense_fingerprint": "待人有礼，言行谦让", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc8986b3-b2f6-4123-8222-d26c9cd9393b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95208, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "客气", "is_correct": true, "explanation": "正确：“客气”形容待人有礼、言行谦让，符合句意。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：“高大”形容人的身材，不能用在“不用太”后面说待人的态度。"}, {"text": "矮小", "is_correct": false, "explanation": "体貌：“矮小”形容身材或物体的大小，不能说明朋友之间的相处态度。"}, {"text": "便宜", "is_correct": false, "explanation": "语义：“便宜”形容价格低，不能说明朋友之间的相处态度。"}], "explanations": {"客气": "正确：“客气”形容待人有礼、言行谦让，符合句意。", "高大": "体貌：“高大”形容人的身材，不能用在“不用太”后面说待人的态度。", "矮小": "体貌：“矮小”形容身材或物体的大小，不能说明朋友之间的相处态度。", "便宜": "语义：“便宜”形容价格低，不能说明朋友之间的相处态度。"}, "sentence_index": 0, "correct_answer": "客气"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "邻居对我们很客气，半夜大声骂人。", "explanation": "这里不能用〈客气〉。“客气”指待人有礼，与“半夜大声骂人”矛盾，这里应该说〈凶悍〉。"}, {"text": "邻居对我们很客气，常常抢我们的东西。", "explanation": "这里不能用〈客气〉。“客气”指待人有礼，与“抢东西”矛盾，这里应该说〈蛮横〉。"}, {"text": "他第一次上台讲话，很客气，突然把稿子扔到了台下。", "explanation": "这里不能用〈客气〉。“客气”指待人有礼、言行谦让，与“把稿子扔到台下”矛盾，这里应该说〈失态〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b0d75e0-6e6b-44b8-a337-cd25b194b54f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95208, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "客气", "is_correct": true, "explanation": "正确：“客气”表示朋友之间不必见外、不必推让，符合句意。"}, {"text": "陌生", "is_correct": false, "explanation": "语义：“陌生”表示彼此不熟，与“老朋友”的语境矛盾。"}, {"text": "满意", "is_correct": false, "explanation": "配价：“满意”要说明对什么满意，不能直接用在“别”后面。"}, {"text": "富有", "is_correct": false, "explanation": "语义：“富有”形容财产或才能，与“老朋友”和“别”的语境不搭。"}], "explanations": {"客气": "正确：“客气”表示朋友之间不必见外、不必推让，符合句意。", "陌生": "语义：“陌生”表示彼此不熟，与“老朋友”的语境矛盾。", "满意": "配价：“满意”要说明对什么满意，不能直接用在“别”后面。", "富有": "语义：“富有”形容财产或才能，与“老朋友”和“别”的语境不搭。"}, "sentence_index": 6, "correct_answer": "客气"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他很客气，把碗里的菜全抢走了。", "explanation": "这里不能用〈客气〉。“客气”指待人有礼、谦让，与“把菜全抢走”矛盾，这里应该说〈贪婪〉。"}, {"text": "这碗汤很客气，喝起来不烫嘴。", "explanation": "这里不能用〈客气〉。“客气”只用于人的言行，汤没有言行，这里应该说〈温〉。"}, {"text": "这台电脑很客气，每天都提醒我保存文件。", "explanation": "这里不能用〈客气〉。“客气”指人待人有礼，电脑不能有礼貌地待人，这里应该说〈贴心〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b0d75e0-6e6b-44b8-a337-cd25b194b54f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95208, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她对我们很客气地，每次都先说谢谢。", "corrected_sentence": "她对我们很客气，每次都先说谢谢。", "error_description": "错误：“很客气地，”。正确：“很客气，”。“客气”作谓语，后面接逗号时不加“地”；“地”只用于修饰动词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b0d75e0-6e6b-44b8-a337-cd25b194b54f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95208, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "新同事都很客气地，见面就打招呼。", "corrected_sentence": "新同事都很客气，见面就打招呼。", "error_description": "错误：“客气地，”。正确：“很客气，”。“客气”后面直接接逗号，这里多加的“地”是多余的。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b0d75e0-6e6b-44b8-a337-cd25b194b54f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
