INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95209, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "只看着一件事，不想别的事。", "primary_collocate": null, "pronunciation": "zhuān zhù", "ipa": "ʈʂwan˥ ʈʂu˥˩", "syllable_count": 2, "sentences": [{"text": "小猫专注地看着窗外的鸟。", "target_word": "专注", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他专注地看着手里的书。", "target_word": "专注", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子专注地看着电视，一动不动。", "target_word": "专注", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的眼神很专注，只看着我。", "target_word": "专注", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他看着地图，神情很专注。", "target_word": "专注", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人专注地看着棋盘。", "target_word": "专注", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "男孩专注地盯着那只蚂蚁。", "target_word": "专注", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她专注地看着他，什么也没说。", "target_word": "专注", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那只狗专注地看着主人手里的肉。", "target_word": "专注", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们专注地看着老师做实验。", "target_word": "专注", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "专注地", "label": "状语形式"}, {"form": "专注力", "label": "复合"}], "register": "中性", "sense_fingerprint": "目光只放在一件事上", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc8986b3-b2f6-4123-8222-d26c9cd9393b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95209, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "专注", "is_correct": true, "explanation": "正确：“专注地”形容小猫目光只放在窗外的鸟上，符合句意。"}, {"text": "热闹", "is_correct": false, "explanation": "搭配：“热闹”形容场面或气氛，不能用来形容看的样子。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：“高大”形容人或物的身材，不能修饰“看着”的样子。"}, {"text": "富有", "is_correct": false, "explanation": "语义：“富有”形容财产或才能，与“看着窗外的鸟”的语境不搭。"}], "explanations": {"专注": "正确：“专注地”形容小猫目光只放在窗外的鸟上，符合句意。", "热闹": "搭配：“热闹”形容场面或气氛，不能用来形容看的样子。", "高大": "体貌：“高大”形容人或物的身材，不能修饰“看着”的样子。", "富有": "语义：“富有”形容财产或才能，与“看着窗外的鸟”的语境不搭。"}, "sentence_index": 0, "correct_answer": "专注"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她的眼神很专注，到处乱瞟。", "explanation": "这里不能用〈专注〉。“专注”表示目光只放在一件事上，与“到处乱瞟”矛盾，这里应该说〈游移〉。"}, {"text": "他的眼神很专注，一直左看右看。", "explanation": "这里不能用〈专注〉。“专注”表示目光只放在一件事上，与“一直左看右看”矛盾，这里应该说〈飘忽〉。"}, {"text": "孩子的眼神很专注，一会儿看天，一会儿看地。", "explanation": "这里不能用〈专注〉。“专注”表示目光只放在一件事上，与“一会儿看天，一会儿看地”矛盾，这里应该说〈飘忽〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b0d75e0-6e6b-44b8-a337-cd25b194b54f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95209, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "专注", "is_correct": true, "explanation": "正确：“专注地”形容男孩目光只放在蚂蚁上，符合句意。"}, {"text": "辉煌", "is_correct": false, "explanation": "语义：“辉煌”形容成就或场面，不能修饰“盯着”的样子。"}, {"text": "嘈杂", "is_correct": false, "explanation": "语义：“嘈杂”形容声音杂乱，不能修饰“盯着”的样子。"}, {"text": "冷清", "is_correct": false, "explanation": "语义：“冷清”形容场所冷落，不能修饰“盯着”的样子。"}], "explanations": {"专注": "正确：“专注地”形容男孩目光只放在蚂蚁上，符合句意。", "辉煌": "语义：“辉煌”形容成就或场面，不能修饰“盯着”的样子。", "嘈杂": "语义：“嘈杂”形容声音杂乱，不能修饰“盯着”的样子。", "冷清": "语义：“冷清”形容场所冷落，不能修饰“盯着”的样子。"}, "sentence_index": 6, "correct_answer": "专注"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这片树叶专注地飘落在地上。", "explanation": "这里不能用〈专注〉。“专注”描述人的注意力，树叶没有注意力，这里应该说〈慢慢〉。"}, {"text": "这个灯泡专注地发光。", "explanation": "这里不能用〈专注〉。“专注”只用于人的注意力，灯泡没有注意力，这里应该说〈稳定〉。"}, {"text": "这辆车专注地开着。", "explanation": "这里不能用〈专注〉。“专注”只用于人的注意力，车没有注意力，这里应该说〈平稳〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b0d75e0-6e6b-44b8-a337-cd25b194b54f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95209, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "猫专注的盯着鱼缸，一动不动。", "corrected_sentence": "猫专注地盯着鱼缸，一动不动。", "error_description": "错误：“专注的盯着”。正确：“专注地盯着”。“专注”修饰动词“盯”，作状语要用“地”，不用“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b0d75e0-6e6b-44b8-a337-cd25b194b54f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95209, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "孩子们专注的看着老师做实验，没有说话。", "corrected_sentence": "孩子们专注地看着老师做实验，没有说话。", "error_description": "错误：“专注的看着”。正确：“专注地看着”。“专注”修饰动词“看”，作状语要用“地”，不用“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b0d75e0-6e6b-44b8-a337-cd25b194b54f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
