INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95210, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "注意力集中，专心致志。", "primary_collocate": null, "pronunciation": "zhuān zhù", "ipa": "ʈʂwan˥ ʈʂu˥˩", "syllable_count": 2, "sentences": [{"text": "他学习的时候很专注。", "target_word": "专注", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子画画时非常专注。", "target_word": "专注", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她专注地听老师讲课。", "target_word": "专注", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他工作很专注，没有听见电话响。", "target_word": "专注", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上课要专注，不能玩手机。", "target_word": "专注", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位医生做事特别专注。", "target_word": "专注", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他专注的样子让我很感动。", "target_word": "专注", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "运动员比赛时必须很专注。", "target_word": "专注", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他读书时专注得忘了吃饭。", "target_word": "专注", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她专注地写着作业，没有抬头。", "target_word": "专注", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "专注地", "label": "状语形式"}, {"form": "专注力", "label": "复合"}], "register": "中性", "sense_fingerprint": "做事时注意力集中", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc8986b3-b2f6-4123-8222-d26c9cd9393b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95210, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "专注", "is_correct": true, "explanation": "正确：“专注”形容学习时注意力集中，符合句意。"}, {"text": "辉煌", "is_correct": false, "explanation": "语义：“辉煌”形容成就或场面，不能形容学习时的状态。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：“高大”形容人的身材，不能形容学习时的状态。"}, {"text": "矮小", "is_correct": false, "explanation": "体貌：“矮小”形容身材或物体的大小，不能形容学习时的状态。"}], "explanations": {"专注": "正确：“专注”形容学习时注意力集中，符合句意。", "辉煌": "语义：“辉煌”形容成就或场面，不能形容学习时的状态。", "高大": "体貌：“高大”形容人的身材，不能形容学习时的状态。", "矮小": "体貌：“矮小”形容身材或物体的大小，不能形容学习时的状态。"}, "sentence_index": 0, "correct_answer": "专注"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他专注地走神，一句话也没听进去。", "explanation": "这里不能用〈专注〉。“专注”表示注意力集中，与“走神”矛盾，这里应该说〈分心〉。"}, {"text": "他的眼睛到处乱看，专注地东张西望。", "explanation": "这里不能用〈专注〉。“专注”表示注意力集中，与“东张西望”矛盾，这里应该说〈散漫〉。"}, {"text": "学生专注地打哈欠，昏昏欲睡。", "explanation": "这里不能用〈专注〉。“专注”表示注意力集中，与“昏昏欲睡”矛盾，这里应该说〈困倦〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b0d75e0-6e6b-44b8-a337-cd25b194b54f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95210, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "专注", "is_correct": true, "explanation": "正确：“专注”形容人做事时注意力集中，符合句意。"}, {"text": "冷清", "is_correct": false, "explanation": "语义：“冷清”形容场所冷落，不能形容人的样子。"}, {"text": "辉煌", "is_correct": false, "explanation": "语义：“辉煌”形容成就或场面，不能形容人的样子。"}, {"text": "嘈杂", "is_correct": false, "explanation": "语义：“嘈杂”形容声音杂乱，不能形容人的样子。"}], "explanations": {"专注": "正确：“专注”形容人做事时注意力集中，符合句意。", "冷清": "语义：“冷清”形容场所冷落，不能形容人的样子。", "辉煌": "语义：“辉煌”形容成就或场面，不能形容人的样子。", "嘈杂": "语义：“嘈杂”形容声音杂乱，不能形容人的样子。"}, "sentence_index": 6, "correct_answer": "专注"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这张桌子专注地站在墙角。", "explanation": "这里不能用〈专注〉。“专注”描述人的注意力，桌子没有注意力，这里应该说〈稳稳〉。"}, {"text": "这盏灯专注地亮着。", "explanation": "这里不能用〈专注〉。“专注”只用于人的注意力，灯没有注意力，这里应该说〈一直〉。"}, {"text": "这株植物专注地向上长。", "explanation": "这里不能用〈专注〉。“专注”只用于人的注意力，植物没有注意力，这里应该说〈慢慢〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b0d75e0-6e6b-44b8-a337-cd25b194b54f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95210, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妹妹看书时很专注地，连饭也不吃。", "corrected_sentence": "妹妹看书时很专注，连饭也不吃。", "error_description": "错误：“很专注地，”。正确：“很专注，”。“专注”作谓语，后面接逗号时不加“地”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b0d75e0-6e6b-44b8-a337-cd25b194b54f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95210, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "哥哥专注的写着作业，没有抬头。", "corrected_sentence": "哥哥专注地写着作业，没有抬头。", "error_description": "错误：“专注的写着”。正确：“专注地写着”。“专注”修饰动词“写”，作状语要用“地”，不用“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b0d75e0-6e6b-44b8-a337-cd25b194b54f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
