INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95211, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "性情温柔、喜欢做家里小事的女子。", "primary_collocate": null, "pronunciation": "xiǎo nǚ rén", "ipa": "ɕiau²¹⁴ ny²¹⁴ ʐən³⁵", "syllable_count": 3, "sentences": [{"text": "她是个温柔的小女人，每天都在家做饭。", "target_word": "小女人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他喜欢小女人，因为她们爱照顾家。", "target_word": "小女人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我妹妹不是小女人，她喜欢工作。", "target_word": "小女人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她嫁人以后，变成了一个爱做家务的小女人。", "target_word": "小女人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小女人每天给丈夫准备早饭。", "target_word": "小女人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想找一个爱家的小女人。", "target_word": "小女人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在家里，她是个喜欢操持家务的小女人。", "target_word": "小女人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多男人觉得小女人很可爱。", "target_word": "小女人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她看起来像个小女人，其实工作很能干。", "target_word": "小女人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位小女人正在厨房里给孩子做饭。", "target_word": "小女人", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}], "register": "口语", "sense_fingerprint": "温柔、爱做家里小事的女子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'db3644ad-b860-49ef-adcd-01357c77d0ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95211, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "小女人", "is_correct": true, "explanation": "正确。“小女人”指喜欢温柔、爱做家务的女子，与“温柔”和“在家做饭”相符。"}, {"text": "女强人", "is_correct": false, "explanation": "语义：“女强人”指事业型、独立能干的女性，与“每天都在家做饭”的日常形象相冲突。"}, {"text": "男子汉", "is_correct": false, "explanation": "语义：“男子汉”指男性，与前面的“她”不一致。"}, {"text": "铅笔", "is_correct": false, "explanation": "语义：“铅笔”是文具，不能指人，与“温柔的”搭配不成立。"}], "explanations": {"小女人": "正确。“小女人”指喜欢温柔、爱做家务的女子，与“温柔”和“在家做饭”相符。", "女强人": "语义：“女强人”指事业型、独立能干的女性，与“每天都在家做饭”的日常形象相冲突。", "男子汉": "语义：“男子汉”指男性，与前面的“她”不一致。", "铅笔": "语义：“铅笔”是文具，不能指人，与“温柔的”搭配不成立。"}, "sentence_index": 0, "correct_answer": "小女人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她辞职以后，当了一名小女人。", "explanation": "这里应该用〈家庭主妇〉。〈小女人〉描述性情，不能用来指身份或职业。"}, {"text": "她是个雷厉风行的小女人，手下几百号人都怕她。", "explanation": "这里应该用〈女强人〉。〈小女人〉指性情温柔、爱做家务的女子，不指雷厉风行、有魄力的女性。"}, {"text": "她是全校最受崇拜的小女人，大家都追捧她。", "explanation": "这里应该用〈女神〉。〈小女人〉指温柔顾家的女子，不指备受追捧的偶像。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0951cffc-c221-4855-94ff-5e8df6e4b522') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95211, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "小女人", "is_correct": true, "explanation": "正确。“小女人”指爱做家务、以家庭为重的女子，与“操持家务”相符。"}, {"text": "客人", "is_correct": false, "explanation": "语义：“客人”指到访的人，与“在家里操持家务”相冲突。"}, {"text": "石头", "is_correct": false, "explanation": "语义：“石头”是无生命的物体，不能“操持家务”。"}, {"text": "雨伞", "is_correct": false, "explanation": "语义：“雨伞”是物品，不能“操持家务”。"}], "explanations": {"小女人": "正确。“小女人”指爱做家务、以家庭为重的女子，与“操持家务”相符。", "客人": "语义：“客人”指到访的人，与“在家里操持家务”相冲突。", "石头": "语义：“石头”是无生命的物体，不能“操持家务”。", "雨伞": "语义：“雨伞”是物品，不能“操持家务”。"}, "sentence_index": 6, "correct_answer": "小女人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "那位小女人在谈判桌上寸步不让，把对方逼得没了退路。", "explanation": "〈小女人〉指温柔顾家的性情，不能用来形容在谈判中寸步不让、咄咄逼人的人。"}, {"text": "那位小女人在台上大声训斥下属，满脸怒气。", "explanation": "〈小女人〉指温柔顾家的性情，不用于形容大声训斥下属、满脸怒气的人。"}, {"text": "那位小女人在舞台上放声唱歌，声音低沉有力。", "explanation": "这里应该用〈男低音〉。〈小女人〉指温柔的女子，不用于描述声音低沉的男性声部。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0951cffc-c221-4855-94ff-5e8df6e4b522') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95211, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她是一只勤快的小女人，家里总是很干净。", "corrected_sentence": "她是一个勤快的小女人，家里总是很干净。", "error_description": "量词错误：“小女人”指人，应用量词〈个〉，不能用〈只〉（〈只〉用于动物等）。正确说法是“一个勤快的小女人”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0951cffc-c221-4855-94ff-5e8df6e4b522') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95211, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈是个勤快地小女人，大家都很喜欢她。", "corrected_sentence": "妈妈是个勤快的小女人，大家都很喜欢她。", "error_description": "结构错误：修饰名词时应用“的”，不用“地”（“地”修饰动词）。正确说法是“勤快的小女人”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0951cffc-c221-4855-94ff-5e8df6e4b522') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
