INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95212, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指性情温柔、注重家庭生活的女子。", "primary_collocate": null, "pronunciation": "xiǎo nǚ rén", "ipa": "ɕiau²¹⁴ ny²¹⁴ ʐən³⁵", "syllable_count": 3, "sentences": [{"text": "她是个小女人，最大的愿望就是有个温暖的家。", "target_word": "小女人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小女人喜欢把家里收拾得干干净净。", "target_word": "小女人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不喜欢女强人，喜欢温柔的小女人。", "target_word": "小女人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她以前工作很忙，现在成了小女人，天天在家。", "target_word": "小女人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做个小女人，也是一种幸福。", "target_word": "小女人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位小女人每天等丈夫回家吃饭。", "target_word": "小女人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小女人最关心的是孩子和家人。", "target_word": "小女人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在朋友眼里，她是个很温柔的小女人。", "target_word": "小女人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他笑着说，我太太是个小女人。", "target_word": "小女人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小女人也可以有自己的工作。", "target_word": "小女人", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}], "register": "口语", "sense_fingerprint": "性情温柔、注重家庭生活的女子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'db3644ad-b860-49ef-adcd-01357c77d0ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95212, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "小女人", "is_correct": true, "explanation": "正确。“小女人”指性情温柔、注重家庭的女子，与“有个温暖的家”的愿望相符。"}, {"text": "客人", "is_correct": false, "explanation": "语义：“客人”指到访的人，与“有个温暖的家”这种长期愿望不相符。"}, {"text": "男子汉", "is_correct": false, "explanation": "语义：“男子汉”指男性，与前面的“她”不一致。"}, {"text": "铅笔", "is_correct": false, "explanation": "语义：“铅笔”是文具，不能用来指“她”这样的人。"}], "explanations": {"小女人": "正确。“小女人”指性情温柔、注重家庭的女子，与“有个温暖的家”的愿望相符。", "客人": "语义：“客人”指到访的人，与“有个温暖的家”这种长期愿望不相符。", "男子汉": "语义：“男子汉”指男性，与前面的“她”不一致。", "铅笔": "语义：“铅笔”是文具，不能用来指“她”这样的人。"}, "sentence_index": 0, "correct_answer": "小女人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她是个做事果断的小女人，独自打理着一家公司。", "explanation": "这里应该用〈女强人〉。〈小女人〉指性情温柔、注重家庭的女子，不指做事果断、事业有成的女性。"}, {"text": "她是大学里的一名小女人，每天都去图书馆。", "explanation": "这里应该用〈女学生〉。〈小女人〉指注重家庭生活的成年女子，不用于指在校学生。"}, {"text": "她是个力气很大的小女人，一个人能扛起整袋大米。", "explanation": "这里应该用〈女汉子〉。〈小女人〉指温柔、注重家庭的女子，不指力气大、性格刚强的女性。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0951cffc-c221-4855-94ff-5e8df6e4b522') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95212, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "小女人", "is_correct": true, "explanation": "正确。“小女人”指以家庭为重的女子，与“最关心的是孩子和家人”相符。"}, {"text": "石头", "is_correct": false, "explanation": "语义：“石头”是无生命的物体，不能“最关心”孩子和家人。"}, {"text": "花瓶", "is_correct": false, "explanation": "语义：“花瓶”不具备关心他人的能力，与句意不符。"}, {"text": "电脑", "is_correct": false, "explanation": "语义：“电脑”是无生命的物体，不能“最关心”孩子和家人。"}], "explanations": {"小女人": "正确。“小女人”指以家庭为重的女子，与“最关心的是孩子和家人”相符。", "石头": "语义：“石头”是无生命的物体，不能“最关心”孩子和家人。", "花瓶": "语义：“花瓶”不具备关心他人的能力，与句意不符。", "电脑": "语义：“电脑”是无生命的物体，不能“最关心”孩子和家人。"}, "sentence_index": 6, "correct_answer": "小女人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "那位小女人在股东大会上据理力争，把对手驳得哑口无言。", "explanation": "〈小女人〉指温柔、注重家庭的性情，不用于形容在股东大会上据理力争、咄咄逼人的人。"}, {"text": "那位小女人一拳就把木门砸开了，力气很大。", "explanation": "〈小女人〉指温柔的性情，不用于形容力气大、一拳砸开木门的人。"}, {"text": "那位小女人是国家队的主力前锋，常常一个人攻破对方的球门。", "explanation": "〈小女人〉指温柔、注重家庭的女子，不用于描述在赛场上攻门的运动员。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0951cffc-c221-4855-94ff-5e8df6e4b522') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95212, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她是一只注重家庭的小女人，每天都在家做饭。", "corrected_sentence": "她是一个注重家庭的小女人，每天都在家做饭。", "error_description": "量词错误：“小女人”指人，应用量词〈个〉，不能用〈只〉。正确说法是“一个注重家庭的小女人”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0951cffc-c221-4855-94ff-5e8df6e4b522') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95212, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "姐姐是个温柔地小女人，家里人都很依赖她。", "corrected_sentence": "姐姐是个温柔的小女人，家里人都很依赖她。", "error_description": "结构错误：修饰名词时应用“的”，不用“地”（“地”修饰动词）。正确说法是“温柔的小女人”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0951cffc-c221-4855-94ff-5e8df6e4b522') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
