INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95213, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "几个人只为自己好，凑成一小群。", "primary_collocate": null, "pronunciation": "xiǎo jí tuán", "ipa": "ɕjɑʊ tɕi tʰwan", "syllable_count": 3, "sentences": [{"text": "班里有几个人凑成小集团，不理别人。", "target_word": "小集团", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们几个总在一起，像个小集团。", "target_word": "小集团", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她不喜欢这种只顾自己的小集团。", "target_word": "小集团", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那几个同学成了一个小集团。", "target_word": "小集团", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们说，他们是班里的小集团。", "target_word": "小集团", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "食堂里，几个小集团各坐一桌。", "target_word": "小集团", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们不要搞小集团，要和大家一起玩。", "target_word": "小集团", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个小集团不让新同学加入。", "target_word": "小集团", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们三个人成天在一起，是个小集团。", "target_word": "小集团", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小集团的人只关心自己。", "target_word": "小集团", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "几个人只顾自己，凑成的一小群", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3fe24b8-ed9b-4c4c-b194-80ca274be0f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95213, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "小集团", "is_correct": true, "explanation": "正确。小集团指几个人只顾自己凑成的一小群，与“凑成”和“不理别人”相符。"}, {"text": "积木", "is_correct": false, "explanation": "语义：积木是玩具，几个人凑成积木还“不理别人”，意思说不通。"}, {"text": "花瓶", "is_correct": false, "explanation": "语义：花瓶是器物，不会“不理别人”，也不能被几个人凑成。"}, {"text": "云朵", "is_correct": false, "explanation": "搭配：“几个人”不能凑成云朵，“凑成”不能与“云朵”搭配。"}], "explanations": {"小集团": "正确。小集团指几个人只顾自己凑成的一小群，与“凑成”和“不理别人”相符。", "积木": "语义：积木是玩具，几个人凑成积木还“不理别人”，意思说不通。", "花瓶": "语义：花瓶是器物，不会“不理别人”，也不能被几个人凑成。", "云朵": "搭配：“几个人”不能凑成云朵，“凑成”不能与“云朵”搭配。"}, "sentence_index": 0, "correct_answer": "小集团"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "那几个同学组成了一个小集团，每周一起复习，还主动给班里的同学讲题。", "explanation": "这里应该用〈小组〉。小集团指只顾自己、凑成的一小群，与“主动给同学讲题”的利他行为相矛盾。"}, {"text": "那个小集团在野外露营，大家互相照顾，很开心。", "explanation": "这里应该用〈小队〉。小集团只为自己好，含贬义，与“大家互相照顾”的意思相反。"}, {"text": "这个小集团在比赛中为集体争荣誉，赢得了冠军。", "explanation": "这里应该用〈队伍〉。小集团只顾自己，与“为集体争荣誉”相矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '552e5b7a-b4eb-4b55-be64-712c72ccd081') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95213, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "小集团", "is_correct": true, "explanation": "正确。小集团指只顾自己凑成的一小群，与“不要搞”和“要和大家一起玩”的对立相符。"}, {"text": "黑板", "is_correct": false, "explanation": "搭配：“搞”不能接“黑板”，句子不成立。"}, {"text": "爆炸", "is_correct": false, "explanation": "语义：爆炸会伤害人，与“要和大家一起玩”的意思相反。"}, {"text": "大火", "is_correct": false, "explanation": "搭配：“搞”后不接“大火”，应说“放火”，而且与“一起玩”冲突。"}], "explanations": {"小集团": "正确。小集团指只顾自己凑成的一小群，与“不要搞”和“要和大家一起玩”的对立相符。", "黑板": "搭配：“搞”不能接“黑板”，句子不成立。", "爆炸": "语义：爆炸会伤害人，与“要和大家一起玩”的意思相反。", "大火": "搭配：“搞”后不接“大火”，应说“放火”，而且与“一起玩”冲突。"}, "sentence_index": 6, "correct_answer": "小集团"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个小集团的人互相关心，一起帮助有困难的同学。", "explanation": "这里应该用〈班级〉。小集团的人只关心自己，与“一起帮助有困难的同学”相矛盾。"}, {"text": "这个小集团的志愿者每天为老人服务，大家都很喜欢他们。", "explanation": "这里应该用〈志愿服务队〉。小集团只关心自己，含贬义，与“每天为老人服务”的志愿者不符。"}, {"text": "这个小集团的成员都很关心彼此，一起做饭。", "explanation": "这里应该用〈家庭〉。小集团只关心自己，与“关心彼此”相矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '552e5b7a-b4eb-4b55-be64-712c72ccd081') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95213, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "几个同学组成了两只小集团，互不理睬。", "corrected_sentence": "几个同学组成了两个小集团，互不理睬。", "error_description": "量词错误：小集团指一群人，量词应用“个”，不能用“只”。应改为“两个小集团”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '552e5b7a-b4eb-4b55-be64-712c72ccd081') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95213, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那个班里有三只小集团，谁也不理谁。", "corrected_sentence": "那个班里有三个小集团，谁也不理谁。", "error_description": "量词错误：小集团指一群人，量词应用“个”，不能用“只”。应改为“三个小集团”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '552e5b7a-b4eb-4b55-be64-712c72ccd081') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
