INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95214, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "为谋取私利而结成的小团体。", "primary_collocate": null, "pronunciation": "xiǎo jí tuán", "ipa": "ɕjɑʊ tɕi tʰwan", "syllable_count": 3, "sentences": [{"text": "公司里有个小集团，只想为自己争好处。", "target_word": "小集团", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理发现几个人搞小集团，就找他们谈话。", "target_word": "小集团", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在这家公司里，小集团让别人没有机会。", "target_word": "小集团", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不愿加入任何小集团。", "target_word": "小集团", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板说，公司里不能有小集团。", "target_word": "小集团", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小集团为了赚钱，骗了很多人。", "target_word": "小集团", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们结成小集团，只管自己的利益。", "target_word": "小集团", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司的小集团把好处都拿走了。", "target_word": "小集团", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小集团里的人互相帮忙，却不管别人。", "target_word": "小集团", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "校长决定打破这个小集团。", "target_word": "小集团", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "为谋取私利而结成的小团体", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3fe24b8-ed9b-4c4c-b194-80ca274be0f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95214, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "小集团", "is_correct": true, "explanation": "正确。小集团指为谋取私利结成的小团体，与“只想为自己争好处”相符。"}, {"text": "小费", "is_correct": false, "explanation": "语义：小费是给服务人员的钱，不能“只想为自己争好处”。"}, {"text": "小镇", "is_correct": false, "explanation": "语义：小镇是地方，与“公司里”冲突，也不会想为自己争好处。"}, {"text": "小区", "is_correct": false, "explanation": "搭配：“公司里”后接“小区”不通，小区是居民居住的地方。"}], "explanations": {"小集团": "正确。小集团指为谋取私利结成的小团体，与“只想为自己争好处”相符。", "小费": "语义：小费是给服务人员的钱，不能“只想为自己争好处”。", "小镇": "语义：小镇是地方，与“公司里”冲突，也不会想为自己争好处。", "小区": "搭配：“公司里”后接“小区”不通，小区是居民居住的地方。"}, "sentence_index": 0, "correct_answer": "小集团"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们小集团这次为班级捐了很多书，大家都很感动。", "explanation": "这里应该用〈团队〉。小集团指为谋取私利结成的团体，与“为班级捐书”的利他行为相矛盾。"}, {"text": "学校的小集团每周都组织活动，免费教大家画画，不收任何费用。", "explanation": "这里应该用〈社团〉。小集团指为谋取私利结成的团体，“免费教大家、不收费用”与之相矛盾。"}, {"text": "研究所的小集团把自己的研究成果无偿分享给大家，大家都很敬佩他们。", "explanation": "这里应该用〈课题组〉。小集团指为谋取私利结成的团体，“无偿分享”与之相矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '552e5b7a-b4eb-4b55-be64-712c72ccd081') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95214, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "小集团", "is_correct": true, "explanation": "正确。小集团指只管自己利益的小团体，与“结成”及“只管自己的利益”相符。"}, {"text": "冰", "is_correct": false, "explanation": "语义：冰是水凝结的固体，不能“只管自己的利益”。"}, {"text": "友谊", "is_correct": false, "explanation": "语义：友谊讲互助和信任，与“只管自己的利益”的意思相反。"}, {"text": "果实", "is_correct": false, "explanation": "搭配：果实没有利益可言，“只管自己的利益”不能用于果实。"}], "explanations": {"小集团": "正确。小集团指只管自己利益的小团体，与“结成”及“只管自己的利益”相符。", "冰": "语义：冰是水凝结的固体，不能“只管自己的利益”。", "友谊": "语义：友谊讲互助和信任，与“只管自己的利益”的意思相反。", "果实": "搭配：果实没有利益可言，“只管自己的利益”不能用于果实。"}, "sentence_index": 6, "correct_answer": "小集团"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个小集团为社区做了很多好事，大家都很感谢。", "explanation": "这里应该用〈团队〉。小集团指为谋取私利结成的团体，与“为社区做了很多好事”相矛盾。"}, {"text": "大家成立了一个小集团，专门去河边免费捡垃圾，不求任何回报。", "explanation": "这里应该用〈环保团体〉。小集团指为谋取私利结成的团体，“不求任何回报”与之相矛盾。"}, {"text": "我们小集团每个周末都会组织徒步，全部费用自己承担，只为让大家开心。", "explanation": "这里应该用〈俱乐部〉。小集团指为谋取私利结成的团体，“只为让大家开心”与之相矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '552e5b7a-b4eb-4b55-be64-712c72ccd081') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95214, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "公司里有两只小集团，只顾自己的利益。", "corrected_sentence": "公司里有两个小集团，只顾自己的利益。", "error_description": "量词错误：小集团是团体，应说“两个小集团”，不能用量词“只”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '552e5b7a-b4eb-4b55-be64-712c72ccd081') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95214, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "部门里出现了一只小集团，只为自己捞好处。", "corrected_sentence": "部门里出现了一个小集团，只为自己捞好处。", "error_description": "量词错误：小集团是团体，应说“一个小集团”，不能用量词“只”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '552e5b7a-b4eb-4b55-be64-712c72ccd081') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95215, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "食言", "is_correct": true, "explanation": "与“履行”相反：“履行”是兑现承诺，“食言”是说了不算、不守诺言，属反义关系。"}, {"text": "观看", "is_correct": false, "explanation": "与“履行”没有反义关系，“观看”指看，意思无关。"}, {"text": "修理", "is_correct": false, "explanation": "与“履行”没有反义关系，“修理”指修补损坏的东西，意思无关。"}, {"text": "打扫", "is_correct": false, "explanation": "与“履行”没有反义关系，“打扫”指清除脏物，意思无关。"}], "correct_answer": "食言", "explanations": {"食言": "与“履行”相反：“履行”是兑现承诺，“食言”是说了不算、不守诺言，属反义关系。", "观看": "与“履行”没有反义关系，“观看”指看，意思无关。", "修理": "与“履行”没有反义关系，“修理”指修补损坏的东西，意思无关。", "打扫": "与“履行”没有反义关系，“打扫”指清除脏物，意思无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '503170ae-c285-467c-84c1-fba5608e9ba4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95215, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "食言", "is_correct": true, "explanation": "与“履行”相反：“履行”是兑现承诺，“食言”是说了不算、不守诺言，属反义关系。"}, {"text": "发呆", "is_correct": false, "explanation": "与“履行”没有反义关系，“发呆”指神情呆滞，意思无关。"}, {"text": "浇花", "is_correct": false, "explanation": "与“履行”没有反义关系，“浇花”指给植物浇水，意思无关。"}, {"text": "煮饭", "is_correct": false, "explanation": "与“履行”没有反义关系，“煮饭”指做饭，意思无关。"}], "correct_answer": "食言", "explanations": {"食言": "与“履行”相反：“履行”是兑现承诺，“食言”是说了不算、不守诺言，属反义关系。", "发呆": "与“履行”没有反义关系，“发呆”指神情呆滞，意思无关。", "浇花": "与“履行”没有反义关系，“浇花”指给植物浇水，意思无关。", "煮饭": "与“履行”没有反义关系，“煮饭”指做饭，意思无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '503170ae-c285-467c-84c1-fba5608e9ba4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95215, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "说过要做的事，就真的去做。", "primary_collocate": null, "pronunciation": "lǚ xíng", "ipa": "ly˨˩˦ ɕiŋ˧˥", "syllable_count": 2, "sentences": [{"text": "他说过要带我去玩，现在终于履行了诺言。", "target_word": "履行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你答应了孩子，就要履行自己的承诺。", "target_word": "履行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是个说话算话的人，总会履行诺言。", "target_word": "履行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板说过要加工资，可是一直没履行这个承诺。", "target_word": "履行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我向妈妈保证过每天读书，我要履行我的承诺。", "target_word": "履行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市长上任前说要修路，现在他履行了诺言。", "target_word": "履行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友借了钱，答应下个月还，但他没有履行承诺。", "target_word": "履行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他履行了对女儿的承诺，带她去了海边。", "target_word": "履行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她从不乱答应别人，答应了就一定履行。", "target_word": "履行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我答应弟弟周末修车，周日真的履行了诺言。", "target_word": "履行", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "履行了", "label": "体标"}, {"form": "履行过", "label": "体标"}], "register": "正式", "sense_fingerprint": "兑现自己说过、答应过的事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ce6f043-36d5-4f98-a980-2e9de3c98ca2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95215, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "履行", "is_correct": true, "explanation": "“履行”指兑现说过的话，“终于履行了诺言”符合语境。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”只能跟可以吃的东西搭配，不能说“吃诺言”。"}, {"text": "散步", "is_correct": false, "explanation": "配价：“散步”是不及物动词，不能带“诺言”作宾语，句子说不通。"}, {"text": "收拾", "is_correct": false, "explanation": "搭配：“收拾”指整理或修理，不能与“诺言”搭配。"}], "explanations": {"履行": "“履行”指兑现说过的话，“终于履行了诺言”符合语境。", "吃": "搭配：“吃”只能跟可以吃的东西搭配，不能说“吃诺言”。", "散步": "配价：“散步”是不及物动词，不能带“诺言”作宾语，句子说不通。", "收拾": "搭配：“收拾”指整理或修理，不能与“诺言”搭配。"}, "sentence_index": 0, "correct_answer": "履行"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他一直很认真地履行早起的习惯。", "explanation": "这里应该用〈养成〉。习惯要说养成或保持；履行用于承诺、约定和义务，不能用于习惯。"}, {"text": "我的愿望终于履行了。", "explanation": "这里应该用〈实现〉。愿望要说实现；履行用于依约或依义务去做的事。"}, {"text": "这台电脑已经履行了三年。", "explanation": "这里应该用〈运行〉。履行的主体是人或组织，电脑运转不能说履行。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '503170ae-c285-467c-84c1-fba5608e9ba4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95215, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "履行", "is_correct": true, "explanation": "“履行”指兑现承诺，“但他没有履行”与前文“答应下个月还”的语境相合。"}, {"text": "哭", "is_correct": false, "explanation": "语义：“哭”与前文借钱、答应还钱的语境无关，句子不合理。"}, {"text": "撒泼", "is_correct": false, "explanation": "语域：“撒泼”是口语且带贬义，与“履行”的正式语域不匹配，句中也说不通。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”与借钱还钱的语境无关，句子意思说不通。"}], "explanations": {"履行": "“履行”指兑现承诺，“但他没有履行”与前文“答应下个月还”的语境相合。", "哭": "语义：“哭”与前文借钱、答应还钱的语境无关，句子不合理。", "撒泼": "语域：“撒泼”是口语且带贬义，与“履行”的正式语域不匹配，句中也说不通。", "唱": "语义：“唱”与借钱还钱的语境无关，句子意思说不通。"}, "sentence_index": 6, "correct_answer": "履行"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们正在履行一场比赛。", "explanation": "这里应该用〈举行〉。比赛、活动要说举行；履行用于依约或依义务去做的事。"}, {"text": "这份报告我已经履行完了。", "explanation": "这里应该用〈完成〉。报告、工作要说完成；履行用于合同、义务、诺言等约定。"}, {"text": "这家餐厅已经履行了二十年。", "explanation": "这里应该用〈经营〉。餐厅要说经营；履行不用于做生意。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '503170ae-c285-467c-84c1-fba5608e9ba4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95215, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他没有履行了诺言，所以我很生气。", "corrected_sentence": "他没有履行诺言，所以我很生气。", "error_description": "体标错误：“没有”否定的是未发生的动作，不能与“了”同用，应说“没有履行诺言”，删去“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '503170ae-c285-467c-84c1-fba5608e9ba4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95215, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他履行了对孩子承诺，带他们去了公园。", "corrected_sentence": "他履行了对孩子的承诺，带他们去了公园。", "error_description": "结构助词错误：“对孩子”是修饰“承诺”的定语，中间要加“的”，应说“履行了对孩子的承诺”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '503170ae-c285-467c-84c1-fba5608e9ba4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95216, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "违约", "is_correct": true, "explanation": "与“履行”相反：“履行”是依约去做，“违约”是不按约定去做，属反义关系。"}, {"text": "收拾", "is_correct": false, "explanation": "与“履行”没有反义关系，“收拾”指整理或处理东西，意思无关。"}, {"text": "观看", "is_correct": false, "explanation": "与“履行”没有反义关系，“观看”指看，意思无关。"}, {"text": "修理", "is_correct": false, "explanation": "与“履行”没有反义关系，“修理”指修补损坏的东西，意思无关。"}], "correct_answer": "违约", "explanations": {"违约": "与“履行”相反：“履行”是依约去做，“违约”是不按约定去做，属反义关系。", "收拾": "与“履行”没有反义关系，“收拾”指整理或处理东西，意思无关。", "观看": "与“履行”没有反义关系，“观看”指看，意思无关。", "修理": "与“履行”没有反义关系，“修理”指修补损坏的东西，意思无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '503170ae-c285-467c-84c1-fba5608e9ba4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95216, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "违约", "is_correct": true, "explanation": "与“履行”相反：“履行”是依约去做，“违约”是不按约定去做，属反义关系。"}, {"text": "发呆", "is_correct": false, "explanation": "与“履行”没有反义关系，“发呆”指神情呆滞，意思无关。"}, {"text": "浇花", "is_correct": false, "explanation": "与“履行”没有反义关系，“浇花”指给植物浇水，意思无关。"}, {"text": "煮饭", "is_correct": false, "explanation": "与“履行”没有反义关系，“煮饭”指做饭，意思无关。"}], "correct_answer": "违约", "explanations": {"违约": "与“履行”相反：“履行”是依约去做，“违约”是不按约定去做，属反义关系。", "发呆": "与“履行”没有反义关系，“发呆”指神情呆滞，意思无关。", "浇花": "与“履行”没有反义关系，“浇花”指给植物浇水，意思无关。", "煮饭": "与“履行”没有反义关系，“煮饭”指做饭，意思无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '503170ae-c285-467c-84c1-fba5608e9ba4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95216, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "依照约定或规定实际去做。", "primary_collocate": null, "pronunciation": "lǚ xíng", "ipa": "ly˨˩˦ ɕiŋ˧˥", "syllable_count": 2, "sentences": [{"text": "公司没有按时履行合同，客户很生气。", "target_word": "履行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "租房的人要履行合同里写的规定。", "target_word": "履行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个公民都应该履行纳税的义务。", "target_word": "履行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板说不履行合同就要赔钱。", "target_word": "履行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两家公司都要履行签好的协议。", "target_word": "履行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生要履行救人的职责，不能不管病人。", "target_word": "履行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对方已经履行了合同，我们也该付钱了。", "target_word": "履行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子长大后，要履行照顾父母的义务。", "target_word": "履行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "双方签了字，就要履行合同上的内容。", "target_word": "履行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "厂家没有履行保修的约定，我很不满意。", "target_word": "履行", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "履行了", "label": "体标"}, {"form": "履行过", "label": "体标"}], "register": "正式", "sense_fingerprint": "按合同、协议、义务或规定的要求去做", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ce6f043-36d5-4f98-a980-2e9de3c98ca2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95216, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "履行", "is_correct": true, "explanation": "“履行”指依照合同去做，句中说“没有按时履行合同”，符合语境。"}, {"text": "违约", "is_correct": false, "explanation": "配价：“违约”是不及物动词，不能直接带“合同”作宾语，应说“违反合同”。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”只能跟可以吃的东西搭配，不能说“吃合同”。"}, {"text": "散步", "is_correct": false, "explanation": "配价：“散步”是不及物动词，不能带“合同”作宾语，句子说不通。"}], "explanations": {"履行": "“履行”指依照合同去做，句中说“没有按时履行合同”，符合语境。", "违约": "配价：“违约”是不及物动词，不能直接带“合同”作宾语，应说“违反合同”。", "吃": "搭配：“吃”只能跟可以吃的东西搭配，不能说“吃合同”。", "散步": "配价：“散步”是不及物动词，不能带“合同”作宾语，句子说不通。"}, "sentence_index": 0, "correct_answer": "履行"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个计划我们一定要履行好。", "explanation": "这里应该用〈执行〉。计划、方案要说执行；履行只用于合同、义务、诺言等约定。"}, {"text": "他终于履行了自己的梦想。", "explanation": "这里应该用〈实现〉。梦想要说实现；履行只用于依约或依义务去做的事。"}, {"text": "这台机器已经履行了十年。", "explanation": "这里应该用〈运行〉。履行的主体是人或组织，机器运转不能说履行。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '503170ae-c285-467c-84c1-fba5608e9ba4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95216, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "履行", "is_correct": true, "explanation": "“履行”指依约去做，这里指对方已经依合同做了事，符合语境。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”不能与“合同”搭配，“唱了合同”说不通。"}, {"text": "哭", "is_correct": false, "explanation": "搭配：“哭”不能带“合同”作宾语，“哭了合同”说不通。"}, {"text": "跑", "is_correct": false, "explanation": "搭配：“跑”不能带“合同”作宾语，“跑了合同”说不通。"}], "explanations": {"履行": "“履行”指依约去做，这里指对方已经依合同做了事，符合语境。", "唱": "搭配：“唱”不能与“合同”搭配，“唱了合同”说不通。", "哭": "搭配：“哭”不能带“合同”作宾语，“哭了合同”说不通。", "跑": "搭配：“跑”不能带“合同”作宾语，“跑了合同”说不通。"}, "sentence_index": 6, "correct_answer": "履行"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "会议已经履行了一个小时，大家都很累。", "explanation": "这里应该用〈进行〉。会议、活动要说进行；履行只用于依约或依义务去做的事。"}, {"text": "他从小就履行了画画的爱好。", "explanation": "这里应该用〈培养〉。爱好要说培养；履行用于承诺、约定和义务。"}, {"text": "这项政策已经履行了一年。", "explanation": "这里应该用〈实施〉。政策、措施要说实施；履行用于合同、义务、诺言等约定。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '503170ae-c285-467c-84c1-fba5608e9ba4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95216, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "公司没有把合同履行。", "corrected_sentence": "公司没有把合同履行好。", "error_description": "补语错误：“把”字句里的动词不能单独出现，“履行”后面要带补语，应说“没有把合同履行好”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '503170ae-c285-467c-84c1-fba5608e9ba4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95216, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把合同履行很认真。", "corrected_sentence": "他把合同履行得很认真。", "error_description": "补语错误：动词“履行”后带程度补语，要用“得”连接，应说“把合同履行得很认真”；“把合同履行很认真”漏掉“得”，不成句。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '503170ae-c285-467c-84c1-fba5608e9ba4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
