INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95220, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "管理城市行政事务的政府机关。", "primary_collocate": null, "pronunciation": "shì zhèng fǔ", "ipa": "ʂɻ̩˥˩ ʈʂɤŋ˥˩ fu˨˩˦", "syllable_count": 3, "sentences": [{"text": "市政府决定修一条新地铁。", "target_word": "市政府", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市政府今天发了新的通知。", "target_word": "市政府", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市政府要求大家少开车。", "target_word": "市政府", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市政府会帮助有困难的家庭。", "target_word": "市政府", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市政府准备建三所新学校。", "target_word": "市政府", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市政府对这个问题很重视。", "target_word": "市政府", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市政府已经批准了这个计划。", "target_word": "市政府", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市政府提出了新的环保办法。", "target_word": "市政府", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听说市政府想增加公园。", "target_word": "市政府", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市政府公布了去年的工作结果。", "target_word": "市政府", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "市政府大楼", "label": "复合"}], "register": "正式", "sense_fingerprint": "作出决定、发布通知的城市行政机关", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dcd4018f-a1c8-4a3f-b92d-7f066eb0ba12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95220, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "小猫", "is_correct": false, "explanation": "语义：小猫没有决策能力，不能决定修建地铁。"}, {"text": "夏天", "is_correct": false, "explanation": "搭配：“决定”的主语要是人或机构，不能用“夏天”。"}, {"text": "市政府", "is_correct": true, "explanation": "正确。市政府是城市行政机关，有权决定修建地铁。"}, {"text": "树叶", "is_correct": false, "explanation": "语义：树叶是植物的一部分，不能做出修建地铁的决定。"}], "explanations": {"小猫": "语义：小猫没有决策能力，不能决定修建地铁。", "夏天": "搭配：“决定”的主语要是人或机构，不能用“夏天”。", "市政府": "正确。市政府是城市行政机关，有权决定修建地铁。", "树叶": "语义：树叶是植物的一部分，不能做出修建地铁的决定。"}, "sentence_index": 0, "correct_answer": "市政府"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个市政府每个月生产两万辆汽车。", "explanation": "这里应该用〈工厂〉。市政府是行政机关，不生产汽车，生产要靠工厂。"}, {"text": "市政府判决了这个案子。", "explanation": "这里应该用〈法院〉。市政府是行政机关，不审理案件，判决要用法院。"}, {"text": "市政府抓到了那个小偷。", "explanation": "这里应该用〈派出所〉。市政府不负责抓人，抓人是派出所的工作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2f607f4-3adb-4b83-8dd1-5e16a2915b5e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95220, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "手机", "is_correct": false, "explanation": "语义：手机是物品，不能做出批准计划的行为。"}, {"text": "市政府", "is_correct": true, "explanation": "正确。市政府是城市行政机关，有权批准计划。"}, {"text": "雨水", "is_correct": false, "explanation": "语义：雨水是自然现象，没有审批权，不能批准计划。"}, {"text": "天空", "is_correct": false, "explanation": "搭配：“批准”需要有权限的机构或人作主语，不能用“天空”。"}], "explanations": {"手机": "语义：手机是物品，不能做出批准计划的行为。", "市政府": "正确。市政府是城市行政机关，有权批准计划。", "雨水": "语义：雨水是自然现象，没有审批权，不能批准计划。", "天空": "搭配：“批准”需要有权限的机构或人作主语，不能用“天空”。"}, "sentence_index": 6, "correct_answer": "市政府"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "市政府公布了期末成绩单。", "explanation": "这里应该用〈学校〉。期末成绩是学校的事，市政府不负责公布学生成绩。"}, {"text": "市政府烤了一块蛋糕。", "explanation": "这里应该用〈面包店〉。烤蛋糕要在面包店，市政府不做烘焙。"}, {"text": "市政府治好了很多病人。", "explanation": "这里应该用〈医院〉。治病是医院的职能，市政府不做诊疗。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2f607f4-3adb-4b83-8dd1-5e16a2915b5e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95220, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这条市政府的办事效率很高。", "corrected_sentence": "这个市政府的办事效率很高。", "error_description": "错误：“条”用于细长的东西，不用于机关；市政府应用量词“个”。正确：这个市政府的办事效率很高。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2f607f4-3adb-4b83-8dd1-5e16a2915b5e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95220, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "上个月那张市政府公布了新的规定。", "corrected_sentence": "上个月市政府公布了新的规定。", "error_description": "错误：“那张”中的“张”用于平面的东西，不能用来限定机关；“上个月市政府”前不应加“那张”。正确：上个月市政府公布了新的规定。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2f607f4-3adb-4b83-8dd1-5e16a2915b5e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
