INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95221, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "有本领、能教别人手艺的人。", "primary_collocate": null, "pronunciation": "shī fu", "ipa": "ʂʅ˥ fu", "syllable_count": 2, "sentences": [{"text": "他跟着师傅学做木工。", "target_word": "师傅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "师傅教我怎么做面包。", "target_word": "师傅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的师傅做了三十年饭，手艺很好。", "target_word": "师傅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "徒弟要听师傅的话。", "target_word": "师傅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "师傅一边做，一边给徒弟看。", "target_word": "师傅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在这位师傅手下学画画，学了三年。", "target_word": "师傅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "师傅说，学手艺要有耐心。", "target_word": "师傅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位师傅带过很多徒弟。", "target_word": "师傅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "徒弟做错了，师傅没有生气。", "target_word": "师傅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的师傅是镇上最有名的铁匠。", "target_word": "师傅", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "師傅", "label": "繁体"}], "register": "口语", "sense_fingerprint": "有本领、教徒弟手艺的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'db3644ad-b860-49ef-adcd-01357c77d0ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95221, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "师傅", "is_correct": true, "explanation": "正确。“师傅”指能教别人手艺的人，与“跟着……学做木工”相符。"}, {"text": "医生", "is_correct": false, "explanation": "语义：“医生”的职责是看病，不是传授木工手艺。"}, {"text": "石头", "is_correct": false, "explanation": "语义：“石头”不能教人，与“跟着……学做木工”不相符。"}, {"text": "学徒", "is_correct": false, "explanation": "搭配：“学徒”指正在学艺的人，不能作为“跟着……学”的传授者。"}], "explanations": {"师傅": "正确。“师傅”指能教别人手艺的人，与“跟着……学做木工”相符。", "医生": "语义：“医生”的职责是看病，不是传授木工手艺。", "石头": "语义：“石头”不能教人，与“跟着……学做木工”不相符。", "学徒": "搭配：“学徒”指正在学艺的人，不能作为“跟着……学”的传授者。"}, "sentence_index": 0, "correct_answer": "师傅"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位师傅替我们辩护，打赢了官司。", "explanation": "这里应该用〈律师〉。〈师傅〉指有本领、能教别人手艺的人，不指从事法律工作的人。"}, {"text": "这位师傅在电影里演了主角，很受欢迎。", "explanation": "这里应该用〈演员〉。〈师傅〉指有本领、能教别人手艺的人，不指从事表演的人。"}, {"text": "这位师傅在医院给病人做了手术。", "explanation": "这里应该用〈医生〉。〈师傅〉指有本领、能教别人手艺的人，不指给病人做手术的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0951cffc-c221-4855-94ff-5e8df6e4b522') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95221, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "师傅", "is_correct": true, "explanation": "正确。“师傅”指传授手艺的人，与“说，学手艺要有耐心”的语境相符。"}, {"text": "花瓶", "is_correct": false, "explanation": "语义：“花瓶”不会说话，与“说，学手艺要有耐心”不相符。"}, {"text": "老虎", "is_correct": false, "explanation": "语义：“老虎”是动物，不会说这样的话。"}, {"text": "巾帼", "is_correct": false, "explanation": "语域：“巾帼”是书面语，不适合此处的口语叙述。"}], "explanations": {"师傅": "正确。“师傅”指传授手艺的人，与“说，学手艺要有耐心”的语境相符。", "花瓶": "语义：“花瓶”不会说话，与“说，学手艺要有耐心”不相符。", "老虎": "语义：“老虎”是动物，不会说这样的话。", "巾帼": "语域：“巾帼”是书面语，不适合此处的口语叙述。"}, "sentence_index": 6, "correct_answer": "师傅"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位师傅发表了一篇论文。", "explanation": "这里应该用〈教授〉。〈师傅〉有本领、能教手艺，不指从事学术研究的人。"}, {"text": "这位师傅给我打了一针，动作很熟练。", "explanation": "这里应该用〈护士〉。〈师傅〉指有本领、能教别人手艺的人，不指护理工作。"}, {"text": "这位师傅在法庭上判了这个案子。", "explanation": "这里应该用〈法官〉。〈师傅〉指有本领、能教别人手艺的人，不指在法庭上判案的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0951cffc-c221-4855-94ff-5e8df6e4b522') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95221, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他有一只很好的师傅，教他做木工。", "corrected_sentence": "他有一位很好的师傅，教他做木工。", "error_description": "量词错误：“师傅”指人，应用量词〈位〉，不能用〈只〉。正确说法是“一位很好的师傅”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0951cffc-c221-4855-94ff-5e8df6e4b522') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95221, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他找到了一位耐心地师傅，学会了做木工。", "corrected_sentence": "他找到了一位耐心的师傅，学会了做木工。", "error_description": "结构错误：修饰名词时应用“的”，不用“地”（“地”修饰动词）。正确说法是“耐心的师傅”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0951cffc-c221-4855-94ff-5e8df6e4b522') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
