INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95222, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "对有专门技艺者的尊称。", "primary_collocate": null, "pronunciation": "shī fu", "ipa": "ʂʅ˥ fu", "syllable_count": 2, "sentences": [{"text": "师傅，请问去火车站怎么走？", "target_word": "师傅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出租车师傅开得很稳。", "target_word": "师傅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "修车师傅说，车已经修好了。", "target_word": "师傅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "师傅，麻烦您把空调开大一点。", "target_word": "师傅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位师傅做的面条特别好吃。", "target_word": "师傅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "厨房里的师傅正在炒菜。", "target_word": "师傅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们请了一位师傅来修水管。", "target_word": "师傅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "师傅，这件衣服能改短一点吗？", "target_word": "师傅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "楼下的修鞋师傅每天早上八点出摊。", "target_word": "师傅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "街角的理发师傅剪得很好看。", "target_word": "师傅", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "師傅", "label": "繁体"}], "register": "口语", "sense_fingerprint": "对有专门技艺者的尊称", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'db3644ad-b860-49ef-adcd-01357c77d0ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95222, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "师傅", "is_correct": true, "explanation": "正确。“师傅”用作对有专门技艺者的尊称，与向人问路的语境相符。"}, {"text": "石头", "is_correct": false, "explanation": "语义：“石头”不能回答问路，也无法听懂问题。"}, {"text": "老虎", "is_correct": false, "explanation": "语义：“老虎”是动物，不是可以向其问路的人。"}, {"text": "巾帼", "is_correct": false, "explanation": "语域：“巾帼”是书面语，不适合这句口语的问路用语。"}], "explanations": {"师傅": "正确。“师傅”用作对有专门技艺者的尊称，与向人问路的语境相符。", "石头": "语义：“石头”不能回答问路，也无法听懂问题。", "老虎": "语义：“老虎”是动物，不是可以向其问路的人。", "巾帼": "语域：“巾帼”是书面语，不适合这句口语的问路用语。"}, "sentence_index": 0, "correct_answer": "师傅"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位师傅是我的表哥，今年刚上大学。", "explanation": "这里应该用〈表哥〉。〈师傅〉是对有专门技艺者的尊称，不用于称呼家中的亲戚。"}, {"text": "这位师傅是我们班的新同学，个子很高。", "explanation": "这里应该用〈同学〉。〈师傅〉是对有专门技艺者的尊称，不用于称呼同龄的同学。"}, {"text": "这位师傅今年才六岁，还在上幼儿园。", "explanation": "这里应该用〈小朋友〉。〈师傅〉是尊称，六岁的孩子没有专门技艺，不能这样称呼。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0951cffc-c221-4855-94ff-5e8df6e4b522') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95222, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "师傅", "is_correct": true, "explanation": "正确。“师傅”指有修理技艺的人，与“请来修水管”相符。"}, {"text": "老师", "is_correct": false, "explanation": "搭配：“请……来修水管”要请有修理技能的人，“老师”一般不指修理工。"}, {"text": "医生", "is_correct": false, "explanation": "语义：“医生”的职责是看病，与“修水管”的事情不相符。"}, {"text": "红颜", "is_correct": false, "explanation": "语域：“红颜”是文言词，不适合此处的口语叙述。"}], "explanations": {"师傅": "正确。“师傅”指有修理技艺的人，与“请来修水管”相符。", "老师": "搭配：“请……来修水管”要请有修理技能的人，“老师”一般不指修理工。", "医生": "语义：“医生”的职责是看病，与“修水管”的事情不相符。", "红颜": "语域：“红颜”是文言词，不适合此处的口语叙述。"}, "sentence_index": 6, "correct_answer": "师傅"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位师傅是我的爷爷，每天都来接我放学。", "explanation": "这里应该用〈爷爷〉。〈师傅〉是对有专门技艺者的尊称，不用于称呼家中长辈。"}, {"text": "这位师傅是大学里的历史教授，常常写论文。", "explanation": "这里应该用〈教授〉。〈师傅〉是对有专门技艺者的尊称，不用于称呼从事学术研究的大学教授。"}, {"text": "这位师傅是一只小猫，每天在沙发上睡觉。", "explanation": "这里应该用〈小猫〉。〈师傅〉指有专门技艺的人，不用于称呼动物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0951cffc-c221-4855-94ff-5e8df6e4b522') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95222, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "楼下来了一只修鞋的师傅，他很热心。", "corrected_sentence": "楼下来了一位修鞋的师傅，他很热心。", "error_description": "量词错误：“师傅”指人，应用量词〈位〉，不能用〈只〉（〈只〉用于动物等）。正确说法是“一位修鞋的师傅”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0951cffc-c221-4855-94ff-5e8df6e4b522') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95222, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这位师傅们很热心，帮我修好了水管。", "corrected_sentence": "这位师傅很热心，帮我修好了水管。", "error_description": "复数错误：“这位”表示单数，“师傅”后不能加“们”，应说“这位师傅”，不能说“这位师傅们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0951cffc-c221-4855-94ff-5e8df6e4b522') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
