INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95224, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个月底大家都忙着账算。", "corrected_sentence": "这个月底大家都忙着算账。", "error_description": "离合词语序错误：“算账”是动宾式，不能说“账算”，应说“算账”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70428954-4397-48b4-b49b-6d906a67ae78') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95224, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "上个月的一把账已经算清楚了。", "corrected_sentence": "上个月的一笔账已经算清楚了。", "error_description": "量词错误：账目按笔计，应说“一笔账”，不说“一把账”（把多用于有柄的东西）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70428954-4397-48b4-b49b-6d906a67ae78') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
