INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95227, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "人背上正中间、心的后面那一块。", "primary_collocate": null, "pronunciation": "hòu xīn", "ipa": "xou˥˩ ɕin˥", "syllable_count": 2, "sentences": [{"text": "他的后心出了很多汗。", "target_word": "后心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生用手轻轻拍了拍我的后心。", "target_word": "后心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈给孩子的后心贴了一块暖宝宝。", "target_word": "后心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天风大，我觉得后心发凉。", "target_word": "后心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他躺在床上，妈妈把热水袋放在他的后心。", "target_word": "后心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子出汗了，我用毛巾擦他的后心。", "target_word": "后心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "跑完步，我的后心全湿了。", "target_word": "后心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在我的后心上挠了几下，真舒服。", "target_word": "后心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶怕我着凉，在我后心垫了一块毛巾。", "target_word": "后心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生用听诊器听了听他的后心。", "target_word": "后心", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "後心", "label": "繁体"}], "register": "口语", "sense_fingerprint": "人背上正中间、心脏后面的那一块", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'db3644ad-b860-49ef-adcd-01357c77d0ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95227, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "后心", "is_correct": true, "explanation": "正确：后心是背部正中间的一块，可以出汗，符合句意。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包是物品，不会出汗。"}, {"text": "钥匙", "is_correct": false, "explanation": "语义：钥匙不是身体部位，不能说出汗。"}, {"text": "眼睛", "is_correct": false, "explanation": "搭配：出汗要说身体的皮肤部位，“眼睛”不跟“出汗”搭配，眼睛湿要说“流泪”。"}], "explanations": {"后心": "正确：后心是背部正中间的一块，可以出汗，符合句意。", "书包": "语义：书包是物品，不会出汗。", "钥匙": "语义：钥匙不是身体部位，不能说出汗。", "眼睛": "搭配：出汗要说身体的皮肤部位，“眼睛”不跟“出汗”搭配，眼睛湿要说“流泪”。"}, "sentence_index": 0, "correct_answer": "后心"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "跑完步，他的后心跳得很快。", "explanation": "这里应该用〈心脏〉。跳的是心脏；“后心”指背部正中间一小块，不能说“后心跳”。"}, {"text": "他穿着新鞋走了很久，后心磨出了一个大水泡。", "explanation": "这里应该用〈后跟〉。鞋磨出的水泡在脚后跟；“后心”是背中间，走路磨不到那里。"}, {"text": "他的后心很宽，能扛很重的东西。", "explanation": "这里应该用〈肩背〉。“后心”只是背上的一小块，不能说“后心很宽”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0951cffc-c221-4855-94ff-5e8df6e4b522') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95227, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "后心", "is_correct": true, "explanation": "正确：跑步出汗后，背部正中间的后心会湿，符合句意。"}, {"text": "想法", "is_correct": false, "explanation": "语义：“想法”是脑子里的东西，看不见摸不着，不会被汗湿。"}, {"text": "钥匙", "is_correct": false, "explanation": "语义：钥匙不会因为跑步而湿透。"}, {"text": "天空", "is_correct": false, "explanation": "搭配：“全湿了”要搭配身体或衣物，“天空”不能说被打湿。"}], "explanations": {"后心": "正确：跑步出汗后，背部正中间的后心会湿，符合句意。", "想法": "语义：“想法”是脑子里的东西，看不见摸不着，不会被汗湿。", "钥匙": "语义：钥匙不会因为跑步而湿透。", "天空": "搭配：“全湿了”要搭配身体或衣物，“天空”不能说被打湿。"}, "sentence_index": 6, "correct_answer": "后心"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他低头看书太久，后心僵硬，转不动头。", "explanation": "这里应该用〈后颈〉。转头困难、僵硬的是后颈；“后心”是背中间一小块，不能这样说。"}, {"text": "他扛了一天货，后心上的戒指丢了。", "explanation": "这里应该用〈手指〉。戒指戴在手指上；“后心”是背部，不能戴戒指。"}, {"text": "他跪了太久，后心疼得站不起来。", "explanation": "这里应该用〈膝盖〉。跪久了疼的是膝盖；“后心”是背中间，跪时不会疼在那里。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0951cffc-c221-4855-94ff-5e8df6e4b522') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95227, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他摸了摸自己的一只后心，觉得有点儿发烫。", "corrected_sentence": "他摸了摸自己的后心，觉得有点儿发烫。", "error_description": "量词错误：后心只有一处，不能用量词〈只〉。正确说法是“自己的后心”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0951cffc-c221-4855-94ff-5e8df6e4b522') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95227, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他刚洗完澡，两个后心上还有水。", "corrected_sentence": "他刚洗完澡，后心上还有水。", "error_description": "数量错误：后心只有一处，不能说“两个后心”。正确说法是“后心上还有水”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0951cffc-c221-4855-94ff-5e8df6e4b522') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
