INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95229, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "心里想做某件事的想法。", "primary_collocate": null, "pronunciation": "yì yuàn", "ipa": "i˥˩ ɥɛn˥˩", "syllable_count": 2, "sentences": [{"text": "很多年轻人没有马上买房的意愿。", "target_word": "意愿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子学习的意愿不强，老师很着急。", "target_word": "意愿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司想合作，但对方没有这个意愿。", "target_word": "意愿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他没有搬家的意愿，所以不看新房子。", "target_word": "意愿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份问卷想了解大家买新手机的意愿。", "target_word": "意愿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他嘴上说想去，其实没有真正的意愿。", "target_word": "意愿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "价格太高，客人买的意愿一下子就低了。", "target_word": "意愿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "球队想留住他，他也有留下来的意愿。", "target_word": "意愿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生参加比赛的意愿很高，报名的人很多。", "target_word": "意愿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "双方都有谈判的意愿，会议很快就开始了。", "target_word": "意愿", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "愿不愿意做某件事的心理倾向", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ce6f043-36d5-4f98-a980-2e9de3c98ca2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95229, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "意愿", "is_correct": true, "explanation": "“意愿”指愿不愿意做某事的心理倾向，“没有马上买房的意愿”符合语境。"}, {"text": "手机", "is_correct": false, "explanation": "语义：“手机”与“买房的心理倾向”无关，句子说不通。"}, {"text": "厚度", "is_correct": false, "explanation": "搭配：“厚度”不能与“买房的”搭配，说“买房的厚度”不成立。"}, {"text": "钥匙", "is_correct": false, "explanation": "语义：“钥匙”是开门的工具，与买房的心理倾向无关，句子说不通。"}], "explanations": {"意愿": "“意愿”指愿不愿意做某事的心理倾向，“没有马上买房的意愿”符合语境。", "手机": "语义：“手机”与“买房的心理倾向”无关，句子说不通。", "厚度": "搭配：“厚度”不能与“买房的”搭配，说“买房的厚度”不成立。", "钥匙": "语义：“钥匙”是开门的工具，与买房的心理倾向无关，句子说不通。"}, "sentence_index": 0, "correct_answer": "意愿"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他提了很多意愿，大家都觉得很有道理。", "explanation": "这里应该用〈意见〉。提出看法或建议要说意见；意愿指心里想做某事的打算，不能用来指看法。"}, {"text": "这段绳子的意愿很长，能绕房子一圈。", "explanation": "这里应该用〈长度〉。绳子的长短要说长度；意愿指人心里的打算，不能用来说绳子的长短。"}, {"text": "他的意愿很好听。", "explanation": "这里应该用〈名字〉。好听形容名字或声音，意愿是心里的打算，不能用“好听”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '503170ae-c285-467c-84c1-fba5608e9ba4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95229, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "意愿", "is_correct": true, "explanation": "“意愿”指愿不愿意做某事的心理倾向，“客人买的意愿低了”符合语境。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”与客人想买不买的心理无关，句子说不通。"}, {"text": "高度", "is_correct": false, "explanation": "搭配：“高度”不能说“买的高度”，与“买”搭配不当。"}, {"text": "气味", "is_correct": false, "explanation": "语义：“气味”与客人的购买心理无关，句子说不通。"}], "explanations": {"意愿": "“意愿”指愿不愿意做某事的心理倾向，“客人买的意愿低了”符合语境。", "颜色": "语义：“颜色”与客人想买不买的心理无关，句子说不通。", "高度": "搭配：“高度”不能说“买的高度”，与“买”搭配不当。", "气味": "语义：“气味”与客人的购买心理无关，句子说不通。"}, "sentence_index": 6, "correct_answer": "意愿"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他有很多意愿，总能很快解决问题。", "explanation": "这里应该用〈办法〉。解决问题要用办法；意愿只表示想做的心理倾向，不能说明有没有解决问题的方法。"}, {"text": "他的意愿很标准，说话没有口音。", "explanation": "这里应该用〈发音〉。“标准”形容发音，意愿不能说标准。"}, {"text": "两地的意愿很远。", "explanation": "这里应该用〈距离〉。远近要说距离，意愿是心里的打算，不能用远近来形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '503170ae-c285-467c-84c1-fba5608e9ba4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95229, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他心里有一只换工作的意愿。", "corrected_sentence": "他心里有一种换工作的意愿。", "error_description": "量词错误：“意愿”是抽象名词，应与“种”搭配，说“一种换工作的意愿”；“一只”多用于动物或成对的物品，不能用于“意愿”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '503170ae-c285-467c-84c1-fba5608e9ba4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95229, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他表现出想转行意愿。", "corrected_sentence": "他表现出想转行的意愿。", "error_description": "结构错误：“想转行”修饰“意愿”，中间要用“的”连接，漏掉“的”后句子结构不完整。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '503170ae-c285-467c-84c1-fba5608e9ba4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
