INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95230, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "心中的愿望和打算。", "primary_collocate": null, "pronunciation": "yì yuàn", "ipa": "i˥˩ ɥɛn˥˩", "syllable_count": 2, "sentences": [{"text": "他有去国外工作的意愿，已经在学英语了。", "target_word": "意愿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "父母应该尊重孩子选择专业的意愿。", "target_word": "意愿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她向公司表达了留在北京的意愿。", "target_word": "意愿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事不是我的意愿，是别人让我做的。", "target_word": "意愿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他有很强的意愿，想自己开一家小店。", "target_word": "意愿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "结婚是两个人的事，要看他们自己的意愿。", "target_word": "意愿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人的意愿很简单，就是回老家看看。", "target_word": "意愿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "病人有早点出院的意愿，医生同意了。", "target_word": "意愿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要照他本人的意愿安排这次旅行。", "target_word": "意愿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她学画画的意愿从小就很强。", "target_word": "意愿", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "心中想要实现的愿望和打算", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ce6f043-36d5-4f98-a980-2e9de3c98ca2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95230, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "意愿", "is_correct": true, "explanation": "“意愿”指心里想做某事的打算，“去国外工作的意愿”符合语境。"}, {"text": "工资", "is_correct": false, "explanation": "语义：“工资”是劳动报酬，与“去国外工作的打算”无关，句子说不通。"}, {"text": "意气", "is_correct": false, "explanation": "搭配：“意气”不能说成“去国外工作的意气”，搭配不当。"}, {"text": "语法", "is_correct": false, "explanation": "语义：“语法”指语言规则，与句子表达的打算无关，句子说不通。"}], "explanations": {"意愿": "“意愿”指心里想做某事的打算，“去国外工作的意愿”符合语境。", "工资": "语义：“工资”是劳动报酬，与“去国外工作的打算”无关，句子说不通。", "意气": "搭配：“意气”不能说成“去国外工作的意气”，搭配不当。", "语法": "语义：“语法”指语言规则，与句子表达的打算无关，句子说不通。"}, "sentence_index": 0, "correct_answer": "意愿"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座桥的意愿很宽，两辆车能并排开过去。", "explanation": "这里应该用〈宽度〉。桥的宽窄要说宽度；意愿指心中的愿望和打算，不能用来说桥的宽窄。"}, {"text": "这次的意愿很重，我们要尽快完成。", "explanation": "这里应该用〈任务〉。任务有轻有重，意愿是心里的打算，不能说轻重。"}, {"text": "我们的意愿很紧，得快点做。", "explanation": "这里应该用〈时间〉。时间有紧有松，意愿不能说紧。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '503170ae-c285-467c-84c1-fba5608e9ba4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95230, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "意愿", "is_correct": true, "explanation": "“意愿”指心里想做某事的打算，“老人的意愿很简单”符合语境，指回老家看看的心愿。"}, {"text": "门票", "is_correct": false, "explanation": "语义：“门票”指入场凭证，与“回老家看看”的心愿无关，句子说不通。"}, {"text": "脚步", "is_correct": false, "explanation": "搭配：“脚步”指走路的动作，不能说“老人的脚步很简单”，搭配不当。"}, {"text": "钥匙", "is_correct": false, "explanation": "语义：“钥匙”是开锁的工具，与句子表达的心愿无关，句子说不通。"}], "explanations": {"意愿": "“意愿”指心里想做某事的打算，“老人的意愿很简单”符合语境，指回老家看看的心愿。", "门票": "语义：“门票”指入场凭证，与“回老家看看”的心愿无关，句子说不通。", "脚步": "搭配：“脚步”指走路的动作，不能说“老人的脚步很简单”，搭配不当。", "钥匙": "语义：“钥匙”是开锁的工具，与句子表达的心愿无关，句子说不通。"}, "sentence_index": 6, "correct_answer": "意愿"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这本书的意愿很厚，有五百多页。", "explanation": "这里应该用〈厚度〉。书的薄厚要说厚度；意愿指心中的愿望和打算，不能用来说书的薄厚。"}, {"text": "这个盒子的意愿很大，装得下很多东西。", "explanation": "这里应该用〈容量〉。盒子能装多少要说容量；意愿指人心里的打算，不能用来说盒子的大小。"}, {"text": "他跑步的意愿很快。", "explanation": "这里应该用〈速度〉。跑步快慢要说速度，意愿不能用快慢来形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '503170ae-c285-467c-84c1-fba5608e9ba4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95230, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她有一只强烈的意愿，想去海外读书。", "corrected_sentence": "她有一种强烈的意愿，想去海外读书。", "error_description": "量词错误：“意愿”是抽象名词，应与“种”搭配，说“一种强烈的意愿”；“一只”多用于动物或成对的物品，不能用于“意愿”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '503170ae-c285-467c-84c1-fba5608e9ba4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95230, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他学做饭意愿很强。", "corrected_sentence": "他学做饭的意愿很强。", "error_description": "结构错误：“学做饭”修饰“意愿”，中间要用“的”连接，漏掉“的”后句子结构不完整。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '503170ae-c285-467c-84c1-fba5608e9ba4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
