INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95231, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70428954-4397-48b4-b49b-6d906a67ae78') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95231, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一样东西是你的，别人不能随便拿走。", "primary_collocate": null, "pronunciation": "suǒ yǒu quán", "ipa": "swɔ˨˩˦ joʊ˨˩˦ tɕʰɥɛn˧˥", "syllable_count": 3, "sentences": [{"text": "这把伞是我的，所有权在我这儿，你别随便拿走。", "target_word": "所有权", "complexity_tier": "T3", "furigana": "zhè bǎ sǎn shì wǒ de, suǒ yǒu quán zài wǒ zhèr, nǐ bié suíbiàn ná zǒu", "sentence_source": "generated"}, {"text": "这辆车的所有权在爸爸手里，别人不能随便开。", "target_word": "所有权", "complexity_tier": "T3", "furigana": "zhè liàng chē de suǒ yǒu quán zài bà ba shǒu lǐ, bié rén bù néng suíbiàn kāi", "sentence_source": "generated"}, {"text": "房子的所有权在谁手里？", "target_word": "所有权", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你有这只狗的所有权，别人不能带走它。", "target_word": "所有权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我买了这块地，所有权就是我的了。", "target_word": "所有权", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "朋友借走了我的书，但所有权还是我的。", "target_word": "所有权", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小明说，这个球的所有权在他那儿，别人不能拿。", "target_word": "所有权", "complexity_tier": "T3", "furigana": "Xiǎo Míng shuō, zhè ge qiú de suǒ yǒu quán zài tā nàr, bié rén bù néng ná", "sentence_source": "generated"}, {"text": "买下这套房子后，所有权就是你的。", "target_word": "所有权", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "谁有这幅画的所有权？", "target_word": "所有权", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这只猫是我养的，所有权当然是我的。", "target_word": "所有权", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "所有權", "label": "繁体"}, {"form": "所有权人", "label": "复合"}], "register": "中性", "sense_fingerprint": "东西归谁，别人不能随便拿走", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17ff06e6-d05a-42d0-84b6-f1fd5eae80ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95231, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "颜色", "is_correct": false, "explanation": "语义：颜色不能“在我这儿”，句中指的是东西归属。"}, {"text": "所有权", "is_correct": true, "explanation": "正确：所有权在我这儿，所以别人不能随便拿走，与上下文相符。"}, {"text": "名字", "is_correct": false, "explanation": "语义：名字不是可以被谁握在手里的东西，与“别随便拿走”无关。"}, {"text": "重量", "is_correct": false, "explanation": "搭配：重量不说“在我这儿”，也不与“拿走”搭配。"}], "explanations": {"颜色": "语义：颜色不能“在我这儿”，句中指的是东西归属。", "所有权": "正确：所有权在我这儿，所以别人不能随便拿走，与上下文相符。", "名字": "语义：名字不是可以被谁握在手里的东西，与“别随便拿走”无关。", "重量": "搭配：重量不说“在我这儿”，也不与“拿走”搭配。"}, "sentence_index": 0, "correct_answer": "所有权"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他拥有这栋房子的一只所有权。", "explanation": "这里应该用〈项〉。所有权是抽象的权利，量词用项，不用只（只多用于动物等）。"}, {"text": "我只有这台电脑的所有权，它不是我的。", "explanation": "这里应该用〈使用权〉。句中说“它不是我的”，只能有使用权，不能说所有权。"}, {"text": "这只猫的所有权每天都喂它。", "explanation": "这里应该用〈主人〉。喂养是人的动作，所有权是抽象的权利，不能做动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70428954-4397-48b4-b49b-6d906a67ae78') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95231, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "形状", "is_correct": false, "explanation": "语义：形状不是能“在他那儿”的权利，句中指的是归属。"}, {"text": "所有权", "is_correct": true, "explanation": "正确：球的所有权在他那儿，别人就不能拿，与上下文相符。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：价格不能被“拿”，与“别人不能拿”不搭。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：球没有年龄可以“在他那儿”，句中指归属。"}], "explanations": {"形状": "语义：形状不是能“在他那儿”的权利，句中指的是归属。", "所有权": "正确：球的所有权在他那儿，别人就不能拿，与上下文相符。", "价格": "搭配：价格不能被“拿”，与“别人不能拿”不搭。", "年龄": "语义：球没有年龄可以“在他那儿”，句中指归属。"}, "sentence_index": 6, "correct_answer": "所有权"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他买了一幅所有权，挂在墙上。", "explanation": "这里应该用〈项〉。所有权是抽象权利，量词用项，不用幅（幅多用于画）。"}, {"text": "他对家人有很大的所有权。", "explanation": "这里应该用〈责任〉。所有权指对财产的法定权利，对家人的担当要说责任，不能说所有权。"}, {"text": "他身上有一颗所有权。", "explanation": "这里应该用〈项〉。所有权是抽象权利，不能用颗计量（颗多用于小而圆的东西）。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70428954-4397-48b4-b49b-6d906a67ae78') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95231, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我所有权这把伞，你别随便拿走。", "corrected_sentence": "我拥有这把伞，你别随便拿走。", "error_description": "词性错误：所有权是名词，不能直接当动词带宾语，这里应该用动词“拥有”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70428954-4397-48b4-b49b-6d906a67ae78') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95231, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "小明所有权这个球，别人不能拿。", "corrected_sentence": "小明拥有这个球，别人不能拿。", "error_description": "词性错误：所有权是名词，不能直接当动词带宾语，这里应该用动词“拥有”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70428954-4397-48b4-b49b-6d906a67ae78') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
