INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95232, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70428954-4397-48b4-b49b-6d906a67ae78') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95232, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "对财产依法占有、使用和处分的权利。", "primary_collocate": null, "pronunciation": "suǒ yǒu quán", "ipa": "swɔ˨˩˦ joʊ˨˩˦ tɕʰɥɛn˧˥", "syllable_count": 3, "sentences": [{"text": "买房以后，你就有这套房子的所有权。", "target_word": "所有权", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "法律保护公民的财产所有权。", "target_word": "所有权", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "房产证上写着房子的所有权属于谁。", "target_word": "所有权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "土地的所有权属于国家。", "target_word": "所有权", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他们为这块地的所有权打了官司。", "target_word": "所有权", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司把汽车的所有权转给了他。", "target_word": "所有权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "卖房子时，要把所有权转给买房的人。", "target_word": "所有权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "合同上写清楚了房子的所有权归谁。", "target_word": "所有权", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家公司拥有这些专利的所有权。", "target_word": "所有权", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "法院说这块地的所有权应该归他。", "target_word": "所有权", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "所有權", "label": "繁体"}, {"form": "所有权人", "label": "复合"}], "register": "书面", "sense_fingerprint": "法律上对财产占有、使用、处分的权利", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17ff06e6-d05a-42d0-84b6-f1fd5eae80ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95232, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "颜色", "is_correct": false, "explanation": "语义：颜色不是可以“拥有”的权利，句中指的是房子的产权。"}, {"text": "所有权", "is_correct": true, "explanation": "正确：买房后拥有的是房子的所有权，与上下文相符。"}, {"text": "味道", "is_correct": false, "explanation": "语义：味道不能被“拥有”，与买房后取得的权利不符。"}, {"text": "年龄", "is_correct": false, "explanation": "搭配：年龄多说人或动物，房子要说房龄，不说年龄。"}], "explanations": {"颜色": "语义：颜色不是可以“拥有”的权利，句中指的是房子的产权。", "所有权": "正确：买房后拥有的是房子的所有权，与上下文相符。", "味道": "语义：味道不能被“拥有”，与买房后取得的权利不符。", "年龄": "搭配：年龄多说人或动物，房子要说房龄，不说年龄。"}, "sentence_index": 0, "correct_answer": "所有权"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这栋所有权属于他。", "explanation": "这里应该用〈项〉。所有权是抽象的权利，量词用项，不用栋（栋多用于房屋）。"}, {"text": "他对这块地负有照顾的所有权。", "explanation": "这里应该用〈义务〉。所有权是对财产的权利，对地的照顾要说义务，不能说所有权。"}, {"text": "这个所有权太重了，我搬不动。", "explanation": "这里应该用〈箱子〉。所有权是抽象的权利，没有重量，搬不动的是箱子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70428954-4397-48b4-b49b-6d906a67ae78') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95232, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "感情", "is_correct": false, "explanation": "语义：感情不是可以转让给买房者的东西，句中指的是权利。"}, {"text": "所有权", "is_correct": true, "explanation": "正确：卖房时要转给买房的人的是所有权，与上下文相符。"}, {"text": "名字", "is_correct": false, "explanation": "语义：名字一般不能转让给买房的人，与卖房子无关。"}, {"text": "笑容", "is_correct": false, "explanation": "搭配：“转让”多用于权利、物品，不说转让笑容。"}], "explanations": {"感情": "语义：感情不是可以转让给买房者的东西，句中指的是权利。", "所有权": "正确：卖房时要转给买房的人的是所有权，与上下文相符。", "名字": "语义：名字一般不能转让给买房的人，与卖房子无关。", "笑容": "搭配：“转让”多用于权利、物品，不说转让笑容。"}, "sentence_index": 6, "correct_answer": "所有权"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这颗所有权应该归他。", "explanation": "这里应该用〈项〉。所有权是抽象权利，量词用项，不用颗（颗多用于小而圆的东西）。"}, {"text": "法院说这个孩子的所有权应该归他。", "explanation": "这里应该用〈监护权〉。孩子不能作为财产被拥有，抚养与监护要用监护权，不能说所有权。"}, {"text": "这首所有权应该归他。", "explanation": "这里应该用〈项〉。所有权是抽象权利，量词用项，不用首（首多用于诗歌、歌曲）。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70428954-4397-48b4-b49b-6d906a67ae78') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95232, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "国家所有权这片土地。", "corrected_sentence": "国家拥有这片土地。", "error_description": "词性错误：所有权是名词，不能直接当动词带宾语，这里应该用动词“拥有”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70428954-4397-48b4-b49b-6d906a67ae78') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95232, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "卖房子以后，买房的人就所有权了房子。", "corrected_sentence": "卖房子以后，买房的人就拥有了房子。", "error_description": "词性错误：所有权是名词，不能当动词带“了”和宾语，这里应该用动词“拥有”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70428954-4397-48b4-b49b-6d906a67ae78') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95233, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '181cd7c8-eea7-4335-8e9c-3f32a868aace') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95233, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '181cd7c8-eea7-4335-8e9c-3f32a868aace') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95233, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "做错了事，心里不好意思，要对别人说对不起。", "primary_collocate": null, "pronunciation": "bào qiàn", "ipa": "pɑʊ̯˥˩ tɕʰi̯ɛn˥˩", "syllable_count": 2, "sentences": [{"text": "我做错了事，要对她说抱歉。", "target_word": "抱歉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他踩到我的脚，马上说了声抱歉。", "target_word": "抱歉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我忘了你的生日，真抱歉。", "target_word": "抱歉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我来晚了，抱歉，让大家等我。", "target_word": "抱歉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她不小心撞到人，连忙说抱歉。", "target_word": "抱歉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做错了事，就应该说抱歉。", "target_word": "抱歉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他没有说一句抱歉就走了。", "target_word": "抱歉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "抱歉，我拿错了你的伞。", "target_word": "抱歉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈，我弄丢了你的手机，很抱歉。", "target_word": "抱歉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明骂了同学，老师让他说声抱歉。", "target_word": "抱歉", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "做错事后不好意思，向人说对不起", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f7b11e6-f8b1-44fd-9869-ef9467b2bef7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95233, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "生气", "is_correct": false, "explanation": "搭配：“说生气”不成词组，不能跟“说”搭配作宾语。"}, {"text": "抱歉", "is_correct": true, "explanation": "抱歉：做错了事后向她道歉，“说抱歉”搭配自然，语境相符。"}, {"text": "感谢", "is_correct": false, "explanation": "语义：“做错了事”之后应表示歉意，说“感谢”与句子的语境相反。"}, {"text": "高兴", "is_correct": false, "explanation": "搭配：“说高兴”不成词组，“高兴”不能作为说话的内容。"}], "explanations": {"生气": "搭配：“说生气”不成词组，不能跟“说”搭配作宾语。", "抱歉": "抱歉：做错了事后向她道歉，“说抱歉”搭配自然，语境相符。", "感谢": "语义：“做错了事”之后应表示歉意，说“感谢”与句子的语境相反。", "高兴": "搭配：“说高兴”不成词组，“高兴”不能作为说话的内容。"}, "sentence_index": 0, "correct_answer": "抱歉"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他一直抱歉天气太热，不停地发牢骚。", "explanation": "这里应该用〈抱怨〉。“抱怨”是对不满意的事情发牢骚，“抱歉”表示做错事后心里不安、向人道歉。"}, {"text": "老师当众表扬了我，我觉得很抱歉。", "explanation": "语义：被表扬并没有做错事，不需要道歉，这里应表达高兴。"}, {"text": "今天天气很好，我觉得很抱歉。", "explanation": "这里应该用〈高兴〉。“抱歉”表示做错事而心中不安，对好天气的感受应说“高兴”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '181cd7c8-eea7-4335-8e9c-3f32a868aace') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95233, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "亲热", "is_correct": false, "explanation": "搭配：“亲热”是形容词，“说一句亲热”不成词组，应说“亲热话”。"}, {"text": "着急", "is_correct": false, "explanation": "语义：“着急”表示焦虑，不能作为“说一句”后面的内容，句意说不通。"}, {"text": "抱歉", "is_correct": true, "explanation": "抱歉：他没有说一句道歉的话就走了，“说一句抱歉”搭配自然，语境相符。"}, {"text": "得意", "is_correct": false, "explanation": "语义：“得意”表示自我满足，不能作为“说一句”的内容，句子不通。"}], "explanations": {"亲热": "搭配：“亲热”是形容词，“说一句亲热”不成词组，应说“亲热话”。", "着急": "语义：“着急”表示焦虑，不能作为“说一句”后面的内容，句意说不通。", "抱歉": "抱歉：他没有说一句道歉的话就走了，“说一句抱歉”搭配自然，语境相符。", "得意": "语义：“得意”表示自我满足，不能作为“说一句”的内容，句子不通。"}, "sentence_index": 6, "correct_answer": "抱歉"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈收到我送的花，她很抱歉。", "explanation": "这里应该用〈感动〉。“抱歉”表示做错事后的歉意，收到礼物应表示感动。"}, {"text": "我们班赢得了比赛，同学们都很抱歉。", "explanation": "语义：赢了比赛应当庆祝，不需要道歉，这里“抱歉”的意思不成立。"}, {"text": "这本书的内容很有趣，我读得很抱歉。", "explanation": "语义：有趣的书应表达喜欢或赞赏，“读得很抱歉”没有意义。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '181cd7c8-eea7-4335-8e9c-3f32a868aace') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95233, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把牛奶洒在桌上，马上说了一条抱歉。", "corrected_sentence": "他把牛奶洒在桌上，马上说了声抱歉。", "error_description": "错误：量词用错。表示说道歉的话，要用“声”或“句”，不能用“条”，应说“说了声抱歉”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '181cd7c8-eea7-4335-8e9c-3f32a868aace') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95233, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "弄丢了你的书，我非常很抱歉。", "corrected_sentence": "弄丢了你的书，我非常抱歉。", "error_description": "错误：“抱歉”前面只能用一个程度副词，“非常”和“很”不能连用。应说“非常抱歉”或“很抱歉”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '181cd7c8-eea7-4335-8e9c-3f32a868aace') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
