INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95237, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把一个故事改一改，变成另一种样子。", "primary_collocate": null, "pronunciation": "gǎi biān", "ipa": "kai̯˨˩ pi̯ɛn˥", "syllable_count": 2, "sentences": [{"text": "老师把这个故事改编成了一个短剧。", "target_word": "改编", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想把这个童话改编成一部短片。", "target_word": "改编", "complexity_tier": "T3", "furigana": "wǒ xiǎng bǎ zhè ge tónghuà gǎi biān chéng yí bù duǎnpiàn", "sentence_source": "generated"}, {"text": "他把爷爷讲的故事改编成了歌。", "target_word": "改编", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小故事我改编过两次。", "target_word": "改编", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们改编了《三只小猪》的故事。", "target_word": "改编", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要把课文里的故事改编一下，再演给大家看。", "target_word": "改编", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她喜欢改编古老的民间故事，让孩子们听得更开心。", "target_word": "改编", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个故事太长了，需要改编一下才能演。", "target_word": "改编", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他改编的故事很有意思，同学们都爱听。", "target_word": "改编", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你把这个故事改编得短一点儿。", "target_word": "改编", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "改编了", "label": "体标（了）"}, {"form": "改编过", "label": "体标（过）"}, {"form": "改编版", "label": "复合词"}], "register": "中性", "sense_fingerprint": "把故事改成另一种样子，如童话改成短剧", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ec53b00-6195-460c-9dc7-5a5e3f5ff1e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95237, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "改变", "is_correct": false, "explanation": "biàn（第四声）与 biān（第一声）声调不同，意思是变化。"}, {"text": "改编", "is_correct": true, "explanation": "gǎi biān：把一个故事改一改，变成另一种样子，正确答案。"}, {"text": "改班", "is_correct": false, "explanation": "bān 与 biān 韵母不同（缺少 i），意思是改换班次。"}, {"text": "改天", "is_correct": false, "explanation": "tiān 与 biān 声母不同（t 与 b），意思是改日、另找一天。"}, {"text": "海边", "is_correct": false, "explanation": "hǎi 与 gǎi 声母不同（h 与 g），意思是海边。"}, {"text": "改签", "is_correct": false, "explanation": "qiān 与 biān 声母不同（q 与 b），意思是更改票据或日期。"}], "explanations": {"改变": "biàn（第四声）与 biān（第一声）声调不同，意思是变化。", "改编": "gǎi biān：把一个故事改一改，变成另一种样子，正确答案。", "改班": "bān 与 biān 韵母不同（缺少 i），意思是改换班次。", "改天": "tiān 与 biān 声母不同（t 与 b），意思是改日、另找一天。", "海边": "hǎi 与 gǎi 声母不同（h 与 g），意思是海边。", "改签": "qiān 与 biān 声母不同（q 与 b），意思是更改票据或日期。"}, "sentence_index": null, "correct_answer": "改编"}, "level_3": {"options": [{"text": "改编", "is_correct": true, "explanation": "把一个故事改一改，变成另一种样子，符合“把这个故事……成了一个短剧”。"}, {"text": "染", "is_correct": false, "explanation": "语义：“染”指给物体着色，故事不能染成短剧。"}, {"text": "切", "is_correct": false, "explanation": "搭配：“切成”针对具体实物，不能说把故事切成短剧。"}, {"text": "烧", "is_correct": false, "explanation": "语义：“烧”指用火加热，与把故事变成短剧无关。"}], "explanations": {"改编": "把一个故事改一改，变成另一种样子，符合“把这个故事……成了一个短剧”。", "染": "语义：“染”指给物体着色，故事不能染成短剧。", "切": "搭配：“切成”针对具体实物，不能说把故事切成短剧。", "烧": "语义：“烧”指用火加热，与把故事变成短剧无关。"}, "sentence_index": 0, "correct_answer": "改编"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我把作业改编了三遍。", "explanation": "这里应该用〈修改〉。改编指把一个故事改一改、变成另一种样子，修改作业是改动细节，不能说改编。"}, {"text": "他的性格改编了很多。", "explanation": "这里应该用〈改变〉。改编只用于作品或故事，人的性格变化要说改变。"}, {"text": "妈妈把旧裙子改编成了外套。", "explanation": "这里应该用〈改做〉。改编用于把故事改成另一种样子，旧裙子改做成外套要用改做。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '941e0a09-4e7f-42c2-bcae-44406f5b4567') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95237, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "改编", "is_correct": true, "explanation": "把一个故事改一改，变成另一种样子，符合“她喜欢……古老的民间故事”。"}, {"text": "喝", "is_correct": false, "explanation": "搭配：“喝”的对象是饮品，不能说喝民间故事。"}, {"text": "穿", "is_correct": false, "explanation": "搭配：“穿”的对象是衣物，不能说穿民间故事。"}, {"text": "扔", "is_correct": false, "explanation": "语义：“扔”与“喜欢”及“让孩子们听得更开心”的语境相反。"}], "explanations": {"改编": "把一个故事改一改，变成另一种样子，符合“她喜欢……古老的民间故事”。", "喝": "搭配：“喝”的对象是饮品，不能说喝民间故事。", "穿": "搭配：“穿”的对象是衣物，不能说穿民间故事。", "扔": "语义：“扔”与“喜欢”及“让孩子们听得更开心”的语境相反。"}, "sentence_index": 6, "correct_answer": "改编"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我想把这段英文改编成中文。", "explanation": "这里应该用〈翻译〉。改编指把一个故事改成另一种样子，换语言要用翻译。"}, {"text": "请你把这句话改编一下，别再出错了。", "explanation": "这里应该用〈改正〉。改编指把一个故事改成另一种样子，改正错误要用改正。"}, {"text": "请你把这张照片改编得亮一点儿。", "explanation": "这里应该用〈调整〉。改编只用于依据原作改成新作品，照片亮度调整要用调整。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '941e0a09-4e7f-42c2-bcae-44406f5b4567') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95237, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这位作家把那部旧小说改编了剧本。", "corrected_sentence": "这位作家把那部旧小说改编成了剧本。", "error_description": "“把”字句中“改编”后缺少结果补语“成”。应说“改编成了剧本”，不能直接说“改编了剧本”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '941e0a09-4e7f-42c2-bcae-44406f5b4567') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95237, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师把那个童话改编了成短剧。", "corrected_sentence": "老师把那个童话改编成了短剧。", "error_description": "“了”的位置错了。“改编”后应先接结果补语“成”，再接“了”，说“改编成了短剧”，不能说“改编了成”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '941e0a09-4e7f-42c2-bcae-44406f5b4567') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
