INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95238, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "依据原作加以修改，使之成为新的作品。", "primary_collocate": null, "pronunciation": "gǎi biān", "ipa": "kai̯˨˩ pi̯ɛn˥", "syllable_count": 2, "sentences": [{"text": "这部电影是根据一本小说改编的。", "target_word": "改编", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "导演把那本小说改编成了电视剧。", "target_word": "改编", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部动画改编自一部有名的漫画。", "target_word": "改编", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把自己的小说改编成了电影剧本。", "target_word": "改编", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个电视剧改编得很成功，很多人喜欢。", "target_word": "改编", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这首歌是改编过的，和原来不太一样。", "target_word": "改编", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "作家同意把这本书改编成电影。", "target_word": "改编", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好看的小说常常会改编成电视剧。", "target_word": "改编", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我更喜欢原来的书，不喜欢改编的电影。", "target_word": "改编", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个舞台剧改编自一部老电影。", "target_word": "改编", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "改编了", "label": "体标（了）"}, {"form": "改编过", "label": "体标（过）"}, {"form": "改编版", "label": "复合词"}], "register": "中性", "sense_fingerprint": "依据原作改成新作品，如小说改成电影", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ec53b00-6195-460c-9dc7-5a5e3f5ff1e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95238, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "改变", "is_correct": false, "explanation": "biàn（第四声）与 biān（第一声）声调不同，意思是变化。"}, {"text": "改编", "is_correct": true, "explanation": "gǎi biān：依据原作加以修改，使之成为新的作品，正确答案。"}, {"text": "改班", "is_correct": false, "explanation": "bān 与 biān 韵母不同（缺少 i），意思是改换班次。"}, {"text": "改天", "is_correct": false, "explanation": "tiān 与 biān 声母不同（t 与 b），意思是改日、另找一天。"}, {"text": "海边", "is_correct": false, "explanation": "hǎi 与 gǎi 声母不同（h 与 g），意思是海边。"}, {"text": "改签", "is_correct": false, "explanation": "qiān 与 biān 声母不同（q 与 b），意思是更改票据或日期。"}], "explanations": {"改变": "biàn（第四声）与 biān（第一声）声调不同，意思是变化。", "改编": "gǎi biān：依据原作加以修改，使之成为新的作品，正确答案。", "改班": "bān 与 biān 韵母不同（缺少 i），意思是改换班次。", "改天": "tiān 与 biān 声母不同（t 与 b），意思是改日、另找一天。", "海边": "hǎi 与 gǎi 声母不同（h 与 g），意思是海边。", "改签": "qiān 与 biān 声母不同（q 与 b），意思是更改票据或日期。"}, "sentence_index": null, "correct_answer": "改编"}, "level_3": {"options": [{"text": "改编", "is_correct": true, "explanation": "依据原作改成新作品，符合“这部电影是根据一本小说……的”。"}, {"text": "买", "is_correct": false, "explanation": "语义：“买”指购买，电影不能说是根据小说买的。"}, {"text": "印", "is_correct": false, "explanation": "语义：“印”指印刷，电影不是根据小说印出来的。"}, {"text": "切", "is_correct": false, "explanation": "搭配：“切”针对具体实物，不能说根据小说切的。"}], "explanations": {"改编": "依据原作改成新作品，符合“这部电影是根据一本小说……的”。", "买": "语义：“买”指购买，电影不能说是根据小说买的。", "印": "语义：“印”指印刷，电影不是根据小说印出来的。", "切": "搭配：“切”针对具体实物，不能说根据小说切的。"}, "sentence_index": 0, "correct_answer": "改编"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把这本书的错字改编了两次。", "explanation": "这里应该用〈修订〉。改编指依据原作另成新作品，改正书中的错字要用修订。"}, {"text": "他把旧椅子改编成了书架。", "explanation": "这里应该用〈改做〉。改编用于依据原作改成新作品，旧椅子改做成书架要用改做。"}, {"text": "这座旧工厂改编成了商场。", "explanation": "这里应该用〈改造〉。改编用于作品，旧工厂改成商场要用改造。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '941e0a09-4e7f-42c2-bcae-44406f5b4567') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95238, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "改编", "is_correct": true, "explanation": "依据原作改成新作品，符合“作家同意把这本书……成电影”。"}, {"text": "缝", "is_correct": false, "explanation": "语义：“缝”指用针线连缀，书不能缝成电影。"}, {"text": "烧", "is_correct": false, "explanation": "语义：“烧”指用火加热，与把书变成电影不符。"}, {"text": "煮", "is_correct": false, "explanation": "搭配：“煮成”针对食物，书不能煮成电影。"}], "explanations": {"改编": "依据原作改成新作品，符合“作家同意把这本书……成电影”。", "缝": "语义：“缝”指用针线连缀，书不能缝成电影。", "烧": "语义：“烧”指用火加热，与把书变成电影不符。", "煮": "搭配：“煮成”针对食物，书不能煮成电影。"}, "sentence_index": 6, "correct_answer": "改编"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我想把这份资料改编成英文。", "explanation": "这里应该用〈翻译〉。改编指依据原作改成新作品，换语言要用翻译。"}, {"text": "这间房子改编成了书房。", "explanation": "这里应该用〈改造〉。改编只用于依据原作改成新作品，把房间改成书房要用改造。"}, {"text": "我把这条裤子改编得短了一点儿。", "explanation": "这里应该用〈修改〉。改编用于依据原作改成新作品，裤子改短要用修改。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '941e0a09-4e7f-42c2-bcae-44406f5b4567') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95238, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她把旧小说改编了广播剧。", "corrected_sentence": "她把旧小说改编成了广播剧。", "error_description": "“把”字句中“改编”后缺少结果补语“成”。应说“改编成了广播剧”，不能直接说“改编了广播剧”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '941e0a09-4e7f-42c2-bcae-44406f5b4567') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95238, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这部小说改编了成一部话剧。", "corrected_sentence": "这部小说改编成了一部话剧。", "error_description": "“了”的位置错了。“成”是“改编”的结果补语，“了”应放在“成”之后，说“改编成了一部话剧”，不能说“改编了成”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '941e0a09-4e7f-42c2-bcae-44406f5b4567') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
