INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95239, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "数出来的确切个数，即有几个。", "primary_collocate": null, "pronunciation": "shù mù", "ipa": "ʂu˥˩ mu˥˩", "syllable_count": 2, "sentences": [{"text": "请先数一数，看看数目对不对。", "target_word": "数目", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个数目我记不住。", "target_word": "数目", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "来参加会议的人，数目比去年多。", "target_word": "数目", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "箱子里苹果的数目是二十个。", "target_word": "数目", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说错了数目，所以多买了东西。", "target_word": "数目", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你知道准确的数目吗？", "target_word": "数目", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把数目写在这张纸上。", "target_word": "数目", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "账上的数目和钱包里的不一样。", "target_word": "数目", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明数了一下，数目是八个。", "target_word": "数目", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师问全班同学的数目。", "target_word": "数目", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "数出来的具体个数、多少（名词）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4747408d-1a98-454a-a674-44dda78aa04a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95239, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "数目", "is_correct": true, "explanation": "正确答案。数目（shù mù）指有几个、有多少。"}, {"text": "书目", "is_correct": false, "explanation": "shū（第一声）与 shù（第四声）声调不同，意思是书的目录。"}, {"text": "注目", "is_correct": false, "explanation": "zhù（第四声）与 shù 声母不同（zh 与 sh），意思是注意、看。"}, {"text": "触目", "is_correct": false, "explanation": "chù（第四声）与 shù 声母不同（ch 与 sh），意思是容易引起注意。"}, {"text": "肃穆", "is_correct": false, "explanation": "sù（第四声）与 shù 声母不同（s 与 sh），意思是庄严、安静。"}], "explanations": {"数目": "正确答案。数目（shù mù）指有几个、有多少。", "书目": "shū（第一声）与 shù（第四声）声调不同，意思是书的目录。", "注目": "zhù（第四声）与 shù 声母不同（zh 与 sh），意思是注意、看。", "触目": "chù（第四声）与 shù 声母不同（ch 与 sh），意思是容易引起注意。", "肃穆": "sù（第四声）与 shù 声母不同（s 与 sh），意思是庄严、安静。"}, "sentence_index": null, "correct_answer": "数目"}, "level_3": {"options": [{"text": "数目", "is_correct": true, "explanation": "正确。“数一数，看看数目对不对”指检查数出来的个数。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不能数，“数一数”后面接“天气”说不通。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：脾气不能一个一个数。"}, {"text": "风景", "is_correct": false, "explanation": "搭配：“数一数”要求对象可以数，风景不能这样数。"}], "explanations": {"数目": "正确。“数一数，看看数目对不对”指检查数出来的个数。", "天气": "语义：天气不能数，“数一数”后面接“天气”说不通。", "脾气": "语义：脾气不能一个一个数。", "风景": "搭配：“数一数”要求对象可以数，风景不能这样数。"}, "sentence_index": 0, "correct_answer": "数目"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这桶水的数目很多。", "explanation": "这里应该用〈数量〉。数目指可以一个一个数的个数，水不能一个一个数，应该说数量。"}, {"text": "我忘了他的电话数目。", "explanation": "这里应该用〈号码〉。数目指有多少，不能指电话的号码。"}, {"text": "这只数目太大了。", "explanation": "这里应该用〈个〉。数目不用“只”计量，“只”用于动物、成对或单个的物件。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '293ba40b-5c94-4f9c-adcb-2dc4aaba108d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95239, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "数目", "is_correct": true, "explanation": "正确。“请把数目写在这张纸上”指把数出来的个数写下来。"}, {"text": "阳光", "is_correct": false, "explanation": "语义：阳光不能被写在纸上。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空不能被写在纸上，句子说不通。"}, {"text": "声音", "is_correct": false, "explanation": "搭配：声音要用“录”，不用“写”。"}], "explanations": {"数目": "正确。“请把数目写在这张纸上”指把数出来的个数写下来。", "阳光": "语义：阳光不能被写在纸上。", "天空": "语义：天空不能被写在纸上，句子说不通。", "声音": "搭配：声音要用“录”，不用“写”。"}, "sentence_index": 6, "correct_answer": "数目"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这箱苹果的数目是十公斤。", "explanation": "这里应该用〈重量〉。数目是个数，不能用来说多少公斤。"}, {"text": "这件衣服的数目很贵。", "explanation": "这里应该用〈价格〉。数目指数量，不能用来说东西贵不贵。"}, {"text": "这张数目太大了。", "explanation": "这里应该用〈个〉。“张”用于纸、桌子等平面的东西，数目不用“张”计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '293ba40b-5c94-4f9c-adcb-2dc4aaba108d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95239, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "请你再核对一只数目，看看有没有错。", "corrected_sentence": "请你再核对一个数目，看看有没有错。", "error_description": "“数目”的量词用“个”，不用“只”，应说“一个数目”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '293ba40b-5c94-4f9c-adcb-2dc4aaba108d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95239, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "参加活动的人，数目们比去年多。", "corrected_sentence": "参加活动的人，数目比去年多。", "error_description": "“数目”是抽象名词，不能加“们”表示复数，应去掉“们”，说“数目比去年多”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '293ba40b-5c94-4f9c-adcb-2dc4aaba108d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
