INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95240, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "事物的数量。", "primary_collocate": null, "pronunciation": "shù mù", "ipa": "ʂu˥˩ mu˥˩", "syllable_count": 2, "sentences": [{"text": "这个城市的图书馆数目很多。", "target_word": "数目", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校里树的数目一年比一年多。", "target_word": "数目", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "参加比赛的队伍数目增加了。", "target_word": "数目", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "超市里商品的数目很大。", "target_word": "数目", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个月游客的数目减少了很多。", "target_word": "数目", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书的数目不够，有的同学没有。", "target_word": "数目", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路上汽车的数目越来越多。", "target_word": "数目", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为天气不好，来的客人数目很少。", "target_word": "数目", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请别买太多，数目够用就好。", "target_word": "数目", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "动物园里熊猫的数目不多。", "target_word": "数目", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "事物数量的多少大小（名词）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4747408d-1a98-454a-a674-44dda78aa04a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95240, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "数目", "is_correct": true, "explanation": "正确答案。数目（shù mù）指事物的数量。"}, {"text": "书目", "is_correct": false, "explanation": "shū（第一声）与 shù（第四声）声调不同，意思是书的目录。"}, {"text": "注目", "is_correct": false, "explanation": "zhù（第四声）与 shù 声母不同（zh 与 sh），意思是注意、看。"}, {"text": "触目", "is_correct": false, "explanation": "chù（第四声）与 shù 声母不同（ch 与 sh），意思是容易引起注意。"}, {"text": "肃穆", "is_correct": false, "explanation": "sù（第四声）与 shù 声母不同（s 与 sh），意思是庄严、安静。"}], "explanations": {"数目": "正确答案。数目（shù mù）指事物的数量。", "书目": "shū（第一声）与 shù（第四声）声调不同，意思是书的目录。", "注目": "zhù（第四声）与 shù 声母不同（zh 与 sh），意思是注意、看。", "触目": "chù（第四声）与 shù 声母不同（ch 与 sh），意思是容易引起注意。", "肃穆": "sù（第四声）与 shù 声母不同（s 与 sh），意思是庄严、安静。"}, "sentence_index": null, "correct_answer": "数目"}, "level_3": {"options": [{"text": "数目", "is_correct": true, "explanation": "正确。“图书馆数目很多”指这个城市图书馆的数量多。"}, {"text": "高度", "is_correct": false, "explanation": "搭配：“高度”说“高”，不说“多”。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：年龄不是可以计数的东西，不能说“很多”。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：脾气不能用“很多”来形容。"}], "explanations": {"数目": "正确。“图书馆数目很多”指这个城市图书馆的数量多。", "高度": "搭配：“高度”说“高”，不说“多”。", "年龄": "语义：年龄不是可以计数的东西，不能说“很多”。", "脾气": "语义：脾气不能用“很多”来形容。"}, "sentence_index": 0, "correct_answer": "数目"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的电话数目很长。", "explanation": "这里应该用〈号码〉。数目指事物的数量，不能用来说电话号码有多长。"}, {"text": "这件衣服的数目很高。", "explanation": "这里应该用〈价格〉。数目指事物的数量，不能用来说衣服的价格高低。"}, {"text": "这只数目很大。", "explanation": "这里应该用〈个〉。数目不用“只”计量，“只”用于动物或单个的物件。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '293ba40b-5c94-4f9c-adcb-2dc4aaba108d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95240, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "数目", "is_correct": true, "explanation": "正确。“汽车的数目越来越多”指路上汽车的数量增加。"}, {"text": "车速", "is_correct": false, "explanation": "搭配：车速说“快”或“慢”，不说“多”。"}, {"text": "亮度", "is_correct": false, "explanation": "语义：亮度是程度，不能计数，不能说“越来越多”。"}, {"text": "温度", "is_correct": false, "explanation": "搭配：温度说“高”或“低”，不说“多”。"}], "explanations": {"数目": "正确。“汽车的数目越来越多”指路上汽车的数量增加。", "车速": "搭配：车速说“快”或“慢”，不说“多”。", "亮度": "语义：亮度是程度，不能计数，不能说“越来越多”。", "温度": "搭配：温度说“高”或“低”，不说“多”。"}, "sentence_index": 6, "correct_answer": "数目"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的数目有一米八。", "explanation": "这里应该用〈身高〉。数目指事物的数量，人的身高不能用数目来说。"}, {"text": "这箱苹果的数目很重。", "explanation": "这里应该用〈重量〉。数目指数量，不能说有多重。"}, {"text": "这张数目很大。", "explanation": "这里应该用〈个〉。“张”用于纸、桌子等平面的东西，数目不用“张”计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '293ba40b-5c94-4f9c-adcb-2dc4aaba108d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95240, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个城市的公园数目们很多。", "corrected_sentence": "这个城市的公园数目很多。", "error_description": "“数目”是抽象名词，不能加“们”表示复数，应去掉“们”，说“数目很多”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '293ba40b-5c94-4f9c-adcb-2dc4aaba108d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95240, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个月的游客一种数目减少了。", "corrected_sentence": "这个月的游客数目减少了。", "error_description": "“数目”前不能加“一种”，这里不需要量词，应去掉“一种”，说“游客数目”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '293ba40b-5c94-4f9c-adcb-2dc4aaba108d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
