INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95241, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "历史上从某年到某年的一段日子。", "primary_collocate": null, "pronunciation": "lì shǐ shí qī", "ipa": "li˥˩ ʂɻ̩˨˩˦ ʂɻ̩˧˥ tɕʰi˥", "syllable_count": 4, "sentences": [{"text": "那个历史时期，人们的生活很苦。", "target_word": "历史时期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个历史时期大约有一百年。", "target_word": "历史时期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们讲了这个历史时期的故事。", "target_word": "历史时期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个历史时期是从一九一二年到一九四九年。", "target_word": "历史时期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷常说起他经历过的那个历史时期。", "target_word": "历史时期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书里写了三个不同的历史时期。", "target_word": "历史时期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你说说这个历史时期的大事。", "target_word": "历史时期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个历史时期的人没有电视。", "target_word": "历史时期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张地图是那个历史时期画的。", "target_word": "历史时期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "博物馆里有这个历史时期的东西。", "target_word": "历史时期", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "歷史時期", "label": "繁体"}, {"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "过去从某年到某年的一段时间", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cbe411f-991a-416c-a28b-6dca83adf8ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95241, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "历史时期", "is_correct": true, "explanation": "“历史时期”指很久以前从某年到某年的一段日子，与“那个……人们的生活很苦”相合。"}, {"text": "食物", "is_correct": false, "explanation": "语义：“食物”不指一段时间，“那个食物”无法表示时段。"}, {"text": "节日", "is_correct": false, "explanation": "语义：“节日”指某一天，不是一段时间，与后句描述的生活状况不合。"}, {"text": "年龄", "is_correct": false, "explanation": "搭配：“年龄”指人的岁数，不能用“那个年龄”指一段生活很苦的时期。"}], "explanations": {"历史时期": "“历史时期”指很久以前从某年到某年的一段日子，与“那个……人们的生活很苦”相合。", "食物": "语义：“食物”不指一段时间，“那个食物”无法表示时段。", "节日": "语义：“节日”指某一天，不是一段时间，与后句描述的生活状况不合。", "年龄": "搭配：“年龄”指人的岁数，不能用“那个年龄”指一段生活很苦的时期。"}, "sentence_index": 0, "correct_answer": "历史时期"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "孙中山是一个重要的历史时期。", "explanation": "这里应该用〈人物〉。“历史时期”指一段时间，不能指人。"}, {"text": "故宫是一个著名的历史时期。", "explanation": "这里应该用〈景点〉。“历史时期”指一段时间，故宫是地点，应说“历史景点”。"}, {"text": "他擦掉了这个历史时期。", "explanation": "这里应该用〈污渍〉。“历史时期”是抽象的时段，不能被擦掉，擦掉要说“擦掉污渍”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12927d7c-59d1-40f3-ad1f-89500df274f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95241, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "历史时期", "is_correct": true, "explanation": "“历史时期”指历史上的一段时间，与“请你说说这个……的大事”相合。"}, {"text": "地图", "is_correct": false, "explanation": "语义：“地图”不会有“大事”，且不指历史上的时段。"}, {"text": "作业", "is_correct": false, "explanation": "语义：“作业”是学习任务，不是历史上的一段时间，不能说“大事”。"}, {"text": "味道", "is_correct": false, "explanation": "搭配：“味道”与“大事”搭配不当，句子不通。"}], "explanations": {"历史时期": "“历史时期”指历史上的一段时间，与“请你说说这个……的大事”相合。", "地图": "语义：“地图”不会有“大事”，且不指历史上的时段。", "作业": "语义：“作业”是学习任务，不是历史上的一段时间，不能说“大事”。", "味道": "搭配：“味道”与“大事”搭配不当，句子不通。"}, "sentence_index": 6, "correct_answer": "历史时期"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的历史时期很高。", "explanation": "这里应该用〈个子〉。“历史时期”是时间段，不能用“很高”形容人的身高。"}, {"text": "我已经吃过历史时期了。", "explanation": "这里应该用〈饭〉。“历史时期”不能被吃，应说“吃过饭”。"}, {"text": "他打了一个历史时期。", "explanation": "这里应该用〈电话〉。“历史时期”不能被打，应说“打电话”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12927d7c-59d1-40f3-ad1f-89500df274f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95241, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那条历史时期的人们很少出门。", "corrected_sentence": "那个历史时期的人们很少出门。", "error_description": "错误：量词“条”。正确：“个”。“历史时期”是抽象的时段，量词用“个”，“条”用于细长的东西。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12927d7c-59d1-40f3-ad1f-89500df274f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95241, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们生活这个历史时期，经历了很多变化。", "corrected_sentence": "我们生活在这个历史时期，经历了很多变化。", "error_description": "错误：缺少“在”。正确：“生活在”。表示身处某段时期，动词“生活”后要用“在”引出时段。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12927d7c-59d1-40f3-ad1f-89500df274f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
