INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95242, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "历史上具有某种特点的一段时间。", "primary_collocate": null, "pronunciation": "lì shǐ shí qī", "ipa": "li˥˩ ʂɻ̩˨˩˦ ʂɻ̩˧˥ tɕʰi˥", "syllable_count": 4, "sentences": [{"text": "那是一个战争不断的历史时期。", "target_word": "历史时期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个历史时期，国家特别需要人才。", "target_word": "历史时期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个历史时期都有自己的特点。", "target_word": "历史时期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们生活在一个很特别的历史时期。", "target_word": "历史时期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在这个历史时期，很多人离开了农村。", "target_word": "历史时期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个历史时期以和平为主。", "target_word": "历史时期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是中国变化最快的历史时期。", "target_word": "历史时期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书中写了一个人们不太自由的历史时期。", "target_word": "历史时期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在不同的历史时期，大家喜欢的衣服不一样。", "target_word": "历史时期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "明朝末年是一个动荡不安的历史时期。", "target_word": "历史时期", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "歷史時期", "label": "繁体"}, {"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "历史上有某种特点的一段时间", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cbe411f-991a-416c-a28b-6dca83adf8ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95242, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "历史时期", "is_correct": true, "explanation": "“历史时期”指历史上具有某种特点的一段时间，与“战争不断”相合。"}, {"text": "礼物", "is_correct": false, "explanation": "语义：“礼物”是送人的东西，不指历史上的时段。"}, {"text": "节日", "is_correct": false, "explanation": "语义：“节日”指某一天，“战争不断的节日”句义不通。"}, {"text": "年纪", "is_correct": false, "explanation": "搭配：“年纪”指人的岁数，不能说“战争不断的年纪”。"}], "explanations": {"历史时期": "“历史时期”指历史上具有某种特点的一段时间，与“战争不断”相合。", "礼物": "语义：“礼物”是送人的东西，不指历史上的时段。", "节日": "语义：“节日”指某一天，“战争不断的节日”句义不通。", "年纪": "搭配：“年纪”指人的岁数，不能说“战争不断的年纪”。"}, "sentence_index": 0, "correct_answer": "历史时期"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他是一个很特别的历史时期。", "explanation": "这里应该用〈朋友〉。“历史时期”指时间段，不能指人。"}, {"text": "他吃了一个很特别的历史时期。", "explanation": "这里应该用〈苹果〉。“历史时期”不能被吃，应说“苹果”。"}, {"text": "他会弹一种很特别的历史时期。", "explanation": "这里应该用〈乐器〉。“历史时期”不能被演奏，应说“乐器”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12927d7c-59d1-40f3-ad1f-89500df274f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95242, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "历史时期", "is_correct": true, "explanation": "“历史时期”指历史上有某种特点的时段，与“变化最快”相合。"}, {"text": "手指", "is_correct": false, "explanation": "语义：“手指”是身体部位，不能指一段历史时期。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：“窗户”是建筑部件，不能指历史上的时段。"}, {"text": "声音", "is_correct": false, "explanation": "搭配：“中国变化最快的声音”搭配生硬，不能用来指一段历史时期。"}], "explanations": {"历史时期": "“历史时期”指历史上有某种特点的时段，与“变化最快”相合。", "手指": "语义：“手指”是身体部位，不能指一段历史时期。", "窗户": "语义：“窗户”是建筑部件，不能指历史上的时段。", "声音": "搭配：“中国变化最快的声音”搭配生硬，不能用来指一段历史时期。"}, "sentence_index": 6, "correct_answer": "历史时期"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他买了一个历史时期。", "explanation": "这里应该用〈电视〉。“历史时期”是时间段，不能购买，应说“买电视”。"}, {"text": "他穿上了一个历史时期。", "explanation": "这里应该用〈衣服〉。“历史时期”不能穿，应说“穿衣服”。"}, {"text": "他修好了一个历史时期。", "explanation": "这里应该用〈自行车〉。“历史时期”不能修，应说“修自行车”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12927d7c-59d1-40f3-ad1f-89500df274f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95242, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那是一个很特别历史时期，大家都很怀念。", "corrected_sentence": "那是一个很特别的历史时期，大家都很怀念。", "error_description": "错误：“很特别历史时期”，缺少“的”。正确：“很特别的历史时期”。形容词修饰名词时，中间要加“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12927d7c-59d1-40f3-ad1f-89500df274f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95242, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "在那条历史时期，很多工厂都关门了。", "corrected_sentence": "在那个历史时期，很多工厂都关门了。", "error_description": "错误：量词“条”。正确：“个”。“历史时期”是抽象的时段，量词用“个”，“条”用于细长的东西。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12927d7c-59d1-40f3-ad1f-89500df274f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
