INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95243, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b0d75e0-6e6b-44b8-a337-cd25b194b54f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95243, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "人或动物没有了呼吸，不会再动了。", "primary_collocate": null, "pronunciation": "sǐ qù", "ipa": "sɹ̩˨˩ tɕʰy˥˩", "syllable_count": 2, "sentences": [{"text": "小鸟掉在地上，已经死去了。", "target_word": "死去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那条鱼死去了，一动不动。", "target_word": "死去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我发现小猫躺着，已经死去了。", "target_word": "死去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说，这只狗已经死去了。", "target_word": "死去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老鼠一动不动，好像死去了。", "target_word": "死去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "池塘里有几条死去的鱼。", "target_word": "死去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他摸了摸小鸟，它早就死去了。", "target_word": "死去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "树下躺着一只死去的鸟。", "target_word": "死去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那只兔子死去了，不再呼吸。", "target_word": "死去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他看着死去的小狗，哭了。", "target_word": "死去", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "死去了", "label": "体标：了"}, {"form": "死去过", "label": "体标：过"}, {"form": "死去的", "label": "定语形式"}], "register": "中性", "sense_fingerprint": "没有呼吸，不再动，多指动物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc8986b3-b2f6-4123-8222-d26c9cd9393b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95243, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "死去", "is_correct": true, "explanation": "死去：没有了呼吸，符合句意。"}, {"text": "融化", "is_correct": false, "explanation": "语义：“融化”指冰雪由固态变成液态，不能用于小鸟。"}, {"text": "生锈", "is_correct": false, "explanation": "搭配：“生锈”用于金属，不能用于小鸟。"}, {"text": "开花", "is_correct": false, "explanation": "搭配：“开花”用于植物，不能用于小鸟。"}], "explanations": {"死去": "死去：没有了呼吸，符合句意。", "融化": "语义：“融化”指冰雪由固态变成液态，不能用于小鸟。", "生锈": "搭配：“生锈”用于金属，不能用于小鸟。", "开花": "搭配：“开花”用于植物，不能用于小鸟。"}, "sentence_index": 0, "correct_answer": "死去"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台电脑已经死去了。", "explanation": "这里应该用〈死机〉。死去只用于人或动物，电脑不再响应要说死机。"}, {"text": "这把椅子已经死去了。", "explanation": "这里应该用〈损坏〉。死去只用于人或动物，椅子坏了要说损坏。"}, {"text": "这台打印机已经死去了。", "explanation": "这里应该说〈坏了〉。死去只用于人或动物，打印机坏了要说坏了。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b0d75e0-6e6b-44b8-a337-cd25b194b54f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95243, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "死去", "is_correct": true, "explanation": "死去：没有了呼吸，符合句意。"}, {"text": "生根", "is_correct": false, "explanation": "搭配：“生根”用于植物，不能用于小鸟。"}, {"text": "发芽", "is_correct": false, "explanation": "搭配：“发芽”用于植物或种子，不能用于小鸟。"}, {"text": "点燃", "is_correct": false, "explanation": "语义：“点燃”指使物体燃烧，与小鸟的状态无关。"}], "explanations": {"死去": "死去：没有了呼吸，符合句意。", "生根": "搭配：“生根”用于植物，不能用于小鸟。", "发芽": "搭配：“发芽”用于植物或种子，不能用于小鸟。", "点燃": "语义：“点燃”指使物体燃烧，与小鸟的状态无关。"}, "sentence_index": 6, "correct_answer": "死去"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这只狗每天都死去。", "explanation": "这里应该用〈醒来〉。死去是一次性的结束，不能每天重复发生。"}, {"text": "那只鸟死去了，又飞了起来。", "explanation": "这里不能用〈死去〉。“死去”表示没有了呼吸、不会再动，与“又飞了起来”矛盾，这里应该说〈昏倒〉。"}, {"text": "那辆自行车昨天死去了。", "explanation": "这里应该用〈坏了〉。死去只用于人或动物，自行车坏了要说坏了。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b0d75e0-6e6b-44b8-a337-cd25b194b54f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95243, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "池塘边有一只死去鸭子。", "corrected_sentence": "池塘边有一只死去的鸭子。", "error_description": "“死去”作定语时要加“的”。应说“死去的鸭子”，省掉“的”则不合语法。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b0d75e0-6e6b-44b8-a337-cd25b194b54f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95243, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那只小狗昨晚死去着。", "corrected_sentence": "那只小狗昨晚死去了。", "error_description": "错误：“着”用错。“死去”表示动作已经完成，应说“死去了”，不能说“死去着”；“着”表示动作持续的状态，与此处不符。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b0d75e0-6e6b-44b8-a337-cd25b194b54f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
