INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95247, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "两块陆地中间，一条窄窄的海。", "primary_collocate": null, "pronunciation": "hǎi xiá", "ipa": "xai̯˧ ɕja˧˥", "syllable_count": 2, "sentences": [{"text": "这条海峡很窄，船可以很快过去。", "target_word": "海峡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海峡两边都是山。", "target_word": "海峡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们坐船过海峡，用了一个小时。", "target_word": "海峡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个海峡中间有一个小岛。", "target_word": "海峡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海峡里的风很大，船走得很慢。", "target_word": "海峡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从地图上看，海峡像一条蓝色的线。", "target_word": "海峡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小船在海峡里慢慢地走着。", "target_word": "海峡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海峡的一边是岛，一边是大陆。", "target_word": "海峡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "渔民每天在海峡里打鱼。", "target_word": "海峡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座岛和大陆之间有一条海峡。", "target_word": "海峡", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "海峽", "label": "繁体"}], "register": "中性", "sense_fingerprint": "两块陆地之间窄窄的一片海", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad1d3580-2f81-4f34-89f3-d63ae05c6f1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95247, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "路", "is_correct": false, "explanation": "语义：“路”在陆地上，船不能从路上过去，与后半句“船可以很快过去”矛盾。"}, {"text": "海峡", "is_correct": true, "explanation": "正确：“海峡”是窄窄的水道，与“很窄，船可以很快过去”一致。"}, {"text": "裙子", "is_correct": false, "explanation": "搭配：“裙子”可以“窄”，但“船可以很快过去”的主语不能是裙子。"}, {"text": "围巾", "is_correct": false, "explanation": "语义：“围巾”是布料，船不能从围巾中过去，与后半句矛盾。"}], "explanations": {"路": "语义：“路”在陆地上，船不能从路上过去，与后半句“船可以很快过去”矛盾。", "海峡": "正确：“海峡”是窄窄的水道，与“很窄，船可以很快过去”一致。", "裙子": "搭配：“裙子”可以“窄”，但“船可以很快过去”的主语不能是裙子。", "围巾": "语义：“围巾”是布料，船不能从围巾中过去，与后半句矛盾。"}, "sentence_index": 0, "correct_answer": "海峡"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个海峡三面都是山，只有一个口子通向大海。", "explanation": "这里应该用〈海湾〉。海湾是伸入陆地的一段海，三面环陆、只有一个口子通海；海峡是连接两片海的窄水道，两端都通海。"}, {"text": "这条海峡很长，流进了大海。", "explanation": "这里应该用〈河流〉。河流有源头，最后流入大海；海峡是两片海之间的水道，不会流进大海。"}, {"text": "这条海峡两岸都是高山，河水从谷底缓缓流过。", "explanation": "这里应该用〈峡谷〉。峡谷是两侧高山夹着的谷地，中间有河流流过；海峡是连通两片海的水道，谷底没有河流。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c344b1a-6ec0-49b7-9dc7-d529462b5f32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95247, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "沙漠", "is_correct": false, "explanation": "语义：沙漠是干燥的陆地，小船不能在里面行驶。"}, {"text": "教室", "is_correct": false, "explanation": "语义：教室是室内空间，与“小船慢慢地走着”不合。"}, {"text": "海峡", "is_correct": true, "explanation": "正确：“海峡”是水道，小船在水道里慢慢行进，与句意一致。"}, {"text": "天空", "is_correct": false, "explanation": "搭配：“在天空里”不能与“慢慢地走着”搭配，船不会在天空中行进。"}], "explanations": {"沙漠": "语义：沙漠是干燥的陆地，小船不能在里面行驶。", "教室": "语义：教室是室内空间，与“小船慢慢地走着”不合。", "海峡": "正确：“海峡”是水道，小船在水道里慢慢行进，与句意一致。", "天空": "搭配：“在天空里”不能与“慢慢地走着”搭配，船不会在天空中行进。"}, "sentence_index": 6, "correct_answer": "海峡"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "眼前的海峡无边无际，一眼望不到头。", "explanation": "这里应该用〈大海〉。大海广阔无边；海峡是窄窄的水道，不能形容无边无际。"}, {"text": "这个海峡是货船停靠、装卸货物的地方。", "explanation": "这里应该用〈港口〉。港口是船停靠、装卸货物的地方；海峡只是供船通过的水道，不是停靠地。"}, {"text": "这个海峡很长，游客都爱来这里晒太阳。", "explanation": "这里应该用〈海滩〉。海滩是沿海的沙质陆地，供人游泳、晒太阳；海峡是连通两片海的水道，人不能在上面晒太阳。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c344b1a-6ec0-49b7-9dc7-d529462b5f32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95247, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们每天坐船穿过这座海峡去对岸上学。", "corrected_sentence": "我们每天坐船穿过这条海峡去对岸上学。", "error_description": "错误形式是“这座海峡”，正确形式是“这条海峡”。“海峡”是细长的水道，量词应用“条”，“座”多用于山、岛等。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c344b1a-6ec0-49b7-9dc7-d529462b5f32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95247, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "渔船海峡上慢慢地行驶。", "corrected_sentence": "渔船在海峡上慢慢地行驶。", "error_description": "错误形式是“渔船海峡上”，正确形式是“渔船在海峡上”。表示地点的“海峡上”前面要用介词“在”，不能省略。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c344b1a-6ec0-49b7-9dc7-d529462b5f32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
