INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95248, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c344b1a-6ec0-49b7-9dc7-d529462b5f32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95248, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "两块陆地之间连通两片海域的狭窄水道。", "primary_collocate": null, "pronunciation": "hǎi xiá", "ipa": "xai̯˧ ɕja˧˥", "syllable_count": 2, "sentences": [{"text": "这条海峡连着两片海，很多船从这里过。", "target_word": "海峡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大船要通过海峡，才能去另一片海。", "target_word": "海峡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海峡是两片海之间的水道。", "target_word": "海峡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条海峡连通两片海，船很多。", "target_word": "海峡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "货船每天经过这条海峡。", "target_word": "海峡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条海峡很窄，大船要小心。", "target_word": "海峡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有这条海峡，两片海就不能相通。", "target_word": "海峡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了安全，船在海峡里要慢慢开。", "target_word": "海峡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个海峡对海上运输很重要。", "target_word": "海峡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们坐船穿过海峡，到了另一片海。", "target_word": "海峡", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "海峽", "label": "繁体"}], "register": "中性", "sense_fingerprint": "连通两片海域、供船通行的狭窄水道", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad1d3580-2f81-4f34-89f3-d63ae05c6f1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95248, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "河", "is_correct": false, "explanation": "语义：河流大多只注入一片海，不会“连着两片海”，与“船从这里过”也不合。"}, {"text": "山脉", "is_correct": false, "explanation": "语义：“山脉”是连绵的山，不是水道，船不能从这里过。"}, {"text": "海峡", "is_correct": true, "explanation": "正确：“海峡”是连通两片海的水道，与“连着两片海，很多船从这里过”一致。"}, {"text": "绳子", "is_correct": false, "explanation": "搭配：“绳子”可以“连”，但不能与“连着两片海”搭配。"}], "explanations": {"河": "语义：河流大多只注入一片海，不会“连着两片海”，与“船从这里过”也不合。", "山脉": "语义：“山脉”是连绵的山，不是水道，船不能从这里过。", "海峡": "正确：“海峡”是连通两片海的水道，与“连着两片海，很多船从这里过”一致。", "绳子": "搭配：“绳子”可以“连”，但不能与“连着两片海”搭配。"}, "sentence_index": 0, "correct_answer": "海峡"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这条海峡是古人挖的，连通了南北两条河。", "explanation": "这里应该用〈运河〉。运河是人工开凿、连通河流的水道；海峡连通的是两片海。"}, {"text": "这个海峡被陆地包围，没有出口。", "explanation": "这里应该用〈湖泊〉。湖泊四面是陆地，没有通向海的出口；海峡两端都连着大海。"}, {"text": "这条海峡沙子很细，孩子们在上面堆沙堡。", "explanation": "这里应该用〈海滩〉。海滩是沙子铺成的岸边，人可以在上面堆沙堡；海峡是水道，不是沙地。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c344b1a-6ec0-49b7-9dc7-d529462b5f32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95248, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "道路", "is_correct": false, "explanation": "语义：道路在陆地上，不能让两片海相通。"}, {"text": "铁路", "is_correct": false, "explanation": "语义：铁路是陆上交通线，与“两片海相通”无关。"}, {"text": "海峡", "is_correct": true, "explanation": "正确：“海峡”连通两片海，没有它，两片海就不能相通，句意成立。"}, {"text": "辫子", "is_correct": false, "explanation": "搭配：“相通”用于水域或通道，不能与“辫子”搭配。"}], "explanations": {"道路": "语义：道路在陆地上，不能让两片海相通。", "铁路": "语义：铁路是陆上交通线，与“两片海相通”无关。", "海峡": "正确：“海峡”连通两片海，没有它，两片海就不能相通，句意成立。", "辫子": "搭配：“相通”用于水域或通道，不能与“辫子”搭配。"}, "sentence_index": 6, "correct_answer": "海峡"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这条海峡从高山上落下来，声音很大。", "explanation": "这里应该用〈瀑布〉。瀑布是河水从高处落下；海峡是两片海之间的水道，不会从高山上落下。"}, {"text": "这条海峡上只住着几户人家。", "explanation": "这里应该用〈海岛〉。海岛是四面环水的陆地，可以住人；海峡是水道，不能住人。"}, {"text": "这条海峡一个接一个地打上沙滩。", "explanation": "这里应该用〈海浪〉。海浪是海水的起伏，能拍打海岸；海峡是水道，不会自己一浪接一浪地打上沙滩。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c344b1a-6ec0-49b7-9dc7-d529462b5f32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95248, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这是一条连通两片海海峡，很多船要经过。", "corrected_sentence": "这是一条连通两片海的海峡，很多船要经过。", "error_description": "错误形式是“连通两片海海峡”，正确形式是“连通两片海的海峡”。“连通两片海”修饰“海峡”，二者之间要用结构助词“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c344b1a-6ec0-49b7-9dc7-d529462b5f32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95248, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "渔船每天穿过了海峡去捕鱼。", "corrected_sentence": "渔船每天穿过海峡去捕鱼。", "error_description": "错误形式是“穿过了海峡”，正确形式是“穿过海峡”。“每天”表示经常、反复发生的动作，与表示完成的“了”不能搭配。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c344b1a-6ec0-49b7-9dc7-d529462b5f32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
