INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95250, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "逐项列出物品或事项的单子。", "primary_collocate": null, "pronunciation": "qīng dān", "ipa": "tɕʰiŋ˥ tan˥", "syllable_count": 2, "sentences": [{"text": "公司把货物清单发给了客户。", "target_word": "清单", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理要看今天的工作清单。", "target_word": "清单", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "搬家以后，我们检查了一遍物品清单。", "target_word": "清单", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "清单上有五个任务，我已经做完了三个。", "target_word": "清单", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你按清单上的名字一个一个念。", "target_word": "清单", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份清单列出了房间里所有的家具。", "target_word": "清单", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海关人员正在核对货物清单。", "target_word": "清单", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈列了一份清单，把过年要做的事都写了上去。", "target_word": "清单", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的愿望清单上有一台新电脑。", "target_word": "清单", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "酒店送来了一份费用清单，我们看了很久。", "target_word": "清单", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "份", "label": "量词"}, {"form": "张", "label": "量词"}, {"form": "清單", "label": "繁体"}, {"form": "货物清单", "label": "复合"}], "register": "中性", "sense_fingerprint": "逐项列出物品、费用、任务、名单或愿望等事项的单子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '629e9c88-00bf-45eb-822b-29c0b905eb32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95250, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "清单", "is_correct": true, "explanation": "正确：“货物清单”逐项列出货物，可以发给客户核对，符合句意。"}, {"text": "心情", "is_correct": false, "explanation": "搭配：“发给”的对象应是文件或物品，“心情”不能发给别人。"}, {"text": "同事", "is_correct": false, "explanation": "语义：“同事”是人，不是可以发给客户的东西。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：“身材”指外形，不能被发给客户。"}], "explanations": {"清单": "正确：“货物清单”逐项列出货物，可以发给客户核对，符合句意。", "心情": "搭配：“发给”的对象应是文件或物品，“心情”不能发给别人。", "同事": "语义：“同事”是人，不是可以发给客户的东西。", "身材": "体貌：“身材”指外形，不能被发给客户。"}, "sentence_index": 0, "correct_answer": "清单"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我家的清单很大，一家人住得很舒服。", "explanation": "这里应该用〈房子〉。清单是逐项列出物品或事项的单子，不能用来住人。"}, {"text": "我每天早上打开收音机，听清单播报今天的天气。", "explanation": "这里应该用〈天气预报〉。清单只逐项列出事项，不会播报天气。"}, {"text": "我们在客厅挂了一张清单，画得很有意境。", "explanation": "这里应该用〈画〉。清单是逐项列出物品或事项的单子，不是画作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bab70b32-5cd7-4ce1-9368-e9b36247ac3a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95250, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "清单", "is_correct": true, "explanation": "正确：“核对货物清单”是常见搭配，指逐项查对货物，符合句意。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“核对”的对象应是可以逐项查对的材料或数据，“天气”无法核对。"}, {"text": "脾气", "is_correct": false, "explanation": "搭配：“核对”不能用于“脾气”这类性格状态。"}, {"text": "大海", "is_correct": false, "explanation": "语义：海关不核对大海，句意不通。"}], "explanations": {"清单": "正确：“核对货物清单”是常见搭配，指逐项查对货物，符合句意。", "天气": "搭配：“核对”的对象应是可以逐项查对的材料或数据，“天气”无法核对。", "脾气": "搭配：“核对”不能用于“脾气”这类性格状态。", "大海": "语义：海关不核对大海，句意不通。"}, "sentence_index": 6, "correct_answer": "清单"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "服务员端上来一份清单，我们吃得很开心。", "explanation": "这里应该用〈菜〉。清单是逐项列出物品或事项的单子，不能用来吃。"}, {"text": "医生用清单给我做了手术。", "explanation": "这里应该用〈手术刀〉。清单是逐项列出物品或事项的单子，不能用来切割。"}, {"text": "妈妈把清单放进锅里，煮了二十分钟。", "explanation": "这里应该用〈面条〉。清单是逐项列出物品或事项的单子，不能放进锅里煮来吃。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bab70b32-5cd7-4ce1-9368-e9b36247ac3a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95250, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这把任务清单上有五项，我已经做完了两项。", "corrected_sentence": "这份任务清单上有五项，我已经做完了两项。", "error_description": "“清单”应与“份”或“张”搭配。“把”用于有柄的器具，不用于清单。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bab70b32-5cd7-4ce1-9368-e9b36247ac3a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95250, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "几份清单们都已经核对完了。", "corrected_sentence": "几份清单都已经核对完了。", "error_description": "“清单”不是人，不能加“们”表示复数；“几份”已经表示数量。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bab70b32-5cd7-4ce1-9368-e9b36247ac3a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95251, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "明亮", "is_correct": false, "explanation": "无反义关系：“明亮”形容光线，与人的性情和对人的态度无关。"}, {"text": "粗暴", "is_correct": true, "explanation": "反义：“粗暴”指对人态度粗野、言语伤人，与“温柔”对人很好、不凶正相对。"}, {"text": "聪明", "is_correct": false, "explanation": "无反义关系：“聪明”形容智力，与说话的轻重和对人的态度无关。"}, {"text": "干净", "is_correct": false, "explanation": "无反义关系：“干净”形容清洁，不涉及说话方式或性情。"}], "correct_answer": "粗暴", "explanations": {"明亮": "无反义关系：“明亮”形容光线，与人的性情和对人的态度无关。", "粗暴": "反义：“粗暴”指对人态度粗野、言语伤人，与“温柔”对人很好、不凶正相对。", "聪明": "无反义关系：“聪明”形容智力，与说话的轻重和对人的态度无关。", "干净": "无反义关系：“干净”形容清洁，不涉及说话方式或性情。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c344b1a-6ec0-49b7-9dc7-d529462b5f32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95251, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "灵活", "is_correct": false, "explanation": "无反义关系：“灵活”形容动作或办法变通，与说话和待人的态度无关。"}, {"text": "粗鲁", "is_correct": true, "explanation": "反义：“粗鲁”指言行粗野、不讲礼貌，与“温柔”对人的态度正相对。"}, {"text": "厚实", "is_correct": false, "explanation": "无反义关系：“厚实”形容物体的厚度，不涉及性情。"}, {"text": "苦涩", "is_correct": false, "explanation": "无反义关系：“苦涩”形容味道，与性情和待人方式无关。"}], "correct_answer": "粗鲁", "explanations": {"灵活": "无反义关系：“灵活”形容动作或办法变通，与说话和待人的态度无关。", "粗鲁": "反义：“粗鲁”指言行粗野、不讲礼貌，与“温柔”对人的态度正相对。", "厚实": "无反义关系：“厚实”形容物体的厚度，不涉及性情。", "苦涩": "无反义关系：“苦涩”形容味道，与性情和待人方式无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c344b1a-6ec0-49b7-9dc7-d529462b5f32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95251, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "说话轻轻的，对人很好，不凶。", "primary_collocate": null, "pronunciation": "wēn róu", "ipa": "wən˥ ʐoʊ˧˥", "syllable_count": 2, "sentences": [{"text": "王老师说话很温柔，学生都喜欢她。", "target_word": "温柔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈温柔地对孩子说：“别怕。”", "target_word": "温柔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的声音很温柔，像唱歌一样。", "target_word": "温柔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "护士对病人很温柔，从不大声说话。", "target_word": "温柔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的奶奶是一个温柔的人。", "target_word": "温柔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对小狗很温柔，还给它洗澡。", "target_word": "温柔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她温柔地笑了笑，没有生气。", "target_word": "温柔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位姐姐很温柔，不会对人发脾气。", "target_word": "温柔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他平时很凶，今天却很温柔。", "target_word": "温柔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你温柔一点，宝宝在睡觉。", "target_word": "温柔", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "温温柔柔", "label": "重叠"}, {"form": "溫柔", "label": "繁体"}], "register": "中性", "sense_fingerprint": "说话声音轻、态度好、不凶", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad1d3580-2f81-4f34-89f3-d63ae05c6f1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95251, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "粗鲁", "is_correct": false, "explanation": "语义：“粗鲁”指言语粗野，与后半句“学生都喜欢她”矛盾。"}, {"text": "温柔", "is_correct": true, "explanation": "正确：“温柔”形容老师说话的态度，与“学生都喜欢她”一致。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：“高大”形容身材，不能用来形容说话的样子。"}, {"text": "结实", "is_correct": false, "explanation": "搭配：“结实”形容身体或物体，不能说“说话很结实”。"}], "explanations": {"粗鲁": "语义：“粗鲁”指言语粗野，与后半句“学生都喜欢她”矛盾。", "温柔": "正确：“温柔”形容老师说话的态度，与“学生都喜欢她”一致。", "高大": "体貌：“高大”形容身材，不能用来形容说话的样子。", "结实": "搭配：“结实”形容身体或物体，不能说“说话很结实”。"}, "sentence_index": 0, "correct_answer": "温柔"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这种药的性质很温柔，小孩吃也放心。", "explanation": "这里应该用〈温和〉。温和可形容药物、气候的性质，温柔只形容人的性情和对人的态度。"}, {"text": "这块冰摸起来很温柔。", "explanation": "这里应该用〈冰凉〉。冰凉形容物体温度低的触感；温柔用于形容人的性情和对人的态度，不说冰“温柔”。"}, {"text": "这台机器很温柔，干活很快。", "explanation": "这里应该用〈高效〉。高效形容工作效率高；温柔只用于形容人的性情和对人的态度，不说机器“温柔”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c344b1a-6ec0-49b7-9dc7-d529462b5f32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95251, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "愤怒", "is_correct": false, "explanation": "语义：“愤怒”与后半句“没有生气”矛盾。"}, {"text": "温柔", "is_correct": true, "explanation": "正确：“温柔地笑了笑”形容态度和善，与“没有生气”一致。"}, {"text": "暴躁", "is_correct": false, "explanation": "语义：“暴躁”表示容易发火，同样与“没有生气”矛盾。"}, {"text": "高挑", "is_correct": false, "explanation": "体貌：“高挑”形容身材，不能修饰“笑”的样子。"}], "explanations": {"愤怒": "语义：“愤怒”与后半句“没有生气”矛盾。", "温柔": "正确：“温柔地笑了笑”形容态度和善，与“没有生气”一致。", "暴躁": "语义：“暴躁”表示容易发火，同样与“没有生气”矛盾。", "高挑": "体貌：“高挑”形容身材，不能修饰“笑”的样子。"}, "sentence_index": 6, "correct_answer": "温柔"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位老人的身体很温柔，需要人照顾。", "explanation": "这里应该用〈柔弱〉。柔弱形容身体或力量不足，温柔只形容人的性情和态度，不说“身体很温柔”。"}, {"text": "他做生意很温柔，每笔账都算得很清楚。", "explanation": "这里应该用〈精明〉。精明形容头脑灵活、办事能干，温柔形容性情，不能用来说做生意的能力。"}, {"text": "他板着脸，看上去很温柔。", "explanation": "这里应该用〈严肃〉。严肃形容神情庄重，与“板着脸”一致；温柔表示和善，与“板着脸”的神情相矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c344b1a-6ec0-49b7-9dc7-d529462b5f32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95251, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她用温柔地语气安慰孩子。", "corrected_sentence": "她用温柔的语气安慰孩子。", "error_description": "错误形式是“温柔地语气”，正确形式是“温柔的语气”。“温柔”修饰名词“语气”时作定语，要用“的”；“地”通常用在动词、形容词前作状语，不用来修饰名词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c344b1a-6ec0-49b7-9dc7-d529462b5f32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95251, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她一点也很温柔，说话总是很大声。", "corrected_sentence": "她一点也不温柔，说话总是很大声。", "error_description": "错误形式是“一点也很温柔”，正确形式是“一点也不温柔”。“一点也”后面必须接否定词“不”，不能接程度副词“很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c344b1a-6ec0-49b7-9dc7-d529462b5f32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95252, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "诚实", "is_correct": false, "explanation": "无反义关系：“诚实”说明人讲真话，与“温柔”的性情没有对立关系。"}, {"text": "勇敢", "is_correct": false, "explanation": "无反义关系：“勇敢”形容胆量，与性情柔和不构成反义。"}, {"text": "粗暴", "is_correct": true, "explanation": "反义：“粗暴”指对人态度粗野、言语或动作伤人，与“温柔”性情柔和、待人体贴正相对。"}, {"text": "整齐", "is_correct": false, "explanation": "无反义关系：“整齐”形容排列或仪容，与待人态度无关。"}], "correct_answer": "粗暴", "explanations": {"诚实": "无反义关系：“诚实”说明人讲真话，与“温柔”的性情没有对立关系。", "勇敢": "无反义关系：“勇敢”形容胆量，与性情柔和不构成反义。", "粗暴": "反义：“粗暴”指对人态度粗野、言语或动作伤人，与“温柔”性情柔和、待人体贴正相对。", "整齐": "无反义关系：“整齐”形容排列或仪容，与待人态度无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c344b1a-6ec0-49b7-9dc7-d529462b5f32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95252, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "清脆", "is_correct": false, "explanation": "无反义关系：“清脆”形容声音，与性情和待人方式无关。"}, {"text": "复杂", "is_correct": false, "explanation": "无反义关系：“复杂”形容事物的构成，不涉及性情。"}, {"text": "粗鲁", "is_correct": true, "explanation": "反义：“粗鲁”指言行粗野、不讲礼貌，与“温柔”性情和待人态度正相对。"}, {"text": "陡峭", "is_correct": false, "explanation": "无反义关系：“陡峭”形容地势，与性情无关。"}], "correct_answer": "粗鲁", "explanations": {"清脆": "无反义关系：“清脆”形容声音，与性情和待人方式无关。", "复杂": "无反义关系：“复杂”形容事物的构成，不涉及性情。", "粗鲁": "反义：“粗鲁”指言行粗野、不讲礼貌，与“温柔”性情和待人态度正相对。", "陡峭": "无反义关系：“陡峭”形容地势，与性情无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c344b1a-6ec0-49b7-9dc7-d529462b5f32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95252, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "性情柔和，待人体贴。", "primary_collocate": null, "pronunciation": "wēn róu", "ipa": "wən˥ ʐoʊ˧˥", "syllable_count": 2, "sentences": [{"text": "她是个温柔的女朋友，总会关心我。", "target_word": "温柔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他性格温柔，总是想着别人。", "target_word": "温柔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妻子很温柔，把家里照顾得很好。", "target_word": "温柔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我喜欢温柔的人，他们会听你说话。", "target_word": "温柔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他看起来很高大，其实心很温柔。", "target_word": "温柔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用温柔的话安慰了难过的朋友。", "target_word": "温柔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥对妹妹一直很温柔，很会照顾她。", "target_word": "温柔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "温柔的人不会让别人觉得难受。", "target_word": "温柔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位医生很温柔，每次都先问我怕不怕。", "target_word": "温柔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的性格比以前温柔多了。", "target_word": "温柔", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "温温柔柔", "label": "重叠"}, {"form": "溫柔", "label": "繁体"}], "register": "中性", "sense_fingerprint": "性格柔和、待人体贴关心", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad1d3580-2f81-4f34-89f3-d63ae05c6f1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95252, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "冷漠", "is_correct": false, "explanation": "语义：“冷漠”与后半句“总会关心我”矛盾。"}, {"text": "平整", "is_correct": false, "explanation": "搭配：“平整”形容表面，不能用来形容女朋友的性格。"}, {"text": "温柔", "is_correct": true, "explanation": "正确：“温柔的女朋友”形容性格柔和，与“总会关心我”一致。"}, {"text": "无情", "is_correct": false, "explanation": "语义：“无情”与“总会关心我”矛盾。"}], "explanations": {"冷漠": "语义：“冷漠”与后半句“总会关心我”矛盾。", "平整": "搭配：“平整”形容表面，不能用来形容女朋友的性格。", "温柔": "正确：“温柔的女朋友”形容性格柔和，与“总会关心我”一致。", "无情": "语义：“无情”与“总会关心我”矛盾。"}, "sentence_index": 0, "correct_answer": "温柔"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这条路很温柔，骑车一点也不累。", "explanation": "这里应该用〈平坦〉。平坦形容地面没有高低起伏；温柔只用于形容人的性情和对人的态度，不说路“温柔”。"}, {"text": "她的字又工整又温柔，看着很舒服。", "explanation": "这里应该用〈秀气〉。秀气形容字迹清秀；温柔只用于形容人的性情和对人的态度，不说字“温柔”。"}, {"text": "刚出锅的馒头很温柔，又软又香。", "explanation": "这里应该用〈松软〉。松软形容食物的口感，温柔不用于形容馒头。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c344b1a-6ec0-49b7-9dc7-d529462b5f32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95252, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "粗心", "is_correct": false, "explanation": "语义：“粗心”与后半句“很会照顾她”矛盾。"}, {"text": "温柔", "is_correct": true, "explanation": "正确：“一直很温柔”形容哥哥对妹妹的态度，与“很会照顾她”一致。"}, {"text": "懒散", "is_correct": false, "explanation": "语义：“懒散”与“很会照顾她”矛盾。"}, {"text": "瘦小", "is_correct": false, "explanation": "体貌：“瘦小”形容身材，不能用来形容哥哥对妹妹的态度。"}], "explanations": {"粗心": "语义：“粗心”与后半句“很会照顾她”矛盾。", "温柔": "正确：“一直很温柔”形容哥哥对妹妹的态度，与“很会照顾她”一致。", "懒散": "语义：“懒散”与“很会照顾她”矛盾。", "瘦小": "体貌：“瘦小”形容身材，不能用来形容哥哥对妹妹的态度。"}, "sentence_index": 6, "correct_answer": "温柔"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她生病住院，意志却很温柔，从不喊痛。", "explanation": "这里应该用〈坚强〉。坚强形容意志和承受力；温柔只形容性情和对人的态度，不用于形容意志。"}, {"text": "这位经理看人很温柔，一眼就能看出谁靠得住。", "explanation": "这里应该用〈精明〉。精明形容看人办事的头脑和判断能力，温柔不用于形容判断能力。"}, {"text": "事故发生后，他很温柔，立刻打电话报警。", "explanation": "这里应该用〈冷静〉。冷静形容遇事时的镇定，温柔形容性情和对人的态度，不用于形容遇事的反应。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c344b1a-6ec0-49b7-9dc7-d529462b5f32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95252, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她对我很温柔得，常常给我买吃的。", "corrected_sentence": "她对我很温柔，常常给我买吃的。", "error_description": "错误形式是“很温柔得，”：“温柔”已由“很”修饰作谓语，后面多了结构助词“得”，又没有补语。正确形式是删去“得”，说“很温柔”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c344b1a-6ec0-49b7-9dc7-d529462b5f32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95252, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她笑很温柔，大家都觉得很舒服。", "corrected_sentence": "她笑得很温柔，大家都觉得很舒服。", "error_description": "错误形式是“笑很温柔”，正确形式是“笑得很温柔”。动词“笑”后面带描写状态的补语时，要用结构助词“得”，不能省略。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c344b1a-6ec0-49b7-9dc7-d529462b5f32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
