INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95253, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '979e2659-c933-4818-bcef-e3cf85849824') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95253, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "做东西的时候，人和人之间怎样分工、怎样分东西的关系。", "primary_collocate": null, "pronunciation": "shēng chǎn guān xì", "ipa": "ʂɤŋ˥ ʈʂʰan˨˩ kwan˥ ɕi˥˩", "syllable_count": 4, "sentences": [{"text": "在这家小工厂，生产关系很简单。", "target_word": "生产关系", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家分工清楚，生产关系就更好。", "target_word": "生产关系", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板和工人的生产关系要公平。", "target_word": "生产关系", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村里的生产关系是一起做，一起分。", "target_word": "生产关系", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们改了生产关系，工人拿得更多了。", "target_word": "生产关系", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的生产关系能让大家都愿意工作。", "target_word": "生产关系", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁做什么、谁拿多少，是生产关系的问题。", "target_word": "生产关系", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个家庭作坊的生产关系很特别。", "target_word": "生产关系", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "生产关系不清楚，大家就会吵架。", "target_word": "生产关系", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人给我们讲了从前村里的生产关系。", "target_word": "生产关系", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "生產關係", "label": "繁体"}], "register": "书面", "sense_fingerprint": "生产中分工和分配的关系", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a65ce783-209c-496d-8375-67116e6f7c33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95253, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "天气", "is_correct": false, "explanation": "语义：天气不是在工厂里可以“简单”或“复杂”的事物，与“小工厂”的语境不符。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：月亮不在工厂里，不能说它“很简单”，与语境不符。"}, {"text": "台风", "is_correct": false, "explanation": "语义：台风是天气现象，不能用来说工厂的情况“很简单”，与语境不符。"}, {"text": "生产关系", "is_correct": true, "explanation": "生产关系：做东西时的分工和分配关系，“在这家小工厂，生产关系很简单”指分工分配简单，符合语境。"}], "explanations": {"天气": "语义：天气不是在工厂里可以“简单”或“复杂”的事物，与“小工厂”的语境不符。", "月亮": "语义：月亮不在工厂里，不能说它“很简单”，与语境不符。", "台风": "语义：台风是天气现象，不能用来说工厂的情况“很简单”，与语境不符。", "生产关系": "生产关系：做东西时的分工和分配关系，“在这家小工厂，生产关系很简单”指分工分配简单，符合语境。"}, "sentence_index": 0, "correct_answer": "生产关系"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他这个月的生产关系增加了不少。", "explanation": "这里应该用〈收入〉。收入会增加，生产关系是分工分配的关系，不能说增加了多少。"}, {"text": "这个句子的生产关系很清楚。", "explanation": "这里应该用〈主谓关系〉。生产关系指物质生产中人与人的分工和分配关系，句子成分之间的关系要说“主谓关系”。"}, {"text": "老板把生产关系放进了柜子里。", "explanation": "生产关系是人与人之间的关系，不是物体，不能放进柜子里。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '979e2659-c933-4818-bcef-e3cf85849824') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95253, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "地震", "is_correct": false, "explanation": "语义：地震是自然灾害，不能与“谁做什么、谁拿多少”的问题相关。"}, {"text": "水果", "is_correct": false, "explanation": "语义：水果与分工和分配无关，不能是这类问题的主体。"}, {"text": "河流", "is_correct": false, "explanation": "搭配：“是……的问题”指分工分配的问题，“河流”与之不搭配。"}, {"text": "生产关系", "is_correct": true, "explanation": "生产关系：分工和分配的关系，“谁做什么、谁拿多少”正是它所涉及的问题，符合语境。"}], "explanations": {"地震": "语义：地震是自然灾害，不能与“谁做什么、谁拿多少”的问题相关。", "水果": "语义：水果与分工和分配无关，不能是这类问题的主体。", "河流": "搭配：“是……的问题”指分工分配的问题，“河流”与之不搭配。", "生产关系": "生产关系：分工和分配的关系，“谁做什么、谁拿多少”正是它所涉及的问题，符合语境。"}, "sentence_index": 6, "correct_answer": "生产关系"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我和同学的生产关系很好。", "explanation": "这里应该用〈人际关系〉。生产关系指物质生产中的分工和分配关系，不用来说同学之间的交往。"}, {"text": "这种生产关系很好吃。", "explanation": "这里不能用“好吃”描述关系。“好吃”只用于食物，生产关系不能吃。"}, {"text": "生产关系很重，我们搬不动。", "explanation": "这里应该用〈箱子〉。生产关系是人与人之间的关系，没有重量，不能说很重或搬动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '979e2659-c933-4818-bcef-e3cf85849824') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95253, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那条生产关系很不公平。", "corrected_sentence": "那种生产关系很不公平。", "error_description": "错误在量词“条”。“生产关系”的量词应用“种”，不用“条”，应说“那种生产关系”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '979e2659-c933-4818-bcef-e3cf85849824') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95253, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "大家改变了生产关系们。", "corrected_sentence": "大家改变了生产关系。", "error_description": "错误在“们”。“生产关系”是抽象名词，不能加表示复数的“们”，应说“改变了生产关系”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '979e2659-c933-4818-bcef-e3cf85849824') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95254, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '979e2659-c933-4818-bcef-e3cf85849824') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95254, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '979e2659-c933-4818-bcef-e3cf85849824') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95254, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "人们在物质生产过程中结成的社会关系。", "primary_collocate": null, "pronunciation": "shēng chǎn guān xì", "ipa": "ʂɤŋ˥ ʈʂʰan˨˩ kwan˥ ɕi˥˩", "syllable_count": 4, "sentences": [{"text": "生产关系是社会里最重要的关系之一。", "target_word": "生产关系", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校的课本讲了什么是生产关系。", "target_word": "生产关系", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，生产关系会影响人们的生活。", "target_word": "生产关系", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂里的生产关系和农村不一样。", "target_word": "生产关系", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "社会变了，生产关系也跟着变了。", "target_word": "生产关系", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书研究的是古代的生产关系。", "target_word": "生产关系", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "生产关系决定谁拿多少东西。", "target_word": "生产关系", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在课上问了生产关系是什么意思。", "target_word": "生产关系", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "生产关系和生产工具都很重要。", "target_word": "生产关系", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新的生产关系让工人的生活好了。", "target_word": "生产关系", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "生產關係", "label": "繁体"}], "register": "书面", "sense_fingerprint": "物质生产中形成的社会关系", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a65ce783-209c-496d-8375-67116e6f7c33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95254, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "生产力", "is_correct": false, "explanation": "语义：生产力指生产中的力量，不是社会关系，不能说是“关系之一”。"}, {"text": "水果", "is_correct": false, "explanation": "搭配：“……之一”要求前面是关系类名词，“水果”不能与“关系之一”搭配。"}, {"text": "生产关系", "is_correct": true, "explanation": "生产关系：人们在物质生产过程中结成的社会关系，正是“社会里最重要的关系之一”，符合语境。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是社会关系，不能是“社会里最重要的关系之一”。"}], "explanations": {"生产力": "语义：生产力指生产中的力量，不是社会关系，不能说是“关系之一”。", "水果": "搭配：“……之一”要求前面是关系类名词，“水果”不能与“关系之一”搭配。", "生产关系": "生产关系：人们在物质生产过程中结成的社会关系，正是“社会里最重要的关系之一”，符合语境。", "天气": "语义：天气不是社会关系，不能是“社会里最重要的关系之一”。"}, "sentence_index": 0, "correct_answer": "生产关系"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们班同学的生产关系很好。", "explanation": "这里应该用〈人际关系〉。生产关系指物质生产中人与人的关系，不用来说同学之间的交往。"}, {"text": "他和叔叔是生产关系。", "explanation": "这里应该用〈亲戚关系〉。生产关系指物质生产中人与人的分工和分配关系，不指亲属之间的关系。"}, {"text": "生产关系是一台新机器。", "explanation": "生产关系是人与人之间的关系，不是机器，不能用“一台”来计量，也不能说是机器。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '979e2659-c933-4818-bcef-e3cf85849824') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95254, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "汽车", "is_correct": false, "explanation": "语义：汽车不能决定分配，不符合“决定谁拿多少东西”的语境。"}, {"text": "牙膏", "is_correct": false, "explanation": "语义：牙膏与分配东西毫无关系，不能作“决定谁拿多少东西”的主语。"}, {"text": "冰箱", "is_correct": false, "explanation": "搭配：“决定谁拿多少东西”的主语要是制度或关系，“冰箱”不搭配。"}, {"text": "生产关系", "is_correct": true, "explanation": "生产关系：物质生产中的社会关系，决定分配、决定谁拿多少东西，符合语境。"}], "explanations": {"汽车": "语义：汽车不能决定分配，不符合“决定谁拿多少东西”的语境。", "牙膏": "语义：牙膏与分配东西毫无关系，不能作“决定谁拿多少东西”的主语。", "冰箱": "搭配：“决定谁拿多少东西”的主语要是制度或关系，“冰箱”不搭配。", "生产关系": "生产关系：物质生产中的社会关系，决定分配、决定谁拿多少东西，符合语境。"}, "sentence_index": 6, "correct_answer": "生产关系"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "新机器提高了生产关系。", "explanation": "这里应该用〈生产力〉。机器提高的是生产力，生产关系是人与人之间的关系，不能被机器提高。"}, {"text": "这种生产关系很好吃。", "explanation": "这里不能用“好吃”描述关系。“好吃”只用于食物，生产关系不能吃。"}, {"text": "生产关系跑得很快。", "explanation": "这里应该用〈运动员〉。生产关系是人与人之间的关系，不会跑步，“跑得很快”只能用于人或动物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '979e2659-c933-4818-bcef-e3cf85849824') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95254, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "一条新的生产关系出现了。", "corrected_sentence": "一种新的生产关系出现了。", "error_description": "错误在量词“条”。“生产关系”是抽象的关系，量词应用“种”，不用“条”，应说“一种新的生产关系”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '979e2659-c933-4818-bcef-e3cf85849824') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95254, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这条生产关系很特别。", "corrected_sentence": "这种生产关系很特别。", "error_description": "错误在量词“条”。“生产关系”的量词应用“种”，不用“条”，应说“这种生产关系”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '979e2659-c933-4818-bcef-e3cf85849824') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
