INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95255, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0951cffc-c221-4855-94ff-5e8df6e4b522') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95255, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把事情写好，告诉有关的地方知道。", "primary_collocate": null, "pronunciation": "shēn bào", "ipa": "ʂən⁵⁵ pɑʊ̯⁵¹", "syllable_count": 2, "sentences": [{"text": "村里把受灾情况写好，向县里申报了。", "target_word": "申报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你把家里的人口情况向社区申报。", "target_word": "申报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "搬到新城市后，要尽快申报住址。", "target_word": "申报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在表上写好姓名，然后申报给学校。", "target_word": "申报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂出了事故，必须马上申报。", "target_word": "申报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我已经把这件事向上级申报过了。", "target_word": "申报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新生要向学校申报自己的健康情况。", "target_word": "申报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "邻居家养了狗，也要去有关部门申报。", "target_word": "申报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "司机要先申报路线，才能出发。", "target_word": "申报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "表格写好了，你明天去街道办申报吧。", "target_word": "申报", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "申报了", "label": "完成体"}, {"form": "申报过", "label": "经历体"}, {"form": "申报表", "label": "复合词"}], "register": "正式", "sense_fingerprint": "把情况写成材料，向有关部门报告，让对方知道", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'db3644ad-b860-49ef-adcd-01357c77d0ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95255, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "申报", "is_correct": true, "explanation": "正确：把写好的受灾情况报给县里，与语境相符。"}, {"text": "庆祝", "is_correct": false, "explanation": "语义：受灾情况不值得庆祝，“庆祝”与语境相悖。"}, {"text": "删除", "is_correct": false, "explanation": "语义：情况已经写好，“删除”与“写好”的语境矛盾。"}, {"text": "隐瞒", "is_correct": false, "explanation": "语义：情况已写好并要报给县里，“隐瞒”与此相反。"}], "explanations": {"申报": "正确：把写好的受灾情况报给县里，与语境相符。", "庆祝": "语义：受灾情况不值得庆祝，“庆祝”与语境相悖。", "删除": "语义：情况已经写好，“删除”与“写好”的语境矛盾。", "隐瞒": "语义：情况已写好并要报给县里，“隐瞒”与此相反。"}, "sentence_index": 0, "correct_answer": "申报"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把这件事申报给了朋友。", "explanation": "这里应该用〈告诉〉。申报的对象必须是有关部门，把事情告诉朋友要用〈告诉〉。"}, {"text": "老师向学生申报了考试规则。", "explanation": "这里应该用〈说明〉。申报是向有关部门报告并请其知悉，老师向学生讲清规则要用〈说明〉。"}, {"text": "他回家向父母申报考上大学的喜讯。", "explanation": "这里应该用〈报喜〉。父母不是有关部门，向家人报告好消息要用〈报喜〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0951cffc-c221-4855-94ff-5e8df6e4b522') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95255, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "申报", "is_correct": true, "explanation": "正确：向学校如实报告自己的健康情况，符合语境。"}, {"text": "锻炼", "is_correct": false, "explanation": "搭配：“锻炼”的对象是身体，不能说“锻炼健康情况”。"}, {"text": "抹去", "is_correct": false, "explanation": "语义：学校要求新生如实报告健康情况，“抹去”与此相反。"}, {"text": "推迟", "is_correct": false, "explanation": "搭配：“推迟”不能以“健康情况”为宾语，“推迟健康情况”不成立。"}], "explanations": {"申报": "正确：向学校如实报告自己的健康情况，符合语境。", "锻炼": "搭配：“锻炼”的对象是身体，不能说“锻炼健康情况”。", "抹去": "语义：学校要求新生如实报告健康情况，“抹去”与此相反。", "推迟": "搭配：“推迟”不能以“健康情况”为宾语，“推迟健康情况”不成立。"}, "sentence_index": 6, "correct_answer": "申报"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "姐姐给我申报了一个故事。", "explanation": "这里应该用〈讲〉。申报是向有关部门报告情况，给人讲故事要用〈讲〉。"}, {"text": "记者向社会申报了这次比赛的结果。", "explanation": "这里应该用〈报道〉。申报针对有关部门，把比赛结果公开告诉社会要用〈报道〉。"}, {"text": "校长申报了放假的消息。", "explanation": "这里应该用〈宣布〉。申报的对象是主管部门，向全体师生宣布放假要用〈宣布〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0951cffc-c221-4855-94ff-5e8df6e4b522') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95255, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他已经把住址申报清楚着。", "corrected_sentence": "他已经把住址申报清楚了。", "error_description": "“已经”表示完成，完成体要用“了”，不能用“着”。应说“申报清楚了”，不说“申报清楚着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0951cffc-c221-4855-94ff-5e8df6e4b522') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95255, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我以前不申报过这种表格。", "corrected_sentence": "我以前没申报过这种表格。", "error_description": "表示“从未做过”要用“没”，不用“不”；“不申报过”应改为“没申报过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0951cffc-c221-4855-94ff-5e8df6e4b522') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
