INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95256, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "向主管部门如实报告并请求登记或审批。", "primary_collocate": null, "pronunciation": "shēn bào", "ipa": "ʂən⁵⁵ pɑʊ̯⁵¹", "syllable_count": 2, "sentences": [{"text": "入境时，你要向海关申报所带的现金。", "target_word": "申报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司每年都要向税务局申报收入。", "target_word": "申报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校今年申报了三个研究项目。", "target_word": "申报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "带水果入境也要申报，不然要罚款。", "target_word": "申报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他去派出所申报了新生儿的户口。", "target_word": "申报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "个人所得税要在三月底以前申报。", "target_word": "申报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这批货物的价值，必须如实申报。", "target_word": "申报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他以前申报过两次，都没有通过。", "target_word": "申报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "申报的时间已经过了，你明天再来吧。", "target_word": "申报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请大家在周五前申报参赛作品。", "target_word": "申报", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "申报了", "label": "完成体"}, {"form": "申报过", "label": "经历体"}, {"form": "申报表", "label": "复合词"}, {"form": "申报单", "label": "复合词"}], "register": "正式", "sense_fingerprint": "向主管部门如实报告并请求登记或审批（如海关、税务、项目）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'db3644ad-b860-49ef-adcd-01357c77d0ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95256, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "申报", "is_correct": true, "explanation": "正确：申报指向海关如实报告所带物品，符合语境。"}, {"text": "打扫", "is_correct": false, "explanation": "搭配：“打扫”的对象是地方，不能说“向海关打扫现金”，句意不通。"}, {"text": "购买", "is_correct": false, "explanation": "搭配：“购买”的对象不能是“所带的现金”，句意不通。"}, {"text": "丢失", "is_correct": false, "explanation": "配价：“丢失”不能带“向”引出的对象，“向海关丢失”不成立。"}], "explanations": {"申报": "正确：申报指向海关如实报告所带物品，符合语境。", "打扫": "搭配：“打扫”的对象是地方，不能说“向海关打扫现金”，句意不通。", "购买": "搭配：“购买”的对象不能是“所带的现金”，句意不通。", "丢失": "配价：“丢失”不能带“向”引出的对象，“向海关丢失”不成立。"}, "sentence_index": 0, "correct_answer": "申报"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他向警察申报了那个小偷。", "explanation": "这里应该用〈举报〉。申报是向主管部门如实报告自己或本单位的情况、请求登记或审批；揭发他人违法要用〈举报〉。"}, {"text": "他向公司申报了这个职位。", "explanation": "这里应该用〈申请〉。申报用于向主管部门报告情况并请求登记、审批，应聘职位要用〈申请〉。"}, {"text": "他钱包被偷后，立刻向朋友申报了这件事。", "explanation": "这里应该用〈告诉〉。申报的对象是主管部门，告诉朋友要用〈告诉〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0951cffc-c221-4855-94ff-5e8df6e4b522') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95256, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "申报", "is_correct": true, "explanation": "正确：申报是如实报告货物价值，与“必须如实”相配。"}, {"text": "夸大", "is_correct": false, "explanation": "语义：“夸大”与“如实”意思相反，不符合要求。"}, {"text": "涂改", "is_correct": false, "explanation": "语义：“涂改”会改变真实价值，与“如实”相悖。"}, {"text": "存放", "is_correct": false, "explanation": "搭配：“存放”不能以“价值”为对象，“存放价值”不成立。"}], "explanations": {"申报": "正确：申报是如实报告货物价值，与“必须如实”相配。", "夸大": "语义：“夸大”与“如实”意思相反，不符合要求。", "涂改": "语义：“涂改”会改变真实价值，与“如实”相悖。", "存放": "搭配：“存放”不能以“价值”为对象，“存放价值”不成立。"}, "sentence_index": 6, "correct_answer": "申报"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在网站上申报了一个账号。", "explanation": "这里应该用〈注册〉。申报是向主管部门报告情况、请求登记或审批，网站开通账号要用〈注册〉。"}, {"text": "我在酒店申报了入住手续。", "explanation": "这里应该用〈登记〉。申报针对主管部门的登记或审批，酒店办理入住要用〈登记〉。"}, {"text": "老师申报了全班同学明天考试。", "explanation": "这里应该用〈通知〉。申报的对象是主管部门，告诉学生考试时间要用〈通知〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0951cffc-c221-4855-94ff-5e8df6e4b522') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95256, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我去年申报了过一次，没有通过。", "corrected_sentence": "我去年申报过一次，没有通过。", "error_description": "“申报”的经历体只用“过”，不能与“了”同时使用。应说“申报过”，不说“申报了过”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0951cffc-c221-4855-94ff-5e8df6e4b522') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95256, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我打算下个月向税务局申报了去年的收入。", "corrected_sentence": "我打算下个月向税务局申报去年的收入。", "error_description": "“下个月”指将来，不能与完成体“了”同用。应说“下个月向税务局申报去年的收入”，去掉“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0951cffc-c221-4855-94ff-5e8df6e4b522') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95257, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "亏损", "is_correct": true, "explanation": "反义：盈利与亏损是一对反义词，分别指做生意赚钱与赔钱。"}, {"text": "经营", "is_correct": false, "explanation": "无反义关系：经营指管理和运作，与“盈利”没有反义关系。"}, {"text": "生产", "is_correct": false, "explanation": "无反义关系：生产指制造东西，与“盈利”不构成反义。"}, {"text": "投资", "is_correct": false, "explanation": "无反义关系：投资指用钱获取收益，与“盈利”不是反义词。"}], "correct_answer": "亏损", "explanations": {"亏损": "反义：盈利与亏损是一对反义词，分别指做生意赚钱与赔钱。", "经营": "无反义关系：经营指管理和运作，与“盈利”没有反义关系。", "生产": "无反义关系：生产指制造东西，与“盈利”不构成反义。", "投资": "无反义关系：投资指用钱获取收益，与“盈利”不是反义词。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '293ba40b-5c94-4f9c-adcb-2dc4aaba108d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95257, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "亏损", "is_correct": true, "explanation": "反义：盈利与亏损是一对反义词，分别指做生意赚钱与赔钱。"}, {"text": "合作", "is_correct": false, "explanation": "无反义关系：合作指共同做事，与“盈利”没有反义关系。"}, {"text": "销售", "is_correct": false, "explanation": "无反义关系：销售指卖东西，与“盈利”不构成反义。"}, {"text": "采购", "is_correct": false, "explanation": "无反义关系：采购指买东西进货，与“盈利”不构成反义。"}], "correct_answer": "亏损", "explanations": {"亏损": "反义：盈利与亏损是一对反义词，分别指做生意赚钱与赔钱。", "合作": "无反义关系：合作指共同做事，与“盈利”没有反义关系。", "销售": "无反义关系：销售指卖东西，与“盈利”不构成反义。", "采购": "无反义关系：采购指买东西进货，与“盈利”不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '293ba40b-5c94-4f9c-adcb-2dc4aaba108d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95257, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "做生意赚到的钱比花掉的多。", "primary_collocate": null, "pronunciation": "yíng lì", "ipa": "iŋ˧˥ li˥˩", "syllable_count": 2, "sentences": [{"text": "这家小店去年开始盈利了。", "target_word": "盈利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司今年第一次盈利。", "target_word": "盈利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的网店已经盈利两年了。", "target_word": "盈利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家饭馆生意好，每个月都盈利。", "target_word": "盈利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新开的超市还没有盈利。", "target_word": "盈利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司为什么一直不盈利？", "target_word": "盈利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们卖水果，一年能盈利十万元。", "target_word": "盈利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个软件免费用，公司怎么盈利？", "target_word": "盈利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理说，咖啡店下个月就能盈利。", "target_word": "盈利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "虽然很忙，书店还是没盈利。", "target_word": "盈利", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "盈利了", "label": "体标"}, {"form": "盈利过", "label": "体标"}], "register": "中性", "sense_fingerprint": "做生意赚的钱比花的钱多（动词）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4747408d-1a98-454a-a674-44dda78aa04a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95257, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "盈利", "is_correct": true, "explanation": "正确答案。盈利（yíng lì）指做生意赚的钱比花的多。"}, {"text": "应力", "is_correct": false, "explanation": "声调混淆：yìng（第四声）与 yíng（第二声）只差声调，意思是受力时物体内部产生的力，与盈利无关。"}, {"text": "灵力", "is_correct": false, "explanation": "声母不同（l 与 y），声调相同（第二声），意思是神秘的力量。"}, {"text": "凌厉", "is_correct": false, "explanation": "声母不同（l 与 y），声调相同（第二声），意思是严厉、猛烈。"}], "explanations": {"盈利": "正确答案。盈利（yíng lì）指做生意赚的钱比花的多。", "应力": "声调混淆：yìng（第四声）与 yíng（第二声）只差声调，意思是受力时物体内部产生的力，与盈利无关。", "灵力": "声母不同（l 与 y），声调相同（第二声），意思是神秘的力量。", "凌厉": "声母不同（l 与 y），声调相同（第二声），意思是严厉、猛烈。"}, "sentence_index": null, "correct_answer": "盈利"}, "level_3": {"options": [{"text": "盈利", "is_correct": true, "explanation": "正确。盈利指做生意赚的钱比花的多，与“去年开始”“了”的语境相符。"}, {"text": "结婚", "is_correct": false, "explanation": "语义：小店不能结婚，“结婚”只能用于人。"}, {"text": "散步", "is_correct": false, "explanation": "语义：散步是人或动物的动作，小店不能散步。"}, {"text": "毕业", "is_correct": false, "explanation": "搭配：“毕业”用于学生或学员，不能用于小店。"}], "explanations": {"盈利": "正确。盈利指做生意赚的钱比花的多，与“去年开始”“了”的语境相符。", "结婚": "语义：小店不能结婚，“结婚”只能用于人。", "散步": "语义：散步是人或动物的动作，小店不能散步。", "毕业": "搭配：“毕业”用于学生或学员，不能用于小店。"}, "sentence_index": 0, "correct_answer": "盈利"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家超市晚上十点停止盈利。", "explanation": "这里应该用〈营业〉。盈利指做生意赚的钱比花的多，说店铺的营业时间要用“营业”，不能说“停止盈利”。"}, {"text": "我在公司上班，每个月盈利五千元。", "explanation": "这里应该用〈挣〉。盈利指做生意赚到的钱比花的多，靠工作领工资的人不说盈利。"}, {"text": "这个网站每天盈利二十四小时。", "explanation": "这里应该用〈运营〉。盈利是赚钱的意思，不能用来说持续多少个小时。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '293ba40b-5c94-4f9c-adcb-2dc4aaba108d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95257, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "盈利", "is_correct": true, "explanation": "正确答案。盈利（yíng lì）指做生意赚的钱比花的多。"}, {"text": "伶俐", "is_correct": false, "explanation": "声母不同（l 与 y），两字声调与盈利相同，意思是聪明灵巧。"}, {"text": "应力", "is_correct": false, "explanation": "声调混淆：yìng（第四声）与 yíng（第二声）只差声调，意思是物体受力时内部产生的力。"}, {"text": "引力", "is_correct": false, "explanation": "韵尾不同（yǐn 的 n 与 yíng 的 ng），意思是物体相互吸引的力。"}], "explanations": {"盈利": "正确答案。盈利（yíng lì）指做生意赚的钱比花的多。", "伶俐": "声母不同（l 与 y），两字声调与盈利相同，意思是聪明灵巧。", "应力": "声调混淆：yìng（第四声）与 yíng（第二声）只差声调，意思是物体受力时内部产生的力。", "引力": "韵尾不同（yǐn 的 n 与 yíng 的 ng），意思是物体相互吸引的力。"}, "sentence_index": null, "correct_answer": "盈利"}, "level_3": {"options": [{"text": "盈利", "is_correct": true, "explanation": "正确。“一年能盈利十万元”指一年赚到十万元的利润。"}, {"text": "唱歌", "is_correct": false, "explanation": "语义：“唱歌”是动作，不能与金额搭配表示赚到的钱。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：“游泳”是动作，不能表示赚到十万元。"}, {"text": "出版", "is_correct": false, "explanation": "搭配：“出版”用于书刊、音像等，不能用于金钱数额。"}], "explanations": {"盈利": "正确。“一年能盈利十万元”指一年赚到十万元的利润。", "唱歌": "语义：“唱歌”是动作，不能与金额搭配表示赚到的钱。", "游泳": "语义：“游泳”是动作，不能表示赚到十万元。", "出版": "搭配：“出版”用于书刊、音像等，不能用于金钱数额。"}, "sentence_index": 6, "correct_answer": "盈利"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个学期，他的成绩盈利了不少。", "explanation": "这里应该用〈提高〉。盈利只用于企业或店铺赚钱，成绩不能盈利。"}, {"text": "他每天早上八点盈利。", "explanation": "这里应该用〈上班〉。盈利指做生意赚钱，不能用来说人的上班时间。"}, {"text": "这家店每晚十点盈利。", "explanation": "这里应该用〈打烊〉。盈利不能用来说店铺的关门时间。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '293ba40b-5c94-4f9c-adcb-2dc4aaba108d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_error