INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95257, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家店去年盈利着。", "corrected_sentence": "这家店去年盈利了。", "error_description": "错误：“去年”指已经完成的时间，“着”表示持续的状态，二者不搭配，应改为完成态“盈利了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '293ba40b-5c94-4f9c-adcb-2dc4aaba108d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95257, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家书店明年能盈利过。", "corrected_sentence": "这家书店明年能盈利。", "error_description": "错误：“明年能”说的是将来的可能，“过”表示过去的经历，二者不搭配，应去掉“过”，说“明年能盈利”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '293ba40b-5c94-4f9c-adcb-2dc4aaba108d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95258, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "亏损", "is_correct": true, "explanation": "反义：盈利与亏损是一对反义词，分别指企业经营赚到的利润与亏掉的钱。"}, {"text": "资产", "is_correct": false, "explanation": "无反义关系：资产指拥有的财产，与“盈利”没有反义关系。"}, {"text": "品牌", "is_correct": false, "explanation": "无反义关系：品牌指产品的牌子，与“盈利”不构成反义。"}, {"text": "股份", "is_correct": false, "explanation": "无反义关系：股份指股权的份额，与“盈利”不构成反义。"}], "correct_answer": "亏损", "explanations": {"亏损": "反义：盈利与亏损是一对反义词，分别指企业经营赚到的利润与亏掉的钱。", "资产": "无反义关系：资产指拥有的财产，与“盈利”没有反义关系。", "品牌": "无反义关系：品牌指产品的牌子，与“盈利”不构成反义。", "股份": "无反义关系：股份指股权的份额，与“盈利”不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '293ba40b-5c94-4f9c-adcb-2dc4aaba108d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95258, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "亏损", "is_correct": true, "explanation": "反义：盈利与亏损是一对反义词，分别指企业经营赚到的利润与亏掉的钱。"}, {"text": "税收", "is_correct": false, "explanation": "无反义关系：税收指国家征收的钱，与“盈利”不构成反义。"}, {"text": "股息", "is_correct": false, "explanation": "无反义关系：股息指股东分得的红利，与“盈利”不是反义词。"}, {"text": "薪资", "is_correct": false, "explanation": "无反义关系：薪资指员工的工资，与“盈利”没有反义关系。"}], "correct_answer": "亏损", "explanations": {"亏损": "反义：盈利与亏损是一对反义词，分别指企业经营赚到的利润与亏掉的钱。", "税收": "无反义关系：税收指国家征收的钱，与“盈利”不构成反义。", "股息": "无反义关系：股息指股东分得的红利，与“盈利”不是反义词。", "薪资": "无反义关系：薪资指员工的工资，与“盈利”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '293ba40b-5c94-4f9c-adcb-2dc4aaba108d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95258, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "企业经营所获得的利润。", "primary_collocate": null, "pronunciation": "yíng lì", "ipa": "iŋ˧˥ li˥˩", "syllable_count": 2, "sentences": [{"text": "这家公司今年的盈利很高。", "target_word": "盈利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "去年的盈利比前年多了一倍。", "target_word": "盈利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "盈利下降，老板很担心。", "target_word": "盈利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把一半的盈利拿来买新机器。", "target_word": "盈利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司的盈利主要来自海外市场。", "target_word": "盈利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要想办法提高盈利。", "target_word": "盈利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个季度的盈利是五百万元。", "target_word": "盈利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "盈利增加了，员工的工资也高了。", "target_word": "盈利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报告里写着公司的全年盈利。", "target_word": "盈利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小店的盈利不多，但是很稳定。", "target_word": "盈利", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "企业经营获得的利润（名词）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4747408d-1a98-454a-a674-44dda78aa04a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95258, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "盈利", "is_correct": true, "explanation": "正确答案。盈利（yíng lì）指企业经营所获得的利润。"}, {"text": "应力", "is_correct": false, "explanation": "声调混淆：yìng（第四声）与 yíng（第二声）只差声调，意思是受力时物体内部产生的力，与盈利无关。"}, {"text": "灵力", "is_correct": false, "explanation": "声母不同（l 与 y），声调相同（第二声），意思是神秘的力量。"}, {"text": "凌厉", "is_correct": false, "explanation": "声母不同（l 与 y），声调相同（第二声），意思是严厉、猛烈。"}], "explanations": {"盈利": "正确答案。盈利（yíng lì）指企业经营所获得的利润。", "应力": "声调混淆：yìng（第四声）与 yíng（第二声）只差声调，意思是受力时物体内部产生的力，与盈利无关。", "灵力": "声母不同（l 与 y），声调相同（第二声），意思是神秘的力量。", "凌厉": "声母不同（l 与 y），声调相同（第二声），意思是严厉、猛烈。"}, "sentence_index": null, "correct_answer": "盈利"}, "level_3": {"options": [{"text": "盈利", "is_correct": true, "explanation": "正确。盈利指企业经营赚到的利润，可以“很高”。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：说“体重”用“重”，不说“高”，也不属于公司。"}, {"text": "名字", "is_correct": false, "explanation": "语义：名字没有高低，不能用“很高”来描述公司。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不属于公司的经营情况，“这家公司今年的天气很高”说不通。"}], "explanations": {"盈利": "正确。盈利指企业经营赚到的利润，可以“很高”。", "体重": "搭配：说“体重”用“重”，不说“高”，也不属于公司。", "名字": "语义：名字没有高低，不能用“很高”来描述公司。", "天气": "语义：天气不属于公司的经营情况，“这家公司今年的天气很高”说不通。"}, "sentence_index": 0, "correct_answer": "盈利"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "员工的盈利提高了。", "explanation": "这里应该用〈工资〉。盈利是企业经营赚到的利润，员工的工资不能说盈利。"}, {"text": "这家公司去年有一只盈利。", "explanation": "这里应该用〈笔〉。盈利用“笔”计量，“只”用于动物或单个物件。"}, {"text": "这次活动对大家都有盈利。", "explanation": "这里应该用〈利益〉。盈利指企业经营赚到的钱，对大家的好处不能说盈利。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '293ba40b-5c94-4f9c-adcb-2dc4aaba108d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95258, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "盈利", "is_correct": true, "explanation": "正确答案。盈利（yíng lì）指企业经营所获得的利润。"}, {"text": "伶俐", "is_correct": false, "explanation": "声母不同（l 与 y），两字声调与盈利相同，意思是聪明灵巧。"}, {"text": "应力", "is_correct": false, "explanation": "声调混淆：yìng（第四声）与 yíng（第二声）只差声调，意思是物体受力时内部产生的力。"}, {"text": "引力", "is_correct": false, "explanation": "韵尾不同（yǐn 的 n 与 yíng 的 ng），意思是物体相互吸引的力。"}], "explanations": {"盈利": "正确答案。盈利（yíng lì）指企业经营所获得的利润。", "伶俐": "声母不同（l 与 y），两字声调与盈利相同，意思是聪明灵巧。", "应力": "声调混淆：yìng（第四声）与 yíng（第二声）只差声调，意思是物体受力时内部产生的力。", "引力": "韵尾不同（yǐn 的 n 与 yíng 的 ng），意思是物体相互吸引的力。"}, "sentence_index": null, "correct_answer": "盈利"}, "level_3": {"options": [{"text": "盈利", "is_correct": true, "explanation": "正确。盈利指企业经营赚到的利润，符合“这个季度的……是五百万元”。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：年龄是岁数，不是金额，不能说“是五百万元”。"}, {"text": "身高", "is_correct": false, "explanation": "搭配：身高用厘米、米计量，不说“元”。"}, {"text": "体温", "is_correct": false, "explanation": "搭配：体温用“度”计量，不说“元”。"}], "explanations": {"盈利": "正确。盈利指企业经营赚到的利润，符合“这个季度的……是五百万元”。", "年龄": "语义：年龄是岁数，不是金额，不能说“是五百万元”。", "身高": "搭配：身高用厘米、米计量，不说“元”。", "体温": "搭配：体温用“度”计量，不说“元”。"}, "sentence_index": 6, "correct_answer": "盈利"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位老师的盈利不多，但是很稳定。", "explanation": "这里应该用〈收入〉。盈利指企业经营的利润，老师的工资收入不能说盈利。"}, {"text": "这家小店今年有一根盈利。", "explanation": "这里应该用〈笔〉。盈利用“笔”计量，“根”用于细长的东西。"}, {"text": "这家店每天盈利到十点。", "explanation": "这里应该用〈营业〉。盈利指赚到的利润，不能用来说店铺营业到几点。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '293ba40b-5c94-4f9c-adcb-2dc4aaba108d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95258, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家工厂去年有一张可观的盈利。", "corrected_sentence": "这家工厂去年有一笔可观的盈利。", "error_description": "“盈利”的量词应用“笔”，不能用“张”，应说“一笔可观的盈利”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '293ba40b-5c94-4f9c-adcb-2dc4aaba108d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95258, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这只盈利有五百万元。", "corrected_sentence": "这笔盈利有五百万元。", "error_description": "盈利的计量词应为“笔”，不用“只”，应说“这笔盈利”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '293ba40b-5c94-4f9c-adcb-2dc4aaba108d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
