INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95259, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "不用做了，少做一件事。", "primary_collocate": null, "pronunciation": "shěng què", "ipa": "ʂɤŋ˨˩˦ tɕʰɥɛ˥˩", "syllable_count": 2, "sentences": [{"text": "这一步可以省却，直接开始吧。", "target_word": "省却", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友之间，客气话就省却了。", "target_word": "省却", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "时间不够，开会前的介绍省却了。", "target_word": "省却", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，今天的听写可以省却。", "target_word": "省却", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们是熟人，这些手续省却了吧。", "target_word": "省却", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你已经懂了，我就省却解释了。", "target_word": "省却", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这道菜省却了煎的步骤。", "target_word": "省却", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天太晚了，复习就省却吧。", "target_word": "省却", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们省却开场白，直接说正事。", "target_word": "省却", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都认识，自我介绍就省却了。", "target_word": "省却", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "省却了", "label": "体标"}], "register": "书面", "sense_fingerprint": "省却：把某个步骤、话语或环节略去不做", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '016a8d2a-68e4-4db2-b1cd-c081d7aad3bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95259, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "省却", "is_correct": true, "explanation": "省却：略去不做，符合“直接开始”的语境。"}, {"text": "增加", "is_correct": false, "explanation": "语义：“增加”是加上这一步，与“直接开始”的语境相反。"}, {"text": "感谢", "is_correct": false, "explanation": "配价：“感谢”要求的对象是人，不能以“这一步”作宾语。"}, {"text": "叹息", "is_correct": false, "explanation": "配价：“叹息”是不及物动词，不能带“这一步”作宾语。"}], "explanations": {"省却": "省却：略去不做，符合“直接开始”的语境。", "增加": "语义：“增加”是加上这一步，与“直接开始”的语境相反。", "感谢": "配价：“感谢”要求的对象是人，不能以“这一步”作宾语。", "叹息": "配价：“叹息”是不及物动词，不能带“这一步”作宾语。"}, "sentence_index": 0, "correct_answer": "省却"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工人省却了路上的积雪。", "explanation": "这里应该用〈清除〉。省却指把某个步骤、话语或环节略去不做，不能用来说清除路上的积雪。"}, {"text": "老师省却了全班同学。", "explanation": "这里“省却”被误用为“略去、不理会某人”。省却的对象只能是步骤、手续、话语等环节，不能是人。"}, {"text": "他省却了老师的名字。", "explanation": "这里应该用〈忘记〉。省却只能免去可以不做的步骤或手续，不能用来说忘记别人的名字。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04d2236b-4500-4360-93e1-98363f6eb264') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95259, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "省却", "is_correct": true, "explanation": "省却：略去不做，符合“这道菜”省去煎的步骤的语境。"}, {"text": "讨论", "is_correct": false, "explanation": "配价：“讨论”的主体须是人，“这道菜”不能作主语。"}, {"text": "监督", "is_correct": false, "explanation": "语义：“监督”是管理他人的行为，用在菜的做法上说不通。"}, {"text": "嫌弃", "is_correct": false, "explanation": "配价：“嫌弃”的主语须是人，“这道菜”不能嫌弃什么。"}], "explanations": {"省却": "省却：略去不做，符合“这道菜”省去煎的步骤的语境。", "讨论": "配价：“讨论”的主体须是人，“这道菜”不能作主语。", "监督": "语义：“监督”是管理他人的行为，用在菜的做法上说不通。", "嫌弃": "配价：“嫌弃”的主语须是人，“这道菜”不能嫌弃什么。"}, "sentence_index": 6, "correct_answer": "省却"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈省却了桌上的碗。", "explanation": "这里应该用〈收走〉。省却指略去某个步骤或环节不做，碗是具体的东西，不能被省却。"}, {"text": "老板省却了我们的请假。", "explanation": "这里应该用〈同意〉。请假需要批准，不是可以略去的步骤，省却不能这样用。"}, {"text": "她省却了对丈夫的信任。", "explanation": "这里“省却”被误用为“不再信任”。省却指把步骤、话语、环节略去不做，不能用于信任这类情感。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04d2236b-4500-4360-93e1-98363f6eb264') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95259, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这份表格可以省却着，大家直接交材料吧。", "corrected_sentence": "这份表格可以省却，大家直接交材料吧。", "error_description": "错误：“省却”是一次性完成的动作，不能用“着”表示持续状态，句中“可以省却着”里的“着”多余。正确：“这份表格可以省却”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04d2236b-4500-4360-93e1-98363f6eb264') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95259, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "做这道菜时，可以省却得煎的步骤。", "corrected_sentence": "做这道菜时，可以省却煎的步骤。", "error_description": "错误形式是“省却得煎的步骤”，正确形式是“省却煎的步骤”。“得”不能插在动词和宾语之间，这里多余。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04d2236b-4500-4360-93e1-98363f6eb264') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
