INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95260, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04d2236b-4500-4360-93e1-98363f6eb264') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95260, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "免去；节省掉。", "primary_collocate": null, "pronunciation": "shěng què", "ipa": "ʂɤŋ˨˩˦ tɕʰɥɛ˥˩", "syllable_count": 2, "sentences": [{"text": "坐地铁省却了不少时间。", "target_word": "省却", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网上买票省却了排队的麻烦。", "target_word": "省却", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "自己做饭省却了一大笔开支。", "target_word": "省却", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个办法省却了许多费用。", "target_word": "省却", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新机器省却了很多人力。", "target_word": "省却", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这样做可以省却不少手续。", "target_word": "省却", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "搬到公司旁边，省却了每天坐车的时间。", "target_word": "省却", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他发电子邮件，省却了寄信的钱。", "target_word": "省却", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有了洗碗机，省却了不少家务活。", "target_word": "省却", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "用手机付款省却了找零的麻烦。", "target_word": "省却", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "省却了", "label": "体标"}], "register": "书面", "sense_fingerprint": "省却：靠某种方式免去或节省掉时间、费用、麻烦等", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '016a8d2a-68e4-4db2-b1cd-c081d7aad3bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95260, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "省却", "is_correct": true, "explanation": "省却：免去或节省掉，符合“坐地铁”带来的时间节省。"}, {"text": "批评", "is_correct": false, "explanation": "配价：“批评”要求的对象是人或言行，不能以“时间”作宾语。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”不能和“时间”搭配，“洗了不少时间”说不通。"}, {"text": "迎接", "is_correct": false, "explanation": "语义：“迎接”指欢迎到来的人或事，与“坐地铁”所省下的时间不合。"}], "explanations": {"省却": "省却：免去或节省掉，符合“坐地铁”带来的时间节省。", "批评": "配价：“批评”要求的对象是人或言行，不能以“时间”作宾语。", "洗": "搭配：“洗”不能和“时间”搭配，“洗了不少时间”说不通。", "迎接": "语义：“迎接”指欢迎到来的人或事，与“坐地铁”所省下的时间不合。"}, "sentence_index": 0, "correct_answer": "省却"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "上级省却了他的职务。", "explanation": "这里应该用〈免去〉。省却只用于时间、费用、手续、麻烦这类可以省掉的事，不能用来说免去某人的职务。"}, {"text": "他省却了这次很好的机会。", "explanation": "这里应该用〈放弃〉。省却表示免去不必要的麻烦，不能用来说放弃宝贵的机会。"}, {"text": "他一早起来，省却了桌上的灰尘。", "explanation": "这里应该用〈清除〉。省却只用于时间、费用、手续、麻烦这类可以省掉的事，不能用来说清除桌上的灰尘。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04d2236b-4500-4360-93e1-98363f6eb264') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95260, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "省却", "is_correct": true, "explanation": "省却：免去麻烦、节省时间，符合“搬到公司旁边”的语境。"}, {"text": "拒绝", "is_correct": false, "explanation": "配价：“拒绝”需要邀请、请求等作宾语，“时间”不能被拒绝。"}, {"text": "完成", "is_correct": false, "explanation": "语义：“完成”指做完任务，“每天坐车的时间”不能被完成。"}, {"text": "答应", "is_correct": false, "explanation": "配价：“答应”需要请求或要求作宾语，不能带“时间”作宾语。"}], "explanations": {"省却": "省却：免去麻烦、节省时间，符合“搬到公司旁边”的语境。", "拒绝": "配价：“拒绝”需要邀请、请求等作宾语，“时间”不能被拒绝。", "完成": "语义：“完成”指做完任务，“每天坐车的时间”不能被完成。", "答应": "配价：“答应”需要请求或要求作宾语，不能带“时间”作宾语。"}, "sentence_index": 6, "correct_answer": "省却"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他省却了一位好朋友。", "explanation": "这里应该用〈失去〉。省却只用于时间、费用、手续、麻烦这类可以免去的事，不能用来说失去一位朋友。"}, {"text": "我省却了他的邀请。", "explanation": "这里应该用〈拒绝〉。省却表示免去、节省，不表示拒绝别人的邀请。"}, {"text": "她省却了对家乡的思念。", "explanation": "这里“省却”被误用为“不再思念”。省却只用于时间、费用、手续、麻烦这类可以免去的事，不能用于思念这类心理活动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04d2236b-4500-4360-93e1-98363f6eb264') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95260, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "改成线上办理，省却的了很多手续。", "corrected_sentence": "改成线上办理，省却了很多手续。", "error_description": "错误：“的”是定语标记，不能插在动词“省却”和宾语“很多手续”之间，且“的”后接“了”，句子不通。正确：“改成线上办理，省却了很多手续。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04d2236b-4500-4360-93e1-98363f6eb264') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95260, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "改用无线充电，省却着插线的麻烦。", "corrected_sentence": "改用无线充电，省却了插线的麻烦。", "error_description": "错误形式是“省却着”，正确形式是“省却了”。“着”表示持续状态，这里说的是已经完成的省去，应该用“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04d2236b-4500-4360-93e1-98363f6eb264') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
