INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95261, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "墙上可以看到外面的那个口子。", "primary_collocate": null, "pronunciation": "chuāng kǒu", "ipa": "tʂʰuɑŋ⁵⁵ kʰou²¹⁴", "syllable_count": 2, "sentences": [{"text": "他坐在窗口,看着外面的雨。", "target_word": "窗口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "窗口开着,房间里很凉快。", "target_word": "窗口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小猫跳上窗口,晒太阳。", "target_word": "窗口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外面下大雨了，雨从窗口飘了进来。", "target_word": "窗口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "窗口外面有一棵很大的树。", "target_word": "窗口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈站在窗口,等孩子回家。", "target_word": "窗口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这间屋子的窗口朝南,阳光很好。", "target_word": "窗口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风从窗口吹进来,很舒服。", "target_word": "窗口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "窗口太小了,屋里不太亮。", "target_word": "窗口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子趴在窗口,看楼下的小狗。", "target_word": "窗口", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "窗口边", "label": "复合"}], "register": "中性", "sense_fingerprint": "墙上装窗、可以看到外面的开口", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78e60e0e-e792-48a1-bca2-90faf2e2bfb6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95261, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "窗口", "is_correct": true, "explanation": "正确：“窗口”指墙上可以看到外面的开口，人可以坐在旁边看雨。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：“冰箱”不能供人坐，与“坐在”的语境不合。"}, {"text": "黑板", "is_correct": false, "explanation": "语义：“黑板”是教室里的书写板，不能用来坐。"}, {"text": "电视", "is_correct": false, "explanation": "搭配：“坐在”后接的是可以坐的地方，不说“坐在电视”。"}], "explanations": {"窗口": "正确：“窗口”指墙上可以看到外面的开口，人可以坐在旁边看雨。", "冰箱": "语义：“冰箱”不能供人坐，与“坐在”的语境不合。", "黑板": "语义：“黑板”是教室里的书写板，不能用来坐。", "电视": "搭配：“坐在”后接的是可以坐的地方，不说“坐在电视”。"}, "sentence_index": 0, "correct_answer": "窗口"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把作业写在窗口上，一写就是一晚上。", "explanation": "这里应该用〈纸〉或〈本子〉。“窗口”指墙上的开口，不能当作写字的地方。"}, {"text": "天亮了，窗口拉开了。", "explanation": "这里应该用〈窗帘〉。窗口是墙上的开口，不能拉开，拉开的是窗帘。"}, {"text": "这个窗口很可爱，每天都会摇尾巴。", "explanation": "这里应该用〈小狗〉。窗口是墙上的开口，不会摇尾巴，应说“小狗”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16dcdeb9-61f9-472a-9708-f012839813a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95261, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "窗口", "is_correct": true, "explanation": "正确：“窗口”指屋子的墙上可以透光、通风的开口，可以朝南。"}, {"text": "价格", "is_correct": false, "explanation": "语义：“价格”没有朝向，不能说“朝南”。"}, {"text": "名字", "is_correct": false, "explanation": "语义：“名字”没有朝向，与“朝南，阳光很好”的语境不合。"}, {"text": "声音", "is_correct": false, "explanation": "搭配：“朝南”用于房屋、窗户等有朝向的事物，“声音”不说朝向。"}], "explanations": {"窗口": "正确：“窗口”指屋子的墙上可以透光、通风的开口，可以朝南。", "价格": "语义：“价格”没有朝向，不能说“朝南”。", "名字": "语义：“名字”没有朝向，与“朝南，阳光很好”的语境不合。", "声音": "搭配：“朝南”用于房屋、窗户等有朝向的事物，“声音”不说朝向。"}, "sentence_index": 6, "correct_answer": "窗口"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用窗口切了一块西瓜。", "explanation": "这里应该用〈刀〉。窗口是墙上的开口，不能用来切东西。"}, {"text": "一个窗口挂在墙上，很好看。", "explanation": "这里应该用〈画〉。窗口是墙上的开口，不能挂在墙上。"}, {"text": "我家的窗口很爱笑，每天都很开心。", "explanation": "这里应该用〈孩子〉。窗口是墙上的开口，不会笑，应说“孩子”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16dcdeb9-61f9-472a-9708-f012839813a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95261, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我家的窗口一直开了着，屋里很凉快。", "corrected_sentence": "我家的窗口一直开着，屋里很凉快。", "error_description": "错误形式：“我家的窗口一直开了着”；正确形式：“我家的窗口一直开着”。同一个动词不能同时带体标“了”和“着”，“开”后多余的“了”应删去，保留“着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16dcdeb9-61f9-472a-9708-f012839813a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95261, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "屋子的墙上开了一只窗口。", "corrected_sentence": "屋子的墙上开了一个窗口。", "error_description": "错误形式：“一只窗口”；正确形式：“一个窗口”。“窗口”的量词应用“个”，不能用“只”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16dcdeb9-61f9-472a-9708-f012839813a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95262, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16dcdeb9-61f9-472a-9708-f012839813a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95262, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16dcdeb9-61f9-472a-9708-f012839813a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95262, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "办事时对外办理业务的小窗口，如银行、车站的服务台。", "primary_collocate": null, "pronunciation": "chuāng kǒu", "ipa": "tʂʰuɑŋ⁵⁵ kʰou²¹⁴", "syllable_count": 2, "sentences": [{"text": "银行的窗口十点才开门。", "target_word": "窗口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请到三号窗口办手续。", "target_word": "窗口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在火车站的窗口买了两张票。", "target_word": "窗口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院的窗口前有很多人在排队。", "target_word": "窗口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你去窗口问一下,工作人员会告诉你。", "target_word": "窗口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个窗口只办护照,不办身份证。", "target_word": "窗口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "窗口里的工作人员很热情。", "target_word": "窗口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下午五点,窗口就关了。", "target_word": "窗口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在窗口交了钱,拿到了收据。", "target_word": "窗口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在窗口等了很久,还没轮到我。", "target_word": "窗口", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "服务窗口", "label": "复合"}], "register": "中性", "sense_fingerprint": "银行、车站等办理业务的服务窗口", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78e60e0e-e792-48a1-bca2-90faf2e2bfb6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95262, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "窗口", "is_correct": true, "explanation": "正确：“窗口”指银行办理业务的服务台，银行的窗口按时开门，符合句意。"}, {"text": "饭", "is_correct": false, "explanation": "搭配：“开门”与“饭”不搭配，说“开饭”才对。"}, {"text": "水果", "is_correct": false, "explanation": "语义：“水果”不能开门，与银行营业的语境不合。"}, {"text": "小狗", "is_correct": false, "explanation": "语义：“小狗”不是营业场所，不能说它十点才开门。"}], "explanations": {"窗口": "正确：“窗口”指银行办理业务的服务台，银行的窗口按时开门，符合句意。", "饭": "搭配：“开门”与“饭”不搭配，说“开饭”才对。", "水果": "语义：“水果”不能开门，与银行营业的语境不合。", "小狗": "语义：“小狗”不是营业场所，不能说它十点才开门。"}, "sentence_index": 0, "correct_answer": "窗口"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他提着一个窗口去超市买了一斤苹果。", "explanation": "这里应该用〈篮子〉。窗口是银行、车站等办理业务的地方，不能提着去装东西。"}, {"text": "他推开医院的窗口，走进了大厅。", "explanation": "这里应该用〈大门〉。服务窗口不能推开走进去，进大厅要用门。"}, {"text": "这个窗口很会唱歌，大家都很喜欢。", "explanation": "这里应该用〈歌手〉。窗口是办事的小窗，不会唱歌，应说“歌手”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16dcdeb9-61f9-472a-9708-f012839813a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95262, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "窗口", "is_correct": true, "explanation": "正确：“窗口”指办事的服务台，窗口里的工作人员很热情，符合句意。"}, {"text": "鱼缸", "is_correct": false, "explanation": "语义：“鱼缸”里不能有办事的工作人员，与句意不合。"}, {"text": "口袋", "is_correct": false, "explanation": "语义：“口袋”装不下工作人员，与句意不合。"}, {"text": "垃圾桶", "is_correct": false, "explanation": "搭配：“里”前的场所要能容纳办事人员，“垃圾桶”不能用于办事，这种说法不通。"}], "explanations": {"窗口": "正确：“窗口”指办事的服务台，窗口里的工作人员很热情，符合句意。", "鱼缸": "语义：“鱼缸”里不能有办事的工作人员，与句意不合。", "口袋": "语义：“口袋”装不下工作人员，与句意不合。", "垃圾桶": "搭配：“里”前的场所要能容纳办事人员，“垃圾桶”不能用于办事，这种说法不通。"}, "sentence_index": 6, "correct_answer": "窗口"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用窗口切了一块蛋糕。", "explanation": "这里应该用〈刀〉。窗口是办理业务的地方，不能用来切东西。"}, {"text": "我在窗口跳了很久的舞，还没停。", "explanation": "这里应该用〈广场〉。窗口是办理业务的地方，不是跳舞的地方。"}, {"text": "他在窗口里踢了一场足球。", "explanation": "这里应该用〈操场〉。窗口不是足球场，不能在里面踢球。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16dcdeb9-61f9-472a-9708-f012839813a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95262, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只窗口只办理身份证业务。", "corrected_sentence": "这个窗口只办理身份证业务。", "error_description": "错误形式：“这只窗口”；正确形式：“这个窗口”。“窗口”的量词应用“个”，不能用“只”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16dcdeb9-61f9-472a-9708-f012839813a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95262, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我窗口领了一张表格。", "corrected_sentence": "我在窗口领了一张表格。", "error_description": "错误形式：“我窗口领”；正确形式：“我在窗口领”。表示动作发生的地点，要用介词“在”引出“窗口”，不能省略。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16dcdeb9-61f9-472a-9708-f012839813a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
