INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95263, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4a3377f-3e32-4c57-9340-b9253ea5873e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95263, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一个人做了坏事，别人给这件坏事起的名字。", "primary_collocate": null, "pronunciation": "zuì míng", "ipa": "tsweɪ˥˩ miŋ˧˥", "syllable_count": 2, "sentences": [{"text": "别人给他安了一个“小偷”的罪名。", "target_word": "罪名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他没有做错事，却有了说谎的罪名。", "target_word": "罪名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家给这个孩子安了迟到的罪名。", "target_word": "罪名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她担心别人给她加上坏人的罪名。", "target_word": "罪名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不想背着这个罪名过日子。", "target_word": "罪名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "杯子是弟弟打破的，哥哥却背了这个罪名。", "target_word": "罪名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给小明加了一个爱说谎的罪名。", "target_word": "罪名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没做过的事，不要让别人给你加罪名。", "target_word": "罪名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个罪名对她不公平，她很难过。", "target_word": "罪名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想让大家知道真相，洗清这个罪名。", "target_word": "罪名", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个罪名", "label": "量词"}], "register": "中性", "sense_fingerprint": "别人给坏事起的名字", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '755a2819-fc8e-4d21-b491-ab1430d215e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95263, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "罪名", "is_correct": true, "explanation": "“罪名”指别人给坏事起的名字，常说“给人安罪名”，与“安了一个‘小偷’的”搭配。"}, {"text": "奖状", "is_correct": false, "explanation": "语义：“奖状”是奖励好事的证明，与“小偷”的坏名声矛盾。"}, {"text": "成绩", "is_correct": false, "explanation": "搭配：“安”可接“罪名、帽子”，不能说“安了一个成绩”。"}, {"text": "名片", "is_correct": false, "explanation": "语义：“名片”是个人的身份卡，不是给人起的坏名声。"}], "explanations": {"罪名": "“罪名”指别人给坏事起的名字，常说“给人安罪名”，与“安了一个‘小偷’的”搭配。", "奖状": "语义：“奖状”是奖励好事的证明，与“小偷”的坏名声矛盾。", "成绩": "搭配：“安”可接“罪名、帽子”，不能说“安了一个成绩”。", "名片": "语义：“名片”是个人的身份卡，不是给人起的坏名声。"}, "sentence_index": 0, "correct_answer": "罪名"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个孩子有一个很好听的罪名。", "explanation": "这里应该用〈名字〉。罪名指别人给坏事起的说法，好听的称呼要用名字。"}, {"text": "他获得了一个荣誉罪名。", "explanation": "这里应该用〈称号〉。罪名只指坏事的名称，荣誉的名号要用称号。"}, {"text": "她被选为班长，这是一个光荣的罪名。", "explanation": "这里应该用〈头衔〉。头衔指职务或荣誉的名称，罪名指别人给坏事起的名字，不能用来形容荣誉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4a3377f-3e32-4c57-9340-b9253ea5873e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95263, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "罪名", "is_correct": true, "explanation": "“罪名”指别人给人起的坏名声，与“加了一个爱说谎的”搭配。"}, {"text": "奖品", "is_correct": false, "explanation": "语义：“奖品”是奖励好表现的东西，与“爱说谎”矛盾。"}, {"text": "证书", "is_correct": false, "explanation": "语义：“证书”是证明资格的文件，不能用来给人加上缺点。"}, {"text": "作业", "is_correct": false, "explanation": "语义：“作业”是学生的练习，不能是“爱说谎的”，与句意不合。"}], "explanations": {"罪名": "“罪名”指别人给人起的坏名声，与“加了一个爱说谎的”搭配。", "奖品": "语义：“奖品”是奖励好表现的东西，与“爱说谎”矛盾。", "证书": "语义：“证书”是证明资格的文件，不能用来给人加上缺点。", "作业": "语义：“作业”是学生的练习，不能是“爱说谎的”，与句意不合。"}, "sentence_index": 6, "correct_answer": "罪名"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "医生告诉他，他的罪名是感冒。", "explanation": "这里应该用〈病名〉。罪名指坏事的名称，疾病的名称要用病名。"}, {"text": "这艘船的罪名叫“海燕”。", "explanation": "这里应该用〈船名〉。罪名指坏事的名称，船的名字要用船名。"}, {"text": "这座小城的罪名叫“青山”。", "explanation": "这里应该用〈地名〉。罪名指坏事的名称，地方的名称要用地名。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4a3377f-3e32-4c57-9340-b9253ea5873e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95263, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "别人给她安了一张罪名，她很难过。", "corrected_sentence": "别人给她安了一个罪名，她很难过。", "error_description": "量词错误：“罪名”应配量词“个”，“一张罪名”是错误的。正确说法是“一个罪名”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4a3377f-3e32-4c57-9340-b9253ea5873e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95263, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "大家都说他是小偷，就这样给他安下了一个罪名。", "corrected_sentence": "大家都说他是小偷，就这样给他安上了一个罪名。", "error_description": "补语错误：“安”与“罪名”搭配时补语应为“上”，说“安下”是错误的。正确说法是“安上了一个罪名”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4a3377f-3e32-4c57-9340-b9253ea5873e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
