INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95266, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "老人和小孩，泛指一家人。", "primary_collocate": null, "pronunciation": "lǎo xiǎo", "ipa": "lɑʊ˨˩˦ ɕjɑʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "全家老小都来给奶奶过生日。", "target_word": "老小", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天工作，为了让老小过好日子。", "target_word": "老小", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一家老小都很感谢这位医生。", "target_word": "老小", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老小平安，他才放心。", "target_word": "老小", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一家老小住在一座小房子里。", "target_word": "老小", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "台风来了，他先送老小到安全的地方。", "target_word": "老小", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板请公司同事和他们的老小吃饭。", "target_word": "老小", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把老小都接到了城里。", "target_word": "老小", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过节的时候，老小团聚在一起。", "target_word": "老小", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们全家老小都喜欢看这个电视节目。", "target_word": "老小", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "泛指一家人或全家大大小小的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee0abe9c-383b-4465-adda-6a9bff074073') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95266, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "老小", "is_correct": true, "explanation": "正确：「全家老小」指全家大大小小的人，与「都来给奶奶过生日」吻合。"}, {"text": "外人", "is_correct": false, "explanation": "语义：「外人」不是家里人，与「全家」矛盾。"}, {"text": "邻居", "is_correct": false, "explanation": "语义：邻居不属于「全家」，句子说不通。"}, {"text": "客人", "is_correct": false, "explanation": "搭配：「全家」不说「全家客人」。"}], "explanations": {"老小": "正确：「全家老小」指全家大大小小的人，与「都来给奶奶过生日」吻合。", "外人": "语义：「外人」不是家里人，与「全家」矛盾。", "邻居": "语义：邻居不属于「全家」，句子说不通。", "客人": "搭配：「全家」不说「全家客人」。"}, "sentence_index": 0, "correct_answer": "老小"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "班里的老小都来了。", "explanation": "这里应该用〈同学〉。老小指家里的老人和孩子，班里的同学不能叫老小。"}, {"text": "公司的老小都放假了。", "explanation": "这里应该用〈员工〉。老小指家里的人，公司的员工放假不能用老小。"}, {"text": "这个病房的老小很快就好了。", "explanation": "这里应该用〈病人〉。老小指一家人的老人和孩子，病房里的病人不能叫老小。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c021f814-7f9b-4430-8829-5cdce2863511') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95266, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "老小", "is_correct": true, "explanation": "正确：「他们的老小」指同事的家人，与「吃饭」搭配的是人。"}, {"text": "行李", "is_correct": false, "explanation": "语义：行李不能和人一起吃饭，句子说不通。"}, {"text": "工资", "is_correct": false, "explanation": "语义：工资不能和人一起吃饭，与句意矛盾。"}, {"text": "桌椅", "is_correct": false, "explanation": "搭配：「吃饭」的对象是人，不能和桌椅一起吃饭。"}], "explanations": {"老小": "正确：「他们的老小」指同事的家人，与「吃饭」搭配的是人。", "行李": "语义：行李不能和人一起吃饭，句子说不通。", "工资": "语义：工资不能和人一起吃饭，与句意矛盾。", "桌椅": "搭配：「吃饭」的对象是人，不能和桌椅一起吃饭。"}, "sentence_index": 6, "correct_answer": "老小"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "饭店的老小都很满意。", "explanation": "这里应该用〈顾客〉。老小指家里的人，饭店的顾客不能叫老小。"}, {"text": "这趟车的老小都买了票。", "explanation": "这里应该用〈乘客〉。老小指家里的人，车上的乘客不能叫老小。"}, {"text": "景区的老小越来越多。", "explanation": "这里应该用〈游客〉。老小指家里的人，景区的游客不能叫老小。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c021f814-7f9b-4430-8829-5cdce2863511') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95266, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把一个老小都接到了郊区。", "corrected_sentence": "他把一家老小都接到了郊区。", "error_description": "错误：「老小」前的量词应用「家」，不能用「个」。正确说法是「一家老小」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c021f814-7f9b-4430-8829-5cdce2863511') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95266, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们全家老小们都在院子里吃月饼。", "corrected_sentence": "我们全家老小都在院子里吃月饼。", "error_description": "错误：「老小」是集合名词，后面不能再加「们」。正确说法是「全家老小都在院子里吃月饼」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c021f814-7f9b-4430-8829-5cdce2863511') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
