INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95267, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "参加考试的人。", "primary_collocate": null, "pronunciation": "kǎo shēng", "ipa": "kʰaʊ̯˨˩˦ ʂɤŋ˥", "syllable_count": 2, "sentences": [{"text": "参加公务员考试的考生很多。", "target_word": "考生", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "驾校的考生今天都通过了。", "target_word": "考生", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这次考试有三千名考生。", "target_word": "考生", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "年纪大的考生也在认真答题。", "target_word": "考生", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位考生已经复习了三个月。", "target_word": "考生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "监考老师检查每位考生的证件。", "target_word": "考生", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "很多考生是从外地赶来的。", "target_word": "考生", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "有的考生一边走一边复习。", "target_word": "考生", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "考生们拿着准考证走进考场。", "target_word": "考生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考试结束后，考生陆续离开了教室。", "target_word": "考生", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一名考生", "label": "量词（名）"}, {"form": "一位考生", "label": "量词（位）"}, {"form": "应届考生", "label": "复合词"}], "register": "中性", "sense_fingerprint": "参加各类考试的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd6312ee1-cc85-480e-9e11-314a38805b1d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95267, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "考生", "is_correct": true, "explanation": "“考生”指参加考试的人，符合“参加公务员考试的……很多”的语境。"}, {"text": "考场", "is_correct": false, "explanation": "语义：“考场”是考试的地方，不能“参加考试”，句子不通。"}, {"text": "试题", "is_correct": false, "explanation": "语义：“试题”是考试的题目，不能“参加考试”，句子不通。"}, {"text": "考卷", "is_correct": false, "explanation": "语义：“考卷”是试卷，不能参加考试，与句意不合。"}], "explanations": {"考生": "“考生”指参加考试的人，符合“参加公务员考试的……很多”的语境。", "考场": "语义：“考场”是考试的地方，不能“参加考试”，句子不通。", "试题": "语义：“试题”是考试的题目，不能“参加考试”，句子不通。", "考卷": "语义：“考卷”是试卷，不能参加考试，与句意不合。"}, "sentence_index": 0, "correct_answer": "考生"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "教室里坐着一只考生。", "explanation": "“只”多用于动物，指人应用「名」或「位」，这里量词用错了。"}, {"text": "我们班有一头考生。", "explanation": "“头”多用于牲畜，不能用来计数人，这里量词用错了。"}, {"text": "年纪大的考生负责发卷子，不能答题。", "explanation": "这里应该用〈监考员〉。考生指参加考试的人，负责发卷子的是监考员，不能称“考生”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c73c3855-31f5-4796-b66d-21a7a8336ea2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95267, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "考生", "is_correct": true, "explanation": "“考生”指参加考试的人，符合“很多……是从外地赶来的”的语境。"}, {"text": "行李", "is_correct": false, "explanation": "语义：“行李”是物品，不能自己“赶来”，句子不通。"}, {"text": "当地人", "is_correct": false, "explanation": "语义：当地人不是从外地赶来的，与句意相矛盾。"}, {"text": "餐桌", "is_correct": false, "explanation": "语义：“餐桌”不能“赶来”，只有人才能从外地赶来，句子不通。"}], "explanations": {"考生": "“考生”指参加考试的人，符合“很多……是从外地赶来的”的语境。", "行李": "语义：“行李”是物品，不能自己“赶来”，句子不通。", "当地人": "语义：当地人不是从外地赶来的，与句意相矛盾。", "餐桌": "语义：“餐桌”不能“赶来”，只有人才能从外地赶来，句子不通。"}, "sentence_index": 6, "correct_answer": "考生"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "一条考生走进了考场。", "explanation": "“条”多用于长条形的东西，指人应用「名」或「位」，这里量词用错了。"}, {"text": "考试前，考生负责出题，并把题目写在黑板上。", "explanation": "这里应该用〈老师〉。考生指参加考试的人，出题、写题目的是老师，不能用“考生”。"}, {"text": "这位考生负责监考，不能离开考场。", "explanation": "“考生”指参加考试的人，负责监考的人应称“监考员”，这里用错了对象。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c73c3855-31f5-4796-b66d-21a7a8336ea2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95267, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "很多只考生在等待。", "corrected_sentence": "很多考生在等待。", "error_description": "错误在于多余的量词“只”。“只”用于动物，不能用在“考生”前，正确应为“很多考生在等待”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c73c3855-31f5-4796-b66d-21a7a8336ea2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95267, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "一只考生在门口等候。", "corrected_sentence": "一位考生在门口等候。", "error_description": "错误在于量词“只”。“只”用于动物，不能修饰人，正确应为“一位考生”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c73c3855-31f5-4796-b66d-21a7a8336ea2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
