INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95268, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "参加考试的学生。", "primary_collocate": null, "pronunciation": "kǎo shēng", "ipa": "kʰaʊ̯˨˩˦ ʂɤŋ˥", "syllable_count": 2, "sentences": [{"text": "考生要带身份证进考场。", "target_word": "考生", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "今年有很多考生参加高考。", "target_word": "考生", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师让考生先坐好。", "target_word": "考生", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "考生们在门口排着队。", "target_word": "考生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位考生的字写得很漂亮。", "target_word": "考生", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "考生迟到十分钟就不能进场。", "target_word": "考生", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "一名考生考试时忘了带铅笔。", "target_word": "考生", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "考场外的考生都很紧张。", "target_word": "考生", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "家长在外面等着考生出来。", "target_word": "考生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校给考生准备了热水。", "target_word": "考生", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一名考生", "label": "量词（名）"}, {"form": "一位考生", "label": "量词（位）"}, {"form": "应届考生", "label": "复合词"}], "register": "中性", "sense_fingerprint": "参加考试的学生", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd6312ee1-cc85-480e-9e11-314a38805b1d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95268, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "考生", "is_correct": true, "explanation": "“考生”指参加考试的人，符合句中“带身份证进考场”的语境。"}, {"text": "书桌", "is_correct": false, "explanation": "语义：“书桌”是家具，不能带身份证进考场。"}, {"text": "顾客", "is_correct": false, "explanation": "语义：顾客与“进考场”的语境不合，句子不通。"}, {"text": "病人", "is_correct": false, "explanation": "语义：病人与“进考场带身份证”的语境不合，句子不通。"}], "explanations": {"考生": "“考生”指参加考试的人，符合句中“带身份证进考场”的语境。", "书桌": "语义：“书桌”是家具，不能带身份证进考场。", "顾客": "语义：顾客与“进考场”的语境不合，句子不通。", "病人": "语义：病人与“进考场带身份证”的语境不合，句子不通。"}, "sentence_index": 0, "correct_answer": "考生"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "教室里坐着一只考生。", "explanation": "“只”多用于动物，指人应用「名」或「位」，这里量词用错了。"}, {"text": "我们班有一头考生。", "explanation": "“头”多用于牲畜，不能用来计数人，这里量词用错了。"}, {"text": "这位考生负责监考，不能离开考场。", "explanation": "“考生”指参加考试的人，负责监考的人应称“监考员”，这里用错了对象。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c73c3855-31f5-4796-b66d-21a7a8336ea2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95268, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "考生", "is_correct": true, "explanation": "“考生”指参加考试的人，符合“考试时忘了带铅笔”的语境。"}, {"text": "小猫", "is_correct": false, "explanation": "语义：“小猫”是动物，不能用“名”计数，也不会参加考试。"}, {"text": "书包", "is_correct": false, "explanation": "语义：“书包”是物品，不能用“名”计数，也不会考试。"}, {"text": "考卷", "is_correct": false, "explanation": "语义：“考卷”是试卷，不能用“名”计数，也不会忘带铅笔。"}], "explanations": {"考生": "“考生”指参加考试的人，符合“考试时忘了带铅笔”的语境。", "小猫": "语义：“小猫”是动物，不能用“名”计数，也不会参加考试。", "书包": "语义：“书包”是物品，不能用“名”计数，也不会考试。", "考卷": "语义：“考卷”是试卷，不能用“名”计数，也不会忘带铅笔。"}, "sentence_index": 6, "correct_answer": "考生"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学校给一颗考生准备了热水。", "explanation": "“颗”多用于颗粒状的东西，指人应用「名」或「位」，这里量词用错了。"}, {"text": "这位考生在门口检查证件，不让人进场。", "explanation": "这里应该用〈监考老师〉。考生指参加考试的人，检查证件、拦人进场的是监考老师，不能用“考生”。"}, {"text": "这位考生负责给全校学生发毕业证书。", "explanation": "这里应该用〈工作人员〉。考生指参加考试的人，发放毕业证书的是学校工作人员，不能用“考生”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c73c3855-31f5-4796-b66d-21a7a8336ea2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95268, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只考生迟到了。", "corrected_sentence": "这名考生迟到了。", "error_description": "错误在于量词“只”。“只”用于动物，指人应用「名」或「位」，正确应为“这名考生迟到了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c73c3855-31f5-4796-b66d-21a7a8336ea2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95268, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "一头考生在门口等候。", "corrected_sentence": "一位考生在门口等候。", "error_description": "错误在于量词“头”。“头”用于牲畜，不能修饰人，正确应为“一位考生”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c73c3855-31f5-4796-b66d-21a7a8336ea2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95269, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "急躁", "is_correct": true, "explanation": "反义：耐心指不急不躁、持续做下去，急躁正与之相反。"}, {"text": "聪明", "is_correct": false, "explanation": "无关：“聪明”形容头脑灵活，与“耐心”没有反义关系。"}, {"text": "快速", "is_correct": false, "explanation": "无关：“快速”形容速度，与“耐心”的心性没有反义关系。"}, {"text": "安静", "is_correct": false, "explanation": "无关：“安静”形容环境或状态，与“耐心”没有反义关系。"}], "correct_answer": "急躁", "explanations": {"急躁": "反义：耐心指不急不躁、持续做下去，急躁正与之相反。", "聪明": "无关：“聪明”形容头脑灵活，与“耐心”没有反义关系。", "快速": "无关：“快速”形容速度，与“耐心”的心性没有反义关系。", "安静": "无关：“安静”形容环境或状态，与“耐心”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0951cffc-c221-4855-94ff-5e8df6e4b522') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95269, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0951cffc-c221-4855-94ff-5e8df6e4b522') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95269, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "遇到慢的事或难的事，也不着急，一直做下去。", "primary_collocate": null, "pronunciation": "nài xīn", "ipa": "naɪ̯⁵¹ ɕin⁵⁵", "syllable_count": 2, "sentences": [{"text": "老师耐心地给我讲了三遍。", "target_word": "耐心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "售货员很耐心，一件一件拿给我看。", "target_word": "耐心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你要耐心一点，别太着急。", "target_word": "耐心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生耐心地回答了病人的问题。", "target_word": "耐心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请耐心等一会儿，马上就好。", "target_word": "耐心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他耐心地教奶奶用手机。", "target_word": "耐心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她做事很耐心，慢慢来，不着急。", "target_word": "耐心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈耐心地陪着孩子写作业。", "target_word": "耐心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个工作很难，你得耐心做下去。", "target_word": "耐心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对小朋友要耐心，不能大声说话。", "target_word": "耐心", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "耐心地", "label": "状语形式"}, {"form": "耐心一点", "label": "程度搭配"}], "register": "中性", "sense_fingerprint": "形容词：做事不着急、肯慢慢坚持，常说耐心地、很耐心", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'db3644ad-b860-49ef-adcd-01357c77d0ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95269, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "耐心", "is_correct": true, "explanation": "正确：耐心地讲，形容讲的态度，与语境相符。"}, {"text": "英俊", "is_correct": false, "explanation": "体貌：“英俊”描写外貌，不能用来修饰“讲”。"}, {"text": "沉默", "is_correct": false, "explanation": "语义：“沉默”与“讲”的动作相矛盾，句意不通。"}, {"text": "狭窄", "is_correct": false, "explanation": "搭配：“狭窄”形容空间，不能修饰“讲”的方式。"}], "explanations": {"耐心": "正确：耐心地讲，形容讲的态度，与语境相符。", "英俊": "体貌：“英俊”描写外貌，不能用来修饰“讲”。", "沉默": "语义：“沉默”与“讲”的动作相矛盾，句意不通。", "狭窄": "搭配：“狭窄”形容空间，不能修饰“讲”的方式。"}, "sentence_index": 0, "correct_answer": "耐心"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他耐心地大发了一顿脾气，把大家都吓坏了。", "explanation": "这里不能用〈耐心〉。耐心表示不急躁、持续做下去，与大发脾气的急躁相矛盾。"}, {"text": "他耐心地一下子就跑完了一百米。", "explanation": "这里不能用〈耐心〉。耐心强调慢慢做、一直做下去，“一下子就跑完”指很快完成，两者矛盾。"}, {"text": "他耐心地马上就离开了。", "explanation": "这里不能用〈耐心〉。耐心强调持续坚持，“马上就离开”指立即行动，两者不搭配。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0951cffc-c221-4855-94ff-5e8df6e4b522') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95269, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "耐心", "is_correct": true, "explanation": "正确：做事耐心，与“慢慢来，不着急”相符。"}, {"text": "烦躁", "is_correct": false, "explanation": "语义：“烦躁”与“慢慢来，不着急”的态度相矛盾。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：“高大”形容身材，不能用来形容做事的态度。"}, {"text": "响亮", "is_correct": false, "explanation": "搭配：“响亮”形容声音，不能修饰“做事”。"}], "explanations": {"耐心": "正确：做事耐心，与“慢慢来，不着急”相符。", "烦躁": "语义：“烦躁”与“慢慢来，不着急”的态度相矛盾。", "高大": "体貌：“高大”形容身材，不能用来形容做事的态度。", "响亮": "搭配：“响亮”形容声音，不能修饰“做事”。"}, "sentence_index": 6, "correct_answer": "耐心"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他耐心地笑了一下，就转身走了。", "explanation": "这里不能用〈耐心〉。耐心强调持续做下去，“笑了一下”是短暂的动作，两者不搭配。"}, {"text": "他耐心地和朋友吵了一架。", "explanation": "这里不能用〈耐心〉。耐心指不急躁、不厌烦，与激烈争吵的情绪相矛盾。"}, {"text": "她耐心地从窗口跳了出去。", "explanation": "这里不能用〈耐心〉。耐心指持续的心态，“跳出去”是瞬间的动作，两者矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0951cffc-c221-4855-94ff-5e8df6e4b522') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95269, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "孩子们耐心地的等待老师回来。", "corrected_sentence": "孩子们耐心地等待老师回来。", "error_description": "“地”和“的”不能叠用，应去掉多余的“的”，说“耐心地等待”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0951cffc-c221-4855-94ff-5e8df6e4b522') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95269, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "你做这件事要耐心地一点。", "corrected_sentence": "你做这件事要耐心一点。", "error_description": "“耐心一点”是固定格式，“一点”前不能加“地”。应说“耐心一点”，不说“耐心地一点”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0951cffc-c221-4855-94ff-5e8df6e4b522') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
