INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95270, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "不急躁、不厌烦的心性。", "primary_collocate": null, "pronunciation": "nài xīn", "ipa": "naɪ̯⁵¹ ɕin⁵⁵", "syllable_count": 2, "sentences": [{"text": "教小孩子学走路，需要很多耐心。", "target_word": "耐心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对学生很有耐心，从不发火。", "target_word": "耐心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "等了两个小时，我已经没有耐心了。", "target_word": "耐心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "钓鱼可以培养一个人的耐心。", "target_word": "耐心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位医生对病人总是充满耐心。", "target_word": "耐心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他失去了耐心，开始大声说话。", "target_word": "耐心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做这份工作，你要多一点耐心。", "target_word": "耐心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈的耐心让我很感动。", "target_word": "耐心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学汉字要有耐心，不能着急。", "target_word": "耐心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的耐心有限，请你快一点。", "target_word": "耐心", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一点耐心", "label": "量词搭配"}], "register": "中性", "sense_fingerprint": "名词：不急躁、不厌烦的心性，常与有、没有、培养、失去搭配", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'db3644ad-b860-49ef-adcd-01357c77d0ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95270, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "耐心", "is_correct": true, "explanation": "正确：教孩子学走路需要的是耐心，符合语境。"}, {"text": "怒气", "is_correct": false, "explanation": "语义：教孩子学走路需要的是耐心，“怒气”与此正相反。"}, {"text": "恐惧", "is_correct": false, "explanation": "语义：“恐惧”不是教学所需要的心态，“需要很多恐惧”句意不通。"}, {"text": "速度", "is_correct": false, "explanation": "搭配：“速度”指快慢，“需要很多速度”与教孩子学走路的语境不符。"}], "explanations": {"耐心": "正确：教孩子学走路需要的是耐心，符合语境。", "怒气": "语义：教孩子学走路需要的是耐心，“怒气”与此正相反。", "恐惧": "语义：“恐惧”不是教学所需要的心态，“需要很多恐惧”句意不通。", "速度": "搭配：“速度”指快慢，“需要很多速度”与教孩子学走路的语境不符。"}, "sentence_index": 0, "correct_answer": "耐心"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他对成功充满耐心，相信一定会赢。", "explanation": "这里应该用〈信心〉。耐心指不急躁、不厌烦，对成功的把握要用〈信心〉。"}, {"text": "这个孩子耐心充沛，每天都很活泼。", "explanation": "这里应该用〈精力〉。耐心是不急不躁的心性，形容充沛的活力要用〈精力〉。"}, {"text": "他下定耐心戒烟了。", "explanation": "这里应该用〈决心〉。耐心不能与“下定”搭配，表示下定决心做某事要用〈决心〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0951cffc-c221-4855-94ff-5e8df6e4b522') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95270, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "耐心", "is_correct": true, "explanation": "正确：做这份工作需要耐心，与“多一点”搭配自然。"}, {"text": "怨言", "is_correct": false, "explanation": "语义：这份工作要求的是投入和耐心，“多一点怨言”与此相悖。"}, {"text": "闲暇", "is_correct": false, "explanation": "语义：“多一点闲暇”与“做这份工作”需要投入的语境相反。"}, {"text": "水泥", "is_correct": false, "explanation": "搭配：“水泥”与“做这份工作”无关，“多一点水泥”不成立。"}], "explanations": {"耐心": "正确：做这份工作需要耐心，与“多一点”搭配自然。", "怨言": "语义：这份工作要求的是投入和耐心，“多一点怨言”与此相悖。", "闲暇": "语义：“多一点闲暇”与“做这份工作”需要投入的语境相反。", "水泥": "搭配：“水泥”与“做这份工作”无关，“多一点水泥”不成立。"}, "sentence_index": 6, "correct_answer": "耐心"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个运动员耐心很好，能跑完全程。", "explanation": "这里应该用〈耐力〉。耐心指不急躁、不厌烦的心性，体力上的持久能力要用〈耐力〉。"}, {"text": "她的耐心很好听。", "explanation": "这里应该用〈声音〉。耐心是人的心性，不能用来形容声音好听。"}, {"text": "他的跑步耐心很快。", "explanation": "这里应该用〈速度〉。耐心不能用来形容跑步的快慢，形容速度要用〈速度〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0951cffc-c221-4855-94ff-5e8df6e4b522') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95270, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "照顾老人需要一个耐心。", "corrected_sentence": "照顾老人需要一点耐心。", "error_description": "“耐心”的量词用“点”，不用“个”；“一个耐心”应改为“一点耐心”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0951cffc-c221-4855-94ff-5e8df6e4b522') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95270, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这位护士有很耐心。", "corrected_sentence": "这位护士很有耐心。", "error_description": "“很”修饰“有耐心”，应放在“有”前面，说“很有耐心”；“有很耐心”语序不对。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0951cffc-c221-4855-94ff-5e8df6e4b522') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
