INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95271, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "人们买卖公司小块所有权的地方。", "primary_collocate": null, "pronunciation": "gǔ shì", "ipa": "ku˨˩˦ ʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "他把一部分钱投进了股市。", "target_word": "股市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我爸爸在股市里买了一些股票。", "target_word": "股市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "刚进股市的人要多学习。", "target_word": "股市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在股市赚了钱，也亏过钱。", "target_word": "股市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你为什么对股市这么感兴趣？", "target_word": "股市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他听朋友的话进了股市，结果亏了。", "target_word": "股市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "股市有风险，投资要小心。", "target_word": "股市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多年轻人也开始关注股市了。", "target_word": "股市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈不敢把养老钱放进股市。", "target_word": "股市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在股市买公司的股份，要先开户。", "target_word": "股市", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "股市行情", "label": "复合"}], "register": "中性", "sense_fingerprint": "人们投资、买卖公司股份的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1665dc3-7706-4348-9cee-b52c002cdca1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95271, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "股市", "is_correct": true, "explanation": "正确：“股市”（gǔshì）指人们买卖公司股份的地方。"}, {"text": "古诗", "is_correct": false, "explanation": "gǔshī（第一声）与 gǔshì（第四声）声调不同，意思是古诗。"}, {"text": "古时", "is_correct": false, "explanation": "gǔshí（第二声）与 gǔshì（第四声）末字声调不同，意思是古代。"}, {"text": "故事", "is_correct": false, "explanation": "gùshi（第四声加轻声）与 gǔshì（第三声、第四声）两个音节声调都不同，意思是故事。"}], "explanations": {"股市": "正确：“股市”（gǔshì）指人们买卖公司股份的地方。", "古诗": "gǔshī（第一声）与 gǔshì（第四声）声调不同，意思是古诗。", "古时": "gǔshí（第二声）与 gǔshì（第四声）末字声调不同，意思是古代。", "故事": "gùshi（第四声加轻声）与 gǔshì（第三声、第四声）两个音节声调都不同，意思是故事。"}, "sentence_index": null, "correct_answer": "股市"}, "level_3": {"options": [{"text": "股市", "is_correct": true, "explanation": "正确：“投进”的对象是投资市场，“股市”指买卖公司股份的地方，符合句意。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱不是投资的地方，“投进”的钱不会进入冰箱。"}, {"text": "花瓶", "is_correct": false, "explanation": "语义：花瓶是容器，不是投资对象，钱不能投进花瓶。"}, {"text": "垃圾桶", "is_correct": false, "explanation": "语义：垃圾桶是盛放垃圾的容器，不是投资对象，“投进垃圾桶”说不通。"}], "explanations": {"股市": "正确：“投进”的对象是投资市场，“股市”指买卖公司股份的地方，符合句意。", "冰箱": "语义：冰箱不是投资的地方，“投进”的钱不会进入冰箱。", "花瓶": "语义：花瓶是容器，不是投资对象，钱不能投进花瓶。", "垃圾桶": "语义：垃圾桶是盛放垃圾的容器，不是投资对象，“投进垃圾桶”说不通。"}, "sentence_index": 0, "correct_answer": "股市"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她买股市赚了钱，也亏过钱。", "explanation": "这里应该用〈股票〉。股市是地方，“买”的对象应是股票。"}, {"text": "她持有过这家公司的股市。", "explanation": "这里应该用〈股份〉。股市是地方，持有的是公司的股份。"}, {"text": "她在一张股市里赚了钱，也亏过钱。", "explanation": "这里应该用〈个〉。股市是场所，量词用“个”，不用“张”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc16e87b-3d15-4e1f-8fa1-4ec5a9c7b9e5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95271, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "股市", "is_correct": true, "explanation": "正确：“股市”是买卖公司股份的地方，“有风险，投资要小心”符合投资语境。"}, {"text": "书", "is_correct": false, "explanation": "语义：书不是投资对象，“书有风险”与后句的投资语境矛盾。"}, {"text": "花园", "is_correct": false, "explanation": "搭配：“投资要小心”说的是金融投资，“花园”不能作“有风险”的主语。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户不是投资对象，与“投资要小心”的语境矛盾。"}], "explanations": {"股市": "正确：“股市”是买卖公司股份的地方，“有风险，投资要小心”符合投资语境。", "书": "语义：书不是投资对象，“书有风险”与后句的投资语境矛盾。", "花园": "搭配：“投资要小心”说的是金融投资，“花园”不能作“有风险”的主语。", "窗户": "语义：窗户不是投资对象，与“投资要小心”的语境矛盾。"}, "sentence_index": 6, "correct_answer": "股市"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他买了一些股市，每年有利息。", "explanation": "这里应该用〈债券〉。股市是地方，不能作为“买”的对象；有利息的是债券。"}, {"text": "他是这家公司的股市。", "explanation": "这里应该用〈股东〉。股市是地方，不是人；持有公司股份的人是股东。"}, {"text": "这家公司今年发行了一批新股市。", "explanation": "这里应该用〈股票〉。股市是买卖股票的地方，公司发行的是股票，不能说“发行股市”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc16e87b-3d15-4e1f-8fa1-4ec5a9c7b9e5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95271, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他下班后常常在股市了买卖股份。", "corrected_sentence": "他下班后常常在股市里买卖股份。", "error_description": "错误：“在股市了买卖”；正确：“在股市里买卖”。方位词“里”不能换成“了”，“在……里”表示在某范围内进行买卖。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc16e87b-3d15-4e1f-8fa1-4ec5a9c7b9e5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95271, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他一开始就进在股市，结果亏了不少钱。", "corrected_sentence": "他一开始就进了股市，结果亏了不少钱。", "error_description": "错误：“进在股市”；正确：“进了股市”。动态助词“了”表示“进”这一动作已完成，“在”不能接在“进”后作动态标记。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc16e87b-3d15-4e1f-8fa1-4ec5a9c7b9e5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
