INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95272, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "买卖股票的市场。", "primary_collocate": null, "pronunciation": "gǔ shì", "ipa": "ku˨˩˦ ʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "股市每天早上九点半开门。", "target_word": "股市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天股市大涨，很多人很高兴。", "target_word": "股市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "受坏消息影响，股市下跌了。", "target_word": "股市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末股市不开门。", "target_word": "股市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个月股市一直不太稳定。", "target_word": "股市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中国股市的交易时间是几点？", "target_word": "股市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新闻说，股市今天上涨了三百点。", "target_word": "股市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天看股市行情。", "target_word": "股市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "股市里的价格每天都在变。", "target_word": "股市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春节期间，股市要休市几天。", "target_word": "股市", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "股市行情", "label": "复合"}], "register": "中性", "sense_fingerprint": "买卖股票的市场，指行情与交易", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1665dc3-7706-4348-9cee-b52c002cdca1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95272, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "股市", "is_correct": true, "explanation": "正确：“股市”（gǔshì）指买卖股票的市场。"}, {"text": "古诗", "is_correct": false, "explanation": "gǔshī（第一声）与 gǔshì（第四声）声调不同，意思是古诗。"}, {"text": "古时", "is_correct": false, "explanation": "gǔshí（第二声）与 gǔshì（第四声）末字声调不同，意思是古代。"}, {"text": "故事", "is_correct": false, "explanation": "gùshi（第四声加轻声）与 gǔshì（第三声、第四声）两个音节声调都不同，意思是故事。"}], "explanations": {"股市": "正确：“股市”（gǔshì）指买卖股票的市场。", "古诗": "gǔshī（第一声）与 gǔshì（第四声）声调不同，意思是古诗。", "古时": "gǔshí（第二声）与 gǔshì（第四声）末字声调不同，意思是古代。", "故事": "gùshi（第四声加轻声）与 gǔshì（第三声、第四声）两个音节声调都不同，意思是故事。"}, "sentence_index": null, "correct_answer": "股市"}, "level_3": {"options": [{"text": "股市", "is_correct": true, "explanation": "正确：“股市”是买卖股票的市场，可以“开门”交易，符合句意。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是交易场所，不存在“开门”的说法。"}, {"text": "股票", "is_correct": false, "explanation": "搭配：“开门”通常说商店、银行等场所，不能与“股票”搭配。"}, {"text": "电影", "is_correct": false, "explanation": "语义：电影是影片，不是开门的场所，与“每天早上开门”矛盾。"}], "explanations": {"股市": "正确：“股市”是买卖股票的市场，可以“开门”交易，符合句意。", "天气": "语义：天气不是交易场所，不存在“开门”的说法。", "股票": "搭配：“开门”通常说商店、银行等场所，不能与“股票”搭配。", "电影": "语义：电影是影片，不是开门的场所，与“每天早上开门”矛盾。"}, "sentence_index": 0, "correct_answer": "股市"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他花了很多钱买股市。", "explanation": "这里应该用〈股票〉。股市是交易的市场，买的是股票，不能说“买股市”。"}, {"text": "他持有这家公司的股市。", "explanation": "这里应该用〈股份〉。股市是市场，持有的是公司的股份。"}, {"text": "他在一张股市里买了股票。", "explanation": "这里应该用〈个〉。股市是场所，量词用“个”，不用“张”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc16e87b-3d15-4e1f-8fa1-4ec5a9c7b9e5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95272, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "股市", "is_correct": true, "explanation": "正确：“股市”指股票买卖的市场，“上涨了三百点”说的是行情指数，符合句意。"}, {"text": "学校", "is_correct": false, "explanation": "语义：学校不是价格或指数，不能“上涨三百点”。"}, {"text": "课本", "is_correct": false, "explanation": "搭配：“上涨三百点”说的是价格或指数，不搭配“课本”。"}, {"text": "体温", "is_correct": false, "explanation": "语义：体温用度数表示，不用“三百点”来计量。"}], "explanations": {"股市": "正确：“股市”指股票买卖的市场，“上涨了三百点”说的是行情指数，符合句意。", "学校": "语义：学校不是价格或指数，不能“上涨三百点”。", "课本": "搭配：“上涨三百点”说的是价格或指数，不搭配“课本”。", "体温": "语义：体温用度数表示，不用“三百点”来计量。"}, "sentence_index": 6, "correct_answer": "股市"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "股市是一家上市公司。", "explanation": "这里应该用〈公司〉。股市是买卖股票的市场，不是公司，不能说“是一家上市公司”。"}, {"text": "股市的校长很和善。", "explanation": "这里应该用〈学校〉。股市是市场，不设校长；校长属于学校。"}, {"text": "股市每天早上七点起床。", "explanation": "这里应该用〈人〉。股市是市场，不会起床；起床的是人，应以人作主语。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc16e87b-3d15-4e1f-8fa1-4ec5a9c7b9e5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95272, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他在股市的里买了股票。", "corrected_sentence": "他在股市里买了股票。", "error_description": "错误：“股市的里”；正确：“股市里”。方位词“里”前面不能加结构助词“的”，“在股市里”表示在该市场范围内。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc16e87b-3d15-4e1f-8fa1-4ec5a9c7b9e5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95272, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这张股市这几年变化很大。", "corrected_sentence": "这个股市这几年变化很大。", "error_description": "错误：“这张股市”；正确：“这个股市”。股市指市场，量词应用“个”，不用“张”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc16e87b-3d15-4e1f-8fa1-4ec5a9c7b9e5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
