INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95274, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "某种穿戴、做法或风气在一段时间里流行。", "primary_collocate": null, "pronunciation": "xīng", "ipa": "ɕiŋ˥", "syllable_count": 1, "sentences": [{"text": "那几年兴穿喇叭裤。", "target_word": "兴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现在不兴送红包了。", "target_word": "兴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听说今年兴红色的围巾。", "target_word": "兴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过去兴留长辫子，现在没人留了。", "target_word": "兴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个夏天兴短裤，大家都在买。", "target_word": "兴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那时候兴写信，现在大家都发微信。", "target_word": "兴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "以前兴结婚时请很多人吃饭，现在少了。", "target_word": "兴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "前几年兴骑共享单车，现在人少了。", "target_word": "兴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她妈妈说，她年轻时兴扎两条辫子。", "target_word": "兴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市现在兴喝咖啡，到处都是咖啡店。", "target_word": "兴", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "興", "label": "繁体"}, {"form": "时兴", "label": "复合词"}, {"form": "兴了", "label": "体标"}], "register": "口语", "sense_fingerprint": "兴：某种穿戴、做法或风气在一段时间里流行", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ecab3b97-f3d7-4c95-a0b9-3d6f706e958c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95274, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "兴", "is_correct": true, "explanation": "兴（xīng，第一声）：流行，某种穿戴、做法在一段时间里流行，是本词的读音。"}, {"text": "新", "is_correct": false, "explanation": "新（xīn）：韵尾不同（n 与 ng），意思是新旧的新。"}, {"text": "西", "is_correct": false, "explanation": "西（xī）：比 xīng 少了韵尾 ng，意思是西方。"}, {"text": "冰", "is_correct": false, "explanation": "冰（bīng）：声母不同（b 与 x），意思是冰块。"}, {"text": "行", "is_correct": false, "explanation": "行（xíng，第二声）：与 xīng 声调不同，意思是行走、可以。"}], "explanations": {"兴": "兴（xīng，第一声）：流行，某种穿戴、做法在一段时间里流行，是本词的读音。", "新": "新（xīn）：韵尾不同（n 与 ng），意思是新旧的新。", "西": "西（xī）：比 xīng 少了韵尾 ng，意思是西方。", "冰": "冰（bīng）：声母不同（b 与 x），意思是冰块。", "行": "行（xíng，第二声）：与 xīng 声调不同，意思是行走、可以。"}, "sentence_index": null, "correct_answer": "兴"}, "level_3": {"options": [{"text": "兴", "is_correct": true, "explanation": "兴：流行，某种穿戴在一段时间里流行，符合句意。"}, {"text": "卖", "is_correct": false, "explanation": "语义：“卖”是出售，与穿着的流行无关，“卖穿喇叭裤”说不通。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”后面不能接“穿”，“洗穿喇叭裤”不是说法。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”指饮食，这里的“吃喇叭裤”说不通，句子讲的是穿着风尚。"}], "explanations": {"兴": "兴：流行，某种穿戴在一段时间里流行，符合句意。", "卖": "语义：“卖”是出售，与穿着的流行无关，“卖穿喇叭裤”说不通。", "洗": "搭配：“洗”后面不能接“穿”，“洗穿喇叭裤”不是说法。", "吃": "语义：“吃”指饮食，这里的“吃喇叭裤”说不通，句子讲的是穿着风尚。"}, "sentence_index": 0, "correct_answer": "兴"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件外套最近卖得很兴，店里都断货了。", "explanation": "这里应该用〈火〉。“兴”是动词，表示风气流行，不能用“卖得很”修饰，形容卖得好要说“卖得很火”。"}, {"text": "我很兴见到你。", "explanation": "这里应该用〈高兴〉。“兴”表示风气流行，不表示心情愉快。"}, {"text": "这部电影在那几年兴全国。", "explanation": "这里应该用〈风靡〉。“兴”后面不能直接带“全国”这类地点宾语，应说“风靡全国”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac21c432-ba06-4bde-be5a-b3bcdaf2db26') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95274, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "兴", "is_correct": true, "explanation": "兴（xīng，第一声）：流行，某种穿戴、做法在一段时间里流行，是本词的读音。"}, {"text": "醒", "is_correct": false, "explanation": "醒（xǐng，第三声）：与 xīng 声调不同，意思是醒来。"}, {"text": "清", "is_correct": false, "explanation": "清（qīng）：声母不同（q 与 x），意思是清楚、干净。"}, {"text": "听", "is_correct": false, "explanation": "听（tīng）：声母不同（t 与 x），意思是听见。"}, {"text": "惊", "is_correct": false, "explanation": "惊（jīng）：声母不同（j 与 x），意思是吃惊。"}], "explanations": {"兴": "兴（xīng，第一声）：流行，某种穿戴、做法在一段时间里流行，是本词的读音。", "醒": "醒（xǐng，第三声）：与 xīng 声调不同，意思是醒来。", "清": "清（qīng）：声母不同（q 与 x），意思是清楚、干净。", "听": "听（tīng）：声母不同（t 与 x），意思是听见。", "惊": "惊（jīng）：声母不同（j 与 x），意思是吃惊。"}, "sentence_index": null, "correct_answer": "兴"}, "level_3": {"options": [{"text": "兴", "is_correct": true, "explanation": "兴：流行，这里指习俗上的风气，符合句意。"}, {"text": "搬", "is_correct": false, "explanation": "语义：“搬”是搬运，与结婚的风俗无关，“搬结婚”说不通。"}, {"text": "扔", "is_correct": false, "explanation": "搭配：“扔”不接“结婚”，“扔结婚时”不是说法。"}, {"text": "切", "is_correct": false, "explanation": "语义：“切”是切割，与请客吃饭的习俗无关，句意不通。"}], "explanations": {"兴": "兴：流行，这里指习俗上的风气，符合句意。", "搬": "语义：“搬”是搬运，与结婚的风俗无关，“搬结婚”说不通。", "扔": "搭配：“扔”不接“结婚”，“扔结婚时”不是说法。", "切": "语义：“切”是切割，与请客吃饭的习俗无关，句意不通。"}, "sentence_index": 6, "correct_answer": "兴"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件衣服我穿着很兴。", "explanation": "这里应该用〈合适〉。“兴”表示某种做法流行，不形容衣服合不合身。"}, {"text": "这件裙子很兴，大家都爱穿。", "explanation": "这里应该用〈时髦〉。“兴”是动词，前面不能加“很”修饰；形容衣服时髦要用“时髦”。"}, {"text": "外面雨下得很兴。", "explanation": "这里应该用〈大〉。“兴”表示风气流行，不形容雨的大小。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac21c432-ba06-4bde-be5a-b3bcdaf2db26') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95274, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那时候兴着穿喇叭裤。", "corrected_sentence": "那时候兴穿喇叭裤。", "error_description": "体标错误：“兴”表示流行时不能带“着”，应说“那时候兴穿喇叭裤”，不能说“兴着穿”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac21c432-ba06-4bde-be5a-b3bcdaf2db26') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95274, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那时候兴了戴大耳环。", "corrected_sentence": "那时候兴戴大耳环。", "error_description": "体标错误：“兴”表示习惯上流行，后面不带“了”，应说“那时候兴戴大耳环”，不能说“兴了戴”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac21c432-ba06-4bde-be5a-b3bcdaf2db26') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
