INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95275, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "东西有多大、多长、多重，这些要求就是它。", "primary_collocate": null, "pronunciation": "guī gé", "ipa": "kwei˥ kɤ˧˥", "syllable_count": 2, "sentences": [{"text": "这种箱子的规格是五十厘米长。", "target_word": "规格", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请告诉我这张桌子的规格。", "target_word": "规格", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两本书规格不同，一本大，一本小。", "target_word": "规格", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买床垫以前，先量一下床的规格。", "target_word": "规格", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块木板的规格是长两米、宽一米。", "target_word": "规格", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个行李箱有三种规格，我要最大的。", "target_word": "规格", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "店里的床单规格很多，你要多大的？", "target_word": "规格", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台电视的规格太大，放不进小客厅。", "target_word": "规格", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "盒子的规格写在旁边，长三十，宽二十。", "target_word": "规格", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些瓶子的规格一样，都是一升的。", "target_word": "规格", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}], "register": "中性", "sense_fingerprint": "物品的大小、长短、轻重等尺寸要求", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ce6f043-36d5-4f98-a980-2e9de3c98ca2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95275, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "规格", "is_correct": true, "explanation": "正确：“这种箱子的规格是五十厘米长”指尺寸，符合语境。"}, {"text": "重量", "is_correct": false, "explanation": "语义：“重量”指轻重，与“五十厘米长”的长度要求不符。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“颜色”不能用“长”来描述。"}, {"text": "价格", "is_correct": false, "explanation": "语义：“价格”指钱数，与长度要求无关。"}], "explanations": {"规格": "正确：“这种箱子的规格是五十厘米长”指尺寸，符合语境。", "重量": "语义：“重量”指轻重，与“五十厘米长”的长度要求不符。", "颜色": "搭配：“颜色”不能用“长”来描述。", "价格": "语义：“价格”指钱数，与长度要求无关。"}, "sentence_index": 0, "correct_answer": "规格"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这本书的规格很有意思，我看了两遍。", "explanation": "这里应该用〈内容〉。书有没有意思要说内容；规格指物品的大小、长短、轻重等要求，不能说有意思。"}, {"text": "这种箱子的规格是红色的。", "explanation": "这里应该用〈颜色〉。规格指大小、长短等尺寸要求，不能用来说颜色。"}, {"text": "这台电视的规格是三千元。", "explanation": "这里应该用〈价格〉。规格指尺寸要求，表示钱数要用“价格”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '503170ae-c285-467c-84c1-fba5608e9ba4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95275, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "规格", "is_correct": true, "explanation": "正确：“店里的床单规格很多，你要多大的”符合语境。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：“年龄”指人或动物的岁数，不能用来形容床单。"}, {"text": "学历", "is_correct": false, "explanation": "搭配：“店里的床单学历很多”搭配不当，“学历”不能用来形容商品。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：“身高”只用于人，不能用来描述床单。"}], "explanations": {"规格": "正确：“店里的床单规格很多，你要多大的”符合语境。", "年龄": "语义：“年龄”指人或动物的岁数，不能用来形容床单。", "学历": "搭配：“店里的床单学历很多”搭配不当，“学历”不能用来形容商品。", "身高": "体貌：“身高”只用于人，不能用来描述床单。"}, "sentence_index": 6, "correct_answer": "规格"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台手机的规格是苹果的。", "explanation": "这里应该用〈品牌〉。规格指尺寸、型号等要求，不能用来说品牌。"}, {"text": "这只狗的规格是三岁。", "explanation": "这里应该用〈年龄〉。规格是尺寸要求，不能用来说动物的岁数。"}, {"text": "这杯咖啡的规格很香。", "explanation": "这里应该用〈味道〉。规格指尺寸大小等要求，不能用来形容气味。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '503170ae-c285-467c-84c1-fba5608e9ba4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95275, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个行李箱有三只规格可以选。", "corrected_sentence": "这个行李箱有三种规格可以选。", "error_description": "量词错误：“规格”应搭配“种”，应说“三种规格”；“只”多用于动物或成对的物品，不能用于“规格”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '503170ae-c285-467c-84c1-fba5608e9ba4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95275, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种床单的规格有很多件。", "corrected_sentence": "这种床单的规格有很多种。", "error_description": "量词错误：“规格”应搭配“种”，应说“有很多种规格”；“件”用于物品、事情，不能用来数规格。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '503170ae-c285-467c-84c1-fba5608e9ba4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
