INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95276, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "产品的质量、大小、型号等应达到的标准。", "primary_collocate": null, "pronunciation": "guī gé", "ipa": "kwei˥ kɤ˧˥", "syllable_count": 2, "sentences": [{"text": "这批产品的规格不合要求，不能卖。", "target_word": "规格", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家工厂的产品规格很高。", "target_word": "规格", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这批手机的规格没有达到要求。", "target_word": "规格", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司对每件产品的规格都有要求。", "target_word": "规格", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些零件规格不对，机器装不上。", "target_word": "规格", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们按照规格检查每一个箱子。", "target_word": "规格", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理说，这批货的规格不符合合同。", "target_word": "规格", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "产品规格不一样，价格也不一样。", "target_word": "规格", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种杯子的规格是公司定的，不能改。", "target_word": "规格", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人要按规格做，不能随便改。", "target_word": "规格", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}], "register": "中性", "sense_fingerprint": "产品质量、型号等应达到的标准", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ce6f043-36d5-4f98-a980-2e9de3c98ca2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95276, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "规格", "is_correct": true, "explanation": "正确：“这批产品的规格不合要求，不能卖”指产品质量标准，符合语境。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：“年龄”指人或动物的岁数，不能用来说产品是否合格。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：“身高”只用于人，不能用来形容产品。"}, {"text": "学历", "is_correct": false, "explanation": "搭配：“产品”不能与“学历”搭配，二者不相配。"}], "explanations": {"规格": "正确：“这批产品的规格不合要求，不能卖”指产品质量标准，符合语境。", "年龄": "语义：“年龄”指人或动物的岁数，不能用来说产品是否合格。", "身高": "体貌：“身高”只用于人，不能用来形容产品。", "学历": "搭配：“产品”不能与“学历”搭配，二者不相配。"}, "sentence_index": 0, "correct_answer": "规格"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这种饼干的规格很甜，孩子很爱吃。", "explanation": "这里应该用〈口味〉。“甜”形容口味，规格指产品的标准要求，不能用来说甜不甜。"}, {"text": "这件衣服的规格很漂亮，我想买。", "explanation": "这里应该用〈外观〉。规格指产品的标准要求，不能用来形容外观漂不漂亮。"}, {"text": "这个电池的规格很长，用得很久。", "explanation": "这里应该用〈寿命〉。规格指产品的标准要求，不能用来说使用年限。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '503170ae-c285-467c-84c1-fba5608e9ba4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95276, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "规格", "is_correct": true, "explanation": "正确：“经理说，这批货的规格不符合合同”指产品标准，符合语境。"}, {"text": "籍贯", "is_correct": false, "explanation": "语义：“籍贯”指人的祖籍，不能用来说货物是否符合合同。"}, {"text": "性格", "is_correct": false, "explanation": "语义：“性格”指人的个性，不能用来形容货物。"}, {"text": "性别", "is_correct": false, "explanation": "搭配：“这批货的性别”搭配不当，货物没有性别。"}], "explanations": {"规格": "正确：“经理说，这批货的规格不符合合同”指产品标准，符合语境。", "籍贯": "语义：“籍贯”指人的祖籍，不能用来说货物是否符合合同。", "性格": "语义：“性格”指人的个性，不能用来形容货物。", "性别": "搭配：“这批货的性别”搭配不当，货物没有性别。"}, "sentence_index": 6, "correct_answer": "规格"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学生上课的规格很早，每天七点就到校。", "explanation": "这里应该用〈时间〉。早晚要说时间；规格指产品的标准要求，不能用来说早晚。"}, {"text": "这辆车的规格很快，十分钟就到了。", "explanation": "这里应该用〈速度〉。快慢要说速度；规格指产品的标准要求，不能用来形容快慢。"}, {"text": "他说话的规格很大，隔壁都听得见。", "explanation": "这里应该用〈音量〉。声音大小要说音量；规格指产品应达到的标准，不能用来说声音大小。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '503170ae-c285-467c-84c1-fba5608e9ba4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95276, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种杯子有两只规格可以选。", "corrected_sentence": "这种杯子有两种规格可以选。", "error_description": "量词错误：“规格”应搭配“种”，应说“两种规格”；“只”多用于动物或成对的物品，不能用于“规格”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '503170ae-c285-467c-84c1-fba5608e9ba4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95276, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种手机有两件规格可以选。", "corrected_sentence": "这种手机有两种规格可以选。", "error_description": "量词错误：“规格”应搭配“种”，应说“两种规格”；“件”用于物品、事情，不能用来数规格。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '503170ae-c285-467c-84c1-fba5608e9ba4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
