INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95278, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "对自然现象仔细观察并测量。", "primary_collocate": null, "pronunciation": "guān cè", "ipa": "kwan˥ tsʰɤ˥˩", "syllable_count": 2, "sentences": [{"text": "科学家在山上观测天气。", "target_word": "观测", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们用望远镜观测星星。", "target_word": "观测", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个站每天观测风和雨的变化。", "target_word": "观测", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作人员正在观测河水的高度。", "target_word": "观测", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家观测了三年海水的温度。", "target_word": "观测", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在海边观测过潮水。", "target_word": "观测", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天文学家夜里观测着月亮的位置。", "target_word": "观测", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们把观测到的数据发给了老师。", "target_word": "观测", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "气象站观测到昨天风力有所增强。", "target_word": "观测", "complexity_tier": "T3", "furigana": "qì xiàng zhàn guān cè dào zuótiān fēnglì yǒu suǒ zēngqiáng.", "sentence_source": "generated"}, {"text": "科学家用新机器观测地震前的变化。", "target_word": "观测", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "观测了", "label": "体标（完成）"}, {"form": "观测过", "label": "体标（经历）"}, {"form": "观测着", "label": "体标（持续）"}, {"form": "观测站", "label": "复合词"}], "register": "书面语", "sense_fingerprint": "科学地观察并测量自然现象", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ec53b00-6195-460c-9dc7-5a5e3f5ff1e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95278, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "观测", "is_correct": true, "explanation": "“观测”指仔细观察并测量自然现象，与“天气”相符。"}, {"text": "煮", "is_correct": false, "explanation": "搭配：“煮”针对食物，不能说煮天气。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”的对象是衣服、碗等具体物品，不能说洗天气。"}, {"text": "烤", "is_correct": false, "explanation": "语义：“烤”指用火加热，与观测天气的科学活动无关。"}], "explanations": {"观测": "“观测”指仔细观察并测量自然现象，与“天气”相符。", "煮": "搭配：“煮”针对食物，不能说煮天气。", "洗": "搭配：“洗”的对象是衣服、碗等具体物品，不能说洗天气。", "烤": "语义：“烤”指用火加热，与观测天气的科学活动无关。"}, "sentence_index": 0, "correct_answer": "观测"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "周末我们去博物馆观测恐龙化石。", "explanation": "这里应该用〈参观〉。“观测”用于自然现象的仔细观察和测量，去博物馆看展品要用〈参观〉。"}, {"text": "妈妈每天观测生病的孩子。", "explanation": "这里应该用〈照顾〉。“观测”是对自然现象的观察和测量，照顾病人要用〈照顾〉。"}, {"text": "我们细细观测这道菜的味道。", "explanation": "这里应该用〈品尝〉。“观测”是观察测量，不能用来形容尝味道。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '941e0a09-4e7f-42c2-bcae-44406f5b4567') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95278, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "观测", "is_correct": true, "explanation": "“观测”与“着”搭配，指持续观察测量月亮的位置，与句意相符。"}, {"text": "追逐", "is_correct": false, "explanation": "语义：“追逐”是紧跟着跑，与观察月亮位置的测量活动不符。"}, {"text": "躲避", "is_correct": false, "explanation": "语义：“躲避”是避开，与天文学家主动观测的目的相反。"}, {"text": "拆卸", "is_correct": false, "explanation": "搭配：“拆卸”用于机器零件，不能用来修饰“月亮的位置”。"}], "explanations": {"观测": "“观测”与“着”搭配，指持续观察测量月亮的位置，与句意相符。", "追逐": "语义：“追逐”是紧跟着跑，与观察月亮位置的测量活动不符。", "躲避": "语义：“躲避”是避开，与天文学家主动观测的目的相反。", "拆卸": "搭配：“拆卸”用于机器零件，不能用来修饰“月亮的位置”。"}, "sentence_index": 6, "correct_answer": "观测"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "气象台每天观测明天的天气，提醒大家带伞。", "explanation": "这里应该用〈预报〉。“观测”针对当前可见的现象，对未来的天气要用〈预报〉。"}, {"text": "侦探从脚印观测凶手的身高。", "explanation": "这里应该用〈推测〉。“观测”是直接观察记录，从线索推断身高要用〈推测〉。"}, {"text": "工人用扳手观测螺丝。", "explanation": "这里应该用〈拧〉。扳手用于拧动，“观测”只是观察记录，不能代替拧的动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '941e0a09-4e7f-42c2-bcae-44406f5b4567') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95278, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "科学家仔细观测了着海浪的高度。", "corrected_sentence": "科学家仔细观测着海浪的高度。", "error_description": "错误：“观测”后同时用了“了”和“着”，两个体标不能叠用。持续态只用“着”，应说“观测着海浪的高度”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '941e0a09-4e7f-42c2-bcae-44406f5b4567') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95278, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这里有一座气象观测。", "corrected_sentence": "这里有一座气象观测站。", "error_description": "错误：“观测”后缺少“站”。“一座”指建筑，应说“观测站”，“观测”本身不是建筑。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '941e0a09-4e7f-42c2-bcae-44406f5b4567') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
