INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95279, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "有好东西让人很想要，忍不住想去拿。", "primary_collocate": null, "pronunciation": "yòu huò", "ipa": "joʊ˥˩ xwɔ˥˩", "syllable_count": 2, "sentences": [{"text": "桌上的蛋糕香香的，诱惑着饿肚子的孩子。", "target_word": "诱惑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "橱窗里的新手机诱惑了路过的我。", "target_word": "诱惑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "面包店里飘出的香味诱惑着路人。", "target_word": "诱惑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那盘红烧肉太香了，诱惑得我忍不住想吃。", "target_word": "诱惑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "减肥的时候，甜点最容易诱惑我。", "target_word": "诱惑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌上的钱诱惑了他，他伸手拿了一张。", "target_word": "诱惑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "玩具店里的新玩具诱惑着小朋友。", "target_word": "诱惑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "打折的衣服诱惑不了她，她只买了鞋。", "target_word": "诱惑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "半夜，冰箱里的冰淇淋一直诱惑着我。", "target_word": "诱惑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那双运动鞋的颜色很亮眼，诱惑着她想马上试穿。", "target_word": "诱惑", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "诱惑了", "label": "体标（了）"}, {"form": "诱惑着", "label": "体标（着）"}, {"form": "诱惑过", "label": "体标（过）"}, {"form": "诱惑力", "label": "复合"}, {"form": "誘惑", "label": "繁体"}], "register": "中性", "sense_fingerprint": "好东西让人很想要而忍不住", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91f27bcb-e915-4d91-af5c-63c661bfa7ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95279, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "诱惑", "is_correct": true, "explanation": "诱惑：用香味等好东西吸引人，让人想要，与“香香的”蛋糕和“饿肚子的孩子”相符。"}, {"text": "喂养", "is_correct": false, "explanation": "搭配：“喂养”的对象一般是动物或婴幼儿，且需要人去喂，不能说蛋糕喂养孩子。"}, {"text": "讨厌", "is_correct": false, "explanation": "语义：“讨厌”表示厌恶，与“香香的”蛋糕让人想吃的意思相反，句子不通。"}, {"text": "烤", "is_correct": false, "explanation": "搭配：“烤”的对象是食物，不能带“孩子”作宾语，“烤着饿肚子的孩子”不成立。"}], "explanations": {"诱惑": "诱惑：用香味等好东西吸引人，让人想要，与“香香的”蛋糕和“饿肚子的孩子”相符。", "喂养": "搭配：“喂养”的对象一般是动物或婴幼儿，且需要人去喂，不能说蛋糕喂养孩子。", "讨厌": "语义：“讨厌”表示厌恶，与“香香的”蛋糕让人想吃的意思相反，句子不通。", "烤": "搭配：“烤”的对象是食物，不能带“孩子”作宾语，“烤着饿肚子的孩子”不成立。"}, "sentence_index": 0, "correct_answer": "诱惑"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老师的问题诱惑了全班的注意力。", "explanation": "这里应该用〈吸引〉。诱惑指用好处或欲望让人想去做某事，不用来说引起注意力；引起注意应说“吸引”。"}, {"text": "爸爸的话诱惑了孩子重新振作。", "explanation": "这里应该用〈鼓励〉。鼓励是用言语增强别人的信心；诱惑是用好处让人想去做某事，不能用来说话语让孩子振作。"}, {"text": "他用道理诱惑了我。", "explanation": "这里应该用〈说服〉。说服是靠道理让人接受；诱惑靠的是好处或欲望，道理不能作为诱惑的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '688b247e-a2ac-4095-bcf3-0f9f901c9e49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95279, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "诱惑", "is_correct": true, "explanation": "诱惑：用新玩具吸引小朋友，让他们想要，与“玩具店里的新玩具”相符。"}, {"text": "指挥", "is_correct": false, "explanation": "配价：“指挥”要求有生命的施事，玩具不能指挥人，“新玩具指挥着小朋友”不成立。"}, {"text": "照顾", "is_correct": false, "explanation": "语义：“照顾”是关心、料理，玩具不能照顾人，与“玩具店里的新玩具”的语境不符。"}, {"text": "批评", "is_correct": false, "explanation": "语义：“批评”是指出错误，玩具不会批评人，句子与玩具的情境不符。"}], "explanations": {"诱惑": "诱惑：用新玩具吸引小朋友，让他们想要，与“玩具店里的新玩具”相符。", "指挥": "配价：“指挥”要求有生命的施事，玩具不能指挥人，“新玩具指挥着小朋友”不成立。", "照顾": "语义：“照顾”是关心、料理，玩具不能照顾人，与“玩具店里的新玩具”的语境不符。", "批评": "语义：“批评”是指出错误，玩具不会批评人，句子与玩具的情境不符。"}, "sentence_index": 6, "correct_answer": "诱惑"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师诱惑我们读懂这篇课文。", "explanation": "这里应该用〈引导〉。诱惑是用好处吸引人去做某事；引导是带领、启发，不能用诱惑来说教人读懂课文。"}, {"text": "妈妈诱惑我带伞。", "explanation": "这里应该用〈提醒〉。提醒是提示别人别忘记某事；诱惑是用好处引人去做，不能用来说提醒带伞。"}, {"text": "妈妈诱惑哭泣的孩子。", "explanation": "这里应该用〈安慰〉。安慰是让伤心的人平静下来；诱惑是用好处让人想去做某事，不能用于哭泣的孩子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '688b247e-a2ac-4095-bcf3-0f9f901c9e49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95279, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家店的打折活动诱惑了。", "corrected_sentence": "这家店的打折活动诱惑了很多顾客。", "error_description": "缺少宾语：“诱惑”是及物动词，后面要带被引诱的人，应说“诱惑了很多顾客”，不能只说“诱惑了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '688b247e-a2ac-4095-bcf3-0f9f901c9e49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95279, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我把新款耳机诱惑了，想马上买下来。", "corrected_sentence": "我被新款耳机诱惑了，想马上买下来。", "error_description": "被动/把字句错误：“诱惑”的施事是“新款耳机”，被引诱的是“我”，应用“被”引出施事，说“我被新款耳机诱惑了”；“把”后面接的是受事，这里误用“把”，所以“我把新款耳机诱惑了”不通。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '688b247e-a2ac-4095-bcf3-0f9f901c9e49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
