INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95280, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '688b247e-a2ac-4095-bcf3-0f9f901c9e49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95280, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用好处吸引人，使人心动而想去做。", "primary_collocate": null, "pronunciation": "yòu huò", "ipa": "joʊ˥˩ xwɔ˥˩", "syllable_count": 2, "sentences": [{"text": "公司用高工资诱惑他换工作。", "target_word": "诱惑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "骗子用小礼物诱惑老人买假药。", "target_word": "诱惑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商家用打折诱惑顾客多买东西。", "target_word": "诱惑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们想用钱诱惑我说出秘密。", "target_word": "诱惑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网上的广告用免费礼品诱惑人点进去。", "target_word": "诱惑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友一直诱惑我和他一起去旅行，还说他请客。", "target_word": "诱惑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板用好位子诱惑他留下来工作。", "target_word": "诱惑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别人拿高利息诱惑他，他一点也不动心。", "target_word": "诱惑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大学用奖学金诱惑好学生来读书。", "target_word": "诱惑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对方用高回报诱惑他投钱，他差点同意了。", "target_word": "诱惑", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "诱惑了", "label": "体标（了）"}, {"form": "诱惑着", "label": "体标（着）"}, {"form": "诱惑过", "label": "体标（过）"}, {"form": "诱惑力", "label": "复合"}, {"form": "誘惑", "label": "繁体"}], "register": "中性", "sense_fingerprint": "用好处吸引人去做某事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91f27bcb-e915-4d91-af5c-63c661bfa7ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95280, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "诱惑", "is_correct": true, "explanation": "诱惑：用高工资这种好处吸引他，使他想去换工作，与语境相符。"}, {"text": "拒绝", "is_correct": false, "explanation": "语义：“拒绝”是不接受，与“用高工资”的好处相反，句子不通。"}, {"text": "惩罚", "is_correct": false, "explanation": "语义：“惩罚”是处罚，与“高工资”的好处相反，“用高工资惩罚他”说不通。"}, {"text": "监督", "is_correct": false, "explanation": "搭配：“监督”的对象是行为或工作，不能用高工资去监督，搭配不当。"}], "explanations": {"诱惑": "诱惑：用高工资这种好处吸引他，使他想去换工作，与语境相符。", "拒绝": "语义：“拒绝”是不接受，与“用高工资”的好处相反，句子不通。", "惩罚": "语义：“惩罚”是处罚，与“高工资”的好处相反，“用高工资惩罚他”说不通。", "监督": "搭配：“监督”的对象是行为或工作，不能用高工资去监督，搭配不当。"}, "sentence_index": 0, "correct_answer": "诱惑"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他们用刀诱惑我交出钱包。", "explanation": "这里应该用〈威胁〉。威胁是用强迫或恐吓逼人服从；诱惑靠的是好处，不能用刀子作为诱惑。"}, {"text": "队长诱惑我们立刻出发。", "explanation": "这里应该用〈命令〉。命令是用权力要求别人立即执行；诱惑是用好处吸引人，不能用来表示强制要求。"}, {"text": "他当众诱惑了我的方案。", "explanation": "这里应该用〈批评〉。批评是指出不足；诱惑是用好处引人去做某事，不能用于评价方案。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '688b247e-a2ac-4095-bcf3-0f9f901c9e49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95280, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "诱惑", "is_correct": true, "explanation": "诱惑：用好位子吸引他留下，与“留下来工作”的语境相符。"}, {"text": "赶走", "is_correct": false, "explanation": "语义：“赶走”是驱逐，与“用好位子”的好处相反，句子不通。"}, {"text": "解雇", "is_correct": false, "explanation": "语义：“解雇”是辞退，与“用好位子”留人的意思相反。"}, {"text": "警告", "is_correct": false, "explanation": "搭配：“警告”的内容是危险或错误，不能用好位子作为手段去警告，搭配不当。"}], "explanations": {"诱惑": "诱惑：用好位子吸引他留下，与“留下来工作”的语境相符。", "赶走": "语义：“赶走”是驱逐，与“用好位子”的好处相反，句子不通。", "解雇": "语义：“解雇”是辞退，与“用好位子”留人的意思相反。", "警告": "搭配：“警告”的内容是危险或错误，不能用好位子作为手段去警告，搭配不当。"}, "sentence_index": 6, "correct_answer": "诱惑"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "大家诱惑新同学的到来。", "explanation": "这里应该用〈欢迎〉。欢迎是表示接待的善意；诱惑是用好处引人去做某事，不能用来说迎接新同学。"}, {"text": "师傅诱惑了坏掉的电脑。", "explanation": "这里应该用〈修理〉。修理是使坏东西恢复正常；诱惑指用好处吸引人去做，不能用于物品。"}, {"text": "老师诱惑了我的作文。", "explanation": "这里应该用〈夸奖〉。夸奖是称赞；诱惑是用好处引人去做某事，不能用来表示称赞作品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '688b247e-a2ac-4095-bcf3-0f9f901c9e49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95280, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把高奖金诱惑，差点就答应了。", "corrected_sentence": "他被高奖金诱惑，差点就答应了。", "error_description": "被动标记错误：被诱惑的人“他”应放在“被”字句的主语位置，并用“被”引出施事“高奖金”。“他把高奖金诱惑”不成立，应说“他被高奖金诱惑”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '688b247e-a2ac-4095-bcf3-0f9f901c9e49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95280, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家店用免费试用诱惑了。", "corrected_sentence": "这家店用免费试用诱惑了很多人。", "error_description": "缺少宾语：“诱惑”后面要带被引诱的人，应说“诱惑了很多人”，不能只说“诱惑了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '688b247e-a2ac-4095-bcf3-0f9f901c9e49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
