INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95281, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把原来的名称、地址、办法等换成新的。", "primary_collocate": null, "pronunciation": "biàn gēng", "ipa": "pi̯ɛn˥˩ kɤŋ˥", "syllable_count": 2, "sentences": [{"text": "这家公司变更了名称，不再用旧名字。", "target_word": "变更", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他变更了联系地址，留下了新地址。", "target_word": "变更", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店变更了负责人，换了新人。", "target_word": "变更", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们变更了原来的办法，用了新方法。", "target_word": "变更", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "银行通知我，手机号码需要变更。", "target_word": "变更", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她变更了自己的姓名，用了新名字。", "target_word": "变更", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂变更了生产方式，用上了新机器。", "target_word": "变更", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司变更了法定代表人，现在是王先生。", "target_word": "变更", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校变更了校服制度，换成了新的款式。", "target_word": "变更", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他变更了登记的电话，留下了新号码。", "target_word": "变更", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "变更了", "label": "完成体"}], "register": "书面", "sense_fingerprint": "把旧的名称、地址、办法等换成新的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2112c95f-d85a-4cfc-ba9f-40b392804a1d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95281, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "保留", "is_correct": false, "explanation": "语义：“保留”是留下不改，与后半句“不再用旧名字”的换名意思相反。"}, {"text": "记住", "is_correct": false, "explanation": "搭配：“记住”指记忆，不能用来说公司更换名称。"}, {"text": "拆", "is_correct": false, "explanation": "搭配：“拆”指拆开、拆除，不用来说公司名称的更换。"}, {"text": "变更", "is_correct": true, "explanation": "正确。“变更”表示把公司原来的名称换成新的，与“不再用旧名字”相符。"}], "explanations": {"保留": "语义：“保留”是留下不改，与后半句“不再用旧名字”的换名意思相反。", "记住": "搭配：“记住”指记忆，不能用来说公司更换名称。", "拆": "搭配：“拆”指拆开、拆除，不用来说公司名称的更换。", "变更": "正确。“变更”表示把公司原来的名称换成新的，与“不再用旧名字”相符。"}, "sentence_index": 0, "correct_answer": "变更"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的心情变更了，现在特别开心。", "explanation": "这里应该用〈改变〉。变更只用于名称、地址、办法等具体事物的更换，不用于心情。"}, {"text": "云的形状变更了，飘得很慢。", "explanation": "这里应该用〈变化〉。变更指人为地更换，不用于云这类自然事物的变化。"}, {"text": "他变更了一下脚步，走得很快。", "explanation": "这里是“脚步发生变化”的意思；“变更”用于名称、地址、办法等具体事物的更换，不用于动作的变化，应说“加快了脚步”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8274a805-2c34-4a6f-9e45-8d48a0d1896d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95281, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "喜欢", "is_correct": false, "explanation": "搭配：“喜欢”表示偏好，不能与“生产方式”搭配作宾语，说“工厂喜欢了生产方式”不成立。"}, {"text": "修理", "is_correct": false, "explanation": "搭配：“修理”针对具体的器物，不用来说生产方式的更换。"}, {"text": "参观", "is_correct": false, "explanation": "搭配：“参观”的对象是场所或展品，不能作“生产方式”的宾语。"}, {"text": "变更", "is_correct": true, "explanation": "正确。“变更”表示工厂把旧的生产方式换成了新的，与后半句“用上了新机器”相符。"}], "explanations": {"喜欢": "搭配：“喜欢”表示偏好，不能与“生产方式”搭配作宾语，说“工厂喜欢了生产方式”不成立。", "修理": "搭配：“修理”针对具体的器物，不用来说生产方式的更换。", "参观": "搭配：“参观”的对象是场所或展品，不能作“生产方式”的宾语。", "变更": "正确。“变更”表示工厂把旧的生产方式换成了新的，与后半句“用上了新机器”相符。"}, "sentence_index": 6, "correct_answer": "变更"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的脾气变更了，现在变得很温和。", "explanation": "这里应该用〈改变〉。变更用于名称、地址、办法等具体事物的更换，不用于脾气这类个人性格的变化，应说“脾气变了”。"}, {"text": "他把头发变更成了棕色。", "explanation": "这里应该用〈染〉。变更不用于头发颜色的改变，把头发染成某种颜色要用〈染〉。"}, {"text": "这个房子变更成了白色。", "explanation": "这里应该用〈粉刷〉。变更用于名称、办法等的更换，给房子换颜色要用〈粉刷〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8274a805-2c34-4a6f-9e45-8d48a0d1896d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95281, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家餐厅很变更了菜单，不再卖旧菜。", "corrected_sentence": "这家餐厅变更了菜单，不再卖旧菜。", "error_description": "错误形式：“很变更”；正确形式：“变更了菜单”。“很”是程度副词，不能修饰动词“变更”，应直接说“变更了菜单”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8274a805-2c34-4a6f-9e45-8d48a0d1896d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95281, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家书店很变更了经营方式，改成了网络销售。", "corrected_sentence": "这家书店变更了经营方式，改成了网络销售。", "error_description": "错误形式：“很变更”；正确形式：“变更了”。“很”是程度副词，不能修饰动词“变更”，应直接说“变更了经营方式”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8274a805-2c34-4a6f-9e45-8d48a0d1896d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
