INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95282, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "更改原来已经定好的时间、地点、计划等安排。", "primary_collocate": null, "pronunciation": "biàn gēng", "ipa": "pi̯ɛn˥˩ kɤŋ˥", "syllable_count": 2, "sentences": [{"text": "因为下雨，我们变更了会议时间。", "target_word": "变更", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师通知大家，考试地点变更了。", "target_word": "变更", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司变更了原来出发的日期。", "target_word": "变更", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "要变更计划，请提前告诉我。", "target_word": "变更", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他临时变更了旅行的路线。", "target_word": "变更", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为天气不好，航班时间变更了。", "target_word": "变更", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校变更了上课的安排。", "target_word": "变更", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次活动的地点不能再变更了。", "target_word": "变更", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理决定变更原来的工作计划。", "target_word": "变更", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "酒店可以帮你变更入住日期。", "target_word": "变更", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "变更了", "label": "完成体"}], "register": "书面", "sense_fingerprint": "更改原来定好的时间、地点、计划等安排", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2112c95f-d85a-4cfc-ba9f-40b392804a1d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95282, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "维持", "is_correct": false, "explanation": "语义：“维持”是保持原状，与“因为下雨”而需要改动的情况相反。"}, {"text": "保留", "is_correct": false, "explanation": "语义：“保留”指留下不动，与因为下雨需要调整时间的情况不符。"}, {"text": "参加", "is_correct": false, "explanation": "搭配：“参加”的对象是活动或会议本身，不能说“参加了会议时间”。"}, {"text": "变更", "is_correct": true, "explanation": "正确。“变更”表示更改原定的会议时间，与“因为下雨”的原因相符。"}], "explanations": {"维持": "语义：“维持”是保持原状，与“因为下雨”而需要改动的情况相反。", "保留": "语义：“保留”指留下不动，与因为下雨需要调整时间的情况不符。", "参加": "搭配：“参加”的对象是活动或会议本身，不能说“参加了会议时间”。", "变更": "正确。“变更”表示更改原定的会议时间，与“因为下雨”的原因相符。"}, "sentence_index": 0, "correct_answer": "变更"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "天气变更了，我们只好改去室内。", "explanation": "这里是“变化”的意思，但变更多指人为更改已定的安排、名称等，不说天气这类自然现象的变化，应说“天气变了”。"}, {"text": "他变更了作文的结尾，写得更感人。", "explanation": "这里应该用〈修改〉。变更用于计划、安排等，修改文章的内容要用〈修改〉。"}, {"text": "他变更了一下声音，听起来很低沉。", "explanation": "这里是“声音发生变化”的意思；变更专指更改已定的安排、名称等，不用于声音这类自然特征的变化，应说“变了声音”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8274a805-2c34-4a6f-9e45-8d48a0d1896d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95282, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "参观", "is_correct": false, "explanation": "搭配：“参观”的对象是地点或展品，不能与“安排”搭配作宾语。"}, {"text": "修理", "is_correct": false, "explanation": "搭配：“修理”针对具体的器物，不用来说学校的安排。"}, {"text": "拆", "is_correct": false, "explanation": "语义：“拆”指拆开、拆除，与“上课的安排”这类抽象事物的调整不符。"}, {"text": "变更", "is_correct": true, "explanation": "正确。“变更”表示学校更改了原定的上课安排，与句意相符。"}], "explanations": {"参观": "搭配：“参观”的对象是地点或展品，不能与“安排”搭配作宾语。", "修理": "搭配：“修理”针对具体的器物，不用来说学校的安排。", "拆": "语义：“拆”指拆开、拆除，与“上课的安排”这类抽象事物的调整不符。", "变更": "正确。“变更”表示学校更改了原定的上课安排，与句意相符。"}, "sentence_index": 6, "correct_answer": "变更"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师变更了他的发音，他念得很标准。", "explanation": "这里应该用〈纠正〉。变更用于已定的安排、名称等，纠正发音要用〈纠正〉。"}, {"text": "他变更了身高，现在比以前高了不少。", "explanation": "这里是“身体发生变化”的意思；变更只用于安排、名称等具体事项，不用于身高这类自然变化，应说“长高了”。"}, {"text": "他的爱好变更了，现在喜欢画画。", "explanation": "这里是“个人兴趣发生变化”的意思；变更用于更改已定的安排、名称等，不用于爱好这类个人习惯的变化，应说“爱好变了”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8274a805-2c34-4a6f-9e45-8d48a0d1896d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95282, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "由于台风，比赛时间很变更了。", "corrected_sentence": "由于台风，比赛时间变更了。", "error_description": "错误形式：“很变更”；正确形式：“变更了”。“很”是程度副词，不能修饰动词“变更”，应直接说“比赛时间变更了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8274a805-2c34-4a6f-9e45-8d48a0d1896d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95282, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学校临时很变更了午饭的时间，改成了十二点。", "corrected_sentence": "学校临时变更了午饭的时间，改成了十二点。", "error_description": "错误形式：“很变更”；正确形式：“变更了”。“很”是程度副词，不能修饰动词“变更”，应直接说“变更了午饭的时间”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8274a805-2c34-4a6f-9e45-8d48a0d1896d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
