INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95283, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "最近的几年。", "primary_collocate": null, "pronunciation": "jìn nián", "ipa": "tɕin˥˩ njɛn˧˥", "syllable_count": 2, "sentences": [{"text": "近年，这个城市的人越来越多。", "target_word": "近年", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "近年天气比以前热了不少。", "target_word": "近年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "近年他一直在国外工作。", "target_word": "近年", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "近年，我们学校买了很多新电脑。", "target_word": "近年", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家店近年生意很好，客人不少。", "target_word": "近年", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "近年出生的孩子，从小就会用手机。", "target_word": "近年", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他近年写过几本关于旅行的书。", "target_word": "近年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "近年的物价比十年前高了很多。", "target_word": "近年", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这条河近年变干净了，常有人来钓鱼。", "target_word": "近年", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她近年很少回老家，因为工作太忙。", "target_word": "近年", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "近年来", "label": "复合"}], "register": "书面", "sense_fingerprint": "与以前相对的最近几年这段时间", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b37fbea5-e5a7-40fc-aef0-8c6a260a8c6f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95283, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "近年", "is_correct": true, "explanation": "正确：近年指最近几年，与“这个城市的人越来越多”这种长期变化相符。"}, {"text": "童年", "is_correct": false, "explanation": "语义：“童年”指人的少年时期，与这座城市的人口增长不搭配。"}, {"text": "眼睛", "is_correct": false, "explanation": "搭配：“眼睛”是身体器官，不能作时间状语，句子不通。"}, {"text": "地铁", "is_correct": false, "explanation": "语义：“地铁”是交通工具，不能作时间状语，句子不通。"}], "explanations": {"近年": "正确：近年指最近几年，与“这个城市的人越来越多”这种长期变化相符。", "童年": "语义：“童年”指人的少年时期，与这座城市的人口增长不搭配。", "眼睛": "搭配：“眼睛”是身体器官，不能作时间状语，句子不通。", "地铁": "语义：“地铁”是交通工具，不能作时间状语，句子不通。"}, "sentence_index": 0, "correct_answer": "近年"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "近年他感冒了，一直在家休息。", "explanation": "这里应该用〈近来〉。近年指最近几年，几天内的感冒要用近来。"}, {"text": "近年我们要去北京旅行。", "explanation": "这里应该用〈将来〉。近年指过去到现在的几年，计划将来的事要用将来。"}, {"text": "近年他下了飞机，现在正在等出租车。", "explanation": "这里应该用〈刚才〉。近年指最近几年，几分钟前刚发生的事要用刚才。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c46cb8d-7db9-433e-929e-cc38fb7b7492') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95283, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "近年", "is_correct": true, "explanation": "正确：近年指最近几年，与“写过几本关于旅行的书”的长期经历相符。"}, {"text": "黎明", "is_correct": false, "explanation": "语义：“黎明”指天刚亮的一刻，与“写过几本书”的长时段经历不合。"}, {"text": "傍晚", "is_correct": false, "explanation": "语义：“傍晚”指一段很短的时间，不能说明写过几本书的经历。"}, {"text": "当下", "is_correct": false, "explanation": "搭配：“当下”指眼前这一刻，不与表示经历的“写过”搭配。"}], "explanations": {"近年": "正确：近年指最近几年，与“写过几本关于旅行的书”的长期经历相符。", "黎明": "语义：“黎明”指天刚亮的一刻，与“写过几本书”的长时段经历不合。", "傍晚": "语义：“傍晚”指一段很短的时间，不能说明写过几本书的经历。", "当下": "搭配：“当下”指眼前这一刻，不与表示经历的“写过”搭配。"}, "sentence_index": 6, "correct_answer": "近年"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "近年早上八点，她离开了老家。", "explanation": "这里应该用〈今天〉。近年指几年，不能说某天早上几点，要用今天。"}, {"text": "她近年还是个小孩子，现在已经四十岁了。", "explanation": "这里应该用〈早年〉。近年指最近几年，很多年以前的事要用早年。"}, {"text": "近年三天，她都在北京开会。", "explanation": "这里应该用〈最近〉。近年指几年，不能和“三天”这样短的时间连用，要说最近三天。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c46cb8d-7db9-433e-929e-cc38fb7b7492') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95283, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "近年的，这个城市的房价涨了很多。", "corrected_sentence": "近年，这个城市的房价涨了很多。", "error_description": "“近年”作时间状语后不能直接加“的”（“近年的，”）；应去掉“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c46cb8d-7db9-433e-929e-cc38fb7b7492') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95283, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "近年的，他写过几本关于旅行的书。", "corrected_sentence": "近年，他写过几本关于旅行的书。", "error_description": "“近年”作时间状语时后面不能加“的”（“近年的，”）；应去掉“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c46cb8d-7db9-433e-929e-cc38fb7b7492') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
