INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95285, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "每个星期出一本的书报。", "primary_collocate": null, "pronunciation": "zhōu kān", "ipa": "ʈʂoʊ˥ kʰan˥", "syllable_count": 2, "sentences": [{"text": "学校门口的小店卖新周刊。", "target_word": "周刊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我订了一份足球周刊。", "target_word": "周刊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周刊每个星期出一本，很快就看完了。", "target_word": "周刊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本电影周刊十块钱一本。", "target_word": "周刊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每个周末都读一本周刊。", "target_word": "周刊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在车站买了一本周刊，路上看。", "target_word": "周刊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本周刊每个星期都出一期。", "target_word": "周刊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶喜欢看生活周刊。", "target_word": "周刊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌上有一本过期的周刊。", "target_word": "周刊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本周刊今天刚到，你要看吗？", "target_word": "周刊", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "本", "label": "量词"}, {"form": "份", "label": "量词"}], "register": "中性", "sense_fingerprint": "每星期出一本、可以买来读的书报", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ce6f043-36d5-4f98-a980-2e9de3c98ca2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95285, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "汽车", "is_correct": false, "explanation": "语义：学校门口的小店不卖汽车。"}, {"text": "周刊", "is_correct": true, "explanation": "周刊是每星期出一本的书报，小店可以卖。"}, {"text": "钢琴", "is_correct": false, "explanation": "语义：这种小店卖的是书报和日用品，不卖钢琴。"}, {"text": "月亮", "is_correct": false, "explanation": "配价：“卖”要求可以出售的物品，“月亮”不能被卖。"}], "explanations": {"汽车": "语义：学校门口的小店不卖汽车。", "周刊": "周刊是每星期出一本的书报，小店可以卖。", "钢琴": "语义：这种小店卖的是书报和日用品，不卖钢琴。", "月亮": "配价：“卖”要求可以出售的物品，“月亮”不能被卖。"}, "sentence_index": 0, "correct_answer": "周刊"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天早上都买一本周刊，看看今天的新闻。", "explanation": "这里应该用〈日报〉。周刊每星期才出一本，不能每天早上都买来看新闻。"}, {"text": "这本周刊每个月出一本。", "explanation": "这里应该用〈月刊〉。周刊是每星期出一本，每月出一本的刊物要用〈月刊〉。"}, {"text": "他用周刊插进锁孔，把门打开了。", "explanation": "这里应该用〈钥匙〉。周刊是印刷品，不能像钥匙一样插进锁孔开门。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '503170ae-c285-467c-84c1-fba5608e9ba4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95285, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "病历", "is_correct": false, "explanation": "语义：病历是医疗记录，不会每个星期出一期。"}, {"text": "周刊", "is_correct": true, "explanation": "周刊是定期出版的刊物，每个星期都出一期，符合句意。"}, {"text": "存折", "is_correct": false, "explanation": "语义：存折是银行账户凭证，不会每个星期出一期。"}, {"text": "户口本", "is_correct": false, "explanation": "语义：户口本是官方证件，不会每个星期出一期。"}], "explanations": {"病历": "语义：病历是医疗记录，不会每个星期出一期。", "周刊": "周刊是定期出版的刊物，每个星期都出一期，符合句意。", "存折": "语义：存折是银行账户凭证，不会每个星期出一期。", "户口本": "语义：户口本是官方证件，不会每个星期出一期。"}, "sentence_index": 6, "correct_answer": "周刊"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我拿起周刊对着电视按了几下，电视就换台了。", "explanation": "这里应该用〈遥控器〉。周刊不能当遥控器用，按它不能让电视换台。"}, {"text": "我用周刊记每天的花费。", "explanation": "这里应该用〈账本〉。周刊是刊物，记花费要用〈账本〉。"}, {"text": "他把周刊放进洗衣机里洗了一遍。", "explanation": "这里应该用〈衣物〉。周刊是印刷品，不能放进洗衣机洗，洗的是衣物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '503170ae-c285-467c-84c1-fba5608e9ba4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95285, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我每期都买一个生活周刊。", "corrected_sentence": "我每期都买一份生活周刊。", "error_description": "量词错误：“周刊”应用量词“本”或“份”，不能用“个”。应说“一份生活周刊”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '503170ae-c285-467c-84c1-fba5608e9ba4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95285, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "桌上放着一本的周刊。", "corrected_sentence": "桌上放着一本周刊。", "error_description": "结构错误：数量词“一本”后不能直接加“的”修饰名词，应说“一本周刊”，不说“一本的周刊”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '503170ae-c285-467c-84c1-fba5608e9ba4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
