INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95287, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "很会做运动、常常比赛的人。", "primary_collocate": null, "pronunciation": "yùn dòng jiā", "ipa": "yn˥˩ tʊŋ˥˩ tɕi̯a˥", "syllable_count": 3, "sentences": [{"text": "他每周都比赛，是一位有名的运动家。", "target_word": "运动家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位运动家每个周末都去比赛。", "target_word": "运动家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我哥哥是运动家，常常参加比赛。", "target_word": "运动家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她从小就爱运动，长大后成了运动家。", "target_word": "运动家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个运动家跑得很快，常常拿第一。", "target_word": "运动家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "运动家每天都要练习几个小时。", "target_word": "运动家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想像他一样，做一个常常参加体育比赛的运动家。", "target_word": "运动家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位运动家去过很多国家参加比赛。", "target_word": "运动家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "运动家常常比赛，所以身体都很好。", "target_word": "运动家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "来我们学校的运动家刚比赛回来。", "target_word": "运动家", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "很会运动、常常参加比赛的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2112c95f-d85a-4cfc-ba9f-40b392804a1d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95287, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "运动家", "is_correct": true, "explanation": "正确：指很会运动、常常参加比赛的人，与“每周都比赛”相符。"}, {"text": "医生", "is_correct": false, "explanation": "语义：医生以看病为业，不以比赛为常态，与“每周都比赛”不符。"}, {"text": "作家", "is_correct": false, "explanation": "语义：作家以写作为业，与“每周都比赛”不符。"}, {"text": "会计", "is_correct": false, "explanation": "搭配：“比赛”的主语应是参赛者，“会计”不是参赛的身份，搭配不当。"}], "explanations": {"运动家": "正确：指很会运动、常常参加比赛的人，与“每周都比赛”相符。", "医生": "语义：医生以看病为业，不以比赛为常态，与“每周都比赛”不符。", "作家": "语义：作家以写作为业，与“每周都比赛”不符。", "会计": "搭配：“比赛”的主语应是参赛者，“会计”不是参赛的身份，搭配不当。"}, "sentence_index": 0, "correct_answer": "运动家"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们坐运动家去北京。", "explanation": "这里应该用〈飞机〉。运动家指很会运动、常常比赛的人，不是交通工具。"}, {"text": "这家运动家的饭菜很好吃。", "explanation": "这里应该用〈饭店〉。运动家指人，不是吃饭的地方。"}, {"text": "我每天早上喝一杯运动家。", "explanation": "这里应该用〈牛奶〉。运动家指人，不能喝。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8274a805-2c34-4a6f-9e45-8d48a0d1896d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95287, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "运动家", "is_correct": true, "explanation": "正确：指常常参加比赛的运动员，与句中“常常比赛”相符。"}, {"text": "工程师", "is_correct": false, "explanation": "语义：工程师的工作是设计和建造，与“常常比赛”不符。"}, {"text": "律师", "is_correct": false, "explanation": "语义：律师以法律事务为业，不以比赛为常态，与句意不符。"}, {"text": "护士", "is_correct": false, "explanation": "搭配：“常常比赛的”后面接的是参赛者，“护士”不是参赛者的身份，搭配不当。"}], "explanations": {"运动家": "正确：指常常参加比赛的运动员，与句中“常常比赛”相符。", "工程师": "语义：工程师的工作是设计和建造，与“常常比赛”不符。", "律师": "语义：律师以法律事务为业，不以比赛为常态，与句意不符。", "护士": "搭配：“常常比赛的”后面接的是参赛者，“护士”不是参赛者的身份，搭配不当。"}, "sentence_index": 6, "correct_answer": "运动家"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我把书放进了运动家。", "explanation": "这里应该用〈书包〉。运动家指很会运动、常常比赛的人，不是装东西的用品。"}, {"text": "我们明天去运动家跑步。", "explanation": "这里应该用〈体育场〉。运动家指人，不指场地，在场地跑步要说〈体育场〉。"}, {"text": "我昨天在商店买了一个运动家。", "explanation": "这里应该用〈运动服〉。运动家指人，不是商品，要买的是〈运动服〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8274a805-2c34-4a6f-9e45-8d48a0d1896d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95287, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们学校有三只很厉害的运动家。", "corrected_sentence": "我们学校有三位很厉害的运动家。", "error_description": "错误形式是“三只”，正确形式是“三位”。“运动家”指人，要用量词“位”或“个”，“只”多用于动物，不用于指人。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8274a805-2c34-4a6f-9e45-8d48a0d1896d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95287, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我姐姐认识一很有名的运动家。", "corrected_sentence": "我姐姐认识一位很有名的运动家。", "error_description": "错误形式是缺少量词：“一很有名的运动家”，正确形式是“一位很有名的运动家”。指人的名词前要加量词“位”或“个”，不能省略。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8274a805-2c34-4a6f-9e45-8d48a0d1896d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
