INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95289, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04d2236b-4500-4360-93e1-98363f6eb264') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95289, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "离说话的人比较远的地方。", "primary_collocate": null, "pronunciation": "nàr", "ipa": "nɑɻ˥˩", "syllable_count": 2, "sentences": [{"text": "你看，我家就在那儿，不太远。", "target_word": "那儿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河对面有一家书店，那儿的书很多。", "target_word": "那儿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在这儿，他在那儿，中间有一条河。", "target_word": "那儿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在对面的路口，你去那儿找他。", "target_word": "那儿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那儿的天气比这儿冷。", "target_word": "那儿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山那边很美，我想去那儿看看。", "target_word": "那儿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "远处有座小山，那儿住着一位老人。", "target_word": "那儿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别去那儿，太远了，又没有车。", "target_word": "那儿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看，那儿有一只小狗，离我们很远。", "target_word": "那儿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从这儿走到那儿要十分钟。", "target_word": "那儿", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "那里", "label": "变体"}], "register": "口语", "sense_fingerprint": "那儿：指离说话人较远的地方，与“这儿”相对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '016a8d2a-68e4-4db2-b1cd-c081d7aad3bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95289, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "那儿", "is_correct": true, "explanation": "正确。“那儿”指说话人用手指着的、离自己有一段距离的地方，与“你看”相合。"}, {"text": "哪里", "is_correct": false, "explanation": "语义：“哪里”是疑问代词，句中是陈述，不能指“我家”所在的地方。"}, {"text": "谁", "is_correct": false, "explanation": "配价：“就在”后要接处所，“谁”指人，不能作处所。"}, {"text": "什么", "is_correct": false, "explanation": "语义：“什么”指事物或表示疑问，不能指“我家”所在的地方。"}], "explanations": {"那儿": "正确。“那儿”指说话人用手指着的、离自己有一段距离的地方，与“你看”相合。", "哪里": "语义：“哪里”是疑问代词，句中是陈述，不能指“我家”所在的地方。", "谁": "配价：“就在”后要接处所，“谁”指人，不能作处所。", "什么": "语义：“什么”指事物或表示疑问，不能指“我家”所在的地方。"}, "sentence_index": 0, "correct_answer": "那儿"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我手里拿着的书就在那儿。", "explanation": "这里应该用〈这儿〉。那儿指离说话人较远的地方，书就在手边，应用〈这儿〉。"}, {"text": "那儿是我的书，别拿错了。", "explanation": "这里应该用〈那〉。那儿只指处所，指东西要用〈那〉，如“那是我的书”。"}, {"text": "那儿是下午三点，我们该出发了。", "explanation": "这里应该用〈现在〉。那儿只指处所，不能用来表示时间。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04d2236b-4500-4360-93e1-98363f6eb264') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95289, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "那儿", "is_correct": true, "explanation": "正确。“那儿”指远处的山，与前句“远处有座小山”相呼应。"}, {"text": "这儿", "is_correct": false, "explanation": "语义：“远处”指离说话人远，“这儿”指说话人所在处，二者矛盾。"}, {"text": "这里", "is_correct": false, "explanation": "语义：“这里”同样指说话人近处，与“远处有座小山”不符。"}, {"text": "这", "is_correct": false, "explanation": "配价：“这”指事物，不能作“住着”的处所主语。"}], "explanations": {"那儿": "正确。“那儿”指远处的山，与前句“远处有座小山”相呼应。", "这儿": "语义：“远处”指离说话人远，“这儿”指说话人所在处，二者矛盾。", "这里": "语义：“这里”同样指说话人近处，与“远处有座小山”不符。", "这": "配价：“这”指事物，不能作“住着”的处所主语。"}, "sentence_index": 6, "correct_answer": "那儿"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "那儿是我的老师，他教我们数学。", "explanation": "这里应该用〈那位〉。那儿只指处所，指人要用〈那位〉。"}, {"text": "那儿已经是期末了，大家都很忙。", "explanation": "这里应该用〈现在〉。那儿只指处所，不能用来表示时间，“已经是期末了”说的是时间。"}, {"text": "那儿是一个好主意，我们就这么办。", "explanation": "这里应该用〈那〉。那儿只指处所，不能指想法，指想法要用〈那〉，如“那是一个好主意”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04d2236b-4500-4360-93e1-98363f6eb264') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95289, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那儿的有一家面包店，面包很好吃。", "corrected_sentence": "那儿有一家面包店，面包很好吃。", "error_description": "错误：“那儿”后多加了结构助词“的”，“那儿的”需要带中心语，这里没有。正确：处所词“那儿”直接作主语，应说“那儿有一家面包店”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04d2236b-4500-4360-93e1-98363f6eb264') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95289, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我在那儿了住三年。", "corrected_sentence": "我在那儿住了三年。", "error_description": "错误：“了”插在处所词“那儿”和动词“住”之间，位置不对。正确：“我在那儿住了三年”，“了”应放在动词后。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04d2236b-4500-4360-93e1-98363f6eb264') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95290, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04d2236b-4500-4360-93e1-98363f6eb264') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95290, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04d2236b-4500-4360-93e1-98363f6eb264') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95290, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "指示较远的处所；那里。", "primary_collocate": null, "pronunciation": "nàr", "ipa": "nɑɻ˥˩", "syllable_count": 2, "sentences": [{"text": "北京很大，我没去过那儿。", "target_word": "那儿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听说那儿的冬天很长。", "target_word": "那儿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "前面那座桥，你过了桥就到那儿了。", "target_word": "那儿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这儿离车站很近，那儿却很远。", "target_word": "那儿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那座城市很远，我坐飞机去那儿。", "target_word": "那儿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的老家在南方，他每年回那儿一次。", "target_word": "那儿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你先走，我晚点再去那儿找你。", "target_word": "那儿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这儿太吵了，我们去那儿坐吧。", "target_word": "那儿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那儿有个公园，孩子们都在那儿玩。", "target_word": "那儿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山顶上有一间小屋，我们晚上住那儿。", "target_word": "那儿", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "那里", "label": "变体"}], "register": "口语", "sense_fingerprint": "那儿：指示较远的处所，相当于“那里”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '016a8d2a-68e4-4db2-b1cd-c081d7aad3bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95290, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "那儿", "is_correct": true, "explanation": "正确。“那儿”指较远的处所，与“北京很大”的语境相合。"}, {"text": "他", "is_correct": false, "explanation": "配价：“去过”要求处所宾语，“他”指人，不能作去的地点。"}, {"text": "你", "is_correct": false, "explanation": "配价：“去过”要求处所宾语，“你”指人，不能作去的地点。"}, {"text": "谁", "is_correct": false, "explanation": "语义：“谁”表示疑问，与“北京很大”后面的陈述不符。"}], "explanations": {"那儿": "正确。“那儿”指较远的处所，与“北京很大”的语境相合。", "他": "配价：“去过”要求处所宾语，“他”指人，不能作去的地点。", "你": "配价：“去过”要求处所宾语，“你”指人，不能作去的地点。", "谁": "语义：“谁”表示疑问，与“北京很大”后面的陈述不符。"}, "sentence_index": 0, "correct_answer": "那儿"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的眼镜就在那儿，我伸手就能拿到。", "explanation": "这里应该用〈这儿〉。那儿指较远的处所，眼镜伸手可及，应用〈这儿〉。"}, {"text": "那儿是我的字典，你别乱动。", "explanation": "这里应该用〈那〉。那儿只指处所，指东西要用〈那〉，如“那是我的字典”。"}, {"text": "那儿已经是晚上十点了，快睡吧。", "explanation": "这里应该用〈现在〉。那儿只指处所，不能用来表示时间。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04d2236b-4500-4360-93e1-98363f6eb264') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95290, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "那儿", "is_correct": true, "explanation": "正确。“那儿”指离说话人较远的地方，与“晚点再去”的语境相合。"}, {"text": "她", "is_correct": false, "explanation": "配价：“去”后要接处所，“她”指人，不能作去的地点。"}, {"text": "我", "is_correct": false, "explanation": "语义：“我”指说话人自己，“去我找你”自相矛盾。"}, {"text": "它", "is_correct": false, "explanation": "配价：“它”指事物，不能作“去”的处所。"}], "explanations": {"那儿": "正确。“那儿”指离说话人较远的地方，与“晚点再去”的语境相合。", "她": "配价：“去”后要接处所，“她”指人，不能作去的地点。", "我": "语义：“我”指说话人自己，“去我找你”自相矛盾。", "它": "配价：“它”指事物，不能作“去”的处所。"}, "sentence_index": 6, "correct_answer": "那儿"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "那儿是我的表哥，他在大学教书。", "explanation": "这里应该用〈那位〉。那儿只指处所，指人要用〈那位〉。"}, {"text": "那儿已经是中午十二点了，我们去吃饭吧。", "explanation": "这里应该用〈现在〉。那儿只指处所，不能用来表示时间，“已经是中午十二点了”说的是时间。"}, {"text": "那儿是一个好办法，我们试试吧。", "explanation": "这里应该用〈那〉。那儿只指处所，不能指办法，指办法要用〈那〉，如“那是一个好办法”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04d2236b-4500-4360-93e1-98363f6eb264') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95290, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那儿的放着一把旧椅子。", "corrected_sentence": "那儿放着一把旧椅子。", "error_description": "错误：“那儿”后多加了结构助词“的”，“那儿的”需要带中心语，这里没有。正确：处所词“那儿”直接作主语，应说“那儿放着一把旧椅子”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04d2236b-4500-4360-93e1-98363f6eb264') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95290, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他在那儿里工作了五年。", "corrected_sentence": "他在那儿工作了五年。", "error_description": "错误：“那儿”本身就是处所词，后面不能再加方位词“里”，“那儿里”多余。正确：直接说“他在那儿工作了五年”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04d2236b-4500-4360-93e1-98363f6eb264') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
