INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95291, 1, 'prompt1_core', '{"pos": "量词", "semantic_class": "function", "definition": "量长短的小单位，比一米小很多。", "primary_collocate": null, "pronunciation": "lí mǐ", "ipa": "li˧˥ mi˨˩˦", "syllable_count": 2, "sentences": [{"text": "这只小虫只有一厘米长。", "target_word": "厘米", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌子和墙之间只差一厘米。", "target_word": "厘米", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "米太大了，量铅笔要用厘米。", "target_word": "厘米", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他比我高了两厘米。", "target_word": "厘米", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小草今天又长了一厘米。", "target_word": "厘米", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "量书的宽度，用厘米比用米方便。", "target_word": "厘米", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块布还差三厘米才够长。", "target_word": "厘米", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子一年长高了五厘米。", "target_word": "厘米", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张照片宽十厘米，高八厘米。", "target_word": "厘米", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "铅笔只有几厘米长，不能再写了。", "target_word": "厘米", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "平方厘米", "label": "复合"}, {"form": "立方厘米", "label": "复合"}], "register": "中性", "sense_fingerprint": "量短距离、小物体的小长度单位", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2112c95f-d85a-4cfc-ba9f-40b392804a1d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95291, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "厘米", "is_correct": true, "explanation": "正确：量长短的小单位，一厘米的小虫符合句意。"}, {"text": "公里", "is_correct": false, "explanation": "语义：一公里太长，小虫不可能只有这么长。"}, {"text": "公斤", "is_correct": false, "explanation": "语义：公斤是重量单位，不能用来量长短。"}, {"text": "分钟", "is_correct": false, "explanation": "搭配：“一”后应接长度单位，“分钟”是时间单位，搭配不当。"}], "explanations": {"厘米": "正确：量长短的小单位，一厘米的小虫符合句意。", "公里": "语义：一公里太长，小虫不可能只有这么长。", "公斤": "语义：公斤是重量单位，不能用来量长短。", "分钟": "搭配：“一”后应接长度单位，“分钟”是时间单位，搭配不当。"}, "sentence_index": 0, "correct_answer": "厘米"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他比我重了两厘米。", "explanation": "这里应该用〈公斤〉。体重要用公斤，厘米只用于长度。"}, {"text": "这件衣服比那件贵了二十厘米。", "explanation": "这里应该用〈元〉。价钱要用元，厘米只用于长度。"}, {"text": "我比他晚了五厘米。", "explanation": "这里应该用〈分钟〉。时间差要用分钟，厘米是长度单位。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8274a805-2c34-4a6f-9e45-8d48a0d1896d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95291, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "厘米", "is_correct": true, "explanation": "正确：长度单位，“还差三”后面要接长度单位。"}, {"text": "天", "is_correct": false, "explanation": "语义：天是时间单位，不能用来表示布的长度差。"}, {"text": "小时", "is_correct": false, "explanation": "搭配：“差”后面接的应是长度单位，“小时”是时间单位，搭配不当。"}, {"text": "年", "is_correct": false, "explanation": "语义：年是时间单位，布的长度差不能用年来表示。"}], "explanations": {"厘米": "正确：长度单位，“还差三”后面要接长度单位。", "天": "语义：天是时间单位，不能用来表示布的长度差。", "小时": "搭配：“差”后面接的应是长度单位，“小时”是时间单位，搭配不当。", "年": "语义：年是时间单位，布的长度差不能用年来表示。"}, "sentence_index": 6, "correct_answer": "厘米"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这桶油重十厘米。", "explanation": "这里应该用〈公斤〉。重量要用公斤，厘米只用于长度。"}, {"text": "今天的气温是八厘米。", "explanation": "这里应该用〈摄氏度〉。气温要用摄氏度，厘米只用于长度。"}, {"text": "我买了三厘米苹果。", "explanation": "这里应该用〈个〉。苹果一般用〈个〉来数，厘米不能用来数苹果。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8274a805-2c34-4a6f-9e45-8d48a0d1896d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95291, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "桌上的纸条只有厘米宽。", "corrected_sentence": "桌上的纸条只有两厘米宽。", "error_description": "错误形式是“只有厘米宽”，正确形式是“只有两厘米宽”。“厘米”前须有数量词，否则句子不完整。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8274a805-2c34-4a6f-9e45-8d48a0d1896d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95291, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这块布比那块长了五个厘米。", "corrected_sentence": "这块布比那块长了五厘米。", "error_description": "错误形式是“五个厘米”，正确形式是“五厘米”。“厘米”本身就是量词，前面不能再加“个”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8274a805-2c34-4a6f-9e45-8d48a0d1896d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
