INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95292, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8274a805-2c34-4a6f-9e45-8d48a0d1896d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95292, 1, 'prompt1_core', '{"pos": "量词", "semantic_class": "function", "definition": "长度单位，一百厘米等于一米。", "primary_collocate": null, "pronunciation": "lí mǐ", "ipa": "li˧˥ mi˨˩˦", "syllable_count": 2, "sentences": [{"text": "一米等于一百厘米。", "target_word": "厘米", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这根绳子长五十厘米。", "target_word": "厘米", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你量一量桌子有多少厘米。", "target_word": "厘米", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的尺子有三十厘米长。", "target_word": "厘米", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书厚三厘米。", "target_word": "厘米", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一百厘米正好是一米。", "target_word": "厘米", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他身高一百七十厘米。", "target_word": "厘米", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条鱼只有二十厘米长。", "target_word": "厘米", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把一米布剪成两段，每段五十厘米。", "target_word": "厘米", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "尺子上相邻两个数字之间的距离是一厘米。", "target_word": "厘米", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "平方厘米", "label": "复合"}, {"form": "立方厘米", "label": "复合"}], "register": "中性", "sense_fingerprint": "长度单位，一米的百分之一", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2112c95f-d85a-4cfc-ba9f-40b392804a1d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95292, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "厘米", "is_correct": true, "explanation": "正确：长度单位，一米等于一百厘米。"}, {"text": "公里", "is_correct": false, "explanation": "语义：公里是更大的长度单位，一米并不等于一百公里。"}, {"text": "千克", "is_correct": false, "explanation": "语义：千克是质量单位，不能用来换算长度。"}, {"text": "小时", "is_correct": false, "explanation": "搭配：“一百”后面应接长度单位，“小时”是时间单位，搭配不当。"}], "explanations": {"厘米": "正确：长度单位，一米等于一百厘米。", "公里": "语义：公里是更大的长度单位，一米并不等于一百公里。", "千克": "语义：千克是质量单位，不能用来换算长度。", "小时": "搭配：“一百”后面应接长度单位，“小时”是时间单位，搭配不当。"}, "sentence_index": 0, "correct_answer": "厘米"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的体重是三十厘米。", "explanation": "这里应该用〈公斤〉。体重是质量，要用公斤；厘米只用于长度。"}, {"text": "这次考试我用了两厘米。", "explanation": "这里应该用〈小时〉。考试时间要用小时或分钟，厘米是长度单位。"}, {"text": "这件衣服花了一百厘米。", "explanation": "这里应该用〈元〉。钱数要用元，厘米只用于长度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8274a805-2c34-4a6f-9e45-8d48a0d1896d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95292, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "厘米", "is_correct": true, "explanation": "正确：长度单位，身高要用长度单位来表示。"}, {"text": "元", "is_correct": false, "explanation": "语义：元是货币单位，身高不能用钱来计量。"}, {"text": "亩", "is_correct": false, "explanation": "语义：亩是面积单位，不能用来量身高。"}, {"text": "斤", "is_correct": false, "explanation": "搭配：斤是重量单位，身高应使用长度单位，搭配不当。"}], "explanations": {"厘米": "正确：长度单位，身高要用长度单位来表示。", "元": "语义：元是货币单位，身高不能用钱来计量。", "亩": "语义：亩是面积单位，不能用来量身高。", "斤": "搭配：斤是重量单位，身高应使用长度单位，搭配不当。"}, "sentence_index": 6, "correct_answer": "厘米"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "桌上放着两厘米苹果。", "explanation": "这里应该用〈个〉。苹果要用〈个〉来数，厘米是长度单位，不能用来数苹果。"}, {"text": "我买了三厘米牛奶。", "explanation": "这里应该用〈升〉。牛奶的量要用升，厘米只用于长度。"}, {"text": "今天气温是五厘米。", "explanation": "这里应该用〈摄氏度〉。气温要用摄氏度，厘米只用于长度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8274a805-2c34-4a6f-9e45-8d48a0d1896d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95292, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这张桌子长一百二十个厘米。", "corrected_sentence": "这张桌子长一百二十厘米。", "error_description": "错误形式是“一百二十个厘米”，正确形式是“一百二十厘米”。“厘米”本身就是量词，前面不能再加“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8274a805-2c34-4a6f-9e45-8d48a0d1896d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95292, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这根木条长了厘米。", "corrected_sentence": "这根木条长了三十厘米。", "error_description": "错误形式是“长了厘米”，正确形式是“长了三十厘米”。“厘米”前须有数量词，否则句子不完整。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8274a805-2c34-4a6f-9e45-8d48a0d1896d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
