INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95294, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "辨别并判定事物的真伪、优劣。", "primary_collocate": null, "pronunciation": "jiàn dìng", "ipa": "tɕjɛn˥˩ tiŋ˥˩", "syllable_count": 2, "sentences": [{"text": "专家鉴定这幅画是真品。", "target_word": "鉴定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件玉器要先鉴定，才能知道值多少钱。", "target_word": "鉴定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们请人鉴定了这批古董的真假。", "target_word": "鉴定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作人员鉴定了这批茶叶的好坏。", "target_word": "鉴定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块石头是不是宝石，要到店里鉴定。", "target_word": "鉴定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察请专家鉴定这张字条是不是他写的。", "target_word": "鉴定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "收藏家鉴定了很久，说这只碗是假的。", "target_word": "鉴定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份文件的真假，只有专家才能鉴定。", "target_word": "鉴定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把旧手镯拿去鉴定，结果是真银的。", "target_word": "鉴定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师傅鉴定了一下，说这块布料质量很好。", "target_word": "鉴定", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "鉴定了", "label": "体标（了）"}, {"form": "鉴定过", "label": "体标（过）"}, {"form": "鉴定书", "label": "复合"}, {"form": "鉴定师", "label": "复合"}, {"form": "鑑定", "label": "繁体"}], "register": "中性", "sense_fingerprint": "辨别判定事物的真伪优劣", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91f27bcb-e915-4d91-af5c-63c661bfa7ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95294, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "鉴定", "is_correct": true, "explanation": "鉴定：专家经过辨别，判定这幅画的真假，与语境相符。"}, {"text": "欣赏", "is_correct": false, "explanation": "语义：“欣赏”是喜爱、品味，不用来判定画是不是真品。"}, {"text": "修复", "is_correct": false, "explanation": "语义：“修复”是把坏的东西修好，不是判定真假，与“是真品”的判断不符。"}, {"text": "哭泣", "is_correct": false, "explanation": "配价：“哭泣”是不及物动词，不能带“这幅画”作宾语，“专家哭泣这幅画”不成立。"}], "explanations": {"鉴定": "鉴定：专家经过辨别，判定这幅画的真假，与语境相符。", "欣赏": "语义：“欣赏”是喜爱、品味，不用来判定画是不是真品。", "修复": "语义：“修复”是把坏的东西修好，不是判定真假，与“是真品”的判断不符。", "哭泣": "配价：“哭泣”是不及物动词，不能带“这幅画”作宾语，“专家哭泣这幅画”不成立。"}, "sentence_index": 0, "correct_answer": "鉴定"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我一眼就鉴定了那位老朋友。", "explanation": "这里应该用〈认出〉。认出是认得某人；鉴定是专业判定物品的真伪优劣，不能用来指认人。"}, {"text": "妈妈鉴定了一桌丰盛的晚饭。", "explanation": "这里应该用〈做〉。做饭是动手烹调；鉴定是辨别判定物品的真伪优劣，不能用来表示做饭。"}, {"text": "孩子鉴定了窗外的天气。", "explanation": "这里应该用〈观察〉。观察是仔细看并了解情况；鉴定是判定物品的真伪优劣，不能用来说天气。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '688b247e-a2ac-4095-bcf3-0f9f901c9e49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95294, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "鉴定", "is_correct": true, "explanation": "鉴定：收藏家经过仔细辨别，判定碗的真假，与“说这只碗是假的”相符。"}, {"text": "推荐", "is_correct": false, "explanation": "语义：“推荐”是称赞介绍，与“说这只碗是假的”的否定判断相反。"}, {"text": "忘记", "is_correct": false, "explanation": "语义：“忘记了很久”后不能接“说这只碗是假的”这样的判断，前后矛盾。"}, {"text": "夸奖", "is_correct": false, "explanation": "语义：“夸奖”是称赞，与“说这只碗是假的”的结论矛盾。"}], "explanations": {"鉴定": "鉴定：收藏家经过仔细辨别，判定碗的真假，与“说这只碗是假的”相符。", "推荐": "语义：“推荐”是称赞介绍，与“说这只碗是假的”的否定判断相反。", "忘记": "语义：“忘记了很久”后不能接“说这只碗是假的”这样的判断，前后矛盾。", "夸奖": "语义：“夸奖”是称赞，与“说这只碗是假的”的结论矛盾。"}, "sentence_index": 6, "correct_answer": "鉴定"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "仓库管理员鉴定了货物的数量。", "explanation": "这里应该用〈清点〉。清点是逐一数出数目；鉴定是判定真伪优劣，不能用来核对数量。"}, {"text": "工人鉴定了桌子的长度。", "explanation": "这里应该用〈测量〉。测量是用工具量出长短；鉴定是判定真伪优劣，不能用来量长度。"}, {"text": "学生鉴定了那次会议。", "explanation": "这里应该用〈组织〉。组织是安排并筹办活动；鉴定是判定物品的真伪优劣，不能用来指会议。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '688b247e-a2ac-4095-bcf3-0f9f901c9e49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95294, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这幅画把专家鉴定了，是真品。", "corrected_sentence": "这幅画被专家鉴定了，是真品。", "error_description": "被动/把字句错误：“这幅画”是被鉴定的对象，应用“被”引出施事“专家”，说“这幅画被专家鉴定了”。“把”后面的宾语应是受事，这里却接了施事“专家”，所以“这幅画把专家鉴定了”不通。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '688b247e-a2ac-4095-bcf3-0f9f901c9e49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95294, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师傅明天鉴定过这块布料。", "corrected_sentence": "老师傅明天鉴定这块布料。", "error_description": "体标错误：“过”表示动作已经完成，不能与“明天”这样的将来时间词搭配；去掉“过”，应说“老师傅明天鉴定这块布料。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '688b247e-a2ac-4095-bcf3-0f9f901c9e49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
