INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95296, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "对与母亲年龄相仿的女性的称呼，也指母亲的姐妹。", "primary_collocate": null, "pronunciation": "ā yí", "ipa": "a˥ i˧˥", "syllable_count": 2, "sentences": [{"text": "我阿姨在北京工作。", "target_word": "阿姨", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "阿姨是我妈妈的妹妹。", "target_word": "阿姨", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "楼下的阿姨每天早上跳舞。", "target_word": "阿姨", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "阿姨，请问去地铁站怎么走？", "target_word": "阿姨", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那位阿姨帮我找到了钱包。", "target_word": "阿姨", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "周末我去阿姨家看表弟。", "target_word": "阿姨", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "超市里的阿姨给我拿了一袋米。", "target_word": "阿姨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的阿姨做的菜非常好吃。", "target_word": "阿姨", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "阿姨，这个多少钱？", "target_word": "阿姨", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他阿姨去年来过我们学校。", "target_word": "阿姨", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "个", "label": "量词"}], "register": "口语", "sense_fingerprint": "称呼与母亲年龄相仿的女性，或指母亲的姐妹", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b37fbea5-e5a7-40fc-aef0-8c6a260a8c6f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95296, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "阿姨", "is_correct": true, "explanation": "正确：“阿姨”指母亲的姐妹或与母亲年龄相仿的女性，可以在北京工作。"}, {"text": "小猫", "is_correct": false, "explanation": "语义：“小猫”不是人，不能在北京工作。"}, {"text": "作业", "is_correct": false, "explanation": "语义：“作业”是学习任务，不能作“在北京工作”的主语。"}, {"text": "眼睛", "is_correct": false, "explanation": "搭配：“眼睛”是身体部位，不能说“在北京工作”。"}], "explanations": {"阿姨": "正确：“阿姨”指母亲的姐妹或与母亲年龄相仿的女性，可以在北京工作。", "小猫": "语义：“小猫”不是人，不能在北京工作。", "作业": "语义：“作业”是学习任务，不能作“在北京工作”的主语。", "眼睛": "搭配：“眼睛”是身体部位，不能说“在北京工作”。"}, "sentence_index": 0, "correct_answer": "阿姨"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我妈妈的女儿是我的阿姨，她比我大三岁。", "explanation": "这里应该用〈姐姐〉。阿姨指母亲的姐妹或与母亲年龄相仿的女性，不能指母亲的女儿，也就是自己的姐姐。"}, {"text": "阿姨生下了我的弟弟。", "explanation": "这里应该用〈妈妈〉。“生下”的是母亲，阿姨不能这样用。"}, {"text": "这个阿姨刚出生，还不会说话。", "explanation": "这里应该用〈宝宝〉。阿姨指成年女性，不用于刚出生的婴儿。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c46cb8d-7db9-433e-929e-cc38fb7b7492') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95296, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "阿姨", "is_correct": true, "explanation": "正确：超市里的“阿姨”可以给顾客拿东西，符合句意。"}, {"text": "货架", "is_correct": false, "explanation": "语义：“货架”不是人，不能给我拿东西。"}, {"text": "收银机", "is_correct": false, "explanation": "语义：“收银机”不是人，不能给我拿东西。"}, {"text": "蔬菜", "is_correct": false, "explanation": "语义：“蔬菜”不是人，不能给我拿东西。"}], "explanations": {"阿姨": "正确：超市里的“阿姨”可以给顾客拿东西，符合句意。", "货架": "语义：“货架”不是人，不能给我拿东西。", "收银机": "语义：“收银机”不是人，不能给我拿东西。", "蔬菜": "语义：“蔬菜”不是人，不能给我拿东西。"}, "sentence_index": 6, "correct_answer": "阿姨"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的阿姨和我同班，每天一起上课。", "explanation": "这里应该用〈同学〉。阿姨指年纪比小朋友大的女性，不能和说话人同班。"}, {"text": "她是我的阿姨，才三岁。", "explanation": "这里应该用〈女儿〉。阿姨是成年女性的称呼，三岁的孩子不能是阿姨。"}, {"text": "我的阿姨是一位留着胡子的男人，他每天骑车送我上学。", "explanation": "这里应该用〈叔叔〉。阿姨指女性，不能用来称呼男性。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c46cb8d-7db9-433e-929e-cc38fb7b7492') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95296, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我有一只阿姨住在上海。", "corrected_sentence": "我有一位阿姨住在上海。", "error_description": "量词错误：“阿姨”指人，应用量词“位”（或“个”）。“只”用于动物，应改为“一位阿姨”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c46cb8d-7db9-433e-929e-cc38fb7b7492') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95296, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我家附近那位热心得阿姨常帮我买菜。", "corrected_sentence": "我家附近那位热心的阿姨常帮我买菜。", "error_description": "助词错误：“热心”修饰名词“阿姨”时应用“的”，不能用“得”（“得”用于补语）。应说“那位热心的阿姨”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c46cb8d-7db9-433e-929e-cc38fb7b7492') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
