INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95297, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "身体或脑子转得快，不呆板。", "primary_collocate": null, "pronunciation": "líng huó", "ipa": "liŋ˧˥ xwo˧˥", "syllable_count": 2, "sentences": [{"text": "他的脑子很灵活，一学就会。", "target_word": "灵活", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个孩子想问题很灵活。", "target_word": "灵活", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，学数学要灵活一点，不要死记公式。", "target_word": "灵活", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的思路很灵活，总能想出新办法。", "target_word": "灵活", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年纪大了，我的头脑不如以前灵活了。", "target_word": "灵活", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做生意要头脑灵活，才能赚到钱。", "target_word": "灵活", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他头脑灵活，很快就想出了解决难题的办法。", "target_word": "灵活", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一听就反应过来，脑子转得很灵活。", "target_word": "灵活", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小李的头脑很灵活，看一遍题目就想出了解法。", "target_word": "灵活", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位经理头脑很灵活，客户一提问他就能马上回答。", "target_word": "灵活", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "灵活性", "label": "复合"}], "register": "中性", "sense_fingerprint": "脑子或身体反应快、不呆板", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f60e3e1-7e5c-4460-8a03-18319ddd28e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95297, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "灵活", "is_correct": true, "explanation": "正确：灵活指脑子转得快、不呆板，与“一学就会”相符。"}, {"text": "迟钝", "is_correct": false, "explanation": "语义：脑子迟钝与“一学就会”矛盾。"}, {"text": "结实", "is_correct": false, "explanation": "搭配：“结实”说身体或物体牢固，不能形容脑子。"}, {"text": "慢", "is_correct": false, "explanation": "语义：脑子慢与“一学就会”矛盾。"}], "explanations": {"灵活": "正确：灵活指脑子转得快、不呆板，与“一学就会”相符。", "迟钝": "语义：脑子迟钝与“一学就会”矛盾。", "结实": "搭配：“结实”说身体或物体牢固，不能形容脑子。", "慢": "语义：脑子慢与“一学就会”矛盾。"}, "sentence_index": 0, "correct_answer": "灵活"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台仪器很灵活，测量非常准确。", "explanation": "这里应该用〈灵敏〉。仪器对细微变化反应快要说灵敏，“灵活”不用于形容仪器的感应能力。"}, {"text": "这个偏方很灵活，吃了就好了。", "explanation": "这里应该用〈灵验〉。偏方有效果要说灵验，“灵活”指动作或思路敏捷、不死板。"}, {"text": "他消息很灵活，什么事都知道。", "explanation": "这里应该用〈灵通〉。消息知道得多、传得快要说灵通，“灵活”不用于消息。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79a7f742-7ea7-4ddd-8813-2caa673a1ddf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95297, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "灵活", "is_correct": true, "explanation": "正确：头脑灵活指脑子转得快，与“很快就想出了办法”相符。"}, {"text": "漆黑", "is_correct": false, "explanation": "搭配：“漆黑”形容颜色或光线，不能形容头脑。"}, {"text": "矮", "is_correct": false, "explanation": "语义：“矮”描写人或物的高度，不能形容头脑。"}, {"text": "鲜艳", "is_correct": false, "explanation": "搭配：“鲜艳”形容颜色，不能形容头脑。"}], "explanations": {"灵活": "正确：头脑灵活指脑子转得快，与“很快就想出了办法”相符。", "漆黑": "搭配：“漆黑”形容颜色或光线，不能形容头脑。", "矮": "语义：“矮”描写人或物的高度，不能形容头脑。", "鲜艳": "搭配：“鲜艳”形容颜色，不能形容头脑。"}, "sentence_index": 6, "correct_answer": "灵活"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这座桥很灵活，车辆可以安全通过。", "explanation": "这里应该用〈坚固〉。桥梁的牢固稳定要说坚固，“灵活”指动作敏捷或思路不死板。"}, {"text": "这棵树很灵活，有十几米高。", "explanation": "这里应该用〈高大〉。树木或人的体形高要说高大，“灵活”不用于形容体形。"}, {"text": "教室里很灵活，大家都在认真听讲。", "explanation": "这里应该用〈安静〉。环境或场所寂静要说安静，“灵活”不用于形容环境。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79a7f742-7ea7-4ddd-8813-2caa673a1ddf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95297, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他灵活的解决了这个问题。", "corrected_sentence": "他灵活地解决了这个问题。", "error_description": "错误：“灵活的解决”。正确：“灵活地解决”。作状语修饰动词时要用“地”，“的”用来连接名词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79a7f742-7ea7-4ddd-8813-2caa673a1ddf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95297, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的脑子变灵活着。", "corrected_sentence": "他的脑子变灵活了。", "error_description": "错误：“变灵活着”。正确：“变灵活了”。“着”表示状态或动作的持续，不能表示变化的完成；“变灵活”表示已经发生的变化，要用“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79a7f742-7ea7-4ddd-8813-2caa673a1ddf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
