INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95298, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "动作敏捷，不死板，善于应变。", "primary_collocate": null, "pronunciation": "líng huó", "ipa": "liŋ˧˥ xwo˧˥", "syllable_count": 2, "sentences": [{"text": "小猫的动作很灵活，一下子跳上了桌子。", "target_word": "灵活", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位足球运动员转身非常灵活。", "target_word": "灵活", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他虽然胖，但是跳舞时身体很灵活。", "target_word": "灵活", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人每天打太极拳，手脚还是很灵活。", "target_word": "灵活", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的手指很灵活，弹钢琴弹得又快又好。", "target_word": "灵活", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "守门员身体灵活，接住了好几个球。", "target_word": "灵活", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "猴子在树上爬来爬去，动作灵活极了。", "target_word": "灵活", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "司机灵活地绕过了前面的车。", "target_word": "灵活", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做了手术以后，他的腿不太灵活。", "target_word": "灵活", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这只小鸟飞得又快又灵活。", "target_word": "灵活", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "灵活性", "label": "派生"}], "register": "中性", "sense_fingerprint": "动作敏捷、善于应变", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f60e3e1-7e5c-4460-8a03-18319ddd28e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95298, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "灵活", "is_correct": true, "explanation": "正确：灵活指动作敏捷，与“一下子跳上了桌子”相符。"}, {"text": "笨重", "is_correct": false, "explanation": "语义：笨重的动作难以“一下子跳上桌子”。"}, {"text": "呆滞", "is_correct": false, "explanation": "语义：呆滞指动作或表情不灵敏，与“一下子跳上了桌子”矛盾。"}, {"text": "缓慢", "is_correct": false, "explanation": "语义：缓慢与“一下子”矛盾。"}], "explanations": {"灵活": "正确：灵活指动作敏捷，与“一下子跳上了桌子”相符。", "笨重": "语义：笨重的动作难以“一下子跳上桌子”。", "呆滞": "语义：呆滞指动作或表情不灵敏，与“一下子跳上了桌子”矛盾。", "缓慢": "语义：缓慢与“一下子”矛盾。"}, "sentence_index": 0, "correct_answer": "灵活"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的耳朵很灵活，一点声音都能听见。", "explanation": "这里应该用〈灵敏〉。感官反应快要说灵敏，“灵活”用于动作或思路。"}, {"text": "这棵老树很灵活，枝叶很茂盛。", "explanation": "这里应该用〈高大〉。树木的体形要说高大，“灵活”形容动作敏捷，不用于树木。"}, {"text": "这座老桥很灵活，车辆可以通过。", "explanation": "这里应该用〈坚固〉。桥梁牢固要说坚固，“灵活”不用于建筑。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79a7f742-7ea7-4ddd-8813-2caa673a1ddf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95298, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "灵活", "is_correct": true, "explanation": "正确：灵活指动作敏捷，与爬树的情景相符。"}, {"text": "僵硬", "is_correct": false, "explanation": "语义：僵硬的动作与“爬来爬去”矛盾。"}, {"text": "迟缓", "is_correct": false, "explanation": "语义：迟缓与“动作灵活极了”的赞许语气相反，也与“爬来爬去”的敏捷形象不符。"}, {"text": "沉重", "is_correct": false, "explanation": "语义：沉重的动作与“爬来爬去”矛盾。"}], "explanations": {"灵活": "正确：灵活指动作敏捷，与爬树的情景相符。", "僵硬": "语义：僵硬的动作与“爬来爬去”矛盾。", "迟缓": "语义：迟缓与“动作灵活极了”的赞许语气相反，也与“爬来爬去”的敏捷形象不符。", "沉重": "语义：沉重的动作与“爬来爬去”矛盾。"}, "sentence_index": 6, "correct_answer": "灵活"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他对新闻很灵活，什么消息都知道。", "explanation": "这里应该用〈灵通〉。对消息了解多、传播快要说灵通，“灵活”不用于消息。"}, {"text": "这床被子很灵活，摸起来很舒服。", "explanation": "这里应该用〈柔软〉。质地松软、不硬要说柔软，“灵活”用于动作或思路。"}, {"text": "这根绳子很灵活，怎么拉也拉不断。", "explanation": "这里应该用〈结实〉。物体牢固、不易断要说结实，“灵活”不用于形容绳子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79a7f742-7ea7-4ddd-8813-2caa673a1ddf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95298, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只狗跑很灵活。", "corrected_sentence": "这只狗跑得很灵活。", "error_description": "错误：“跑很灵活”，缺少“得”。正确：“跑得很灵活”。描述动作达到的程度要用“动词+得+程度补语”结构，省略“得”后句子不成立。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79a7f742-7ea7-4ddd-8813-2caa673a1ddf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95298, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "小猫灵活的跳上了桌子。", "corrected_sentence": "小猫灵活地跳上了桌子。", "error_description": "错误：“灵活的跳上”。正确：“灵活地跳上”。修饰动词的状语要用“地”，“的”用来连接名词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79a7f742-7ea7-4ddd-8813-2caa673a1ddf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
