INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95299, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '503170ae-c285-467c-84c1-fba5608e9ba4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95299, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "在某件事上特别厉害的人。", "primary_collocate": null, "pronunciation": "gāo shǒu", "ipa": "kɑʊ˥ ʂoʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "我弟弟是玩游戏的高手。", "target_word": "高手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她是我们班的英语高手。", "target_word": "高手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是省钱高手，每个月都能存钱。", "target_word": "高手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个问题要找高手来帮忙。", "target_word": "高手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王是跑步高手，每次都第一。", "target_word": "高手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我妈妈是买菜高手，会选又会讲价。", "target_word": "高手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是拍照高手，照片都很好看。", "target_word": "高手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你是高手，教教我怎么做吧。", "target_word": "高手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他看起来很普通，其实是高手。", "target_word": "高手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网球高手在场上跑得很快。", "target_word": "高手", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "个", "label": "量词"}], "register": "口语", "sense_fingerprint": "在某件事上特别厉害的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ce6f043-36d5-4f98-a980-2e9de3c98ca2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95299, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "护士", "is_correct": false, "explanation": "语义：护士是医护人员，不是玩游戏的人。"}, {"text": "高手", "is_correct": true, "explanation": "高手指在某件事上特别厉害的人，与“玩游戏的”相符。"}, {"text": "农民", "is_correct": false, "explanation": "语义：农民与玩游戏无关。"}, {"text": "律师", "is_correct": false, "explanation": "搭配：“玩游戏的”后接的是玩家或高手，不说“玩游戏的律师”。"}], "explanations": {"护士": "语义：护士是医护人员，不是玩游戏的人。", "高手": "高手指在某件事上特别厉害的人，与“玩游戏的”相符。", "农民": "语义：农民与玩游戏无关。", "律师": "搭配：“玩游戏的”后接的是玩家或高手，不说“玩游戏的律师”。"}, "sentence_index": 0, "correct_answer": "高手"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这种通关办法很高手。", "explanation": "这里应该用〈高明〉。高手是指人的名词，不能受“很”修饰；形容办法好要用〈高明〉。"}, {"text": "我对电脑是门外汉，什么都不会，却是电脑高手。", "explanation": "这里不能称〈高手〉。高手指在某件事上特别厉害的人，对电脑一窍不通的人只能算〈外行〉。"}, {"text": "他是网球新手，第一次拿拍，却是网球高手。", "explanation": "这里不能称〈高手〉。第一次拿拍的人还谈不上在这件事上特别厉害，只能算〈初学者〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '503170ae-c285-467c-84c1-fba5608e9ba4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95299, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "厨师", "is_correct": false, "explanation": "语义：厨师与拍照无关。"}, {"text": "高手", "is_correct": true, "explanation": "高手指在拍照方面特别厉害的人，与“照片都很好看”相符。"}, {"text": "司机", "is_correct": false, "explanation": "语义：司机与拍照无关，句子说的是照片好看。"}, {"text": "裁缝", "is_correct": false, "explanation": "搭配：“拍照”不说“拍照裁缝”，裁缝做的是衣服。"}], "explanations": {"厨师": "语义：厨师与拍照无关。", "高手": "高手指在拍照方面特别厉害的人，与“照片都很好看”相符。", "司机": "语义：司机与拍照无关，句子说的是照片好看。", "裁缝": "搭配：“拍照”不说“拍照裁缝”，裁缝做的是衣服。"}, "sentence_index": 6, "correct_answer": "高手"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "网球学员还在练基本功，却已经是网球高手了。", "explanation": "这里不能用〈高手〉。高手指在某件事上特别厉害的人，还在练基本功的人只能算〈新手〉。"}, {"text": "这个网球拍很高手，用起来很顺手。", "explanation": "这里应该用〈好用〉。高手是指人的名词，不能说“很高手”；说球拍用着顺手要用〈好用〉。"}, {"text": "我是这场比赛的旁观者，却是网球高手。", "explanation": "这里不能用〈高手〉。没有上场的人谈不上本领高超，这里应称〈观众〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '503170ae-c285-467c-84c1-fba5608e9ba4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95299, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她是弹钢琴得高手。", "corrected_sentence": "她是弹钢琴的高手。", "error_description": "结构助词错误：修饰名词要用“的”，“得”用于动词后的补语。应说“弹钢琴的高手”，不说“弹钢琴得高手”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '503170ae-c285-467c-84c1-fba5608e9ba4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95299, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这位大叔是一条象棋高手，每次都赢。", "corrected_sentence": "这位大叔是一位象棋高手，每次都赢。", "error_description": "量词错误：“高手”指人，应用量词“位”，不用“条”（“条”多用于细长的物件）。应说“一位象棋高手”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '503170ae-c285-467c-84c1-fba5608e9ba4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
