INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95301, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "中学生毕业前，要参加的一次很大的考试。", "primary_collocate": null, "pronunciation": "gāo kǎo", "ipa": "kɑʊ̯˥ kʰɑʊ̯˨˩˦", "syllable_count": 2, "sentences": [{"text": "明年我就要参加高考了。", "target_word": "高考", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "高考前，同学们每天学到很晚。", "target_word": "高考", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈为我的高考准备了很多好吃的。", "target_word": "高考", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "离高考只有一百天了。", "target_word": "高考", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "高考快到了，他有点儿紧张。", "target_word": "高考", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "高三的学生都在准备高考。", "target_word": "高考", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "高考那天，爸爸送我去学校。", "target_word": "高考", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他为了高考，天天做练习。", "target_word": "高考", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "高考对中学生来说很重要。", "target_word": "高考", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考完高考，我们终于可以休息了。", "target_word": "高考", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "高考生", "label": "复合"}], "register": "中性", "sense_fingerprint": "中学生毕业前的一次重要大考", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2112c95f-d85a-4cfc-ba9f-40b392804a1d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95301, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱是家用电器，不是可以参加的活动。"}, {"text": "高考", "is_correct": true, "explanation": "正确：“参加高考”指参加中学毕业前的大考，句意通顺。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“参加”要搭配考试、比赛、活动，天气不能被参加。"}, {"text": "皮鞋", "is_correct": false, "explanation": "语义：皮鞋是衣物，不是活动，不能“参加”。"}], "explanations": {"冰箱": "语义：冰箱是家用电器，不是可以参加的活动。", "高考": "正确：“参加高考”指参加中学毕业前的大考，句意通顺。", "天气": "搭配：“参加”要搭配考试、比赛、活动，天气不能被参加。", "皮鞋": "语义：皮鞋是衣物，不是活动，不能“参加”。"}, "sentence_index": 0, "correct_answer": "高考"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "初三的学生明年六月就要参加高考了。", "explanation": "这里应该用〈中考〉。初三学生考中考，高考要到高三才参加。"}, {"text": "他今天要去公司参加高考。", "explanation": "这里应该用〈招聘考试〉。高考是中学生毕业前参加的全国统一大考，去公司参加的应是招聘考试。"}, {"text": "他花了三年时间读高考。", "explanation": "这里应该用〈高中〉。“读”的对象是学校，高考是考试，不能说“读高考”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8274a805-2c34-4a6f-9e45-8d48a0d1896d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95301, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "墨水", "is_correct": false, "explanation": "语义：墨水是液体，不是日子，不能用“那天”指代它。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头是物体，不是一个可以指代的日子。"}, {"text": "高考", "is_correct": true, "explanation": "正确：“高考那天”指考试当天，爸爸送我去学校，句意通顺。"}, {"text": "板凳", "is_correct": false, "explanation": "搭配：“那天”要指日子或事件，板凳不能作为时间词。"}], "explanations": {"墨水": "语义：墨水是液体，不是日子，不能用“那天”指代它。", "石头": "语义：石头是物体，不是一个可以指代的日子。", "高考": "正确：“高考那天”指考试当天，爸爸送我去学校，句意通顺。", "板凳": "搭配：“那天”要指日子或事件，板凳不能作为时间词。"}, "sentence_index": 6, "correct_answer": "高考"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们在高考里学习英语。", "explanation": "这里应该用〈学校〉。高考是考试，不是地点，不能说“在高考里学习”。"}, {"text": "大学生每天都要上高考。", "explanation": "这里应该用〈课〉。高考是考试，不能说“上高考”；参加高考要说“参加”。"}, {"text": "我给高考买了一件礼物。", "explanation": "这里应该用〈老师〉。高考是考试，不是人，不能收礼物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8274a805-2c34-4a6f-9e45-8d48a0d1896d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95301, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "明年我要参加了高考。", "corrected_sentence": "明年我要参加高考。", "error_description": "错误形式：“要参加了高考”；正确形式：“要参加高考”。“了”表示动作已经完成，与表示将来的“明年”和“要”矛盾，不能加在“参加”后面。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8274a805-2c34-4a6f-9e45-8d48a0d1896d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95301, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们经历了一个高考。", "corrected_sentence": "我们经历了一次高考。", "error_description": "错误形式：“一个高考”；正确形式：“一次高考”。高考是一次性的考试活动，量词应用“次”，不用“个”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8274a805-2c34-4a6f-9e45-8d48a0d1896d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
