INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95302, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "普通高等学校招生全国统一考试的简称。", "primary_collocate": null, "pronunciation": "gāo kǎo", "ipa": "kɑʊ̯˥ kʰɑʊ̯˨˩˦", "syllable_count": 2, "sentences": [{"text": "高考每年六月举行。", "target_word": "高考", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "全国的考生都要参加高考。", "target_word": "高考", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "高考成绩出来了。", "target_word": "高考", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "高考时，学生要带身份证。", "target_word": "高考", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在高考中考了很好的分数。", "target_word": "高考", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "高考的题目每年都不一样。", "target_word": "高考", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "高考结束后，他想去旅行。", "target_word": "高考", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市的高考考场在中学里。", "target_word": "高考", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的高考分数能上北京大学。", "target_word": "高考", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家每年都要组织高考。", "target_word": "高考", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "高考生", "label": "复合"}], "register": "中性", "sense_fingerprint": "全国统一的大学招生考试", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2112c95f-d85a-4cfc-ba9f-40b392804a1d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95302, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "晚饭", "is_correct": false, "explanation": "搭配：“举行”用于会议、比赛、考试等活动，不能说“晚饭每年六月举行”。"}, {"text": "高考", "is_correct": true, "explanation": "正确：高考是全国统一的高校招生考试，每年六月举行，符合句意。"}, {"text": "电脑", "is_correct": false, "explanation": "语义：电脑是设备，不是活动，不能“每年六月举行”。"}, {"text": "身份证", "is_correct": false, "explanation": "语义：身份证是个人证件，不是可以举行的活动。"}], "explanations": {"晚饭": "搭配：“举行”用于会议、比赛、考试等活动，不能说“晚饭每年六月举行”。", "高考": "正确：高考是全国统一的高校招生考试，每年六月举行，符合句意。", "电脑": "语义：电脑是设备，不是活动，不能“每年六月举行”。", "身份证": "语义：身份证是个人证件，不是可以举行的活动。"}, "sentence_index": 0, "correct_answer": "高考"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "高考结束后，他要选择去哪所高中。", "explanation": "这里应该用〈中考〉。中考是初中毕业后考高中的考试；高考是大学入学考试，高中毕业后才参加。"}, {"text": "他明年要读高考。", "explanation": "这里应该用〈高中〉。“读”的对象是学校或学科，高考是考试，不能说“读高考”。"}, {"text": "他这次期末高考又拿了第一名。", "explanation": "这里应该用〈期末考试〉。高考专指全国统一的大学入学考试，学校的期末考试不能说高考。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8274a805-2c34-4a6f-9e45-8d48a0d1896d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95302, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "钥匙", "is_correct": false, "explanation": "语义：钥匙是工具，不是事件或时段，不能“结束后”。"}, {"text": "白菜", "is_correct": false, "explanation": "语义：白菜是蔬菜，不能“结束”，句中“结束后”没有合适的主语。"}, {"text": "高考", "is_correct": true, "explanation": "正确：考试结束后，他才想去旅行，符合句意。"}, {"text": "沙发", "is_correct": false, "explanation": "搭配：“结束”用于活动、时期，不能用于家具。"}], "explanations": {"钥匙": "语义：钥匙是工具，不是事件或时段，不能“结束后”。", "白菜": "语义：白菜是蔬菜，不能“结束”，句中“结束后”没有合适的主语。", "高考": "正确：考试结束后，他才想去旅行，符合句意。", "沙发": "搭配：“结束”用于活动、时期，不能用于家具。"}, "sentence_index": 6, "correct_answer": "高考"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他大学毕业后打算高考，去读研究生。", "explanation": "这里应该用〈考研〉。高考是高中毕业生参加的大学入学考试；大学毕业后升学要考研究生。"}, {"text": "学校给我们发高考。", "explanation": "这里应该用〈教材〉。高考不是可以发放的物品，“发”不能用于考试。"}, {"text": "学校每年都放高考。", "explanation": "这里应该用〈暑假〉。“放”用于假期，高考是考试，不能说“放高考”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8274a805-2c34-4a6f-9e45-8d48a0d1896d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95302, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他下个月参加了高考。", "corrected_sentence": "他下个月参加高考。", "error_description": "错误形式：“下个月参加了高考”；正确形式：“下个月参加高考”。“了”表示动作已经完成，不能与将来的时间“下个月”连用。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8274a805-2c34-4a6f-9e45-8d48a0d1896d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95302, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他经历了一个高考。", "corrected_sentence": "他经历了一次高考。", "error_description": "错误形式：“一个高考”；正确形式：“一次高考”。高考是一次性的考试活动，量词应用“次”，不用“个”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8274a805-2c34-4a6f-9e45-8d48a0d1896d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
