INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95304, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "副词，表示很干脆、一下子地做出某个动作，常用于答应、拒绝、说出等。", "primary_collocate": null, "pronunciation": "yī kǒu", "ipa": "i˥˥ kʰoʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "他一口答应了我的请求。", "target_word": "一口", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老板一口拒绝了我们。", "target_word": "一口", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她一口咬定那个包是自己的。", "target_word": "一口", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他一口答应帮我搬家。", "target_word": "一口", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小王一口说出了答案。", "target_word": "一口", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他一口否认自己拿过那本书。", "target_word": "一口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈一口说出我的名字，我吓了一跳。", "target_word": "一口", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "经理一口回绝了这个想法。", "target_word": "一口", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那个人一口咬定自己没来过这里。", "target_word": "一口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对方一口认定是我们的错。", "target_word": "一口", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一口气", "label": "复合"}], "register": "口语", "sense_fingerprint": "一下子、很干脆地说出或做完", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17ff06e6-d05a-42d0-84b6-f1fd5eae80ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95304, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "一口", "is_correct": true, "explanation": "一口（yī kǒu）：副词，表示很干脆、一下子做出动作。"}, {"text": "衣扣", "is_correct": false, "explanation": "衣扣（yī kòu）与 kǒu 声调不同，kòu 是第四声，意思是衣服上的纽扣。"}, {"text": "衣篓", "is_correct": false, "explanation": "衣篓（yī lǒu）与 kǒu 声母不同，l 与 k 不同，意思是装衣物的篓子。"}, {"text": "一篓", "is_correct": false, "explanation": "一篓（yī lǒu）与 kǒu 声母不同，l 与 k 不同，意思是一篓（盛装的量）。"}], "explanations": {"一口": "一口（yī kǒu）：副词，表示很干脆、一下子做出动作。", "衣扣": "衣扣（yī kòu）与 kǒu 声调不同，kòu 是第四声，意思是衣服上的纽扣。", "衣篓": "衣篓（yī lǒu）与 kǒu 声母不同，l 与 k 不同，意思是装衣物的篓子。", "一篓": "一篓（yī lǒu）与 kǒu 声母不同，l 与 k 不同，意思是一篓（盛装的量）。"}, "sentence_index": null, "correct_answer": "一口"}, "level_3": {"options": [{"text": "一口", "is_correct": true, "explanation": "一口：副词，表示很干脆地一下子做出动作，与“答应”搭配。"}, {"text": "一齐", "is_correct": false, "explanation": "语义：“一齐”指多人或多物同时进行，“他”一人不能与之相合。"}, {"text": "一同", "is_correct": false, "explanation": "语义：“一同”指共同做某事，一人单独答应请求与之不合。"}, {"text": "一并", "is_correct": false, "explanation": "搭配：“一并”多修饰办理、处理类的动作，不与“答应”搭配。"}], "explanations": {"一口": "一口：副词，表示很干脆地一下子做出动作，与“答应”搭配。", "一齐": "语义：“一齐”指多人或多物同时进行，“他”一人不能与之相合。", "一同": "语义：“一同”指共同做某事，一人单独答应请求与之不合。", "一并": "搭配：“一并”多修饰办理、处理类的动作，不与“答应”搭配。"}, "sentence_index": 0, "correct_answer": "一口"}, "level_6": {"correct_sentence_index": 4, "wrong_sentences": [{"text": "他一口明白了我的意思。", "explanation": "这里应该用〈一下子〉。“一口”多修饰表示干脆做出的决定或回答，“明白”是心里的理解，不能用“一口”。"}, {"text": "他一口工作了八个小时。", "explanation": "这里应该用〈一口气〉。“一口”表示干脆或突然，不表示持续的时间，连续不停地做事要说“一口气”。"}, {"text": "他一口走进了房间。", "explanation": "这里应该用〈一下子〉。“一口”多修饰说话、答应、拒绝等干脆做出的决定或回答，不能修饰“走进”这样的位移动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70428954-4397-48b4-b49b-6d906a67ae78') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95304, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "一口", "is_correct": true, "explanation": "一口：副词，很干脆地一下子说出，与“说出”搭配。"}, {"text": "一概", "is_correct": false, "explanation": "语义：“一概”表示没有例外，多用于否定句，与“说出名字”这一次动作不合。"}, {"text": "一律", "is_correct": false, "explanation": "搭配：“一律”多用于同样对待的事物，不能修饰说出名字的动作。"}, {"text": "一共", "is_correct": false, "explanation": "语义：“一共”表示合计数量，不能修饰“说出名字”这样的动作。"}], "explanations": {"一口": "一口：副词，很干脆地一下子说出，与“说出”搭配。", "一概": "语义：“一概”表示没有例外，多用于否定句，与“说出名字”这一次动作不合。", "一律": "搭配：“一律”多用于同样对待的事物，不能修饰说出名字的动作。", "一共": "语义：“一共”表示合计数量，不能修饰“说出名字”这样的动作。"}, "sentence_index": 6, "correct_answer": "一口"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她一口哭了起来。", "explanation": "这里应该用〈一下子〉。“一口”多修饰表示干脆做出的决定或回答，不修饰“哭”这样的情绪反应。"}, {"text": "妈妈一口笑出了声。", "explanation": "这里应该用〈突然〉。“一口”多修饰表示干脆做出的决定或回答，不修饰“笑出声”这样的生理反应。"}, {"text": "这三个人一口吃了一个月的饭。", "explanation": "这里应该用〈一直〉。“一口”表示干脆、一下子，不表示持续的时间；连续不断地做某事要说“一直”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70428954-4397-48b4-b49b-6d906a67ae78') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95304, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他一口拒绝了一口建议。", "corrected_sentence": "他一口拒绝了这个建议。", "error_description": "错误：“他一口拒绝了一口建议”；正确：“他一口拒绝了这个建议”。第二个“一口”作量词修饰“建议”，“口”只用于咬、喝、吃的量，不能计量“建议”，应改为“这个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70428954-4397-48b4-b49b-6d906a67ae78') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95304, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妹妹一口答应了去看一口电影。", "corrected_sentence": "妹妹一口答应了去看电影。", "error_description": "错误：“看一口电影”；正确：“看电影”。“一口”是咬、喝、吃的量词，不能用来计量“电影”，这里不应插入“一口”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70428954-4397-48b4-b49b-6d906a67ae78') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
