INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95308, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "列在下面的。", "primary_collocate": null, "pronunciation": "xià liè", "ipa": "ɕja˥˩ liɛ˥˩", "syllable_count": 2, "sentences": [{"text": "下列名单上的人请到前面来。", "target_word": "下列", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请看下列图片，然后回答问题。", "target_word": "下列", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请对下列句子进行改正。", "target_word": "下列", "complexity_tier": "T3", "furigana": "qǐng duì xiàliè jùzi jìnxíng gǎizhèng", "sentence_source": "generated"}, {"text": "下列词语中有一个写错了。", "target_word": "下列", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下列物品不能带上飞机。", "target_word": "下列", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请在下列选项中选一个。", "target_word": "下列", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请读完下列文章，再回答问题。", "target_word": "下列", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想去下列几个城市旅游。", "target_word": "下列", "complexity_tier": "T3", "furigana": "wǒ xiǎng qù xiàliè jǐ gè chéngshì lǚyóu", "sentence_source": "generated"}, {"text": "请听下列三个句子。", "target_word": "下列", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下列哪个字是新学的？", "target_word": "下列", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "排列在下面的（定语）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4747408d-1a98-454a-a674-44dda78aa04a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95308, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "下列", "is_correct": true, "explanation": "正确：“下列”修饰“名单”，指后文列出的名单。"}, {"text": "美丽", "is_correct": false, "explanation": "搭配：“美丽”形容人或景物，不能修饰“名单”。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：“高大”形容人或物的外形，不能修饰“名单”。"}, {"text": "甜", "is_correct": false, "explanation": "语义：“甜”描述味道，与“名单”不能搭配。"}], "explanations": {"下列": "正确：“下列”修饰“名单”，指后文列出的名单。", "美丽": "搭配：“美丽”形容人或景物，不能修饰“名单”。", "高大": "体貌：“高大”形容人或物的外形，不能修饰“名单”。", "甜": "语义：“甜”描述味道，与“名单”不能搭配。"}, "sentence_index": 0, "correct_answer": "下列"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们刚才看过的下列词语，有一个写错了。", "explanation": "这里应该用〈这些〉。下列指后文才列出的内容，而这些词语是刚才已经看过的，不能用“下列”来指。"}, {"text": "妈妈买的下列水果都很甜。", "explanation": "这里应该用〈那些〉。下列只用于后文要列出的内容，妈妈已经买回来的水果不能这样指。"}, {"text": "下列天气很冷，我们穿厚衣服吧。", "explanation": "这里应该用〈今天的〉。下列只修饰后文列出的项目，不能修饰天气。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '293ba40b-5c94-4f9c-adcb-2dc4aaba108d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95308, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "下列", "is_correct": true, "explanation": "正确：“下列”修饰“文章”，指后文列出的文章。"}, {"text": "咸", "is_correct": false, "explanation": "语义：“咸”形容味道，不能修饰“文章”。"}, {"text": "胖", "is_correct": false, "explanation": "体貌：“胖”形容人或动物的体型，不能修饰“文章”。"}, {"text": "矮小", "is_correct": false, "explanation": "体貌：“矮小”形容人或物的高度，不能修饰“文章”。"}], "explanations": {"下列": "正确：“下列”修饰“文章”，指后文列出的文章。", "咸": "语义：“咸”形容味道，不能修饰“文章”。", "胖": "体貌：“胖”形容人或动物的体型，不能修饰“文章”。", "矮小": "体貌：“矮小”形容人或物的高度，不能修饰“文章”。"}, "sentence_index": 6, "correct_answer": "下列"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在下列地方找到了钱包。", "explanation": "这里应该用〈这个〉。下列指后文要列出的地方，这里的地方是眼前说的，不是后面列出的。"}, {"text": "下列哥哥比我高。", "explanation": "这里应该用〈我的〉。下列只指后文列出的人或事，不能指自己的家人。"}, {"text": "今天下列作业很多。", "explanation": "这里应该用〈这些〉。下列指后文要列出的作业，这里的作业是眼前已有的，不是后面列出的。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '293ba40b-5c94-4f9c-adcb-2dc4aaba108d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
