INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95309, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "和该有的样子不一样，没有做对。", "primary_collocate": null, "pronunciation": "bù biāo zhǔn", "ipa": "pu˥˩ pjɑʊ˥ ʈʂwən˨˩", "syllable_count": 3, "sentences": [{"text": "你的姿势不标准，腿要再直一点。", "target_word": "不标准", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个字的笔画不标准，看起来很怪。", "target_word": "不标准", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他拿筷子的方法不标准。", "target_word": "不标准", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的英语发音不标准，朋友笑了。", "target_word": "不标准", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个动作做得不标准，要再练习。", "target_word": "不标准", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他唱歌的方法不标准，听着很难受。", "target_word": "不标准", "complexity_tier": "T3", "furigana": "tā chàng gē de fāng fǎ bù biāo zhǔn, tīng zhe hěn nán shòu.", "sentence_source": "generated"}, {"text": "孩子写字的姿势不标准。", "target_word": "不标准", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这道菜的做法不标准，味道不对。", "target_word": "不标准", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的汉字写得不标准，老师改了。", "target_word": "不标准", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说我的读音不标准。", "target_word": "不标准", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "不標準", "label": "繁体"}], "register": "中性", "sense_fingerprint": "做得和应有的样子不同", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a65ce783-209c-496d-8375-67116e6f7c33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95309, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "不标准", "is_correct": true, "explanation": "“不标准”说姿势没有做到应有的样子，与后句“腿要再直一点”的建议相符。"}, {"text": "流利", "is_correct": false, "explanation": "搭配：“流利”多用于说话或语言，不用来形容姿势。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：“高大”形容人的身材，不能用来形容姿势。"}, {"text": "完美", "is_correct": false, "explanation": "语义：“完美”说姿势已经很好，与“腿要再直一点”的建议矛盾。"}], "explanations": {"不标准": "“不标准”说姿势没有做到应有的样子，与后句“腿要再直一点”的建议相符。", "流利": "搭配：“流利”多用于说话或语言，不用来形容姿势。", "高大": "体貌：“高大”形容人的身材，不能用来形容姿势。", "完美": "语义：“完美”说姿势已经很好，与“腿要再直一点”的建议矛盾。"}, "sentence_index": 0, "correct_answer": "不标准"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "今天的天气很不标准，突然下起了大雨。", "explanation": "这里应该用〈不正常〉。不标准指做法或东西没有做到应有的样子，不用来形容天气；天气反常要说不正常。"}, {"text": "他这次考试的成绩很不标准，有些难过。", "explanation": "这里应该用〈不理想〉。不标准指做得和应有的样子不同，成绩的好坏要说不理想。"}, {"text": "他对朋友说的话很不标准，朋友都生气了。", "explanation": "这里应该用〈不得体〉。不标准指做得不对，说话是否得体要说不得体。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '979e2659-c933-4818-bcef-e3cf85849824') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95309, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "不标准", "is_correct": true, "explanation": "“不标准”说写字的姿势没有做对，符合句意。"}, {"text": "响亮", "is_correct": false, "explanation": "搭配：“响亮”形容声音，不用来形容写字的姿势。"}, {"text": "活泼", "is_correct": false, "explanation": "语义：“活泼”说性格或样子生动，与写字的姿势无关。"}, {"text": "粗壮", "is_correct": false, "explanation": "体貌：“粗壮”形容身体的粗细，不用来形容姿势。"}], "explanations": {"不标准": "“不标准”说写字的姿势没有做对，符合句意。", "响亮": "搭配：“响亮”形容声音，不用来形容写字的姿势。", "活泼": "语义：“活泼”说性格或样子生动，与写字的姿势无关。", "粗壮": "体貌：“粗壮”形容身体的粗细，不用来形容姿势。"}, "sentence_index": 6, "correct_answer": "不标准"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的脸色很不标准，看上去很累。", "explanation": "这里应该用〈苍白〉。不标准指做得不对，脸色的样子要说苍白。"}, {"text": "他讲的故事很不标准，大家听不懂。", "explanation": "这里应该用〈不清楚〉。不标准用于做法或样子没有达到要求，讲得明不明白要说不清楚。"}, {"text": "他的眼神很不标准，看起来有点慌张。", "explanation": "这里应该用〈躲闪〉。不标准指做得不对，眼神闪躲要说躲闪。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '979e2659-c933-4818-bcef-e3cf85849824') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
