INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95313, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "在事情发生以前，先做好。", "primary_collocate": null, "pronunciation": "shì xiān", "ipa": "ʂɻ̩˥˩ ɕi̯ɛn˥", "syllable_count": 2, "sentences": [{"text": "去饭店吃饭，最好事先订位子。", "target_word": "事先", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开会前，我事先准备好了材料。", "target_word": "事先", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈事先把菜洗好了。", "target_word": "事先", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你们事先看一下课文，上课就容易多了。", "target_word": "事先", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "客人要来，我们事先打扫了房间。", "target_word": "事先", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考试以前，要事先想好怎么回答。", "target_word": "事先", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出门旅行，要事先查好天气。", "target_word": "事先", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他事先写好了要说的话。", "target_word": "事先", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "去医院看病可以事先在网上预约。", "target_word": "事先", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师事先把练习题准备好了。", "target_word": "事先", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "事情发生前先做好准备（订位、准备、打扫）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ec53b00-6195-460c-9dc7-5a5e3f5ff1e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95313, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "事先", "is_correct": true, "explanation": "表示事情发生之前先做好准备，符合“最好……订位子”的建议语境。"}, {"text": "事后", "is_correct": false, "explanation": "语义：“事后”指事情发生之后，订位子在事后已经来不及。"}, {"text": "正在", "is_correct": false, "explanation": "体貌：“正在”表示动作进行中，与“最好……订位子”的建议语境不搭，句子不通。"}, {"text": "故意", "is_correct": false, "explanation": "搭配：“故意”多修饰有意的不当行为，与“最好”的建议语气不搭。"}], "explanations": {"事先": "表示事情发生之前先做好准备，符合“最好……订位子”的建议语境。", "事后": "语义：“事后”指事情发生之后，订位子在事后已经来不及。", "正在": "体貌：“正在”表示动作进行中，与“最好……订位子”的建议语境不搭，句子不通。", "故意": "搭配：“故意”多修饰有意的不当行为，与“最好”的建议语气不搭。"}, "sentence_index": 0, "correct_answer": "事先"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "吃完饭以后，我事先刷了牙。", "explanation": "这里应该用〈之后〉。“事先”指事情发生前做好准备，刷牙发生在吃饭之后，不能说事先。"}, {"text": "我们考完试事先才对答案。", "explanation": "这里应该用〈然后〉。“事先”指事前，“考完试”之后才对答案，应说“然后”。"}, {"text": "客人走以后，我们事先打扫了房间。", "explanation": "这里应该用〈事后〉。“事先”指事前做准备，打扫发生在客人走后，应说“事后”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '941e0a09-4e7f-42c2-bcae-44406f5b4567') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95313, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "事先", "is_correct": true, "explanation": "表示事情发生之前先做好准备，符合“出门旅行，要……查好天气”的语境。"}, {"text": "亲口", "is_correct": false, "explanation": "搭配：“亲口”指用嘴亲自说，不能修饰“查天气”。"}, {"text": "从来", "is_correct": false, "explanation": "语义：“从来”表示一直以来，与“出门前”要做的准备不符。"}, {"text": "刚", "is_correct": false, "explanation": "语义：“刚”表示刚刚发生，与“出门旅行前要查”的时间不符。"}], "explanations": {"事先": "表示事情发生之前先做好准备，符合“出门旅行，要……查好天气”的语境。", "亲口": "搭配：“亲口”指用嘴亲自说，不能修饰“查天气”。", "从来": "语义：“从来”表示一直以来，与“出门前”要做的准备不符。", "刚": "语义：“刚”表示刚刚发生，与“出门旅行前要查”的时间不符。"}, "sentence_index": 6, "correct_answer": "事先"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "上完课，老师事先留了作业。", "explanation": "这里应该用〈随后〉。“事先”指事前，留作业是课后的事，应说“随后”。"}, {"text": "他刚进门，我们就事先迎了上去。", "explanation": "这里应该用〈立刻〉。“事先”指事前，“刚进门”之后才迎接，顺序矛盾。"}, {"text": "他挂了电话，事先离开了。", "explanation": "这里应该用〈随即〉。“事先”指事前，挂电话之后才离开，应说“随即”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '941e0a09-4e7f-42c2-bcae-44406f5b4567') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95313, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们很事先把房间打扫好了。", "corrected_sentence": "我们事先把房间打扫好了。", "error_description": "错误：“很”不能修饰副词“事先”。应删去“很”，说“我们事先把房间打扫好了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '941e0a09-4e7f-42c2-bcae-44406f5b4567') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95313, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师事先了准备好了试卷。", "corrected_sentence": "老师事先准备好了试卷。", "error_description": "“了”的位置错了。“事先”是副词，后面不能直接加“了”，多出的“了”应删去，说“老师事先准备好了试卷”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '941e0a09-4e7f-42c2-bcae-44406f5b4567') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
