INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95314, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "在事情发生或进行之前。", "primary_collocate": null, "pronunciation": "shì xiān", "ipa": "ʂɻ̩˥˩ ɕi̯ɛn˥", "syllable_count": 2, "sentences": [{"text": "这件事我事先不知道。", "target_word": "事先", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他事先没有告诉任何人。", "target_word": "事先", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事他事先没有跟我商量。", "target_word": "事先", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "事先没有人想到会下雨。", "target_word": "事先", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师事先没说今天要考试。", "target_word": "事先", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个消息我事先一点儿也不清楚。", "target_word": "事先", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对不起，我事先不知道你今天过生日。", "target_word": "事先", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他事先没问过我，就把我的书借走了。", "target_word": "事先", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "事先谁也不知道比赛会这么难。", "target_word": "事先", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次旅行的事，爸爸事先谁也没告诉。", "target_word": "事先", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "事情发生之前（还不知道、没说、没想到）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ec53b00-6195-460c-9dc7-5a5e3f5ff1e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95314, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "事先", "is_correct": true, "explanation": "表示在事情发生之前，符合“这件事我……不知道”的语境。"}, {"text": "立刻", "is_correct": false, "explanation": "语义：“立刻”指马上行动，与“事情发生前”的时间不符。"}, {"text": "亲自", "is_correct": false, "explanation": "搭配：“亲自”修饰动作，不能修饰“不知道”这种状态。"}, {"text": "事后", "is_correct": false, "explanation": "语义：“事后”指事情发生之后，与“事先”的时间方向相反。"}], "explanations": {"事先": "表示在事情发生之前，符合“这件事我……不知道”的语境。", "立刻": "语义：“立刻”指马上行动，与“事情发生前”的时间不符。", "亲自": "搭配：“亲自”修饰动作，不能修饰“不知道”这种状态。", "事后": "语义：“事后”指事情发生之后，与“事先”的时间方向相反。"}, "sentence_index": 0, "correct_answer": "事先"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "事先大家才明白原因。", "explanation": "这里应该用〈最后〉。“事先”指事情发生之前，而“才明白”表示发生在后，两者矛盾。"}, {"text": "事先，他才把真相告诉了我。", "explanation": "这里应该用〈事后〉。“事先”指事前，“才把真相告诉”表示事后，顺序相反。"}, {"text": "我们事先赢得了比赛。", "explanation": "这里应该用〈终于〉。“事先”指事前，赢得比赛是结果，不能事先完成。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '941e0a09-4e7f-42c2-bcae-44406f5b4567') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95314, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "事先", "is_correct": true, "explanation": "表示在事情发生之前，符合“对不起，我……不知道你今天过生日”的语境。"}, {"text": "正在", "is_correct": false, "explanation": "语法：“正在”表示进行中的动作，不能修饰“不知道”这种状态，句子不通。"}, {"text": "偶尔", "is_correct": false, "explanation": "搭配：“偶尔”表示不常发生，不能修饰“不知道”这种持续状态。"}, {"text": "忽然", "is_correct": false, "explanation": "语义：“忽然”表示突然发生，“忽然不知道”不合道歉的语境，句意不通。"}], "explanations": {"事先": "表示在事情发生之前，符合“对不起，我……不知道你今天过生日”的语境。", "正在": "语法：“正在”表示进行中的动作，不能修饰“不知道”这种状态，句子不通。", "偶尔": "搭配：“偶尔”表示不常发生，不能修饰“不知道”这种持续状态。", "忽然": "语义：“忽然”表示突然发生，“忽然不知道”不合道歉的语境，句意不通。"}, "sentence_index": 6, "correct_answer": "事先"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他听到消息后，事先出发了。", "explanation": "这里应该用〈立刻〉。“事先”指事前，而“听到消息后”已是之后，出发不能事先。"}, {"text": "我事先才见到他。", "explanation": "这里应该用〈后来〉。“事先”指事前，“才见到”表示事后，两者顺序矛盾。"}, {"text": "他看到信后，事先就回了信。", "explanation": "这里应该用〈马上〉。“事先”指事前，而“看到信后”之后才回信，顺序矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '941e0a09-4e7f-42c2-bcae-44406f5b4567') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95314, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我事先的买好了火车票。", "corrected_sentence": "我事先买好了火车票。", "error_description": "错误：多了“的”。“事先”是副词，直接放在动词前面修饰动词，中间不能加“的”，应说“我事先买好了火车票”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '941e0a09-4e7f-42c2-bcae-44406f5b4567') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95314, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他事先了告诉我这件事。", "corrected_sentence": "他事先告诉我这件事。", "error_description": "“了”的位置错了。“事先”是副词，后面不能直接加“了”，应删去“了”，说“他事先告诉我这件事”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '941e0a09-4e7f-42c2-bcae-44406f5b4567') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
