INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95318, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "居住的地方。", "primary_collocate": null, "pronunciation": "zhù dì", "ipa": "ʈʂu˥˩ ti˥˩", "syllable_count": 2, "sentences": [{"text": "这里是工人们的住地。", "target_word": "住地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山里的住地很简单，可是很干净。", "target_word": "住地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们终于在河边找到了新住地。", "target_word": "住地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个村子是他们祖辈的住地。", "target_word": "住地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想为家人换一个好住地。", "target_word": "住地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外国朋友的住地靠近公园。", "target_word": "住地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的住地离工厂很近。", "target_word": "住地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些民工的住地条件不太好。", "target_word": "住地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请告诉我你们在北京的住地。", "target_word": "住地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师带我们看了工人的住地。", "target_word": "住地", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个住地", "label": "量词"}], "register": "中性", "sense_fingerprint": "居住的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '40ccaa6c-88be-4174-ab0d-a617460feb36') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95318, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "住地", "is_correct": true, "explanation": "正确：住地指居住的地方，“这里是工人们的……”指的正是他们住的地方。"}, {"text": "工资", "is_correct": false, "explanation": "语义：工资是收入，不是场所，不能说“这里是工人们的工资”。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：年龄是岁数，不是场所，不能说“这里是工人们的年龄”。"}, {"text": "身份证", "is_correct": false, "explanation": "搭配：“这里是……的”要接地点或场所，身份证是证件，不能这样说。"}], "explanations": {"住地": "正确：住地指居住的地方，“这里是工人们的……”指的正是他们住的地方。", "工资": "语义：工资是收入，不是场所，不能说“这里是工人们的工资”。", "年龄": "语义：年龄是岁数，不是场所，不能说“这里是工人们的年龄”。", "身份证": "搭配：“这里是……的”要接地点或场所，身份证是证件，不能这样说。"}, "sentence_index": 0, "correct_answer": "住地"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这里是茶叶的住地。", "explanation": "这里应该用〈产地〉。住地指人居住的地方，茶叶不住人，要说“产地”。"}, {"text": "这里是长江的住地。", "explanation": "这里应该用〈发源地〉。住地指人居住的地方，长江不住人，要说“发源地”。"}, {"text": "这片树林是老人安葬的住地。", "explanation": "这里应该用〈墓地〉。住地指人居住的地方，安葬之处要说“墓地”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5b3da8f-38fb-4b17-bfe6-56ca8c06d98f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95318, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "住地", "is_correct": true, "explanation": "正确：住地是居住的地方，可以说“住地离工厂很近”。"}, {"text": "意见", "is_correct": false, "explanation": "语义：意见是想法，不是地点，不能说“他们的意见离工厂很近”。"}, {"text": "时间", "is_correct": false, "explanation": "语义：时间不是地点，没有位置，不能说“他们的时间离工厂很近”。"}, {"text": "爱好", "is_correct": false, "explanation": "语义：爱好是喜欢做的事，不是地点，不能说离工厂近。"}], "explanations": {"住地": "正确：住地是居住的地方，可以说“住地离工厂很近”。", "意见": "语义：意见是想法，不是地点，不能说“他们的意见离工厂很近”。", "时间": "语义：时间不是地点，没有位置，不能说“他们的时间离工厂很近”。", "爱好": "语义：爱好是喜欢做的事，不是地点，不能说离工厂近。"}, "sentence_index": 6, "correct_answer": "住地"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这片住地是用来踢球的。", "explanation": "这里应该用〈场地〉。住地指人居住的地方，踢球的地方要说“场地”。"}, {"text": "这里是火箭的住地。", "explanation": "这里应该用〈发射场〉。住地指人居住的地方，火箭不住人，要说“发射场”。"}, {"text": "演出的住地在剧院。", "explanation": "这里应该用〈演出地点〉。住地指人居住的地方，演出不是人住的，要说“演出地点”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5b3da8f-38fb-4b17-bfe6-56ca8c06d98f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95318, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这里有一只住地。", "corrected_sentence": "这里有一处住地。", "error_description": "量词错误：“只”不能用来数“住地”，应改为“处”，说“一处住地”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5b3da8f-38fb-4b17-bfe6-56ca8c06d98f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95318, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们在河边找到了一位新住地。", "corrected_sentence": "他们在河边找到了一处新住地。", "error_description": "量词错误：“位”用于人，不能用来数“住地”。应改为“处”，说“一处新住地”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5b3da8f-38fb-4b17-bfe6-56ca8c06d98f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
