INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95319, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "做事时不让别人看见也不让别人知道。", "primary_collocate": null, "pronunciation": "tōu tōu", "ipa": "tʰou̯˥ tʰou̯˥", "syllable_count": 2, "sentences": [{"text": "他偷偷把手机放进了书包里。", "target_word": "偷偷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟偷偷拿了妈妈的钱。", "target_word": "偷偷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚上，孩子偷偷打开了冰箱。", "target_word": "偷偷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她偷偷地走出了教室。", "target_word": "偷偷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我没告诉别人，偷偷去看了那场电影。", "target_word": "偷偷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上课时，他偷偷吃东西。", "target_word": "偷偷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们偷偷给老师准备了生日礼物。", "target_word": "偷偷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明偷偷溜出去玩，家人都不知道。", "target_word": "偷偷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈不让吃糖，他就偷偷买了一块。", "target_word": "偷偷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他偷偷在墙上画过一只小狗。", "target_word": "偷偷", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "偷偷地", "label": "带“地”的状语形式"}, {"form": "偷偷摸摸", "label": "复合词"}], "register": "中性", "sense_fingerprint": "做事时瞒着别人，不让人看见（偷偷拿、偷偷溜出去）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ec53b00-6195-460c-9dc7-5a5e3f5ff1e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95319, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "偷偷", "is_correct": true, "explanation": "“偷偷”表示瞒着别人做事，与“把手机放进了书包里”这一隐蔽动作相符。"}, {"text": "正在", "is_correct": false, "explanation": "体貌：“正在”表示动作正在进行，与句中的“了”表示已完成相冲突。"}, {"text": "一直", "is_correct": false, "explanation": "体貌：“一直”表示持续不断，与“放进了”这种一次性动作冲突。"}, {"text": "大声地", "is_correct": false, "explanation": "语义：“大声地”说明声音很大，把手机放进书包不需要发出大声响，句意不通。"}], "explanations": {"偷偷": "“偷偷”表示瞒着别人做事，与“把手机放进了书包里”这一隐蔽动作相符。", "正在": "体貌：“正在”表示动作正在进行，与句中的“了”表示已完成相冲突。", "一直": "体貌：“一直”表示持续不断，与“放进了”这种一次性动作冲突。", "大声地": "语义：“大声地”说明声音很大，把手机放进书包不需要发出大声响，句意不通。"}, "sentence_index": 0, "correct_answer": "偷偷"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他偷偷地在全校大会上宣读了获奖名单。", "explanation": "这里应该用〈公开地〉，不能用“偷偷”。“偷偷”表示瞒着别人，而“全校大会上宣读”是公开进行的，两者矛盾。"}, {"text": "妈妈偷偷地喊孩子回家吃饭，整条街都听见了。", "explanation": "这里应该用〈大声地〉。“偷偷”表示不让别人知道，而“整条街都听见了”与之矛盾。"}, {"text": "老师偷偷地把通知贴在了校门口的大告示牌上，人人都看得见。", "explanation": "这里应该用〈醒目地〉。“偷偷”表示瞒着别人，而“人人都看得见”与之矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '941e0a09-4e7f-42c2-bcae-44406f5b4567') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95319, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "偷偷", "is_correct": true, "explanation": "“偷偷”表示瞒着老师准备，与“礼物”的惊喜性质相符。"}, {"text": "庄严地", "is_correct": false, "explanation": "语域：“庄严地”是正式严肃的语体，与生日礼物的轻松场合不符。"}, {"text": "狠狠地", "is_correct": false, "explanation": "搭配：“狠狠地”表示用力，不能修饰“准备礼物”这类轻松的事。"}, {"text": "奋力地", "is_correct": false, "explanation": "搭配：“奋力地”指费力拼搏，不能用来修饰准备生日礼物。"}], "explanations": {"偷偷": "“偷偷”表示瞒着老师准备，与“礼物”的惊喜性质相符。", "庄严地": "语域：“庄严地”是正式严肃的语体，与生日礼物的轻松场合不符。", "狠狠地": "搭配：“狠狠地”表示用力，不能修饰“准备礼物”这类轻松的事。", "奋力地": "搭配：“奋力地”指费力拼搏，不能用来修饰准备生日礼物。"}, "sentence_index": 6, "correct_answer": "偷偷"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他偷偷地在操场中央放起了鞭炮，整个学校都听见了。", "explanation": "这里应该用〈大张旗鼓地〉。“偷偷”表示瞒着别人，而“整个学校都听见了”是公开的，两者矛盾。"}, {"text": "她偷偷地在街上挥舞着红旗，路人纷纷围观。", "explanation": "这里应该用〈当众〉。“偷偷”表示瞒着别人，而“路人纷纷围观”说明众人都看得见，两者矛盾。"}, {"text": "他偷偷地在黑板上写下了今天的值日表，全班都看见了。", "explanation": "这里应该用〈明目张胆地〉。“偷偷”表示瞒着别人，而“全班都看见了”与之矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '941e0a09-4e7f-42c2-bcae-44406f5b4567') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95319, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妹妹很偷偷地吃掉了最后一块饼干。", "corrected_sentence": "妹妹偷偷地吃掉了最后一块饼干。", "error_description": "错误：“偷偷”前面加了“很”。“偷偷”是副词，不能被“很”修饰，应直接说“偷偷地吃掉”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '941e0a09-4e7f-42c2-bcae-44406f5b4567') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95319, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "弟弟偷偷得把糖藏进了柜子里。", "corrected_sentence": "弟弟偷偷地把糖藏进了柜子里。", "error_description": "错误：状语标记写成了“得”。“偷偷”作状语，后面应接“地”，说“偷偷地把糖藏进”，不能用“得”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '941e0a09-4e7f-42c2-bcae-44406f5b4567') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
