INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95320, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "不让人发觉地；暗暗地。", "primary_collocate": null, "pronunciation": "tōu tōu", "ipa": "tʰou̯˥ tʰou̯˥", "syllable_count": 2, "sentences": [{"text": "听到好消息，她偷偷地笑了。", "target_word": "偷偷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他看着窗外，偷偷擦了擦眼泪。", "target_word": "偷偷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我心里偷偷高兴了好几天。", "target_word": "偷偷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她偷偷看了他一眼，脸一下子红了。", "target_word": "偷偷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听了这些话，他偷偷哭了很久。", "target_word": "偷偷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师偷偷对我点了点头。", "target_word": "偷偷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他心里偷偷想着明天的比赛。", "target_word": "偷偷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她偷偷地在心里说了一声谢谢。", "target_word": "偷偷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都在说话，只有他偷偷地看着窗外。", "target_word": "偷偷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她偷偷想过很多次要去那里工作。", "target_word": "偷偷", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "偷偷地", "label": "带“地”的状语形式"}, {"form": "偷偷摸摸", "label": "复合词"}], "register": "中性", "sense_fingerprint": "不被人发觉，暗暗地（偷偷笑、偷偷高兴、偷偷看一眼）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ec53b00-6195-460c-9dc7-5a5e3f5ff1e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95320, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "偷偷", "is_correct": true, "explanation": "“偷偷”表示不让别人发觉地笑，与“听到好消息”后暗自高兴相符。"}, {"text": "愤怒", "is_correct": false, "explanation": "语义：“愤怒”表示生气，与“听到好消息”的喜悦语境相矛盾。"}, {"text": "痛苦", "is_correct": false, "explanation": "语义：“痛苦”表示难受，与好消息引起的笑意相矛盾。"}, {"text": "猛烈", "is_correct": false, "explanation": "搭配：“猛烈”形容力量强，不能修饰“笑”。"}], "explanations": {"偷偷": "“偷偷”表示不让别人发觉地笑，与“听到好消息”后暗自高兴相符。", "愤怒": "语义：“愤怒”表示生气，与“听到好消息”的喜悦语境相矛盾。", "痛苦": "语义：“痛苦”表示难受，与好消息引起的笑意相矛盾。", "猛烈": "搭配：“猛烈”形容力量强，不能修饰“笑”。"}, "sentence_index": 0, "correct_answer": "偷偷"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老师在全班面前偷偷地表扬了他，大家都看见了。", "explanation": "这里应该用〈当众〉。“偷偷”指不被人发觉，而“全班面前”“大家都看见了”是公开的，与之矛盾。"}, {"text": "我偷偷地在操场上大喊，全校同学都听见了。", "explanation": "这里应该用〈大声〉。“偷偷”表示不被人发觉，与“大喊”以及“全校同学都听见了”矛盾。"}, {"text": "妈妈偷偷地在电视上宣布了新规定。", "explanation": "这里应该用〈公开〉。“偷偷”表示瞒着别人，而在电视上宣布是面向所有人的。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '941e0a09-4e7f-42c2-bcae-44406f5b4567') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95320, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "偷偷", "is_correct": true, "explanation": "“偷偷”表示暗中在心里想，与“心里想着明天的比赛”相符。"}, {"text": "大声地", "is_correct": false, "explanation": "搭配：“大声地”指声音大，心里的想法不发出声音，不能用“大声地”修饰“想”。"}, {"text": "当众地", "is_correct": false, "explanation": "语义：“当众地”指在众人面前，与“心里”这种私密的想法相矛盾。"}, {"text": "放声地", "is_correct": false, "explanation": "搭配：“放声”指放开嗓子唱或喊，不能用来修饰“想”。"}], "explanations": {"偷偷": "“偷偷”表示暗中在心里想，与“心里想着明天的比赛”相符。", "大声地": "搭配：“大声地”指声音大，心里的想法不发出声音，不能用“大声地”修饰“想”。", "当众地": "语义：“当众地”指在众人面前，与“心里”这种私密的想法相矛盾。", "放声地": "搭配：“放声”指放开嗓子唱或喊，不能用来修饰“想”。"}, "sentence_index": 6, "correct_answer": "偷偷"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "听到消息，他偷偷地欢呼起来，全场都听见了。", "explanation": "这里应该用〈大声〉。“偷偷”表示不被人发觉，而“全场都听见了”与之矛盾。"}, {"text": "她偷偷地挥舞着手里的旗子，所有人都注意到了。", "explanation": "这里应该用〈高高地〉。“偷偷”表示不被人发觉，而“所有人都注意到了”说明动作显眼，两者矛盾。"}, {"text": "他偷偷地在黑板上写下答案，还特意让老师看见。", "explanation": "这里应该用〈特意〉。“偷偷”表示不被人发觉，而“特意让老师看见”与之矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '941e0a09-4e7f-42c2-bcae-44406f5b4567') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95320, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈很偷偷地把礼物藏进了柜子。", "corrected_sentence": "妈妈偷偷地把礼物藏进了柜子。", "error_description": "错误：“偷偷”前面加了“很”。副词“偷偷”不能被“很”修饰，应直接说“偷偷地把礼物藏进”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '941e0a09-4e7f-42c2-bcae-44406f5b4567') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95320, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他偷偷了看了看墙上的钟。", "corrected_sentence": "他偷偷地看了看墙上的钟。", "error_description": "错误：“偷偷”后面的“地”写成了“了”。“偷偷”作状语，后面应接“地”，说“偷偷地看”，“了”不能接在副词后面。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '941e0a09-4e7f-42c2-bcae-44406f5b4567') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
