INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95323, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "里面和外面。", "primary_collocate": null, "pronunciation": "nèi wài", "ipa": "nei˥˩ wai˥˩", "syllable_count": 2, "sentences": [{"text": "房子内外都很干净。", "target_word": "内外", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他把车内外都洗了一遍。", "target_word": "内外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公园内外都是人。", "target_word": "内外", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这座楼内外都有灯。", "target_word": "内外", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "晚上，学校内外都很安静。", "target_word": "内外", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "屋子内外的温度差很大。", "target_word": "内外", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她检查了箱子内外。", "target_word": "内外", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "院子内外都种着花。", "target_word": "内外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过年时，商店内外都很热闹。", "target_word": "内外", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请把杯子内外都擦干净。", "target_word": "内外", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "国内外", "label": "复合"}, {"form": "校内外", "label": "复合"}], "register": "中性", "sense_fingerprint": "物体或场所的里面和外面", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3ab1b92-169b-4c40-8f7b-26a651420c25') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95323, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "内外", "is_correct": true, "explanation": "正确：“内外”指房子的里面和外面，“房子内外都很干净”完整通顺。"}, {"text": "远近", "is_correct": false, "explanation": "语义：“远近”指距离，不能用来描述干净与否。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“价格”不能用“干净”来形容，搭配不当。"}, {"text": "高低", "is_correct": false, "explanation": "语义：“高低”指高度，与“干净”的描述不相关。"}], "explanations": {"内外": "正确：“内外”指房子的里面和外面，“房子内外都很干净”完整通顺。", "远近": "语义：“远近”指距离，不能用来描述干净与否。", "价格": "搭配：“价格”不能用“干净”来形容，搭配不当。", "高低": "语义：“高低”指高度，与“干净”的描述不相关。"}, "sentence_index": 0, "correct_answer": "内外"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的内外比我高一头。", "explanation": "这里应该用〈身高〉。“内外”指物体的里面和外面，不能用来比较人的高矮；说“他比我高一头”才合适。"}, {"text": "这家店的内外很便宜。", "explanation": "这里应该用〈价格〉。“内外”指里面和外面，不能用来说价格的高低；价格低要说“便宜”。"}, {"text": "这位老人的内外很大。", "explanation": "这里应该用〈年龄〉。“内外”指里外，不能用来说年龄；说年纪大、岁数多才合适。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8bfad034-e6c0-407b-b152-54d3eb16b850') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95323, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "内外", "is_correct": true, "explanation": "正确：“检查箱子内外”指检查箱子的里面和外面，完整通顺。"}, {"text": "心情", "is_correct": false, "explanation": "搭配：“检查”的对象不能是心情，搭配不当。"}, {"text": "脾气", "is_correct": false, "explanation": "搭配：“脾气”属于人，箱子没有脾气，不能被检查。"}, {"text": "友谊", "is_correct": false, "explanation": "语义：友谊是情感关系，不是可以检查的具体对象。"}], "explanations": {"内外": "正确：“检查箱子内外”指检查箱子的里面和外面，完整通顺。", "心情": "搭配：“检查”的对象不能是心情，搭配不当。", "脾气": "搭配：“脾气”属于人，箱子没有脾气，不能被检查。", "友谊": "语义：友谊是情感关系，不是可以检查的具体对象。"}, "sentence_index": 6, "correct_answer": "内外"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "教室里的内外很多。", "explanation": "这里应该用〈座位〉。“内外”指物体的里外，不能用来说座位的数量。"}, {"text": "这次活动的内外很多。", "explanation": "这里应该用〈人数〉。“内外”不能用来描述人数的多少。"}, {"text": "墙上挂着一幅内外。", "explanation": "这里应该用〈画〉。“幅”用于画，“内外”不能指一幅作品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8bfad034-e6c0-407b-b152-54d3eb16b850') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95323, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们把房间内外很打扫干净。", "corrected_sentence": "我们把房间内外都打扫干净。", "error_description": "错误：“很”放在动词“打扫”前，不能这样修饰动词。正确：应为“都”，统指“房间内外”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8bfad034-e6c0-407b-b152-54d3eb16b850') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95323, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我把箱子内外里都检查了一遍。", "corrected_sentence": "我把箱子内外都检查了一遍。", "error_description": "错误：“内外里”，多加了“里”。“内外”本身已表示里面和外面，后面不能再加“里”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8bfad034-e6c0-407b-b152-54d3eb16b850') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
