INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95324, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "里面和外面；内部和外部。", "primary_collocate": null, "pronunciation": "nèi wài", "ipa": "nei˥˩ wai˥˩", "syllable_count": 2, "sentences": [{"text": "公司内外都在讨论这件事。", "target_word": "内外", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个消息在团队内外传得很快。", "target_word": "内外", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在公司内外都有很多朋友。", "target_word": "内外", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家店的名声，行业内外都知道。", "target_word": "内外", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们要处理好家庭内外的事。", "target_word": "内外", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个问题在政府内外都引起了讨论。", "target_word": "内外", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校内外的人都很关心这件事。", "target_word": "内外", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个组织内外的意见不一样。", "target_word": "内外", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在行业内外都很有名。", "target_word": "内外", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司内外的问题都要解决。", "target_word": "内外", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "国内外", "label": "复合"}, {"form": "校内外", "label": "复合"}], "register": "中性", "sense_fingerprint": "组织、范围或领域的内部和外部", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3ab1b92-169b-4c40-8f7b-26a651420c25') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95324, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "内外", "is_correct": true, "explanation": "正确：“公司内外”指公司的内部和外部，“都在讨论这件事”完整通顺。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“颜色”不能被讨论，与“讨论这件事”搭配不当。"}, {"text": "身高", "is_correct": false, "explanation": "语义：“身高”指人的高矮，不是可以讨论的事情，与句子意思不符。"}, {"text": "味道", "is_correct": false, "explanation": "搭配：“味道”不能被讨论，与“讨论这件事”搭配不当。"}], "explanations": {"内外": "正确：“公司内外”指公司的内部和外部，“都在讨论这件事”完整通顺。", "颜色": "搭配：“颜色”不能被讨论，与“讨论这件事”搭配不当。", "身高": "语义：“身高”指人的高矮，不是可以讨论的事情，与句子意思不符。", "味道": "搭配：“味道”不能被讨论，与“讨论这件事”搭配不当。"}, "sentence_index": 0, "correct_answer": "内外"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次比赛的内外很大。", "explanation": "这里应该用〈范围〉。“内外”指里外两侧，不能用来描述比赛的大小。"}, {"text": "他在这次考试中的内外很差。", "explanation": "这里应该用〈成绩〉。“内外”指里面和外面，不能用来评价考试的好坏；说“成绩很差”才合适。"}, {"text": "他的内外很高。", "explanation": "这里应该用〈水平〉。“内外”不能用来描述能力的高低。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8bfad034-e6c0-407b-b152-54d3eb16b850') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95324, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "内外", "is_correct": true, "explanation": "正确：“学校内外的人”指学校里里外外的人，符合“都很关心这件事”。"}, {"text": "脾气", "is_correct": false, "explanation": "搭配：“脾气”属于人，不能说“学校的脾气”，搭配不当。"}, {"text": "重量", "is_correct": false, "explanation": "语义：“重量”指物体的轻重，不能用来指人，与句子意思不符。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：“年龄”不能用来指学校里的人，与句子意思不符。"}], "explanations": {"内外": "正确：“学校内外的人”指学校里里外外的人，符合“都很关心这件事”。", "脾气": "搭配：“脾气”属于人，不能说“学校的脾气”，搭配不当。", "重量": "语义：“重量”指物体的轻重，不能用来指人，与句子意思不符。", "年龄": "语义：“年龄”不能用来指学校里的人，与句子意思不符。"}, "sentence_index": 6, "correct_answer": "内外"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "教室里的内外很多。", "explanation": "这里应该用〈座位〉。“内外”指物体的里外，不能用来说座位的数量。"}, {"text": "他说话的内外很大。", "explanation": "这里应该用〈声音〉。“内外”指内部和外部，不能用来说声音的大小。"}, {"text": "墙上挂着一幅内外。", "explanation": "这里应该用〈画〉。“幅”用于画，“内外”不能指一幅作品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8bfad034-e6c0-407b-b152-54d3eb16b850') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95324, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "行业内外地人都知道这件事。", "corrected_sentence": "行业内外的人都知道这件事。", "error_description": "错误：“地”。正确：“的”。名词前的修饰语要用“的”，“地”只用于修饰动词、形容词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8bfad034-e6c0-407b-b152-54d3eb16b850') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95324, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学校内外地活动都很多。", "corrected_sentence": "学校内外的活动都很多。", "error_description": "错误：“地”。正确：“的”。名词“活动”前的修饰语要用“的”，“地”只用于修饰动词、形容词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8bfad034-e6c0-407b-b152-54d3eb16b850') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
