INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95325, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "研究身体里面生了什么病、怎样不用开刀来治的学问。", "primary_collocate": null, "pronunciation": "nèi kē xué", "ipa": "nei˥˩ kʰɤ˥ ɕɥe˧˥", "syllable_count": 3, "sentences": [{"text": "内科学不用开刀治病。", "target_word": "内科学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我姐姐正在学内科学。", "target_word": "内科学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "内科学研究身体里的病。", "target_word": "内科学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想当医生，所以学内科学。", "target_word": "内科学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "内科学课在星期三上午。", "target_word": "内科学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "内科学的老师很会讲课。", "target_word": "内科学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本内科学课本太厚了。", "target_word": "内科学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "内科学和外科学不一样。", "target_word": "内科学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她对内科学特别有兴趣。", "target_word": "内科学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在图书馆看内科学的书。", "target_word": "内科学", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "內科學", "label": "繁体"}], "register": "专业", "sense_fingerprint": "研究身体内部疾病及不开刀治法的学问", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1665dc3-7706-4348-9cee-b52c002cdca1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95325, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "内科学", "is_correct": true, "explanation": "正确。内科学以非手术治疗为主，符合“不用开刀治病”的说法。"}, {"text": "外科学", "is_correct": false, "explanation": "语义：外科学研究开刀治疗，与“不用开刀”矛盾。"}, {"text": "手术刀", "is_correct": false, "explanation": "语义：手术刀本身是用来开刀的工具，与“不用开刀”矛盾。"}, {"text": "病房", "is_correct": false, "explanation": "搭配：“治病”的施事应是医生或疗法，“病房”是场所，不能作主语治病。"}], "explanations": {"内科学": "正确。内科学以非手术治疗为主，符合“不用开刀治病”的说法。", "外科学": "语义：外科学研究开刀治疗，与“不用开刀”矛盾。", "手术刀": "语义：手术刀本身是用来开刀的工具，与“不用开刀”矛盾。", "病房": "搭配：“治病”的施事应是医生或疗法，“病房”是场所，不能作主语治病。"}, "sentence_index": 0, "correct_answer": "内科学"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他打算学内科学，专门负责做手术。", "explanation": "这里应该用〈外科学〉。内科学以非手术治疗为主，做手术要学外科学。"}, {"text": "我上学期调到了内科学，负责门诊。", "explanation": "这里应该用〈内科〉。内科学指学问，不是科室；人员调到科室要说“调到内科”。"}, {"text": "她小时候得了内科学，住了一个月院。", "explanation": "这里应该用〈肺炎〉之类的病名。内科学是学问，不是疾病名称，不能说“得了内科学”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc16e87b-3d15-4e1f-8fa1-4ec5a9c7b9e5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
